window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["D"]={"1755":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dæd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>informal</em> father:</div><ul class=\"examples\"><li><em>She lives with her mom and dad.</em></li><li><em>Dad, will you help me?</em></li></ul></div>","1756":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dad‧dy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdædi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural daddies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>informal</em> father – used especially by children or when speaking to children:</div><ul class=\"examples\"><li><em>Daddy’s home!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the daddy/your daddy</strong> <em>informal</em> the best, most important, or most respected person:</div><ul class=\"examples\"><li><em>Damon won the game for us – he’s the daddy!</em></li></ul></div>","1757":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dai‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> happening or done every day:</div><ul class=\"examples\"><li><em>daily flights to Miami</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>daily life</strong> the ordinary things that you usually do or experience</div><div class=\"sense\"><span class=\"snum\">3</span> relating to a single day:</div><ul class=\"examples\"><li><em>the daily rate of pay</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">happening or done every day:</div><ul class=\"examples\"><li><em>The zoo is open daily.</em></li></ul></div></div>","1758":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dai‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeəri $ ˈderi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural dairies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a place on a farm where milk is kept and butter and cheese are made</div><div class=\"sense\"><span class=\"snum\">2</span> a company which sells milk and sometimes makes other things from milk, such as cheese</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>dairy products/produce</strong> milk, butter, cheese etc</div></div>","1759":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dæm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a special wall built across a river or stream to stop the water from flowing, especially in order to make a lake or produce electricity</div><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> the mother of a four-legged animal, especially a horse</div></div>","1760":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dam‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdæmɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[physical harm]</strong> <span class=\"gram\">[uncountable]</span> physical harm that is done to something or to a part of someone’s body, so that it is broken or injured</div><ul class=\"examples\"><li><strong><em>damage to</strong>: damage to property</em></li><li><em>These chemicals have been found to cause serious environmental damage.</em></li><li><em>There may be permanent brain damage.</em></li><li><em>His eyesight suffered irreparable damage.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[emotional harm]</strong> <span class=\"gram\">[uncountable]</span> harm caused to someone’s emotions or mind:</div><ul class=\"examples\"><li><em>The death of a parent can cause long-lasting psychological damage.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bad effect]</strong> <span class=\"gram\">[uncountable]</span> a bad effect on something</div><ul class=\"examples\"><li><strong><em>damage to</strong>: The damage to his reputation was considerable. / The closure of the factory will cause severe damage to the local economy.</em></li><li><strong><em>damage limitation/control</strong>: the attempts at political damage control during the scandal</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>damages</strong> <span class=\"gram\">[plural]</span> <em>law</em> money that a court orders someone to pay to someone else as a punishment for harming them or their property → compensation:</div><ul class=\"examples\"><li><em>The court awarded him £15,000 in damages.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the damage is done</strong> used to say that something bad has happened which makes it impossible to go back to the way things were before it happened:</div><ul class=\"examples\"><li><em>She immediately apologized, but the damage was done.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>what’s the damage?</strong> <em>spoken</em> used humorously to ask how much you have to pay for something</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to cause physical harm to something or to part of someone’s body: ► see thesaurus at harm</div><ul class=\"examples\"><li><em>insects that damage crops</em></li><li><strong><em>badly/severely/seriously damage</strong>: Smoking can severely damage your health.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to have a bad effect on something or someone in a way that makes them weaker or less successful:</div><ul class=\"examples\"><li><em>The changes in share values have damaged investor confidence.</em></li></ul></div></div>","1761":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˈdæmɪdʒd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is damaged has been harmed or injured:</div><ul class=\"examples\"><li><em>a damaged leg</em></li><li><em>The ship is badly damaged.</em></li><li><em>a shampoo for dry or damaged hair (=hair that is in bad condition)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a damaged person has emotional problems because of bad things that have happened to them in the past:</div><ul class=\"examples\"><li><em>She works with emotionally damaged children.</em></li></ul></div>","1762":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dam‧ag‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdæmɪdʒɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> causing physical harm to someone or something: ► see thesaurus at harmful</div><ul class=\"examples\"><li><em>the damaging effects of sunlight</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> affecting someone or something in a bad way:</div><ul class=\"examples\"><li><em>damaging criticism of his policies</em></li><li><strong><em>damaging to</strong>: The loss of jobs was damaging to morale.</em></li></ul></div>","1763":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dæmp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> slightly wet, often in an unpleasant way: ► see thesaurus at wet</div><ul class=\"examples\"><li><em>Wipe the leather with a damp cloth.</em></li><li><em>a cold, damp day</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>damp squib</strong> <em>British English</em> <em>informal</em> something that is intended to be exciting, effective etc, but which is disappointing</div></div>","1764":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɑːns $ dæns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a special set of movements performed to a particular type of music:</div><ul class=\"examples\"><li><em>The waltz is an easy dance to learn.</em></li><li><strong><em>folk/traditional dance</strong>: the traditional dances and music of Russia</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a social event or party where you dance:</div><ul class=\"examples\"><li><em>Are you going to the dance this weekend?</em></li><li><em>the school dance</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an act of dancing:</div><ul class=\"examples\"><li><em>Claire did a little dance of excitement.</em></li><li><strong><em>have a dance<em>especially British English</em></strong>: Let’s have another dance.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a piece of music which you can dance to:</div><ul class=\"examples\"><li><em>The band was playing a slow dance.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> the activity or art of dancing:</div><ul class=\"examples\"><li><em>modern dance</em></li><li><em>dance and movement classes</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to move your feet and body in a way that matches the style and speed of music:</div><ul class=\"examples\"><li><em>Come on, let’s dance.</em></li><li><strong><em>dance to</strong>: They danced to Ruby Newman’s orchestra (=the orchestra was playing).</em></li><li><strong><em>dance with</strong>: The bride danced with her father.</em></li><li><strong><em>dance a waltz/rumba/tango etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to dance in performances, especially in ballet:</div><ul class=\"examples\"><li><em>He danced with the Boston Repertory Ballet.</em></li><li><em>Nakamura dances several solos in this production.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> <em>literary</em> to move up, down, and around quickly:</div><ul class=\"examples\"><li><em>Pink and white balloons danced in the wind.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>dance to somebody’s tune</strong> to do what someone wants you to do – used to show disapproval:</div><ul class=\"examples\"><li><em>At that time, Eastern bloc countries danced to the Soviet tune.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>dance attendance on somebody</strong> to do everything possible in order to please someone:</div><ul class=\"examples\"><li><em>a movie star with several young men dancing attendance on her</em></li></ul></div></div>","1765":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> danc‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɑːnsə $ ˈdænsər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who dances as a profession:</div><ul class=\"examples\"><li><em>The dancer’s technique is strong.</em></li><li><strong><em>ballet/ballroom/flamenco etc dancer</strong>: Margot Fonteyn, the famous British ballet dancer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who dances:</div><ul class=\"examples\"><li><em>the dancers on the floor</em></li><li><strong><em>good/bad dancer</strong>: Dave’s a good dancer.</em></li></ul></div>","1766":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dan‧ger</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪndʒə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the possibility that someone or something will be harmed, destroyed, or killed:</div><ul class=\"examples\"><li><em>Danger! No boats beyond this point.</em></li><li><em>The refugees believe that their lives are in danger.</em></li><li><strong><em>danger of</strong>: The danger of a fire in the home increases during the holidays.</em></li><li><strong><em>danger from</strong>: The public was not aware of the danger from nuclear tests in Nevada.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the possibility that something bad will happen</div><ul class=\"examples\"><li><strong><em>be in danger of (doing) something</strong>: The party is in danger of being defeated in the next election.</em></li><li><strong><em>danger that</strong>: There is a danger that museums will attempt to entertain rather than educate.</em></li><li><strong><em>the danger of (doing) something</strong>: to guard against the danger of becoming isolated</em></li><li><strong><em>a danger sign/signal</strong>: He didn’t look pleased, but she ignored the danger signals.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> something or someone that may harm or kill you:</div><ul class=\"examples\"><li><em>the dangers that abound in the region</em></li><li><strong><em>danger of</strong>: the dangers of drug use</em></li><li><strong><em>be a danger to somebody/something</strong>: The wreck is a danger to other ships.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>there’s no danger of something</strong> used to say that something will not happen:</div><ul class=\"examples\"><li><em>There’s no danger of confusion.</em></li><li><em>There’s no danger of Darren ever getting up early.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be on the danger list</strong> <em>British English</em> to be so ill that you may die</div></div>","1767":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dan‧ger‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪndʒərəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> able or likely to harm or kill you → harmful:</div><ul class=\"examples\"><li><em>laws about dangerous dogs</em></li><li><em>Some of these prisoners are extremely dangerous.</em></li><li><strong><em>highly/very dangerous</strong>: It was a highly dangerous situation.</em></li><li><strong><em>dangerous for</strong>: The crumbling sidewalks are dangerous for old people.</em></li><li><strong><em>dangerous to</strong>: The virus is probably not dangerous to humans.</em></li><li><strong><em>it is dangerous for somebody to do something</strong>: It’s dangerous for a woman to walk alone at night.</em></li><li><em>The powdered milk was not as good as breast milk, and was downright dangerous (=actually dangerous) when it was mixed with unclean water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> involving a lot of risk, or likely to cause problems <em>SYN risky</em>:</div><ul class=\"examples\"><li><em>The business is in a dangerous financial position.</em></li><li><em>a politically dangerous strategy</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>dangerous ground/territory</strong> a situation or subject that could make someone very angry or upset:</div><ul class=\"examples\"><li><em>Teachers can be on dangerous ground if they discuss religion.</em></li></ul></div>","1768":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dan‧ger‧ous‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪndʒərəsli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">in a way that is dangerous:</div><ul class=\"examples\"><li><em>The boat was dangerously close to the rocks.</em></li><li><strong><em>dangerously high/low</strong>: He’s suffering from dangerously high blood pressure.</em></li><li><em>I am used to living dangerously (=doing things that involve risks).</em></li><li><em>She was found guilty of driving dangerously.</em></li></ul></div>","1769":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dan‧gle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdæŋɡəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to hang or swing loosely, or to make something do this</div><ul class=\"examples\"><li><strong><em>dangle from</strong>: A light bulb dangled from a wire in the ceiling.</em></li><li><strong><em>dangle something in/over etc something</strong>: I dangled my feet in the clear blue water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>dangle something in front of somebody/before somebody</strong> to offer something good to someone, in order to persuade them to do something:</div><ul class=\"examples\"><li><em>A good pay package and a company car were dangled in front of her.</em></li></ul></div>","1770":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /deə $ der/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to be brave enough to do something that is risky or that you are afraid to do – used especially in questions or negative sentences:</div><ul class=\"examples\"><li><em>He wanted to ask her, but he didn’t dare.</em></li><li><em>‘I’ll tell Dad.’ ‘You wouldn’t dare!’</em></li><li><strong><em>dare (to) do something</strong>: I daren’t go home. / Only a few journalists dared to cover the story. / She hardly dared hope that he was alive. / Dare we admit this?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>how dare you</strong> <em>spoken</em> said to show that you are very angry and shocked about what someone has done or said:</div><ul class=\"examples\"><li><em>How dare you accuse me of lying!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>don’t you dare!</strong> <em>spoken</em> said to warn someone not to do something because it makes you angry:</div><ul class=\"examples\"><li><em>Don’t you dare talk to me like that!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to try to persuade someone to do something dangerous or embarrassing as a way of proving that they are brave</div><ul class=\"examples\"><li><strong><em>dare somebody to do something</strong>: They dared Ed to steal a bottle of his father’s whiskey.</em></li><li><em>So jump, then. I dare you.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>dare I say/suggest</strong> <em>spoken</em> <em>formal</em> used when saying something that you think people may not accept or believe:</div><ul class=\"examples\"><li><em>I thought the play was, dare I say it, boring.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>I dare say</strong> (also I daresay) <em>spoken</em> <em>especially British English</em> used when saying or agreeing that something may be true:</div><ul class=\"examples\"><li><em>I dare say things will improve.</em></li></ul></div>","1771":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dar‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeərɪŋ $ ˈder-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> involving a lot of risk or danger, or brave enough to do risky things: ► see thesaurus at brave</div><ul class=\"examples\"><li><em>a daring rescue attempt</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> new or unusual in a way that may shock people:</div><ul class=\"examples\"><li><em>a daring new building</em></li></ul></div>","1772":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɑːk $ dɑːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(comparative darker, superlative darkest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[no light]</strong> if it is dark, there is little or no light <em>OPP light</em>:</div><ul class=\"examples\"><li><em>The church was dark and quiet.</em></li><li><em>the dark winter days</em></li><li><em>Suddenly, the room went dark (=became dark).</em></li><li><em>It gets dark (=night begins) about ten o&#x27;clock.</em></li><li><em>It was still dark (=was night) when we boarded the train.</em></li><li><em>It was pitch dark (=completely dark) in the attic.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[colour]</strong> quite close to black in colour <em>OPP light</em> <em>, pale</em>: ► see thesaurus at colour</div><ul class=\"examples\"><li><em>There were dark clouds in the sky.</em></li><li><em>men in dark suits</em></li><li><em>a slightly darker colour</em></li><li><strong><em>dark blue/green/pink etc</strong>: a dark blue dress</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[hair/eyes/skin]</strong> someone who is dark has hair, eyes, or skin that is brown or black in colour <em>OPP fair</em>:</div><ul class=\"examples\"><li><em>a tall, dark man</em></li><li><em>John’s dark skin and eyes</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[mysterious]</strong> mysterious or secret:</div><ul class=\"examples\"><li><em>a dark secret</em></li><li><strong><em>keep something dark<em>British English</em></strong> (=keep something secret): Apparently, he has a son, but he’s kept that very dark.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[evil]</strong> evil or threatening:</div><ul class=\"examples\"><li><em>There was a darker side to his character.</em></li><li><em>a place where so many dark deeds had been committed</em></li><li><em>the dark forces of the universe</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[unhappy time]</strong> a dark time is unhappy or without hope:</div><ul class=\"examples\"><li><em>the dark days of the war</em></li><li><em>Even in the darkest moments, I still had you, my love.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[feelings/thoughts]</strong> if you have dark feelings or thoughts, you are very sad or worried:</div><ul class=\"examples\"><li><em>a dark depression</em></li><li><em>her darkest fears</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[humour]</strong> dark humour deals with things that are bad or upsetting in a funny way <em>SYN black</em>:</div><ul class=\"examples\"><li><em>the dark humor common in difficult situations</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>darkest Africa/South America etc</strong> <em>old-fashioned</em> the parts of Africa etc about which we know very little – this use is now often considered offensive</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the dark</strong> when there is no light, especially because the sun has gone down: ► see thesaurus at colour</div><ul class=\"examples\"><li><em>my childish fear of the dark</em></li><li><strong><em>in the dark</strong>: I turned off the light and lay there in the dark.</em></li><li><em>We stood outside in the pitch dark (=when there is no light at all).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>after/before/until dark</strong> after, before, or until the sun goes down at night:</div><ul class=\"examples\"><li><em>I want you home before dark.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in the dark</strong> <em>informal</em> knowing nothing about something important, because you have not been told about it:</div><ul class=\"examples\"><li><em>We’re in the dark just as much as you are.</em></li><li><em>College officials were kept in the dark about the investigation.</em></li></ul></div></div>","1773":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dark‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɑːkən $ ˈdɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to become dark, or to make something dark:</div><ul class=\"examples\"><li><em>The sky darkened and a few drops of rain fell.</em></li><li><em>a darkened theater</em></li><li><em>The evening shadows darkened the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to become less hopeful or positive, or to make something like this:</div><ul class=\"examples\"><li><em>As he got drunker, his mood darkened.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if someone’s face darkens, they start to look angry:</div><ul class=\"examples\"><li><em>The captain’s face darkened as he read.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>never darken my door again</strong> <em>old-fashioned</em> said when you do not want to see someone again – now used humorously</div></div>","1774":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dark‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɑːknəs $ ˈdɑːrk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when there is no light:</div><ul class=\"examples\"><li><em>the long hours of darkness during winter</em></li><li><strong><em>in darkness</strong>: The lamp suddenly went out, leaving us in darkness.</em></li><li><strong><em>total/pitch/complete darkness</strong>: The room was in total darkness.</em></li><li><em>We lit our campfire as darkness fell (=it became night).</em></li><li><em>He stared out the window at the gathering darkness (=the night slowly coming).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> evil or the devil:</div><ul class=\"examples\"><li><em>His smooth manner covered a heart of darkness.</em></li><li><strong><em>the forces/powers of darkness</strong> (=the devil or evil people)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the dark quality of a colour:</div><ul class=\"examples\"><li><em>the darkness of the lenses</em></li></ul></div>","1775":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dar‧ling</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɑːlɪŋ $ ˈdɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>spoken</em> used when speaking to someone you love:</div><ul class=\"examples\"><li><em>Look, darling, there’s Mary.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone who is very nice:</div><ul class=\"examples\"><li><em>You really are a darling, Barney.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the darling of something</strong> the most popular person or thing in a particular group or area of activity:</div><ul class=\"examples\"><li><em>She’s the darling of the fashion world.</em></li></ul></div>","1776":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɑːt $ dɑːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move suddenly and quickly in a particular direction:</div><ul class=\"examples\"><li><em>Jill darted forward and pulled him away from the fire.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> <em>literary</em> to look at someone or something very quickly:</div><ul class=\"examples\"><li><em>Tom darted a terrified glance over his shoulder at his pursuers.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a small pointed object that is thrown or shot as a weapon, or one that is thrown in the game of darts:</div><ul class=\"examples\"><li><em>a poisoned dart</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>darts</strong> <span class=\"gram\">[uncountable]</span> a game in which darts are thrown at a round board with numbers on it</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> a sudden quick movement in a particular direction:</div><ul class=\"examples\"><li><em>The prisoner made a dart for the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>dart of guilt/panic/pain etc</strong> a very sudden, sharp feeling:</div><ul class=\"examples\"><li><em>It sent a dart of terror through her.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a small fold put into a piece of clothing to make it fit better</div></div></div>","1777":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dæʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to go or run somewhere very quickly: ► see thesaurus at hurry, run</div><ul class=\"examples\"><li><em>Olive dashed into the room, grabbed her bag, and ran out again.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>dash somebody’s hopes</strong> to disappoint someone by telling them that what they want is not possible:</div><ul class=\"examples\"><li><em>Hopkins’ hopes were dashed when his appeal was denied.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>(I) must dash/(I) have to dash</strong> <em>British English</em> <em>spoken</em> used to tell someone that you must leave quickly:</div><ul class=\"examples\"><li><em>Anyway, I must dash – I said I’d meet Daniel at eight.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> <em>written</em> to throw or push something violently against something, especially so that it breaks</div><ul class=\"examples\"><li><strong><em>dash something against/on something</strong>: The ship was dashed against the rocks.</em></li><li><strong><em>dash against</strong>: Waves were dashing against the sea wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>dash it (all)!</strong> <em>British English</em> <em>old-fashioned</em> used to show that you are slightly annoyed or angry about something</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[small amount]</strong> <span class=\"gram\">[singular]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a small amount of a substance that is added to something else</div><ul class=\"examples\"><li><strong><em>dash of</strong>: Add salt, pepper and a dash of vinegar.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a small amount of a quality that is added to something else</div><ul class=\"examples\"><li><strong><em>dash of</strong>: Add a dash of romance to your life with a trip to Paris.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[run quickly]</strong> <span class=\"gram\">[countable usually singular]</span> an occasion when someone runs somewhere very quickly in order to get away from something or someone, or in order to reach them</div><ul class=\"examples\"><li><strong><em>make a dash for something</strong>: He made a dash for the door. / The prisoners made a dash for freedom. / It’s pouring with rain – we’ll have to make a dash for it.</em></li><li><em>When the alarm went there was a mad dash for the exit.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[line]</strong> <span class=\"gram\">[countable]</span> a line (–) used in writing to separate two closely related parts of a sentence, as for example, in the sentence ‘Go home – they’re waiting for you.’</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sound]</strong> <span class=\"gram\">[countable]</span> a long sound or flash of light used for sending messages in Morse code → dot</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[car]</strong> <span class=\"gram\">[countable]</span> <em>American English</em> a dashboard</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[style]</strong> <span class=\"gram\">[uncountable]</span> <em>old-fashioned</em> style, energy, and courage in someone such as a soldier</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>cut a dash</strong> <em>old-fashioned</em> to look very impressive and attractive in particular clothes:</div><ul class=\"examples\"><li><em>With her new image, she’ll certainly cut a dash on her holiday cruise.</em></li></ul></div></div>","1778":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> da‧ta</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪtə, ˈdɑːtə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[plural, uncountable]</span> information or facts: GRAMMAR: Singular or plural verb?• In everyday English, data is usually followed by a singular verb: · The data is collected by trained interviewers.• In academic or very formal English, a plural verb is used: · These data are summarized in Table 5.• When talking about one fact or piece of information, you say a piece of data: · This is a useful piece of data. ✗Don’t say: datas</div><ul class=\"examples\"><li><em>The research involves collecting data from two random samples.</em></li><li><strong><em>data on</strong>: data on pesticide use</em></li><li><strong><em>experimental/historical/statistical etc data</strong>: detailed research data</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> information in a form that can be stored and used, especially on a computer:</div><ul class=\"examples\"><li><em>It’s possible to store a lot more data on a DVD.</em></li><li><strong><em>data storage/transfer/retrieval</em></strong></li></ul></div>","1779":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> da‧ta‧base</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪtəˌbeɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a large amount of data stored in a computer system so that you can find and use it easily:</div><ul class=\"examples\"><li><em>customer details held on a database</em></li><li><strong><em>database system/software/application etc</em></strong></li></ul></div>","1780":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /deɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[day]</strong> a particular day of the month or year, especially shown by a number:</div><ul class=\"examples\"><li><em>The date on the letter was 30th August 1962.</em></li><li><em>What’s today’s date?</em></li><li><strong><em>date of</strong>: What’s the date of the next meeting? / You should apply at least 8 weeks before your date of departure.</em></li><li><strong><em>date for</strong>: Have you set a date for the wedding yet?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>at a later/future date</strong> <em>formal</em> at some time in the future <em>SYN later</em>:</div><ul class=\"examples\"><li><em>The details will be agreed at a later date.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>to date</strong> up to now:</div><ul class=\"examples\"><li><em>The cost of the work to date has been about £150 million.</em></li><li><em>Her best performance to date was her third place at the World Junior Championships.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[romantic meeting]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> an occasion when you go out with someone that you like in a romantic way → blind date</div><ul class=\"examples\"><li><strong><em>date with</strong>: I’ve got a date with Andrea tomorrow night.</em></li><li><em>I felt like a teenager going out on a first date.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>American English</em> someone that you have a date with</div><ul class=\"examples\"><li><strong><em>somebody’s date</strong>: Can I bring my date to the party?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[arrangement to meet somebody]</strong> a time arranged to meet someone, especially socially:</div><ul class=\"examples\"><li><em>Let’s make a date to come over and visit.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[fruit]</strong> a sweet sticky brown fruit with a long hard seed inside</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[write date]</strong> <span class=\"gram\">[transitive]</span> to write or print the date on something:</div><ul class=\"examples\"><li><em>a newspaper dated November 23, 1963</em></li><li><em>Make sure you sign and date it at the bottom.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[find age]</strong> <span class=\"gram\">[transitive]</span> to find out when something old was made or formed:</div><ul class=\"examples\"><li><em>The rocks are dated by examining the fossils found in the same layer.</em></li><li><em>radiocarbon dating</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[old-fashioned]</strong> <span class=\"gram\">[intransitive]</span> if clothing, art etc dates, it begins to look old-fashioned: → dated</div><ul class=\"examples\"><li><em>His designs are so classic, they’ve hardly dated at all.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[relationship]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>American English</em> to have a romantic relationship with someone <em>SYN go out with</em>:</div><ul class=\"examples\"><li><em>Is he still dating Sarah?</em></li><li><em>Are Chris and Liz dating?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[show somebody’s age]</strong> <span class=\"gram\">[transitive]</span> if something that you say, do, or wear dates you, it shows that you are fairly old:</div><ul class=\"examples\"><li><em>Yes, I remember the Moon landings – that dates me, doesn’t it?</em></li></ul></div></div>","1781":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dat‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">old-fashioned → out-of-date: ► see thesaurus at old-fashioned</div><ul class=\"examples\"><li><em>That dress looks a bit dated now.</em></li></ul></div>","1782":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> daugh‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɔːtə $ ˈdɒːtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone’s female child → filial:</div><ul class=\"examples\"><li><em>She’s got two daughters and one son.</em></li><li><em>our eldest daughter</em></li><li><strong><em>daughter of</strong>: the daughter of an English king</em></li></ul></div>","1783":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈdaughter-in-law</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural daughters-in-law)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable]</span> your son’s wife</div></div>","1784":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> daunt‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɔːntɪŋ $ ˈdɒːn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">frightening in a way that makes you feel less confident: ► see thesaurus at difficult</div><ul class=\"examples\"><li><em>The trip seemed rather daunting for a young girl.</em></li><li><em>He’s got the daunting task of following in Ferguson’s footsteps.</em></li><li><em>the daunting prospect of asking for a loan</em></li></ul></div>","1785":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɔːn $ dɒːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the time at the beginning of the day when light first appears <em>SYN daybreak</em> → dusk</div><ul class=\"examples\"><li><strong><em>at dawn</strong>: The boats set off at dawn.</em></li><li><em>When dawn broke (=the first light of the day appeared), we were still 50 miles from Calcutta.</em></li><li><em>I was up at the crack of dawn (=very early in the morning) to get the plane.</em></li><li><em>We worked from dawn to dusk (=through the whole day while it is light).</em></li><li><em>the cold light of dawn</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the dawn of civilization/time etc</strong> the time when something began or first appeared: ► see thesaurus at beginning</div><ul class=\"examples\"><li><em>People have been falling in love since the dawn of time.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a false dawn</strong> something that seems positive or hopeful but really is not:</div><ul class=\"examples\"><li><em>There was talk of share prices recovering, but that was just a false dawn.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if day or morning dawns, it begins:</div><ul class=\"examples\"><li><em>The morning dawned fresh and clear after the storm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a period of time or situation dawns, it begins:</div><ul class=\"examples\"><li><em>The age of Darwin had dawned.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a feeling or idea dawns, you have it for the first time:</div><ul class=\"examples\"><li><em>It began to dawn that something was wrong.</em></li></ul></div></div>","1786":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /deɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[24 hours]</strong> <span class=\"gram\">[countable]</span> a period of 24 hours:</div><ul class=\"examples\"><li><em>We spent three days in Paris.</em></li><li><em>‘What day is it today?’ ‘Friday.’</em></li><li><em>He left two days ago.</em></li><li><em>I’ll call you in a couple of days.</em></li><li><strong><em>on a... day</strong>: We’ll have to hold the party on a different day.</em></li><li><strong><em>(on) that/the following/the previous day</strong> (=during a particular day): What really happened on that day so long ago? / Over 10,000 soldiers died on that one day in January. / The following day, a letter arrived.</em></li><li><em>I saw Jane the day before yesterday.</em></li><li><em>We’re leaving for New York the day after tomorrow.</em></li><li><em>I got an email from Sue the other day (=a few days ago).</em></li><li><em>Women generally use up about 2,000 calories a day (=each day).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not night]</strong> <span class=\"gram\">[countable, uncountable]</span> the period of time between when it gets light in the morning and when it gets dark <em>OPP night</em>:</div><ul class=\"examples\"><li><em>She only leaves her house during the day.</em></li><li><em>It was a cold blustery day.</em></li><li><em>Kept in that dark cell, I could no longer tell whether it was day or night.</em></li><li><strong><em>on a... day</strong>: She first met Steve on a cold but sunny day in March.</em></li><li><strong><em>by day</strong> (=during the day): Owls usually sleep by day and hunt by night.</em></li><li><em>The day dawned (=started) bright and clear.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[when you are awake]</strong> <span class=\"gram\">[countable usually singular]</span> the time during the day when you are awake and active:</div><ul class=\"examples\"><li><em>His day begins at six.</em></li><li><em>Jackie starts the day with a few gentle exercises.</em></li><li><em>Sometimes I feel I just can’t face another day.</em></li><li><em>It’s been a long day (=used when you have been awake and busy for a long time).</em></li><li><strong><em>all day (long)</strong>: I’ve been studying all day. I’m beat!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[time at work]</strong> <span class=\"gram\">[countable]</span> the time you spend doing your job during a 24-hour period:</div><ul class=\"examples\"><li><em>I work a ten-hour day.</em></li><li><em>Rail workers are campaigning for a shorter working day.</em></li><li><em>I’ve got a day off (=a day when I do not have to go to work) tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[past]</strong> <span class=\"gram\">[countable]</span> used to talk about a time in the past:</div><ul class=\"examples\"><li><em>I knew him pretty well from his days as a DJ in the Bounty Club (=from when he was a DJ).</em></li><li><em>I always used to do the cooking in the early days of our marriage.</em></li><li><em>Not much was known about the dangers of smoking in those days (=then).</em></li><li><em>They were very much opposed to the government of the day (=that existed then).</em></li><li><em>One day (=on a day in the past), a mysterious stranger called at the house.</em></li><li><em>From day one (=from the beginning), I knew I wouldn’t get on with him.</em></li><li><em>In my day (=in the past, when I was young), kids used to have some respect for their elders.</em></li><li><strong><em>in somebody’s student/army/childhood etc days</strong> (=in the past when someone was a student etc): I used to run six miles a day in my army days.</em></li><li><strong><em>those were the days<em>spoken</em></strong> (=used to talk about a time in the past you think was better than now): We used to stay in bed all morning and party all night. Those were the days!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[now]</strong> <span class=\"gram\">[countable]</span> used to talk about the situation that exists now:</div><ul class=\"examples\"><li><em>I don’t do much exercise these days (=now).</em></li><li><em>It’s incredible that such attitudes still exist in this day and age (=used to express disapproval that something still exists now).</em></li><li><em>To this day (=until and including now), he denies any involvement in the crime.</em></li><li><strong><em>up to/until/to the present day</strong> (=until and including now): This tradition has continued right up until the present day.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[future]</strong> <span class=\"gram\">[countable]</span> used to talk about a time in the future</div><ul class=\"examples\"><li><strong><em>one day/some day</strong> (=some time in the future): I’d like to go and visit the States one day. / Some day we might get him to see sense.</em></li><li><em>One of these days (=some time soon) I’m going to walk right out of here and never come back.</em></li><li><em>Kelly’s expecting the baby any day now (=very soon).</em></li><li><em>The day will come (=the time will come) when he won’t be able to care for himself anymore.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>somebody’s/something’s day</strong> a successful period of time in someone’s life or in something’s existence:</div><ul class=\"examples\"><li><em>My uncle was a famous radio personality in his day (=at the time he was most successful).</em></li><li><em>Don’t be too disappointed you didn’t win – your day will come (=you will be successful in the future).</em></li><li><em>Game shows like that have had their day (=were successful in the past, but are not anymore).</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>Independence/election/Christmas etc day</strong> a day on which a particular event or celebration takes place:</div><ul class=\"examples\"><li><em>Rioting broke out just three days before polling day.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>five/three/nine etc years to the day</strong> exactly five years etc:</div><ul class=\"examples\"><li><em>It’s two years to the day since he died.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>somebody’s days</strong> someone’s life:</div><ul class=\"examples\"><li><em>She ended her days in poverty.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>somebody’s/something’s days are numbered</strong> used to say that someone or something will not exist for much longer:</div><ul class=\"examples\"><li><em>It seems that the hospital’s days are numbered.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>day after day</strong> (also day in day out) continuously for a long time in a way that is annoying or boring:</div><ul class=\"examples\"><li><em>I couldn’t stand sitting at a desk day after day.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>from day to day</strong> (also from one day to the next) if a situation changes from day to day or from one day to the next, it changes often: → day-to-day, → live from day to day at live1(5)</div><ul class=\"examples\"><li><em>I never know from day to day what I’m going to be doing.</em></li><li><em>His moods swung wildly from one day to the next.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>day by day</strong> slowly and gradually:</div><ul class=\"examples\"><li><em>Her health was improving day by day.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>night and day</strong> (also day and night) all the time <em>SYN continuously</em>:</div><ul class=\"examples\"><li><em>Being together night and day can put a great pressure on any relationship.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>day out</strong> <em>especially British English</em> a trip you make for pleasure on a particular day:</div><ul class=\"examples\"><li><em>A visit to the caves makes a fascinating and exciting day out for all the family.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>have an off day</strong> to be less successful or happy than usual, for no particular reason:</div><ul class=\"examples\"><li><em>Even the greatest athletes have their off days.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>make somebody’s day</strong> to make someone very happy:</div><ul class=\"examples\"><li><em>Hearing her voice on the phone really made my day.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>soup/dish/fish etc of the day</strong> a soup, meal etc that a restaurant serves on a particular day in addition to the meals they always offer</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>be all in a day’s work</strong> if something difficult, unpleasant, or unusual is all in a day’s work for someone, it is a normal part of their job</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>take each day as it comes</strong> (also take it one day at a time) to deal with something as it happens and not worry about the future:</div><ul class=\"examples\"><li><em>Since I had the accident, I’ve learned to take each day as it comes.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>the day of reckoning</strong> a time when you have to deal with the bad results of something you did in the past</div></div>","1787":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌday-to-ˈday</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>day-to-day work/business/life etc</strong> day-to-day jobs or activities are ones that you do every day as a normal part of your life, your job etc:</div><ul class=\"examples\"><li><em>The manager is responsible for the day-to-day running of the hotel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> planning for only one day at a time, usually because you are unable to plan for longer:</div><ul class=\"examples\"><li><em>I see a counsellor and can now handle life on a day-to-day basis.</em></li></ul></div>","1788":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> day‧dream</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪdriːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to think about something pleasant, especially when this makes you forget what you should be doing → dream ► see thesaurus at imagine</div><ul class=\"examples\"><li><strong><em>daydream about</strong>: What are you daydreaming about? There’s work to be done.</em></li></ul></div>","1789":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> day‧light</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪlaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the light produced by the sun during the day → in broad daylight at broad1(7)</div><ul class=\"examples\"><li><strong><em>in daylight</strong>: They’re shy animals and don’t often come out in daylight.</em></li><li><em>The park is open to the public during daylight hours.</em></li><li><em>If possible, it’s better to work in natural daylight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(put) daylight between yourself and somebody</strong> <em>informal</em> if you put daylight between yourself and someone else, you make the distance or difference between you larger:</div><ul class=\"examples\"><li><em>Now the team need to put some daylight between themselves and their rivals for the championship.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>scare/frighten the (living) daylights out of somebody</strong> <em>informal</em> to frighten someone a lot:</div><ul class=\"examples\"><li><em>It scared the living daylights out of me when the flames shot out.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>beat/knock the (living) daylights out of somebody</strong> <em>informal</em> to hit someone a lot and seriously hurt them</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>daylight robbery</strong> <em>British English</em> <em>informal</em> a situation in which something costs you a lot more than is reasonable:</div><ul class=\"examples\"><li><em>£2.50 for a cup of coffee? It’s daylight robbery!</em></li></ul></div>","1790":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> day‧time</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪtaɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the time during the day between the time when it gets light and the time when it gets dark</div><ul class=\"examples\"><li><strong><em>in/during the daytime</strong>: I can’t sleep in the daytime.</em></li><li><em>Can I take your daytime telephone number (=the number of the telephone you use during the day)?</em></li><li><em>daytime television</em></li></ul></div>","1791":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> daz‧zle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdæzəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a very bright light dazzles you, it stops you from seeing properly for a short time:</div><ul class=\"examples\"><li><em>a deer dazzled by the headlights</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone feel strong admiration:</div><ul class=\"examples\"><li><em>As children, we were dazzled by my uncle’s good looks and charm.</em></li></ul></div>","1792":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ded/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[no comparative]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not alive]</strong> no longer alive: ► Do not confuse dead, which is an adjective, with died, which is the past tense and past participle of the verb die: The man was already dead (NOT The man was already died).</div><ul class=\"examples\"><li><em>Her mother had been dead for ten years.</em></li><li><em>Police are trying to contact the family of the dead man.</em></li><li><em>a pile of dead leaves</em></li><li><em>the dead body of a young soldier</em></li><li><em>Two men were shot dead by terrorists.</em></li><li><em>Magnus was found dead in his car.</em></li><li><em>One man is still missing, presumed dead.</em></li><li><em>He suddenly had a heart attack and dropped dead.</em></li><li><em>She was pronounced dead on arrival at the hospital.</em></li><li><em>His fellow climbers had left him for dead on the mountain.</em></li><li><em>We didn’t know if she was dead or alive.</em></li><li><em>When they found him he was more dead than alive.</em></li><li><em>Her parents were long dead.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not working]</strong> <span class=\"gram\">[not before noun]</span> not working because there is no power:</div><ul class=\"examples\"><li><em>I picked up the phone but discovered the line was dead.</em></li><li><em>Suddenly the radio went dead.</em></li><li><em>I think the batteries are dead.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[already used]</strong> already used:</div><ul class=\"examples\"><li><em>a small pile of dead matches</em></li><li><strong><em>dead glass/bottle</strong> (=one that someone has finished drinking from in a bar or restaurant)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[boring]</strong> <span class=\"gram\">[not before noun]</span> a place that is dead is boring because there is nothing interesting or exciting happening there:</div><ul class=\"examples\"><li><em>This place is dead after nine o&#x27;clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[not active/used]</strong> not active or being used:</div><ul class=\"examples\"><li><em>The luxury car market has been dead in recent months.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[arm/leg etc]</strong> a part of your body that is dead has no feeling in it, especially because the blood supply to it has been stopped:</div><ul class=\"examples\"><li><em>When I got up my foot had gone dead where I’d been sitting on it.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[no emotion]</strong> <span class=\"gram\">[not before noun]</span> showing no emotion or sympathy:</div><ul class=\"examples\"><li><em>Jennie’s eyes were cold and dead.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[tired]</strong> <span class=\"gram\">[not before noun]</span> <em>spoken</em> very tired: ► see thesaurus at tired</div><ul class=\"examples\"><li><em>I can’t go out tonight. I’m absolutely dead!</em></li><li><em>She was dead on her feet and didn’t have the energy to argue (=used when someone keeps going even though they are very tired).</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be dead to the world</strong> to be very deeply asleep or unconscious:</div><ul class=\"examples\"><li><em>Better leave Craig – he’s dead to the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[used for emphasis]</strong> <span class=\"gram\">[only before noun]</span> completely or exactly – used to emphasize what you are saying:</div><ul class=\"examples\"><li><em>We all sat waiting in dead silence (=complete silence).</em></li><li><em>The train came to a dead stop (=it stopped completely).</em></li><li><em>The arrow hit the dead centre of the target (=the exact centre).</em></li><li><em>I’ve given the whole thing up as a dead loss (=completely useless or a complete failure).</em></li><li><em>John tells me it’s a dead cert, we can’t lose (=something which will certainly happen, win, succeed etc).</em></li><li><em>He fell to the floor in a dead faint (=completely unconscious).</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>over my dead body</strong> <em>spoken</em> used to say that you are determined not to allow something to happen:</div><ul class=\"examples\"><li><em>You’ll marry him over my dead body!</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>I wouldn’t be seen/caught dead</strong> <em>spoken</em> used to say that you would never wear particular clothes, go to particular places, or do particular things, because you would feel embarrassed</div><ul class=\"examples\"><li><strong><em>dead in/on/with etc</strong>: I wouldn’t be seen dead in a dress like that!</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[in serious trouble]</strong> <em>informal</em> in serious trouble</div><ul class=\"examples\"><li><strong><em>if... I’m dead/you’re dead etc</strong>: If Mum finds out about this, I’m dead.</em></li><li><em>You’re in dead trouble now (=in very serious trouble)!</em></li><li><em>One word of this to Sam and you’re dead meat (=you are in serious trouble and someone is very angry with you)!</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>be dead and buried</strong> an argument, problem, plan etc that is dead and buried is not worth considering again:</div><ul class=\"examples\"><li><em>The old argument about whether the UK should be a member of the EU should now be dead and buried.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>be dead in the water</strong> <em>informal</em> if a plan or idea is dead in the water, it is unlikely to continue successfully</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>drop dead!</strong> <em>spoken</em> used to rudely and angrily tell someone to go away and leave you alone</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>dead language</strong> a dead language, for example Latin or Ancient Greek, is no longer used by ordinary people → living language at living1(1)</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>the dead hand of something</strong> something which stops or slows your progress, especially a strong influence:</div><ul class=\"examples\"><li><em>the dead hand of local government bureaucracy</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>[planet]</strong> a dead planet has no life on it</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>[in sport]</strong> when the ball is dead in some games, it is no longer on the playing area</div></div>","1793":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dead‧line</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdedlaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a date or time by which you have to do or complete something</div><ul class=\"examples\"><li><strong><em>deadline for</strong>: He missed the deadline for applications.</em></li><li><strong><em>deadline of</strong>: It has to be in before the deadline of July 1st.</em></li><li><em>I&#x27;m always working under pressure to meet deadlines (=finish something on time).</em></li><li><strong><em>set/impose a deadline</strong>: They&#x27;ve set a deadline of 12 noon.</em></li><li><strong><em>a tight/strict deadline</strong> (=one that must be met but is difficult)</em></li></ul></div>","1794":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dead‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdedli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[very dangerous]</strong> likely to cause death <em>SYN lethal</em>:</div><ul class=\"examples\"><li><em>a deadly poison</em></li><li><em>a deadly weapon</em></li><li><strong><em>deadly disease/virus</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deadly enemy</strong> someone who will always be your enemy and will try to harm you as much as possible:</div><ul class=\"examples\"><li><em>The two rapidly became deadly enemies.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[complete]</strong> complete or total:</div><ul class=\"examples\"><li><em>We sat in deadly silence.</em></li><li><em>He was in deadly earnest (=completely serious).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[very effective]</strong> causing harm in a very effective way:</div><ul class=\"examples\"><li><em>She hit the target with deadly accuracy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[like death]</strong> <span class=\"gram\">[only before noun]</span> like death in appearance:</div><ul class=\"examples\"><li><em>His face had a deadly paleness.</em></li></ul></div>","1795":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /def/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> physically unable to hear anything or unable to hear well → hearing impaired: → hard of hearing, tone-deaf</div><ul class=\"examples\"><li><em>communication between deaf and hearing people</em></li><li><em>I think Mum’s going a bit deaf.</em></li><li><em>She’s deaf and dumb (=unable to hear or speak) and communicates using sign language.</em></li><li><em>Tom was born profoundly deaf (=having great difficulty hearing).</em></li><li><strong><em>stone deaf/deaf as a post<em>informal</em></strong> (=completely deaf)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the deaf</strong> <span class=\"gram\">[plural]</span> people who are deaf:</div><ul class=\"examples\"><li><em>a school for the deaf</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be deaf to something</strong> <em>literary</em> to be unwilling to hear or listen to something:</div><ul class=\"examples\"><li><em>She was deaf to his pleas.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>turn a deaf ear (to something)</strong> to be unwilling to listen to what someone is saying or asking:</div><ul class=\"examples\"><li><em>The factory owners turned a deaf ear to the demands of the workers.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>fall on deaf ears</strong> if advice or a warning falls on deaf ears, everyone ignores it</div></div>","1796":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /diːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[agreement]</strong> <span class=\"gram\">[countable]</span> an agreement or arrangement, especially in business or politics, that helps both sides involved:</div><ul class=\"examples\"><li><em>They made a deal to sell the land to a property developer.</em></li><li><strong><em>deal with</strong>: rumors that the company had done a deal with Microsoft to market its products</em></li><li><strong><em>deal between</strong>: Twelve US soldiers were released after a deal between the army and the guerillas.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a great/good deal</strong> a large quantity of something <em>SYN a lot</em> GRAMMAR: Comparisona great/good deal of• You use a great deal of or a good deal of with uncountable nouns: · a great deal of money· a good deal of work• A great/good deal of is not used with nouns in the plural. ✗Don’t say: a great deal of peoplea lot of• You can use a lot of with nouns in the plural or uncountable nouns: · a lot of people· a lot of trouble</div><ul class=\"examples\"><li><strong><em>deal of</strong>: It took a great deal of time and effort. / His work has been attracting a great deal of attention.</em></li><li><strong><em>a great/good deal more/less etc</strong> (=a lot more, less etc): He knew a good deal more than I did.</em></li><li><em>She’s married to a man a good deal older than herself.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[treatment]</strong> <span class=\"gram\">[countable usually singular]</span> treatment of a particular type that is given or received</div><ul class=\"examples\"><li><strong><em>a better/fairer etc deal</strong>: a better deal for nurses</em></li><li><em>The prime minister promised farmers a new deal (=a new and fairer system).</em></li><li><strong><em>a rough/raw deal</strong> (=unfair treatment): Women tend to get a raw deal from employers.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>it’s a deal</strong> <em>spoken</em> used to say that you agree to do something:</div><ul class=\"examples\"><li><em>OK, it’s a deal.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>what&#x27;s the deal?</strong> <em>American English</em> <em>spoken</em> used when you want to know about a problem or something strange that is happening:</div><ul class=\"examples\"><li><em>So what&#x27;s the deal? Why is he so mad?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[cards]</strong> <span class=\"gram\">[singular]</span> when you give out cards to players in a card game → dealer:</div><ul class=\"examples\"><li><em>It’s your deal, Alison.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[wood]</strong> <span class=\"gram\">[uncountable]</span> <em>British English</em> fir or pine wood used for making things:</div><ul class=\"examples\"><li><em>a deal table</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>a deal of something</strong> <em>old-fashioned</em> a large amount of something</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /delt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle dealt /delt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> (also deal something ↔ out) to give playing cards to each of the players in a game:</div><ul class=\"examples\"><li><em>Whose turn is it to deal?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> <em>informal</em> to buy and sell illegal drugs:</div><ul class=\"examples\"><li><em>Many users end up dealing to support their habit.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>deal a blow (to somebody/something)</strong> to cause harm to someone or something – used in news reports</div><ul class=\"examples\"><li><strong><em>deal a heavy/severe/serious etc blow</strong>: The sanctions have dealt a severe blow to the local tourism industry.</em></li><li><em>This will deal a blow to consumer confidence.</em></li></ul></div></div>","1797":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> deal‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːlə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who buys and sells a particular product, especially an expensive one</div><ul class=\"examples\"><li><strong><em>car/antique/art etc dealer</em></strong></li><li><strong><em>dealer in</strong>: a dealer in modern art</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who sells illegal drugs</div><div class=\"sense\"><span class=\"snum\">3</span> someone who gives out playing cards in a game</div></div>","1798":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> deal‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːlɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>dealings</strong> <span class=\"gram\">[plural]</span> the business activities or relationships that someone is involved in:</div><ul class=\"examples\"><li><em>his financial dealings</em></li><li><strong><em>dealing with</strong>: She is ruthless in her dealings with competitors.</em></li><li><em>We’ve had dealings with him in the past.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the activity of buying, selling, or doing business with people:</div><ul class=\"examples\"><li><em>penalties for drug dealing</em></li><li><strong><em>plain/honest/fair dealing</strong> (=a particular way of doing business): a reputation for fair dealing</em></li></ul></div>","1799":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">interjection</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪə $ dɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>Oh dear!/Dear oh dear!</strong> (also Dear me!<em>old-fashioned</em>) used to show that you are surprised, upset, or annoyed because something bad has happened:</div><ul class=\"examples\"><li><em>Oh dear, I’ve broken the lamp.</em></li><li><em>‘I think I’m getting a cold.’ ‘Dear oh dear!’</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1</span><span class=\"meta-item\">(comparative dearer, superlative dearest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>Dear</strong> used before someone’s name or title to begin a letter:</div><ul class=\"examples\"><li><em>Dear Sir or Madam,...</em></li><li><em>Dear Mrs. Wilson,...</em></li><li><em>Dear Meg,...</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> expensive <em>OPP cheap</em>: ► see thesaurus at expensive</div><ul class=\"examples\"><li><em>Cars are 59% dearer in Britain than in Europe.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> a dear friend or relative is very important to you and you love them a lot:</div><ul class=\"examples\"><li><em>Mark became a dear friend.</em></li><li><strong><em>be dear to somebody</strong>: His sister was very dear to him.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>hold something dear</strong> to think that something is very important:</div><ul class=\"examples\"><li><em>Household economy was something my mother held very dear.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>dear old...</strong> <em>British English</em> <em>spoken</em> used to describe someone or something in a way that shows your love or liking of them <em>SYN good old</em>:</div><ul class=\"examples\"><li><em>Here we are, back in dear old Manchester!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>for dear life</strong> <em>written</em> if you run, fight, hold on etc for dear life, you do it as fast or as well as you can because you are afraid:</div><ul class=\"examples\"><li><em>She grasped the side of the boat and hung on for dear life.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the dear departed</strong> <em>British English</em> <em>literary</em> a person you love who has died</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used when speaking to someone you love:</div><ul class=\"examples\"><li><em>How did the interview go, dear?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>spoken</em> used when speaking in a friendly way to someone, especially someone who is much younger or much older than you. This use can sometimes sound rather patronizing:</div><ul class=\"examples\"><li><em>Can I help you, dear?</em></li><li><em>Come along, my dear, take a seat.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>spoken</em> someone who is kind and helpful:</div><ul class=\"examples\"><li><em>Be a dear and make me a coffee.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>old dear</strong> <em>British English</em> a fairly rude expression meaning an old woman</div></div></div>","1800":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /deθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> the end of the life of a person or animal</div><ul class=\"examples\"><li><strong><em>death of</strong>: The death of his mother came as a tremendous shock.</em></li><li><em>Cancer is the leading cause of death in women.</em></li><li><em>How Danielle met her death (=died) will probably never be known.</em></li><li><em>His friend was close to death.</em></li><li><em>His family are still mourning John’s tragic death.</em></li><li><em>the anniversary of Lenin’s death</em></li><li><strong><em>bleed/burn/starve etc to death</strong>: a homeless man who froze to death</em></li><li><strong><em>beat/stab/shoot etc somebody to death</strong>: The 76-year-old pensioner was beaten to death.</em></li><li><strong><em>put/sentence/condemn somebody to death</strong> (=kill someone or decide they should be killed as an official punishment): Legend has it that Sarah was put to death for practising witchcraft.</em></li><li><em>Members of the family have received death threats.</em></li><li><em>He remained president until his untimely death (=death at a surprisingly young age).</em></li><li><em>Two of the passengers managed to escape death (=avoid being killed).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> a particular case when someone dies <em>OPP birth</em>:</div><ul class=\"examples\"><li><em>a campaign to reduce the number of traffic deaths</em></li><li><strong><em>death from</strong>: deaths from cancer</em></li><li><em>I heard there’d been a death in the family.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the death of something</strong> the permanent end of something <em>OPP birth</em>:</div><ul class=\"examples\"><li><em>The latest bombing is the death of all our hopes.</em></li><li><em>These regulations could spell the death (=lead to the end) of the American car industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>to death</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to emphasize that a feeling or emotion is very strong</div><ul class=\"examples\"><li><strong><em>be bored/scared/frightened etc to death</strong>: She was scared to death of what might happen next.</em></li><li><em>I’m absolutely sick to death of it (=very angry, bored, or unhappy about something).</em></li><li><strong><em>bore/scare/love etc somebody to death</strong>: He drove at a speed which frightened Leonora to death. / She used to worry me to death.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that an action is continued with a lot of effort and for as long as possible:</div><ul class=\"examples\"><li><em>They just work you to death in that place.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>do something to death</strong> <em>informal</em> to perform or present an idea, joke etc so often that people become tired of it:</div><ul class=\"examples\"><li><em>Most of his material has been done to death by numerous comedians.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>to the death</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> until someone is dead:</div><ul class=\"examples\"><li><em>They will fight to the death rather than give an inch of ground.</em></li><li><em>soldiers locked in a struggle to the death</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> until you achieve something even if it means that you suffer:</div><ul class=\"examples\"><li><em>The leadership election has become a fight to the death.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>Death</strong> a creature that looks like a human skeleton, used in paintings, stories etc to represent the fact that people die</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be at death’s door</strong> to be very ill and likely to die</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>look/feel like death warmed up</strong> <em>British English</em>, look/feel like death warmed over<em>American English</em> <em>informal</em> to look or feel very ill or tired</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>you’ll catch your death (of cold)</strong> <em>spoken</em> <em>old-fashioned</em> used to warn someone that they are likely to become ill because they are wet or cold</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>somebody will be the death of me</strong> <em>spoken</em> <em>old-fashioned</em> used to say that someone is causing you a lot of worry and problems:</div><ul class=\"examples\"><li><em>That boy will be the death of me!</em></li></ul></div>","1801":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧bate</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈbeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> discussion of a particular subject that often continues for a long time and in which people express different opinions:</div><ul class=\"examples\"><li><em>the gun-control debate in the US</em></li><li><em>The new drug has become the subject of heated debate within the medical profession.</em></li><li><strong><em>debate over/about</strong>: There has been widespread public debate over the introduction of genetically modified food. / There was much lively debate about whether women should spend more time in the home.</em></li><li><em>A fierce debate raged over which artist’s work should be chosen for the prize.</em></li><li><strong><em>debate between</strong>: the ongoing debate between environmentalists and the road-building lobby over the future of our countryside</em></li><li><em>Nuclear power has always been a topic that has sparked off considerable debate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a formal discussion of a particular problem, subject etc in which people express different opinions, and sometimes vote on them</div><ul class=\"examples\"><li><strong><em>debate on/over/about</strong>: a debate on legalized gambling</em></li><li><em>a televised debate</em></li><li><strong><em>have/hold/conduct a debate</strong>: It would have been better to hold the debate during the day.</em></li><li><strong><em>be under debate</strong>: What topics are under debate in Congress this week?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be open to debate</strong> (also be a matter for debate) if an idea is open to debate, no one has proved yet whether it is true or false <em>SYN debatable</em>:</div><ul class=\"examples\"><li><em>Whether that would have made any difference is open to debate.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to discuss a subject formally when you are trying to make a decision or find a solution: ► see thesaurus at talk</div><ul class=\"examples\"><li><em>The issue will be debated on Tuesday.</em></li><li><strong><em>debate whether/what/how etc</strong>: Meanwhile, philosophers debate whether it’s right to clone an individual.</em></li><li><strong><em>debate (something) with somebody</strong>: an invitation to debate with William on the future of democracy</em></li><li><em>His conclusions are hotly debated (=argued about strongly).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to consider something carefully before making a decision</div><ul class=\"examples\"><li><strong><em>debate with yourself</strong>: I debated with myself whether I should tell anyone.</em></li><li><strong><em>debate who/what/how etc</strong>: I’m still debating what to do.</em></li><li><strong><em>debate doing something</strong>: For a moment Mary debated telling Rick the truth.</em></li></ul></div></div>","1802":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈdebit card</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a plastic card with your signature on that you can use to pay for things. The money is taken directly from your bank account</div></div>","1803":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> deb‧ris</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdebriː, ˈdeɪ- $ dəˈbriː, deɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the pieces of something that are left after it has been destroyed in an accident, explosion etc:</div><ul class=\"examples\"><li><em>She was hit by flying debris from the blast.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> pieces of waste material, paper etc</div><ul class=\"examples\"><li><strong><em>plant/garden/industrial etc debris</strong>: Clean the ventilation ducts to remove dust and insect debris.</em></li></ul></div>","1804":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /det/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sum of money that a person or organization owes</div><ul class=\"examples\"><li><strong><em>debt of</strong>: She had debts of over £100,000.</em></li><li><em>He had enough money to pay off his outstanding debts.</em></li><li><em>students who run up huge debts</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when you owe money to someone <em>OPP credit</em></div><ul class=\"examples\"><li><strong><em>in debt (to somebody)</strong>: Nearly half the students said they were in debt. / The band will be in debt to the record company for years.</em></li><li><strong><em>£200/$1,000 etc in debt</strong>: A rash business decision left him $600 in debt.</em></li><li><strong><em>get/run/fall etc into debt</strong>: The club sank deeper into debt.</em></li><li><strong><em>be heavily/deeply in debt</strong> (=owe a lot of money)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> the degree to which you have learned from or been influenced by someone or something else</div><ul class=\"examples\"><li><strong><em>debt to</strong>: Braque acknowledged his debt to Impressionist painting.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>debt of gratitude/thanks</strong> the fact of being grateful to someone who has helped you:</div><ul class=\"examples\"><li><em>I owe a debt of gratitude to my tutors.</em></li></ul></div>","1805":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧but</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeɪbjuː, ˈdeb- $ deɪˈbjuː, dɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the first public appearance of an entertainer, sports player etc or of something new and important</div><ul class=\"examples\"><li><strong><em>somebody’s debut</strong>: He made his Major League debut as shortstop.</em></li><li><strong><em>film/acting/directorial etc debut</strong>: His Broadway debut was ‘The Scarlet Pimpernel’.</em></li><li><strong><em>debut album/CD/single etc</strong>: Their debut album was recorded in 1991.</em></li><li><strong><em>debut match/performance etc</strong>: He scored in his debut match for the club.</em></li></ul></div>","1806":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dec‧ade</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdekeɪd, deˈkeɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a period of 10 years</div></div>","1807":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cay</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈkeɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to be slowly destroyed by a natural chemical process, or to make something do this: RegisterIn everyday English, people usually say rot rather than decay when talking about food:· There was a smell of rotting vegetables.</div><ul class=\"examples\"><li><em>Her body was already starting to decay.</em></li><li><em>Most archaeological finds are broken, damaged, or decayed.</em></li><li><em>decaying organic matter</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> if buildings, structures, or areas decay, their condition gradually becomes worse:</div><ul class=\"examples\"><li><em>Hundreds of historic buildings are being allowed to decay.</em></li><li><em>Britain’s decaying inner cities</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if traditional beliefs, standards etc decay, people do not believe in them or support them anymore <em>SYN decline</em>:</div><ul class=\"examples\"><li><em>In Orthodox Europe, mass religion seems to have decayed less.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the natural chemical change that causes the slow destruction of something:</div><ul class=\"examples\"><li><em>old cars in various stages of decay</em></li><li><em>tooth decay</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the gradual destruction of buildings, structures etc because they have not been cared for:</div><ul class=\"examples\"><li><em>poverty and urban decay</em></li><li><strong><em>fall into (a state of) decay</strong>: During the war, the area fell into decay.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the gradual destruction of ideas, beliefs, social or political systems etc:</div><ul class=\"examples\"><li><em>moral decay</em></li></ul></div></div>","1808":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ceased</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsiːst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>the deceased</strong> someone who has died, especially recently:</div><ul class=\"examples\"><li><em>The deceased left a large sum of money to his children.</em></li></ul></div>","1809":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ceive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsiːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone believe something that is not true → deception: RegisterIn everyday English, people usually say trick rather than deceive:· She thought they were trying to trick her.</div><ul class=\"examples\"><li><em>He had been deceived by a young man claiming to be the son of a millionaire.</em></li><li><strong><em>deceive somebody into doing something</strong>: He tried to deceive the public into thinking the war could still be won.</em></li><li><strong><em>deceive somebody about something</strong>: I wouldn’t deceive you about anything as important as this.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deceive yourself</strong> to refuse to believe that something is true because the truth is unpleasant:</div><ul class=\"examples\"><li><em>I thought she loved me, but I was deceiving myself.</em></li><li><strong><em>deceive yourself that</strong>: He didn’t deceive himself that he and Ruth could remain friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to give someone a wrong belief or opinion about something:</div><ul class=\"examples\"><li><em>Don’t be deceived by the new cover – this is a rehash of old hits.</em></li></ul></div>","1810":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> De‧cem‧ber</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsembə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the 12th month of the year, between November and January</div><ul class=\"examples\"><li><strong><em>next/last December</strong>: Last December they visited Prague.</em></li><li><strong><em>in December</strong>: We got married in December.</em></li><li><strong><em>on December 6th</strong>: Jake’s birthday is on December 6th.</em></li><li><strong><em>on 6th December<em>British English</em></strong>: The event was to take place on 6th December.</em></li><li><strong><em>December 6<em>American English</em></strong>: Her letter arrived December 6.</em></li></ul></div>","1811":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːsənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually before noun]</span> of a good enough standard or quality: ► see thesaurus at satisfactory</div><ul class=\"examples\"><li><em>a decent salary</em></li><li><em>Don’t you have a decent jacket?</em></li><li><em>a house with a decent-sized yard</em></li><li><em>Their in-flight magazine is halfway decent (=quite good).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> following moral standards that are acceptable to society → decency</div><ul class=\"examples\"><li><strong><em>decent citizens/people/folk etc</strong>: The majority of residents here are decent citizens.</em></li><li><em>a decent burial</em></li><li><em>Paul visited the local bars more frequently than was decent for a senior lecturer.</em></li><li><em>The chairman did the decent thing (=did what people thought he ought to) and resigned.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[usually before noun]</span> treating people in a fair and kind way:</div><ul class=\"examples\"><li><em>I decided her father was a decent guy after all.</em></li><li><em>It was decent of you to show up today.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> wearing enough clothes so that you do not show too much of your body – used humorously:</div><ul class=\"examples\"><li><em>Are you decent? Can I come in?</em></li></ul></div>","1812":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cep‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsepʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the act of deliberately making someone believe something that is not true → deceive:</div><ul class=\"examples\"><li><em>She didn’t have the courage to admit to her deception.</em></li><li><em>He was convicted of obtaining money by deception.</em></li></ul></div>","1813":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cide</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to make a choice or judgment about something, especially after considering all the possibilities or arguments → decision: GRAMMARIn more formal English, you can say it is decided that something should be done: · It was decided that he should resign.</div><ul class=\"examples\"><li><em>Has anything been decided yet?</em></li><li><strong><em>decide to do something</strong>: Tina’s decided to go to Rome for her holidays.</em></li><li><strong><em>decide (that)</strong>: It was decided that four hospitals should close.</em></li><li><strong><em>decide who/what/whether etc</strong>: I can’t decide whether I like him or not. / People have a right to decide how to spend their own money.</em></li><li><strong><em>decide between something</strong>: A meeting was called to decide between the three candidates.</em></li><li><strong><em>decide for yourself</strong> (=make your own decision): You must decide for yourself.</em></li><li><em>The trainees decide among themselves what programs to take.</em></li><li><strong><em>decide against/in favour of (doing) something</strong>: He eventually decided against telling her. / After a long discussion, they decided in favour of (=chose) the older applicant.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to influence a situation or event so that a particular result is produced:</div><ul class=\"examples\"><li><em>It was the penalty kick that decided the match.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to be the reason for someone making a particular choice:</div><ul class=\"examples\"><li><em>Taxes could be the deciding factor for millions of floating voters.</em></li><li><strong><em>decide somebody to do something</strong>: The look he gave her decided her not to ask.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> <em>law</em> to make an official or legal judgment:</div><ul class=\"examples\"><li><em>The Commission will have the power to decide disputes.</em></li><li><strong><em>decide in favour of/against somebody</strong>: If the Parole Board decides in his favour, the prisoner will be released.</em></li></ul></div>","1814":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cid‧ed‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsaɪdɪdli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[+adjective/adverb]</span> definitely or in a way that is easily noticed:</div><ul class=\"examples\"><li><em>Cole’s style is decidedly more formal than the previous manager’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> <em>written</em> in a way that shows that you are very sure about a decision:</div><ul class=\"examples\"><li><em>‘I’m not going to do it,’ said Margaret decidedly.</em></li></ul></div>","1815":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ci‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsɪʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a choice or judgment that you make after a period of discussion or thought:</div><ul class=\"examples\"><li><em>Do you ever wonder if you made the right decision?</em></li><li><strong><em>decision to do something</strong>: She refused to discuss her decision to quit the group.</em></li><li><strong><em>decision about/on</strong>: We finally came to a firm decision on the matter.</em></li><li><strong><em>decision as to which/whether/who etc</strong>: Viewers make the final decision as to who should be eliminated from the competition.</em></li><li><em>The judges’ decision is final (=it will not be changed).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the quality someone has that makes them able to make choices or judgments quickly and confidently <em>OPP indecision</em>:</div><ul class=\"examples\"><li><em>the ability to act with speed and decision</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the act of deciding something:</div><ul class=\"examples\"><li><em>The Court has the ultimate power of decision.</em></li></ul></div>","1816":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ci‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsaɪsɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an action, event etc that is decisive has a big effect on the way that something develops</div><ul class=\"examples\"><li><strong><em>decisive factor/effect/influence etc</strong>: Women can play a decisive role in the debate over cloning.</em></li><li><strong><em>decisive action/steps</strong>: We will take decisive steps towards political union with Europe.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is decisive is good at making decisions quickly and with confidence <em>OPP indecisive</em>:</div><ul class=\"examples\"><li><em>a decisive leader</em></li><li><em>a talent for quick decisive action</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> definite and clear in a way that leaves no doubt <em>OPP indecisive</em></div><ul class=\"examples\"><li><strong><em>decisive victory/result/defeat etc</em></strong></li><li><em>The answer was a decisive no.</em></li></ul></div>","1817":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dek/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[on a ship]</strong> ► see thesaurus at floor</div><div class=\"subsense\"><span class=\"subnum\">a)</span> the outside top level of a ship that you can walk or sit on:</div><ul class=\"examples\"><li><em>Let’s go up on deck.</em></li><li><strong><em>above/below deck</strong>: Peter stayed below deck.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> one of the different levels on a ship</div><ul class=\"examples\"><li><strong><em>main/passenger/car etc deck</strong>: a staircase leading to the passenger deck</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[on a bus, plane etc]</strong> one of the levels on a bus, plane etc → double-decker(1), single-decker</div><ul class=\"examples\"><li><strong><em>lower/upper etc deck</strong>: I managed to find a seat on the upper deck. / Eddie returned to the flight deck (=the part of an aircraft where the pilot sits).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[at the back of a house]</strong> <em>American English</em> a wooden floor built out from the back of a house, where you can sit and relax outdoors → decking:</div><ul class=\"examples\"><li><em>deck furniture</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[music]</strong> a piece of equipment used for playing music tapes, records etc</div><ul class=\"examples\"><li><strong><em>cassette/tape/record deck</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cards]</strong> a set of playing cards SYN pack<em>British English</em>:</div><ul class=\"examples\"><li><em>Irene shuffled the deck.</em></li><li><em>a deck of cards</em></li></ul></div>","1818":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dec‧la‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdekləˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an important official statement about a particular situation or plan, or the act of making this statement:</div><ul class=\"examples\"><li><em>a ceasefire declaration</em></li><li><em>Under Islamic law it was possible to divorce by simple declaration.</em></li><li><strong><em>declaration of</strong>: the declaration of war</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an official or serious statement of what someone believes</div><ul class=\"examples\"><li><strong><em>declaration of</strong>: the United Nations Declaration of Human Rights</em></li><li><em>declarations of undying love</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a statement in which you officially give information about yourself:</div><ul class=\"examples\"><li><em>a declaration of taxable earnings</em></li></ul></div>","1819":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧clare</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈkleə $ -ˈkler/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[state officially]</strong> <span class=\"gram\">[transitive]</span> to state officially and publicly that a particular situation exists or that something is true: ► see thesaurus at say</div><ul class=\"examples\"><li><em>A state of emergency has been declared.</em></li><li><strong><em>declare that</strong>: The court declared that Brown’s case should be reviewed.</em></li><li><strong><em>declare somebody/something (to be) somebody/something</strong>: Several countries wanted Antarctica to be declared a ‘world park’. / The city was declared to be in a state of siege. / I declare you man and wife.</em></li><li><strong><em>declare something illegal/invalid etc</strong>: The war was declared illegal by the International Court of Justice.</em></li><li><em>Mr Steel has been declared bankrupt (=it has been officially stated that he cannot pay his debts).</em></li><li><em>We celebrate September 16, the day when Mexico declared independence from Spain (=officially stated that it was no longer ruled by Spain).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[state what you think]</strong> <span class=\"gram\">[transitive]</span> to say publicly what you think or feel:</div><ul class=\"examples\"><li><em>‘It’s not fair,’ Jane declared.</em></li><li><em>He declared his intention to stand for president.</em></li><li><strong><em>declare that</strong>: Carol held a press conference and declared that she was innocent.</em></li><li><strong><em>declare yourself (to be) something</strong>: Edward declared himself angry and frustrated.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>declare war (on somebody/something)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to state officially that you are at war with another country</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> to say that something is wrong and that you will do everything you can to stop it:</div><ul class=\"examples\"><li><em>Angry residents have declared war on the owners of the factory.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[money/property etc]</strong> <span class=\"gram\">[transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to state on an official government form how much money you have earned, what property you own etc:</div><ul class=\"examples\"><li><em>All tips are counted as part of your earnings and must be declared.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to tell a customs official that you are carrying goods on which you should pay tax when you enter a country</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>declare an interest</strong> to tell people that you are connected with something that is being discussed:</div><ul class=\"examples\"><li><em>I should, at this point, declare an interest: I own shares in the company.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[cricket]</strong> <span class=\"gram\">[intransitive]</span> to choose to end your team’s turn before all your players have batted</div></div>","1820":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cline</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈklaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a decrease in the quality, quantity, or importance of something</div><ul class=\"examples\"><li><strong><em>decline in</strong>: There has been a decline in the size of families.</em></li><li><strong><em>decline of</strong>: the decline of manufacturing</em></li><li><strong><em>rapid/sharp/steep/dramatic decline</strong>: a rapid decline in unemployment</em></li><li><strong><em>steady/gradual/long-term decline</strong>: The island’s population initially numbered 180, but there was a gradual decline until only 40 people were left.</em></li><li><em>the economic decline faced by many cities</em></li><li><strong><em>in decline/on the decline</strong> (=falling): the widely held belief that educational standards are in decline</em></li><li><strong><em>fall/go etc into decline</strong> (=become less important, successful etc): The port fell into decline in the 1950s.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[decrease]</strong> <span class=\"gram\">[intransitive]</span> to decrease in quantity or importance: ► see thesaurus at decrease</div><ul class=\"examples\"><li><em>Spending on information technology has declined.</em></li><li><em>Car sales have declined by a quarter.</em></li><li><em>After the war, the city declined in importance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[say no]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to say no politely when someone invites you somewhere, offers you something, or wants you to do something: ► see thesaurus at refuse</div><ul class=\"examples\"><li><em>Offered the position of chairman, Smith declined, preferring to keep his current job.</em></li><li><em>Mary declined a hot drink and went to her room.</em></li><li><strong><em>decline an offer/invitation etc</strong>: Mary declined Jay’s invitation to dinner.</em></li><li><strong><em>decline to do something</strong>: The court declined to review her case. / The minister declined to comment (=refused to speak to people who report the news) about the progress of the peace talks.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[become worse]</strong> <span class=\"gram\">[intransitive]</span> to become gradually worse in quality <em>SYN deteriorate</em>:</div><ul class=\"examples\"><li><em>Her health has been declining progressively for several months.</em></li><li><em>Qualified staff are leaving and standards are declining.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>somebody’s declining years</strong> <em>formal</em> the last years of someone’s life</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[grammar]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> if a noun, pronoun, or adjective declines, its form changes according to whether it is the subject, object etc of a sentence</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> if you decline a noun, pronoun, or adjective, you show the various forms that it can take</div></div></div>","1821":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dec‧o‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdekəreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>British English</em> to paint the inside of a room, put special paper on the walls etc:</div><ul class=\"examples\"><li><em>The bathroom is decorated in green and yellow.</em></li><li><em>We plan to spend the weekend decorating.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make something look more attractive by putting something pretty on it:</div><ul class=\"examples\"><li><em>Children’s pictures decorated the walls of the classroom.</em></li><li><strong><em>decorate something with something</strong>: an old-fashioned dress decorated with ribbons and lace</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to give someone a medal as an official sign of honour</div><ul class=\"examples\"><li><strong><em>decorate somebody for something</strong>: soldiers decorated for bravery</em></li></ul></div>","1822":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dec‧o‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdekəˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually plural]</span> something pretty that you put in a place or on top of something to make it look attractive:</div><ul class=\"examples\"><li><em>Christmas decorations</em></li><li><em>cake decorations</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the style in which something is decorated:</div><ul class=\"examples\"><li><em>He is an expert on Islamic decoration.</em></li><li><strong><em>for decoration</strong>: a box with paper flowers glued to it for decoration</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> when you paint or put special paper on the inside walls, ceiling etc of a house or building</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> something such as a medal that is given to someone as an official sign of honour</div></div>","1823":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dec‧o‧ra‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdekərətɪv $ ˈdekərə-, ˈdekəreɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">pretty or attractive, but not always necessary or useful:</div><ul class=\"examples\"><li><em>a decorative panel above the door</em></li></ul></div>","1824":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧crease</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈkriːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to become less or go down to a lower level, or to make something do this → reduce <em>OPP increase</em>:</div><ul class=\"examples\"><li><em>The number of people who have the disease has decreased significantly in recent years.</em></li><li><em>They want to decrease their reliance on oil.</em></li><li><strong><em>decrease by</strong>: Average house prices decreased by 13% last year.</em></li><li><strong><em>decrease to</strong>: By 1881, the population of Ireland had decreased to 5.2 million.</em></li><li><strong><em>decrease from</strong>: The North’s share of the world’s energy consumption is expected to decrease from 70% to 60%.</em></li><li><strong><em>decrease in</strong>: Attacks of asthma decrease in frequency through early adult life.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧crease</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːkriːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the process of becoming less, or the amount by which something becomes less <em>OPP increase</em> <em>SYN reduction</em></div><ul class=\"examples\"><li><strong><em>a decrease in something</strong>: Teachers reported decreases in drug use and verbal abuse of teachers.</em></li><li><strong><em>a decrease of 50/5% etc</strong>: There has been a decrease of 1 degree in average temperature.</em></li></ul></div></div>","1825":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧cree</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈkriː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an official order or decision, especially one made by the ruler of a country:</div><ul class=\"examples\"><li><em>The Emperor issued the decree repealing martial law.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a judgment in a court of law</div></div>","1826":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ded‧i‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdedɪkeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to give all your attention and effort to one particular thing</div><ul class=\"examples\"><li><strong><em>dedicate yourself/your life to something</strong>: The actress now dedicates herself to children’s charity work.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to say at the beginning of a book or film, or before a piece of music, that it has been written, made, or performed for someone that you love or respect</div><ul class=\"examples\"><li><strong><em>dedicate something to somebody</strong>: The book was dedicated to her husband.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to state in an official ceremony that a building will be given someone’s name in order to show respect for them</div><div class=\"sense\"><span class=\"snum\">4</span> to use a place, time, money etc only for a particular purpose</div><ul class=\"examples\"><li><strong><em>dedicate something to/for something</strong>: The company dedicated $50,000 for the study.</em></li></ul></div>","1827":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ded‧i‧cat‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdedɪkeɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is dedicated works very hard at what they do because they care a lot about it:</div><ul class=\"examples\"><li><em>a dedicated and thoughtful teacher</em></li><li><em>She is a dedicated socialist.</em></li><li><strong><em>dedicated to</strong>: The Woodland Trust is dedicated to preserving our native woodland.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> made for or used for only one particular purpose:</div><ul class=\"examples\"><li><em>a dedicated graphics processor</em></li></ul></div>","1828":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ded‧i‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdedɪˈkeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> hard work or effort that someone puts into a particular activity because they care about it a lot:</div><ul class=\"examples\"><li><em>To reach a high level of skill requires talent, dedication, and a lot of hard work.</em></li><li><strong><em>dedication to</strong>: I admire his dedication to the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an act of dedicating something to someone, or a ceremony where this is done</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the words used at the beginning of a book, film, or piece of music, thanking someone or saying that book etc has been written to show respect for them</div></div>","1829":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧duce</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈdjuːs $ dɪˈduːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to use the knowledge and information you have in order to understand something or form an opinion about it</div><ul class=\"examples\"><li><strong><em>deduce that</strong>: From her son’s age, I deduced that her husband must be at least 60.</em></li><li><strong><em>deduce from</strong>: What did Darwin deduce from the presence of these species?</em></li></ul></div>","1830":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧duct</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈdʌkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to take away an amount or part from a total <em>SYN subtract</em></div><ul class=\"examples\"><li><strong><em>deduct something from something</strong>: The payments will be deducted from your salary.</em></li></ul></div>","1831":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧duc‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈdʌkʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the process of using the knowledge or information you have in order to understand something or form an opinion, or the opinion that you form:</div><ul class=\"examples\"><li><em>Children will soon make deductions about the meaning of a word.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the process of taking away an amount from a total, or the amount that is taken away:</div><ul class=\"examples\"><li><em>After deductions for tax etc, your salary is about £700 a month.</em></li></ul></div>","1832":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /diːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> something someone does, especially something that is very good or very bad:</div><ul class=\"examples\"><li><em>After the morning’s good deeds he deserved a rest.</em></li><li><em>She tried to strangle her baby and her lover helped her finish the evil deed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>law</em> an official paper that is a record of an agreement, especially an agreement concerning who owns property:</div><ul class=\"examples\"><li><em>a mortgage deed</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in deed</strong> in what you do:</div><ul class=\"examples\"><li><em>Everyone sins at some time, in thought if not in deed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>your good deed for the day</strong> something kind or helpful that you do – used humorously</div></div>","1833":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /diːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to think of something in a particular way or as having a particular quality <em>SYN consider</em></div><ul class=\"examples\"><li><strong><em>deem that</strong>: They deemed that he was no longer capable of managing the business.</em></li><li><strong><em>deem something necessary/appropriate etc</strong>: They were told to take whatever action they deemed necessary.</em></li><li><strong><em>be deemed to be something</strong>: They were deemed to be illegal immigrants.</em></li><li><strong><em>be deemed to do something</strong>: UK plans were deemed to infringe EU law.</em></li></ul></div>","1834":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /diːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(comparative deeper, superlative deepest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[going far down]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> going far down from the top or from the surface <em>OPP shallow</em>:</div><ul class=\"examples\"><li><em>The castle is on an island surrounded by a deep lake.</em></li><li><em>The swimming pool has a deep end and a shallow end for kids.</em></li><li><em>We’ll take the boat out into deep water where we can dive.</em></li><li><em>a deep narrow valley</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> you use deep to say what distance something goes down from the top or surface → knee-deep</div><ul class=\"examples\"><li><strong><em>2 metres/6 feet etc deep</strong>: Dig a hole around 12 inches deep.</em></li><li><strong><em>ankle-deep/waist-deep etc</strong>: In places, the snow was waist-deep (=deep enough to reach a person’s waist).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[going far in]</strong> going far in from the outside or from the front edge of something:</div><ul class=\"examples\"><li><em>a deep wound</em></li><li><em>She was sitting in a deep leather chair.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[serious]</strong> serious or severe:</div><ul class=\"examples\"><li><em>Despite the peace process, there are deep divisions in the community.</em></li><li><em>The country is in a deep recession.</em></li><li><em>Evan will be in deep trouble if he is caught.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[breath]</strong> a deep breath or sigh is one in which you breathe a lot of air in or out:</div><ul class=\"examples\"><li><em>She stopped and took a deep breath.</em></li><li><em>Tom gave a deep sigh of relief.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[feeling/belief]</strong> a deep feeling, belief etc is very strong and sincere <em>SYN profound</em>:</div><ul class=\"examples\"><li><em>May I express my deepest sympathy.</em></li><li><em>The letters show her deep affection for him.</em></li><li><em>He has a deep understanding of the environment.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sound]</strong> a deep sound is very low:</div><ul class=\"examples\"><li><em>Her laugh was deep and loud.</em></li><li><em>I love that deep bass line.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[colour]</strong> a deep colour is dark and strong <em>OPP light</em> <em>, pale</em>: ► see thesaurus at colour</div><ul class=\"examples\"><li><em>She gazed at him with wide deep blue eyes.</em></li><li><em>The berries are a deep red colour.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[difficult to understand]</strong> important but complicated or difficult to understand:</div><ul class=\"examples\"><li><em>These problems are too deep for me.</em></li><li><em>There is a deep issue of principle involved.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[sleep]</strong> if someone is in a deep sleep, it is difficult to wake them:</div><ul class=\"examples\"><li><em>He lay down and fell into a deep sleep.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>deep in thought/conversation etc</strong> thinking so hard or paying attention to something so much that you do not notice anything else that is happening around you</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>deep in debt</strong> owing a lot of money</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>a deep impression</strong> a strong effect or influence that remains for a long time:</div><ul class=\"examples\"><li><em>What he said made a deep impression on me.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[person]</strong> a deep person is serious and intelligent, but is hard to know well:</div><ul class=\"examples\"><li><em>Henry has always been a deep one. He keeps his views to himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>be in deep shit</strong> <em>spoken</em> <em>not polite</em> to be in a bad situation because of something you have done</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>be in deep water</strong> to be in trouble or in a difficult or serious situation:</div><ul class=\"examples\"><li><em>The company is in deep water over their refusal to reduce prices.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[ball games]</strong> a deep ball is hit, thrown, or kicked to a far part of the sports field</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>jump/be thrown in at the deep end</strong> to choose to do or be made to do a very difficult job without having prepared for it:</div><ul class=\"examples\"><li><em>She decided to jump in at the deep end, buy a farm, and teach herself.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>go off at the deep end</strong> <em>informal</em> to become angry suddenly and violently, usually when there is not a good reason</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adverb/preposition]</span> a long way into or below the surface of something:</div><ul class=\"examples\"><li><em>Some bones were hidden deep beneath the ground.</em></li><li><em>The tunnel led deep under the mountains.</em></li><li><em>We were deep in a tropical rainforest (=far from the edge of the forest).</em></li><li><em>Tom stared deep into her eyes.</em></li><li><em>They talked deep into the night (=very late).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deep down</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if you know or feel something deep down, you secretly know or feel it even though you do not admit it:</div><ul class=\"examples\"><li><em>He knew, deep down, that he would have to apologise.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone is good, evil etc deep down, that is what they are really like even though they usually hide it:</div><ul class=\"examples\"><li><em>Deep down, she is a caring person.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>two/three etc deep</strong> if things or people are two deep, three deep etc, there are two, three etc rows or layers of things or people:</div><ul class=\"examples\"><li><em>People were standing four deep at the bar.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>run/go deep</strong> if a feeling such as hatred or anger runs deep in someone, they feel it very strongly, especially because of something that has happened in the past:</div><ul class=\"examples\"><li><em>The prejudice runs deep and we need to understand the fears behind it.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be in (too) deep</strong> <em>informal</em> to be very involved in a situation, especially so that it causes you problems</div></div></div>","1835":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> deep‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːpən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[get worse]</strong> <span class=\"gram\">[intransitive]</span> if a serious situation deepens, it gets worse – used especially in news reports:</div><ul class=\"examples\"><li><em>The recession continues to deepen.</em></li><li><em>a deepening international crisis</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[become stronger]</strong> <span class=\"gram\">[intransitive, transitive]</span> to become stronger or greater, or to make something stronger or greater:</div><ul class=\"examples\"><li><em>Jeanne liked Simon as a friend but she did not want the relationship to deepen.</em></li><li><em>The idea only deepened his gloom.</em></li><li><em>The mystery deepened (=became even more mysterious).</em></li><li><em>Students explore new ideas as they deepen their understanding (=understand more) of the subject.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[expression on somebody’s face]</strong> <span class=\"gram\">[intransitive]</span> <em>literary</em> if someone’s smile or frown deepens, they smile even more or frown even more:</div><ul class=\"examples\"><li><em>Her worried frown deepened.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[water]</strong> <span class=\"gram\">[intransitive, transitive]</span> if water deepens, or if someone deepens it, it becomes deeper:</div><ul class=\"examples\"><li><em>The river deepens beyond the town.</em></li><li><em>The harbour was deepened to take bigger boats.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[colour]</strong> <span class=\"gram\">[intransitive]</span> <em>literary</em> if light or a colour deepens, it becomes darker:</div><ul class=\"examples\"><li><em>The twilight deepened.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sound]</strong> <span class=\"gram\">[intransitive]</span> if a sound deepens, it becomes lower:</div><ul class=\"examples\"><li><em>His voice deepened as he relaxed.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[breath]</strong> <span class=\"gram\">[intransitive]</span> if your breathing deepens, you take more air into your lungs</div></div>","1836":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> deep‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːpli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to emphasize that a belief, feeling, opinion etc is very strong, important, or sincere:</div><ul class=\"examples\"><li><em>Her lies hurt my father deeply.</em></li><li><em>She is deeply upset.</em></li><li><em>He loves her deeply.</em></li><li><em>Teachers are deeply divided on this issue.</em></li><li><em>deeply held religious beliefs</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a serious, careful way:</div><ul class=\"examples\"><li><em>Most doctors think deeply about what their patients want.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a long way into something</div><ul class=\"examples\"><li><strong><em>deeply into</strong>: John kept sinking more deeply into the mud.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>breathe deeply</strong> to take a large breath of air into your lungs</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>sleep deeply</strong> to be in a deep sleep, from which it is hard to wake up</div></div>","1837":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪə $ dɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural deer)</span></div><div class=\"entry-body\"><div class=\"sense\">a large wild animal that can run very fast, eats grass, and has horns</div></div>","1838":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fault</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfɔːlt $ -ˈfɒːlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>by default</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if you win a game, competition etc by default, you win it because your opponent did not play or because there were no other competitors</div><div class=\"subsense\"><span class=\"subnum\">b)</span> if something happens by default, it happens because you did not do anything to change it</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> failure to pay money that you owe at the right time</div><ul class=\"examples\"><li><strong><em>in default</strong>: The company is in default on its loan agreement.</em></li><li><strong><em>default in</strong>: The bank can seize the asset in the event of a default in payment.</em></li><li><em>the risk of default by borrowers</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>law</em> failure to do something that you are supposed to do according to the law or because it is your duty</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable usually singular]</span> <em>technical</em> the way in which things are arranged on a computer screen unless you decide to change them:</div><ul class=\"examples\"><li><em>You can change the default settings to suit your needs.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[singular]</span> the usual and expected way in which something is done, unless you decide to do something different:</div><ul class=\"examples\"><li><em>This way of working seems to be the default these days.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in default of something</strong> <em>formal</em> because of the lack or absence of something:</div><ul class=\"examples\"><li><em>In default of any other instructions, they decided to use the same system as before.</em></li></ul></div>","1839":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧feat</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfiːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> failure to win or succeed</div><ul class=\"examples\"><li><strong><em>defeat in</strong>: The socialist party suffered a crushing defeat in the elections.</em></li><li><em>She was a woman who hated to admit defeat.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> victory over someone or something</div><ul class=\"examples\"><li><strong><em>defeat of</strong>: The defeat of the army was followed by the establishment of constitutional government.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to win a victory over someone in a war, competition, game etc <em>SYN beat</em>: ► see thesaurus at beat RegisterIn everyday English, people usually say beat rather than defeat when talking about sport, games, or elections:· We were beaten by 3 goals to 2.</div><ul class=\"examples\"><li><em>They hoped to defeat the enemy at sea.</em></li><li><strong><em>defeat somebody by something</strong>: We were defeated by 3 goals to 2.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something defeats you, you cannot understand it and therefore cannot answer or deal with it <em>SYN beat</em>:</div><ul class=\"examples\"><li><em>It was the last question on the paper that defeated me.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to make something fail</div><ul class=\"examples\"><li><strong><em>defeat the object/purpose (of the exercise)</strong>: Don’t let your arms relax as that would defeat the object of the exercise.</em></li></ul></div></div>","1840":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fect</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfekt, ˈdiːfekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a fault or a lack of something that means that something or someone is not perfect: ► see thesaurus at fault</div><ul class=\"examples\"><li><em>All the cars are tested for defects before they leave the factory.</em></li><li><em>a genetic defect</em></li></ul></div>","1841":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fec‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfektɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not made properly, or not working properly <em>SYN faulty</em>:</div><ul class=\"examples\"><li><em>The disease is caused by a defective gene.</em></li><li><em>defective products</em></li></ul></div>","1842":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fence</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfens/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[protection]</strong> → self-defence</div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> the act of protecting something or someone from attack</div><ul class=\"examples\"><li><strong><em>defence of</strong>: In Britain, the defence of the country has historically been left to the navy.</em></li><li><em>a firm commitment to the defense of human rights</em></li><li><em>The first line of defence is a smoke detector.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> something that can be used to protect something or someone from attack:</div><ul class=\"examples\"><li><em>The area’s flood defences need repair.</em></li><li><strong><em>defence against</strong>: The immune system is the body’s defence against infection.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[military]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> all the systems, people, materials etc that a country uses to protect itself from attack:</div><ul class=\"examples\"><li><em>calls for a national debate on defence</em></li><li><em>the Defense Department</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>defences</strong> <em>British English</em>, defenses<em>American English</em> <span class=\"gram\">[plural]</span> all the armies, weapons, structures etc that are available to defend a place:</div><ul class=\"examples\"><li><em>The invading army easily overcame the town’s defences.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[against criticism]</strong> <span class=\"gram\">[countable, uncountable]</span> something that you say or do in order to support someone or something that is being criticized</div><ul class=\"examples\"><li><strong><em>in somebody’s/something’s defence</strong>: Jean wrote a letter to the paper in Angela’s defense.</em></li><li><strong><em>defence of</strong>: a philosophical defence of nationalism</em></li><li><strong><em>come/leap to somebody’s defence</strong>: Evelyn Waugh came to Wilson’s defence and acknowledged the brilliance of the book’s themes.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in a law court]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable]</span> the things that are said in a court of law to prove that someone is not guilty of a crime:</div><ul class=\"examples\"><li><em>Major has a good defence and believes he will win the case.</em></li><li><em>a defence lawyer</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>the defence</strong> all the lawyers who try to prove in a court of law that someone is not guilty of a crime: → prosecution(2)</div><ul class=\"examples\"><li><em>The defense called only one witness.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[emotions]</strong> <span class=\"gram\">[countable]</span> something you do or a way of behaving that prevents you from seeming weak or being hurt by others:</div><ul class=\"examples\"><li><em>Liz dropped her defences and began to relax.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sport]</strong> <span class=\"gram\">[countable]</span> the players on a sports team whose main job is to try to prevent the other team from getting points</div></div>","1843":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fend</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to do something in order to protect someone or something from being attacked:</div><ul class=\"examples\"><li><em>a struggle to defend our homeland</em></li><li><strong><em>defend something against/from something</strong>: the need to defend democracy against fascism</em></li><li><strong><em>defend yourself (against/from somebody/something)</strong>: advice on how women can defend themselves from sex attackers</em></li><li><strong><em>defend against</strong>: We need to defend against military aggression.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to use arguments to protect something or someone from criticism, or to prove that something is right <em>OPP attack</em>: RegisterIn everyday English, people usually say stand up for someone rather than defend someone:· She was the only person who stood up for me at the meeting.</div><ul class=\"examples\"><li><em>She was always defending her husband in front of their daughter.</em></li><li><em>Students should be ready to explain and defend their views.</em></li><li><strong><em>defend somebody against/from somebody/something</strong>: He defended his wife against rumours and allegations.</em></li><li><strong><em>defend yourself (against/from something)</em></strong></li><li><em>Cooper wrote to the journal immediately, defending himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to do something in order to stop something from being taken away or in order to make it possible for something to continue:</div><ul class=\"examples\"><li><em>the workers’ attempts to defend their interests</em></li><li><em>We are defending the right to demonstrate.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> to protect your own team’s end of the field in a game such as football, in order to prevent your opponents from getting points <em>OPP attack</em>:</div><ul class=\"examples\"><li><em>Bournemouth defended well throughout the game.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to take part in a competition that you won the last time it was held, and try to win it again:</div><ul class=\"examples\"><li><em>The world champion was defending his title.</em></li><li><em>the defending champion</em></li><li><em>He is defending a Labour majority of 5,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[intransitive, transitive]</span> to be a lawyer for someone who has been charged with a crime <em>OPP prosecute</em>:</div><ul class=\"examples\"><li><em>He had top lawyers to defend him.</em></li><li><em>Howard, defending, said Thompson had been drinking heavily.</em></li></ul></div>","1844":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fend‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfendə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of the players in a game such as football who has to defend their team’s goal from the opposing team:</div><ul class=\"examples\"><li><em>It’s his fourth season as an Arsenal defender.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who defends a particular idea, belief, person etc:</div><ul class=\"examples\"><li><em>He presented himself as a defender of democracy.</em></li></ul></div>","1845":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fen‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfensɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used or intended to protect someone or something against attack <em>OPP offensive</em>:</div><ul class=\"examples\"><li><em>The prince drew up his forces in a strong defensive position.</em></li><li><em>The rockets are a purely defensive measure against nuclear attack.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> behaving in a way that shows you think someone is criticizing you even if they are not:</div><ul class=\"examples\"><li><em>She despised herself for sounding so defensive.</em></li><li><em>a reserved and defensive manner</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> relating to stopping the other team from getting points in a game <em>OPP offensive</em>:</div><ul class=\"examples\"><li><em>defensive play</em></li></ul></div>","1846":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fer</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfɜː $ -ˈfɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle deferred, present participle deferring)</span></div><div class=\"entry-body\"><div class=\"sense\">to delay something until a later date <em>SYN put back</em> ► see thesaurus at delay</div><ul class=\"examples\"><li><strong><em>defer something until/to something</strong>: Further discussion on the proposal will be deferred until April.</em></li><li><em>The committee deferred their decision.</em></li></ul></div>","1847":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fi‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfaɪəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">behaviour that shows you refuse to do what someone tells you to do, especially because you do not respect them → defy</div><ul class=\"examples\"><li><strong><em>act/gesture of defiance</strong>: Running away was an act of defiance against his parents.</em></li><li><strong><em>in defiance (of something)</strong>: Many people were drinking in the streets, in flagrant defiance of the ban.</em></li><li><em>Her fists clenched in defiance.</em></li></ul></div>","1848":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fi‧cien‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfɪʃənsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural deficiencies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a lack of something that is necessary <em>SYN shortage</em></div><ul class=\"examples\"><li><strong><em>deficiency of</strong>: a deficiency of safe play areas for children</em></li><li><strong><em>iron/vitamin etc deficiency</strong>: Some elderly people suffer from iron deficiency in their diet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a weakness or fault in something</div><ul class=\"examples\"><li><strong><em>deficiency in</strong>: There are deep deficiencies in this law.</em></li></ul></div>","1849":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> def‧i‧cit</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdefɪsɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the difference between the amount of something that you have and the higher amount that you need → shortfall:</div><ul class=\"examples\"><li><em>the country’s widening budget deficit</em></li><li><em>the US’s foreign trade deficit</em></li><li><strong><em>deficit of</strong>: a deficit of £2.5 million</em></li><li><strong><em>deficit in</strong>: Many countries have a big deficit in food supply.</em></li><li><strong><em>in deficit</strong>: The US balance of payments was in deficit.</em></li></ul></div>","1850":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fine</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to describe something correctly and thoroughly, and to say what standards, limits, qualities etc it has that make it different from other things:</div><ul class=\"examples\"><li><em>the ability to define clients’ needs</em></li><li><em>The duties of the post are difficult to define.</em></li><li><strong><em>clearly/well defined</strong>: The tasks will be clearly defined by the tutor.</em></li><li><strong><em>define something as something</strong>: 70% of the workers can be defined as low-paid.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to explain exactly the meaning of a particular word or idea → definition:</div><ul class=\"examples\"><li><em>I’ll now try to define the term ‘popular culture’.</em></li><li><strong><em>define something as something</strong>: A budget is defined as ‘a plan of action expressed in money terms’.</em></li><li><em>Define precisely what you mean by ‘crime’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to show the edge or shape of something clearly → definition:</div><ul class=\"examples\"><li><em>The bird has sharply defined black and rust markings.</em></li></ul></div>","1851":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> def‧i‧nite</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdefɪnət, ˈdefənət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> clearly known, seen, or stated <em>SYN clear</em> <em>OPP indefinite</em>: ► see thesaurus at certain</div><ul class=\"examples\"><li><em>It’s impossible for me to give you a definite answer.</em></li><li><em>We need to record sufficient data to enable definite conclusions to be reached.</em></li><li><em>He’d shown definite signs of resigning himself to the situation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a definite arrangement, promise etc will happen in the way that someone has said → indefinite:</div><ul class=\"examples\"><li><em>Fix a definite date for the delivery of your computer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[not before noun]</span> saying something very firmly so that people understand exactly what you mean</div><ul class=\"examples\"><li><strong><em>definite about</strong>: She’s not definite about retiring from the game.</em></li></ul></div>","1852":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> def‧i‧nite‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdefɪnətli, ˈdefənətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">without any doubt <em>SYN certainly</em>:</div><ul class=\"examples\"><li><em>‘Do you reckon Margot will be there?’ ‘Definitely not.’</em></li><li><em>The hotel fitness centre is definitely worth a visit.</em></li><li><em>I definitely need a holiday.</em></li></ul></div>","1853":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> def‧i‧ni‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdefəˈnɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a phrase or sentence that says exactly what a word, phrase, or idea means → define:</div><ul class=\"examples\"><li><em>a dictionary definition</em></li><li><strong><em>definition of</strong>: There are many definitions of the word ‘feminism’.</em></li><li><strong><em>definition of something as something</strong>: the definition of God as infinite</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>by definition</strong> if something has a particular quality by definition, it must have that quality because all things of that type have it:</div><ul class=\"examples\"><li><em>People say that students are by definition idealistic and impatient.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the clear edges, shapes, or sound that something has:</div><ul class=\"examples\"><li><em>technologies such as high definition television</em></li><li><em>good muscle definition</em></li></ul></div>","1854":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fin‧i‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfɪnətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually before noun]</span> a definitive book, description etc is considered to be the best and cannot be improved</div><ul class=\"examples\"><li><strong><em>definitive study/work/guide etc</strong>: the definitive study of Victorian railway stations</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a definitive agreement, statement etc is one that will not be changed:</div><ul class=\"examples\"><li><em>a definitive agreement to buy the company</em></li></ul></div>","1855":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧flect</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈflekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if someone or something deflects something that is moving, or if it deflects, it turns in a different direction:</div><ul class=\"examples\"><li><em>He deflected the blow with his forearm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to do something to stop people paying attention to you, criticizing you etc</div><ul class=\"examples\"><li><strong><em>deflect something (away) from something</strong>: his attempts to deflect attention away from his private life / The committee is seeking to deflect criticism by blaming me.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to take someone’s attention away from something</div><ul class=\"examples\"><li><strong><em>deflect somebody from (doing) something</strong>: Nothing can deflect me from reaching my goal.</em></li></ul></div>","1856":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧fy</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈfaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle defied, present participle defying, third person singular defies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to refuse to obey a law or rule, or refuse to do what someone in authority tells you to do → defiance: ► see thesaurus at disobey</div><ul class=\"examples\"><li><em>people who openly defy the law</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>defy description/analysis/belief etc</strong> to be almost impossible to describe or understand:</div><ul class=\"examples\"><li><em>The beauty of the scene defies description.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>defy logic/the odds etc</strong> to not happen according to the principles you would expect:</div><ul class=\"examples\"><li><em>a 16-week premature baby who defied the odds and survived</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>I defy somebody to do something</strong> <em>spoken</em> <em>formal</em> used when you ask someone to do something that you think is impossible:</div><ul class=\"examples\"><li><em>I defy anyone to prove otherwise.</em></li></ul></div>","1857":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧gree</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈɡriː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> (written abbreviation deg.) a unit for measuring temperature. It can be shown as a symbol after a number. For example, 70° means 70 degrees:</div><ul class=\"examples\"><li><em>Preheat the oven to 425 degrees.</em></li><li><strong><em>20 degrees Celsius/70 degrees Fahrenheit/1 degree Centigrade etc</strong>: The temperature dropped to five degrees Centigrade.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> (written abbreviation deg.) a unit for measuring the size of an angle. It can be shown as a symbol after a number. For example, 18° means 18 degrees:</div><ul class=\"examples\"><li><em>Then the cylinder is rotated 180 degrees.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> the level or amount of something</div><ul class=\"examples\"><li><strong><em>degree of</strong>: 1960s Britain was characterised by a greater degree of freedom than before.</em></li><li><em>Newspapers vary in the degree to which they emphasize propaganda rather than information.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>to a degree</strong> (also to some degree/to a certain degree) partly:</div><ul class=\"examples\"><li><em>To a degree, it is possible to educate oneself.</em></li><li><em>We’re all willing to support him to some degree.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a course of study at a university or college, or the qualification that is given to you when you have successfully completed the course</div><ul class=\"examples\"><li><strong><em>degree in</strong>: a degree in Economics</em></li><li><em>Applicants must have a degree in Engineering.</em></li><li><em>an Honours degree</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>by degrees</strong> very slowly <em>SYN gradually</em>:</div><ul class=\"examples\"><li><em>By degrees, he forced himself into a sitting position.</em></li></ul></div>","1858":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧lay</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈleɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> when someone or something has to wait, or the length of the waiting time:</div><ul class=\"examples\"><li><em>Sorry for the delay, Mr Weaver.</em></li><li><strong><em>delay in</strong>: Why was there a delay in warning the public?</em></li><li><strong><em>delay of</strong>: a delay of about an hour</em></li><li><strong><em>long/considerable/slight etc delay</strong>: Long delays are expected on the motorways.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when something does not happen or start when it should do</div><ul class=\"examples\"><li><strong><em>without delay</strong>: They must restore normal services without delay.</em></li><li><em>There can be no excuse for any further delay.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to wait until a later time to do something:</div><ul class=\"examples\"><li><em>Don’t delay – send off for the information now.</em></li><li><em>He delayed his decision on whether to call an election.</em></li><li><strong><em>delay something until something</strong>: The opening of this section of the road is delayed until September.</em></li><li><strong><em>delay something for something</strong>: Our meeting was delayed for ten minutes.</em></li><li><strong><em>delay doing something</strong>: Big companies often delay paying their bills.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make someone or something late</div><ul class=\"examples\"><li><strong><em>seriously/badly/slightly etc delayed</strong>: The flight was badly delayed because of fog.</em></li></ul></div></div>","1859":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> del‧e‧gate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdeləɡət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who has been elected or chosen to speak, vote, or take decisions for a group → representative:</div><ul class=\"examples\"><li><em>Around 350 delegates attended the conference.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> del‧e‧gate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdelɪɡeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to give part of your power or work to someone in a lower position than you:</div><ul class=\"examples\"><li><em>A good manager knows when to delegate.</em></li><li><em>It takes experience to judge correctly how much power should be delegated.</em></li><li><strong><em>delegate something to somebody</strong>: Minor tasks should be delegated to your assistant.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to choose someone to do a particular job, or to be a representative of a group, organization etc</div><ul class=\"examples\"><li><strong><em>delegate somebody to do something</strong>: I was delegated to find a suitable conference venue.</em></li></ul></div></div>","1860":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> del‧e‧ga‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdeləˈɡeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a group of people who represent a company, organization etc</div><ul class=\"examples\"><li><strong><em>delegation to</strong>: the head of the American delegation to the United Nations</em></li><li><strong><em>delegation of</strong>: a delegation of government officials</em></li><li><em>A trade delegation will visit Kuwait.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the process of giving power or work to someone else so that they are responsible for part of what you normally do</div><ul class=\"examples\"><li><strong><em>delegation of</strong>: the delegation of authority</em></li></ul></div>","1861":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧lete</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈliːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to remove something that has been written down or stored in a computer: ► see thesaurus at remove</div><ul class=\"examples\"><li><em>His name was deleted from the list.</em></li><li><em>I deleted the file by mistake.</em></li></ul></div>","1862":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧lib‧e‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlɪbərət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> intended or planned <em>OPP unintentional</em> <em>SYN intentional</em>:</div><ul class=\"examples\"><li><em>a deliberate attempt to humiliate her</em></li><li><em>The attack on him was quite deliberate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> deliberate speech, thought, or movement is slow and careful:</div><ul class=\"examples\"><li><em>He approached her with slow, deliberate steps.</em></li></ul></div>","1863":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧lib‧er‧ate‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlɪbərətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> done in a way that is intended or planned:</div><ul class=\"examples\"><li><em>He deliberately upset her.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> done or said in a slow careful way:</div><ul class=\"examples\"><li><em>He shook his head slowly and deliberately.</em></li></ul></div>","1864":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> del‧i‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdelɪkət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> needing to be dealt with carefully or sensitively in order to avoid problems or failure: ► see thesaurus at difficult</div><ul class=\"examples\"><li><em>There’s something I have to speak to you about – it’s a delicate matter.</em></li><li><em>delicate negotiations</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> easily damaged or broken <em>SYN fragile</em>:</div><ul class=\"examples\"><li><em>delicate hand-cut glass</em></li><li><em>The sun can easily damage a child’s delicate skin.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>old-fashioned</em> someone who is delicate is hurt easily or easily becomes ill: ► see thesaurus at ill, weak</div><ul class=\"examples\"><li><em>a delicate child</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a part of the body that is delicate is attractive and graceful:</div><ul class=\"examples\"><li><em>Her wrists and ankles were slim and delicate.</em></li><li><em>her delicate features</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> made skilfully and with attention to the smallest details:</div><ul class=\"examples\"><li><em>a plate with a delicate pattern of leaves</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> a taste, smell, or colour that is delicate is pleasant and not strong:</div><ul class=\"examples\"><li><em>The wine has a dry delicate flavour.</em></li><li><em>a delicate pink</em></li></ul></div>","1865":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧li‧cious</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlɪʃəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very pleasant to taste or smell: ► see thesaurus at taste</div><ul class=\"examples\"><li><em>‘The meal was absolutely delicious,’ she said politely.</em></li><li><em>the delicious smell of new-mown grass</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> extremely pleasant or enjoyable</div></div>","1866":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧light</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a feeling of great pleasure and satisfaction ► see thesaurus at pleasure</div><ul class=\"examples\"><li><strong><em>with/in delight</strong>: The kids were screaming with delight.</em></li><li><strong><em>to somebody’s delight/to the delight of somebody</strong>: To the delight of his proud parents, he has made a full recovery.</em></li><li><strong><em>squeal/gasp/cry etc of delight</strong>: She gave a little gasp of delight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something that makes you feel very happy or satisfied</div><ul class=\"examples\"><li><strong><em>the delights of something</strong>: a chance to sample the delights of nearby Vienna</em></li><li><strong><em>it is a delight to do something</strong>: It was a delight to see him so fit and healthy.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take delight in (doing) something</strong> to enjoy something very much, especially something you should not do:</div><ul class=\"examples\"><li><em>Chris takes great delight in teasing his sister.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to give someone great satisfaction and enjoyment:</div><ul class=\"examples\"><li><em>Her fabulous recipes will delight anyone who loves chocolate.</em></li><li><strong><em>delight somebody with something</strong>: He is delighting audiences with his wit and humour.</em></li></ul></div></div>","1867":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧light‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlaɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">very pleased and happy ► see thesaurus at happy</div><ul class=\"examples\"><li><strong><em>delighted to do something</strong>: Sandy will be delighted to see you.</em></li><li><strong><em>delighted (that)</strong>: I’m delighted that we have settled the matter.</em></li><li><strong><em>delighted with/by/at</strong>: She was delighted with her new home. / I am delighted by the result.</em></li><li><em>Her screams of delighted laughter filled the air.</em></li></ul></div>","1868":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧light‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlaɪtfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very pleasant: ► see thesaurus at nice</div><ul class=\"examples\"><li><em>a delightful little girl</em></li><li><em>The whole house is delightful.</em></li></ul></div>","1869":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧liv‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlɪvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[take something somewhere]</strong> <span class=\"gram\">[intransitive, transitive]</span> to take goods, letters, packages etc to a particular place or person: ► see thesaurus at take</div><ul class=\"examples\"><li><em>The morning mail has just been delivered.</em></li><li><em>Do you deliver on Saturdays?</em></li><li><strong><em>deliver something to somebody</strong>: They set off to deliver supplies to an isolated village.</em></li><li><em>I’m having some flowers delivered for her birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deliver a speech/lecture/address etc</strong> to make a speech etc to a lot of people: RegisterIn everyday English, people usually say give a speech/lecture/talk rather than deliver a speech/lecture/talk.</div><ul class=\"examples\"><li><em>The king delivered a televised speech to the nation on November 5.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[do something you should do]</strong> <span class=\"gram\">[intransitive, transitive]</span> to do or provide the things you are expected to, because you are responsible for them or they are part of your job:</div><ul class=\"examples\"><li><em>the costs of delivering adequate nursing care</em></li><li><em>the failure of some services to deliver the goods (=do what they have promised)</em></li><li><em>The company will deliver on its promises.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[baby]</strong> <span class=\"gram\">[transitive]</span> to help a woman give birth to her baby, or to give birth to a baby:</div><ul class=\"examples\"><li><em>They rushed her to hospital where doctors delivered her baby.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[blow/shock etc]</strong> <span class=\"gram\">[transitive]</span> to give something such as a blow, shock, or warning to someone or something:</div><ul class=\"examples\"><li><em>He delivered a strong warning about the dangers facing the government.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>deliver a judgment/verdict</strong> to officially state a formal decision or judgment:</div><ul class=\"examples\"><li><em>The jury delivered a verdict of unlawful killing.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[person]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to put someone into someone else’s control</div><ul class=\"examples\"><li><strong><em>deliver somebody to somebody</strong>: Sharett had betrayed him and delivered him to the enemy.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[votes]</strong> <span class=\"gram\">[transitive]</span> <em>especially American English</em> to get the votes or support of a particular group of people in an election:</div><ul class=\"examples\"><li><em>He cannot deliver the Latino vote.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[make somebody free of something]</strong> <span class=\"gram\">[transitive]</span> <em>literary</em> or <em>biblical</em> to help someone escape from something bad or evil</div><ul class=\"examples\"><li><strong><em>deliver somebody from something</strong>: ‘Deliver us from evil,’ she prayed.</em></li></ul></div>","1870":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧liv‧er‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈlɪvəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(plural deliveries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the act of bringing goods, letters etc to a particular person or place, or the things that are brought:</div><ul class=\"examples\"><li><em>Most Indian restaurants offer free delivery.</em></li><li><em>You can expect delivery in a week to ten days.</em></li><li><em>fresh milk deliveries</em></li><li><strong><em>delivery of</strong>: deliveries of food and supplies</em></li><li><strong><em>on delivery</strong> (=when something is delivered): The restaurant pays cash on delivery for fish, which the local fishermen like.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>take delivery of something</strong> to officially accept something large that you have bought:</div><ul class=\"examples\"><li><em>We expect to take delivery of the aircraft sometime in June.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the process of giving birth to a child → labour:</div><ul class=\"examples\"><li><em>Mrs Howell had an easy delivery.</em></li><li><em>Liz was taken to the delivery room (=a room in a hospital for births) immediately.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the way in which someone speaks in public:</div><ul class=\"examples\"><li><em>You’ll have to work on your delivery.</em></li></ul></div>","1871":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧mand</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈmɑːnd $ dɪˈmænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> the need or desire that people have for particular goods and services: → supply and demand</div><ul class=\"examples\"><li><em>Production is increasing faster than demand.</em></li><li><strong><em>demand for</strong>: the demand for new housing</em></li><li><strong><em>in demand</strong> (=wanted): As a speaker he was always in demand.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a very firm request for something that you believe you have the right to get:</div><ul class=\"examples\"><li><em>demonstrations in support of the nationalists’ demands</em></li><li><strong><em>demand for</strong>: their demand for higher salaries</em></li><li><strong><em>demand that</strong>: demands that he should resign</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>demands</strong> <span class=\"gram\">[plural]</span> the difficult, annoying, or tiring things that you need to do, or a skill you need to have</div><ul class=\"examples\"><li><strong><em>demand of</strong>: the demands of modern life</em></li><li><strong><em>demand on</strong>: The curriculum makes great demands on the teacher. / There are heavy demands on people’s time these days.</em></li><li><strong><em>place/put demands on/upon somebody/something</strong>: the increased demands placed on police officers</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>popular demand</strong> when a lot of people have asked for something to be done, performed etc</div><ul class=\"examples\"><li><strong><em>by/due to popular demand</strong> (=because of popular demand): The exhibition will run for an extra week, due to popular demand.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>on demand</strong> <em>formal</em> whenever someone asks:</div><ul class=\"examples\"><li><em>Should you feed your baby on demand, or stick to a timetable?</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to ask for something very firmly, especially because you think you have a right to do this: ► see thesaurus at ask, insist</div><ul class=\"examples\"><li><em>Angry demonstrators demanded the resignation of two senior officials.</em></li><li><strong><em>demand to know/see/have etc something</strong>: I demand to know what’s going on.</em></li><li><strong><em>demand that</strong>: They demanded that the military government free all political prisoners.</em></li><li><strong><em>demand something of somebody</strong>: It seemed that no matter what she did, more was demanded of her.</em></li><li><em>‘Where are you going?’ she demanded angrily.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if one thing demands another, it needs that thing in order to happen or be done successfully:</div><ul class=\"examples\"><li><em>Too many things demanded his attention at the same time.</em></li><li><em>It’s a desperate situation demanding a desperate remedy.</em></li></ul></div></div>","1872":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧mand‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈmɑːndɪŋ $ dɪˈmæn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> needing a lot of ability, effort, or skill: ► see thesaurus at difficult</div><ul class=\"examples\"><li><em>a demanding job</em></li><li><strong><em>physically/emotionally/intellectually etc demanding</strong>: Climbing is physically demanding.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> expecting a lot of attention or expecting to have things exactly the way you want them, especially in a way that is not fair:</div><ul class=\"examples\"><li><em>Her mother could be very demanding at times.</em></li></ul></div>","1873":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧mise</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈmaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> the end of something that used to exist</div><ul class=\"examples\"><li><strong><em>demise of</strong>: the imminent demise (=happening soon) of the local newspaper</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> or <em>law</em> death:</div><ul class=\"examples\"><li><em>the mystery surrounding Elena’s untimely demise (=when death happens sooner than is normal or expected)</em></li></ul></div>","1874":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧moc‧ra‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈmɒkrəsi $ dɪˈmɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\">(plural democracies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a system of government in which every citizen in the country can vote to elect its government officials: ► see thesaurus at government</div><ul class=\"examples\"><li><em>a return to democracy after 16 years of military rule</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a country that has a government which has been elected by the people of the country:</div><ul class=\"examples\"><li><em>a parliamentary democracy</em></li><li><em>Western democracies</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a situation or system in which everyone is equal and has the right to vote, make decisions etc → democratic:</div><ul class=\"examples\"><li><em>democracy within the trade unions</em></li></ul></div>","1875":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dem‧o‧crat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdeməˈkrætɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> controlled by representatives who are elected by the people of a country:</div><ul class=\"examples\"><li><em>a democratic government</em></li><li><em>the role of the media in the democratic process</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> organized according to the principle that everyone has a right to be involved in making decisions:</div><ul class=\"examples\"><li><em>a democratic management style</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> organized according to the principle that everyone in a society is equally important, no matter how much money they have or what social class they come from:</div><ul class=\"examples\"><li><em>a democratic society</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (also Democratic) belonging to or supporting the Democratic Party of the US → republican:</div><ul class=\"examples\"><li><em>the Democratic nominee for the presidency</em></li></ul></div>","1876":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dem‧o‧graph‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdeməˈɡræfɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">relating to the population and groups of people in it:</div><ul class=\"examples\"><li><em>Demographic trends show that there are rising numbers of old people.</em></li><li><em>demographic changes</em></li></ul></div>","1877":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧mol‧ish</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈmɒlɪʃ $ dɪˈmɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to completely destroy a building: ► see thesaurus at destroy</div><ul class=\"examples\"><li><em>The entire east wing of the building was demolished in the fire.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to prove that an idea or opinion is completely wrong:</div><ul class=\"examples\"><li><em>He demolished my argument in minutes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to end or ruin something completely:</div><ul class=\"examples\"><li><em>These ants can demolish large areas of forest.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to defeat someone very easily:</div><ul class=\"examples\"><li><em>Miami demolished Texas 46–3.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>especially British English</em> <em>informal</em> to eat all of something very quickly:</div><ul class=\"examples\"><li><em>He demolished a second helping of pie.</em></li></ul></div>","1878":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dem‧o‧li‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdeməˈlɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the complete destruction of a building:</div><ul class=\"examples\"><li><em>Consent is required for the demolition of any building.</em></li><li><em>Demolition work has already begun at the site.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an easy defeat:</div><ul class=\"examples\"><li><em>50,000 fans watched the 7-0 demolition of Dynamo Kiev.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a process in which something is ended or ruined completely:</div><ul class=\"examples\"><li><em>The policies are intended to halt the demolition of the rural economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> the act of proving that an idea, opinion etc is wrong:</div><ul class=\"examples\"><li><em>This is a legend that deserves demolition.</em></li></ul></div>","1879":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧mon</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːmən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an evil spirit or force:</div><ul class=\"examples\"><li><em>He was speeding down the motorway as if pursued by a demon.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> something that makes you anxious and causes you problems:</div><ul class=\"examples\"><li><em>She struggled with her husband’s demons of addiction and alcoholism.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is very good at something – often used humorously:</div><ul class=\"examples\"><li><em>a demon cook</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the demon drink</strong> <em>British English</em> alcoholic drink – often used humorously</div></div>","1880":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dem‧on‧strate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdemənstreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to show or prove something clearly:</div><ul class=\"examples\"><li><em>The study demonstrates the link between poverty and malnutrition.</em></li><li><strong><em>demonstrate that</strong>: Hitchcock’s films demonstrate that a British filmmaker could learn from Hollywood.</em></li><li><strong><em>demonstrate how/what/why etc</strong>: This section will attempt to demonstrate how the Bank of England operates.</em></li><li><em>The government now has an opportunity to demonstrate its commitment to reform.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to show or describe how to do something or how something works ► see thesaurus at explain, show</div><ul class=\"examples\"><li><strong><em>demonstrate how</strong>: They’ll be demonstrating how to handle modern, high performance cars.</em></li><li><em>Instructors should demonstrate new movements before letting the class try them.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to protest or support something in public with a lot of other people:</div><ul class=\"examples\"><li><em>Supporters demonstrated outside the courtroom during the trial.</em></li><li><strong><em>demonstrate against</strong>: What are they demonstrating against?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to show that you have a particular ability, quality, or feeling:</div><ul class=\"examples\"><li><em>He has demonstrated an ability to meet deadlines.</em></li></ul></div>","1881":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dem‧on‧stra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdemənˈstreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an event at which a large group of people meet to protest or to support something in public → protest:</div><ul class=\"examples\"><li><em>Supporters staged a demonstration outside the US embassy.</em></li><li><em>Police opened fire on a peaceful demonstration.</em></li><li><strong><em>demonstration against</strong>: a demonstration against the government’s educational policies</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an act of explaining and showing how to do something or how something works</div><ul class=\"examples\"><li><strong><em>demonstration of</strong>: He gave a practical demonstration of the boat’s military potential.</em></li><li><em>a cookery demonstration</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> an action that proves that someone or something has a particular ability, quality, or feeling</div><ul class=\"examples\"><li><strong><em>demonstration of</strong>: The high level of calls is a clear demonstration of the need for this service. / a physical demonstration of affection</em></li></ul></div>","1882":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dem‧on‧stra‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdemənstreɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who takes part in a demonstration:</div><ul class=\"examples\"><li><em>anti-war demonstrators</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who shows people how to do something or how something works</div></div>","1883":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ni‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈnaɪəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a statement saying that something is not true → deny</div><ul class=\"examples\"><li><strong><em>denial of</strong>: The government issued an official denial of the rumour.</em></li><li><strong><em>denial that</strong>: denials that border security had not been strict enough</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when someone refuses to allow someone else to have or to do something</div><ul class=\"examples\"><li><strong><em>denial of</strong>: protests against the denial of human rights</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a condition in which you refuse to admit or believe that something bad exists or has happened</div><ul class=\"examples\"><li><strong><em>in denial</strong>: His girlfriend is in denial, and refuses to admit that he will soon die.</em></li></ul></div>","1884":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧note</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈnəʊt $ -ˈnoʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to mean something → connote:</div><ul class=\"examples\"><li><em>What does the word ‘curriculum’ denote that ‘course’ does not?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to represent or be a sign of something <em>SYN indicate</em>:</div><ul class=\"examples\"><li><em>Crosses on the map denote villages.</em></li></ul></div>","1885":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧nounce</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈnaʊns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to express strong disapproval of someone or something, especially in public → denunciation:</div><ul class=\"examples\"><li><em>Amnesty International denounced the failure by the authorities to take action.</em></li><li><strong><em>denounce somebody/something as something</strong>: He denounced the election as a farce.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to give information to the police or another authority about someone’s illegal political activities</div><ul class=\"examples\"><li><strong><em>denounce somebody to somebody</strong>: She denounced him to the police.</em></li></ul></div>","1886":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dens/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> made of or containing a lot of things or people that are very close together <em>SYN thick</em></div><ul class=\"examples\"><li><strong><em>dense undergrowth/forest/woodland/jungle etc</strong>: A narrow track wound steeply up through dense forest. / the city&#x27;s dense population</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> difficult to see through or breathe in</div><ul class=\"examples\"><li><strong><em>dense fog/smoke/cloud</strong>: dense black smoke</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> not able to understand things easily <em>SYN stupid</em>:</div><ul class=\"examples\"><li><em>Am I being dense? I don’t quite understand.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a dense piece of writing is difficult to understand because it contains a lot of information or uses complicated language</div><div class=\"sense\"><span class=\"snum\">5</span> <em>technical</em> a substance that is dense has a lot of mass in relation to its size:</div><ul class=\"examples\"><li><em>Water is eight hundred times denser than air.</em></li></ul></div>","1887":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> den‧si‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdensəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the degree to which an area is filled with people or things</div><ul class=\"examples\"><li><strong><em>density of</strong>: the size and density of settlements / areas of high population density</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> the relationship between the mass of something and its size</div></div>","1888":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> den‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdentl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">relating to your teeth</div><ul class=\"examples\"><li><strong><em>dental treatment/care</strong>: Dental care was free in the 60s.</em></li><li><strong><em>dental disease/problems/decay etc</em></strong></li></ul></div>","1889":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> den‧tist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdentɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to treat people’s teeth</div><ul class=\"examples\"><li><strong><em>the dentist/the dentist’s</strong> (=the place where a dentist works): I’m going to the dentist this afternoon.</em></li></ul></div>","1890":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈnaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle denied, present participle denying, third person singular denies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[say something is not true]</strong> to say that something is not true, or that you do not believe something → denial GRAMMARYou deny doing something: · She denied taking the money. ✗Don’t say: She denied to take the money.</div><ul class=\"examples\"><li><strong><em>deny (that)</strong>: I’ve never denied that there is a housing problem. / I can’t deny her remarks hurt me.</em></li><li><strong><em>deny doing something</strong>: Two men have denied murdering a woman at a remote picnic spot.</em></li><li><strong><em>strongly/vehemently/strenuously etc deny something</strong>: Jackson vehemently denied the allegations.</em></li><li><em>The government denied the existence of poverty among 16- and 17-year-olds.</em></li><li><strong><em>deny a charge/allegation/claim</strong>: The men have denied charges of theft.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not allow]</strong> to refuse to allow someone to have or do something: ► see thesaurus at refuse</div><ul class=\"examples\"><li><em>Some landowners deny access to the countryside.</em></li><li><strong><em>deny somebody something</strong>: She could deny her son nothing.</em></li><li><strong><em>deny something to somebody</strong>: This is the only country in Europe to deny cancer screening to its citizens.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>there’s no denying (that/something)</strong> <em>spoken</em> used to say that it is very clear that something is true:</div><ul class=\"examples\"><li><em>There’s no denying that this is an important event.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[feelings]</strong> to refuse to admit that you are feeling something:</div><ul class=\"examples\"><li><em>Emotions can become destructive if they are suppressed and denied.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>deny yourself (something)</strong> to decide not to have something that you would like, especially for moral or religious reasons:</div><ul class=\"examples\"><li><em>He denied himself all pleasures and luxuries.</em></li></ul></div>","1891":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧part</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpɑːt $ -ɑːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to leave, especially when you are starting a journey → departure RegisterIn everyday English, people usually say leave or go rather than depart:· What time does the next plane leave/go?· She left for Germany last week.· Flights leave from Gatwick on Tuesdays.</div><ul class=\"examples\"><li><strong><em>depart from</strong>: ocean liners arriving at and departing from the island</em></li><li><strong><em>depart for</strong>: Dorothy departed for Germany last week.</em></li><li><em>Flights by Air Europe depart Gatwick on Tuesdays.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>depart this life</strong> <em>formal</em> to die</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to start to use new ideas or do something in a different way → departure</div><ul class=\"examples\"><li><strong><em>depart from</strong>: It’s revolutionary music; it departs from the old form and structures. / In his speech, the president departed from his text only once.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> to leave an organization or job → departure:</div><ul class=\"examples\"><li><em>the company’s departing chairman</em></li></ul></div>","1892":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧part‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpɑːtmənt $ -ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of the groups of people who work together in a particular part of a large organization such as a hospital, university, company, or government:</div><ul class=\"examples\"><li><em>the personnel department</em></li><li><em>the English department</em></li><li><strong><em>department of</strong>: the Department of the Environment</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an area in a large shop where a particular type of product is sold:</div><ul class=\"examples\"><li><em>the toy department</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be somebody’s department</strong> <em>spoken</em> if something is someone’s department, they are responsible for it or know a lot about it:</div><ul class=\"examples\"><li><em>I’ll see what I can do, but it’s not really my department.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>spoken</em> a particular part of someone’s character, or a particular part of a larger activity or subject:</div><ul class=\"examples\"><li><em>Dave was lacking in the trustworthiness department.</em></li></ul></div>","1893":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> deˈpartment ˌstore</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a large shop that is divided into separate departments, each selling a different type of goods</div></div>","1894":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧par‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpɑːtʃə $ -ˈpɑːrtʃər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> an act of leaving a place, especially at the start of a journey <em>OPP arrival</em></div><ul class=\"examples\"><li><strong><em>departure for</strong>: I saw Simon shortly before his departure for Russia.</em></li><li><strong><em>departure of</strong>: There was a delay in the departure of our plane.</em></li><li><strong><em>departure from</strong>: Mozart’s departure from Paris in September 1778</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> an act of leaving an organization or position</div><ul class=\"examples\"><li><strong><em>departure from</strong>: He refused to discuss his departure from the government.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a flight, train etc that leaves at a particular time:</div><ul class=\"examples\"><li><em>There are several departures for New York every day.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a way of doing something that is different from the usual, traditional, or expected way</div><ul class=\"examples\"><li><strong><em>departure from</strong>: Their new designs represent a departure from their usual style.</em></li><li><strong><em>radical/major/significant etc departure</strong> (=a big change): This would be a radical departure from the subsidy system.</em></li></ul></div>","1895":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pend</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>it/that depends</strong> <em>spoken</em> used to say that you cannot give a definite answer to something because your answer will be affected by something else:</div><ul class=\"examples\"><li><em>‘How long are you staying?’ ‘I don’t know; it depends.’</em></li><li><strong><em>it depends who/what/how/whether etc</strong>: You may take several months to reach your target weight – it depends how much you want to lose.</em></li></ul></div>","1896":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pend‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpendəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">able to be trusted to do what you need or expect:</div><ul class=\"examples\"><li><em>our most dependable ally</em></li><li><em>a dependable source of income</em></li></ul></div>","1897":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pen‧dence</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpendəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when you depend on the help and support of someone or something else in order to exist or be successful <em>OPP independence</em></div><ul class=\"examples\"><li><strong><em>dependence on/upon</strong>: our dependence on oil as a source of energy / the financial dependency of some women on men</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>drug/alcohol dependence</strong> when someone is addicted to drugs or alcohol</div><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> when one thing is strongly affected by another thing</div><ul class=\"examples\"><li><strong><em>dependence of</strong>: the mutual dependence of profit and growth</em></li></ul></div>","1898":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pen‧dent</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpendənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> needing someone or something in order to exist, be successful, be healthy etc <em>OPP independent</em></div><ul class=\"examples\"><li><strong><em>dependent on/upon</strong>: Norway’s economy is heavily dependent on natural resources. / Jan’s mother was dependent on her for physical care.</em></li><li><em>Do you have any dependent children (=who you are still supporting financially)?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> addicted to drugs, alcohol etc</div><ul class=\"examples\"><li><strong><em>dependent on/upon</strong>: the needs of people dependent on drugs</em></li><li><em>a danger of becoming alcohol dependent</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be dependent on/upon something</strong> to be directly affected or decided by something else:</div><ul class=\"examples\"><li><em>Your pay is dependent on how much you produce.</em></li></ul></div>","1899":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pict</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpɪkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to describe something or someone in writing or speech, or to show them in a painting, picture etc: ► see thesaurus at describe</div><ul class=\"examples\"><li><em>a book depicting life in pre-revolutionary Russia</em></li><li><strong><em>depict somebody/something as something</strong>: The god is depicted as a bird with a human head.</em></li></ul></div>","1900":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ploy</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈplɔɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to organize or move soldiers, military equipment etc so that they are in the right place and ready to be used</div><ul class=\"examples\"><li><strong><em>deploy forces/troops/weapons etc</strong>: NATO’s decision to deploy cruise missiles</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to use something for a particular purpose, especially ideas, arguments etc:</div><ul class=\"examples\"><li><em>a job in which a variety of professional skills will be deployed</em></li></ul></div>","1901":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧port</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpɔːt $ -ɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone leave a country and return to the country they came from, especially because they do not have a legal right to stay → export</div><ul class=\"examples\"><li><strong><em>deport somebody from/to something</strong>: He was deported from Ecuador when his visa expired.</em></li></ul></div>","1902":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pos‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpɒzɪt $ dɪˈpɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a part of the cost of something you are buying that you pay some time before you pay the rest of it</div><ul class=\"examples\"><li><strong><em>deposit of</strong>: A deposit of 10% is required.</em></li><li><strong><em>put down a deposit (on something)</strong> (=pay a deposit): We put down a deposit on a house.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> money that you pay when you rent something such as an apartment or car, which will be given back if you do not damage it</div><ul class=\"examples\"><li><strong><em>deposit of</strong>: We ask for one month’s rent in advance, plus a deposit of $500.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an amount of money that is paid into a bank account <em>OPP withdrawal</em></div><ul class=\"examples\"><li><strong><em>deposit into</strong>: I’d like to make a deposit (=pay some money) into my savings account.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a layer of a mineral, metal etc that is left in soil or rocks through a natural process</div><ul class=\"examples\"><li><strong><em>deposit of</strong>: rich deposits of gold in the hills</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> an amount or layer of a substance that gradually develops in a particular place:</div><ul class=\"examples\"><li><em>fatty deposits on the heart</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> an amount of money paid by a candidate in a political election in Britain, that is returned to them if they get enough votes</div><ul class=\"examples\"><li><strong><em>lose your deposit</strong> (=not get enough votes)</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> <em>formal</em> to put something down in a particular place:</div><ul class=\"examples\"><li><em>The female deposits her eggs directly into the water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to leave a layer of a substance on the surface of something, especially gradually:</div><ul class=\"examples\"><li><em>As the river slows down, it deposits a layer of soil.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to put money or something valuable in a bank or other place where it will be safe RegisterIn everyday English, people usually say they put in or pay in money, rather than deposit money:· I paid/put $100 into his account.· You should put your valuables in the hotel safe.</div><ul class=\"examples\"><li><strong><em>deposit something in something</strong>: You are advised to deposit your valuables in the hotel safe.</em></li><li><strong><em>deposit something with somebody/something</strong>: The dollars are then deposited with banks outside the USA.</em></li></ul></div></div>","1903":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dep‧ot</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdepəʊ $ ˈdiːpoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a place where goods are stored until they are needed:</div><ul class=\"examples\"><li><em>the company’s distribution depot</em></li><li><em>a fuel storage depot</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bus/tram etc depot</strong> <em>British English</em> a place where buses etc are kept and repaired</div><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> a railway station or bus station, especially a small one</div></div>","1904":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pressed</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈprest/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> ► see thesaurus at sad</div><div class=\"subsense\"><span class=\"subnum\">a)</span> very unhappy:</div><ul class=\"examples\"><li><em>She felt lonely and depressed.</em></li><li><strong><em>depressed about</strong>: Don’t get depressed about it.</em></li><li><em>The divorce left him deeply depressed.</em></li><li><em>I was depressed at the thought of all the hard work ahead.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> suffering from a medical condition in which you are so unhappy that you cannot live a normal life:</div><ul class=\"examples\"><li><em>patients who are clinically depressed</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an area, industry etc that is depressed does not have enough economic or business activity:</div><ul class=\"examples\"><li><em>Britain’s depressed housing market</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> a depressed level or amount is lower than normal:</div><ul class=\"examples\"><li><em>a depressed appetite</em></li></ul></div>","1905":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧press‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpresɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">making you feel very sad:</div><ul class=\"examples\"><li><em>It’s a depressing thought.</em></li><li><em>The whole experience was very depressing.</em></li></ul></div>","1906":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧pres‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpreʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a medical condition that makes you very unhappy and anxious and often prevents you from living a normal life:</div><ul class=\"examples\"><li><em>women who suffer from post-natal depression (=that sometimes happens after the birth of a baby)</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a feeling of sadness that makes you think there is no hope for the future:</div><ul class=\"examples\"><li><em>Lucy’s mood was one of deep depression.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the (Great) Depression</strong> the period during the 1930s when there was not much business activity and not many jobs</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a long period during which there is very little business activity and a lot of people do not have jobs → recession:</div><ul class=\"examples\"><li><em>the devastating effects of economic depression</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a part of a surface that is lower than the other parts:</div><ul class=\"examples\"><li><em>depressions in the ground</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>technical</em> a mass of air under low pressure, that usually causes rain</div></div>","1907":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dep‧ri‧va‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdeprəˈveɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the lack of something that you need in order to be healthy, comfortable, or happy:</div><ul class=\"examples\"><li><em>Sleep deprivation can result in mental disorders.</em></li><li><strong><em>social/economic/emotional etc deprivation</strong>: Low birth weight is related to economic deprivation.</em></li><li><strong><em>deprivation of</strong>: the deprivations of prison life</em></li></ul></div>","1908":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧prive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpraɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">deprive de‧prive / dɪˈpraɪv / ●○○ verb Word Origin Verb Table Examples Thesaurus Collocations deprive somebody of something phrasal verb to prevent someone from having something, especially something that they need or should have: A lot of these children have been deprived of a normal home life.</div></div>","1909":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧prived</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈpraɪvd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not having the things that are necessary for a comfortable or happy life: ► see thesaurus at poor</div><ul class=\"examples\"><li><em>Deprived children tend to do less well at school.</em></li><li><strong><em>deprived areas/neighbourhoods etc</strong> (=where a lot of deprived people live): our deprived inner cities</em></li></ul></div>","1910":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /depθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular, uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the distance from the top surface of something such as a river or hole to the bottom of it → deep:</div><ul class=\"examples\"><li><em>a sea with an average depth of 35 metres</em></li><li><strong><em>to/at a depth of something</strong>: The cave descends to a depth of 340 feet. / Plant the beans at a depth of about six inches.</em></li><li><strong><em>a metre/foot etc in depth</strong> (=deep): a channel of two feet in depth</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the distance from the front to the back of an object:</div><ul class=\"examples\"><li><em>The depth of the shelves is about 35 cm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> how strong an emotion is or how serious a situation is</div><ul class=\"examples\"><li><strong><em>depth of</strong>: the depth of public feeling on this issue / People need to realize the depth of the problem.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also depths) the quality of having a lot of knowledge, understanding, or experience</div><ul class=\"examples\"><li><strong><em>depth of knowledge/understanding/experience</strong>: I was impressed by the depth of her knowledge.</em></li><li><em>a man of great depth and insight</em></li><li><em>She’s quiet, but perhaps she has hidden depths.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> when a lot of details about a subject are provided or considered:</div><ul class=\"examples\"><li><em>Network news coverage often lacks depth.</em></li><li><em>The subject was discussed in great depth.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be out of your depth</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be involved in a situation or activity that is too difficult for you to understand or deal with:</div><ul class=\"examples\"><li><em>I felt completely out of my depth at the meeting.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> to be in water that is too deep for you to stand in</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>the depths of something</strong> when a bad feeling or situation is at its worst level:</div><ul class=\"examples\"><li><em>She was in the depths of despair.</em></li><li><em>The country was recovering from the depths of recession.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>the depths of the ocean/countryside/forest etc</strong> the part that is furthest away from people, and most difficult to reach:</div><ul class=\"examples\"><li><em>Astronomers may one day travel to the depths of space.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the depths of winter</strong> the middle of winter, especially when it is very cold</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>the depths</strong> <em>literary</em> the deepest parts of the sea</div></div>","1911":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dep‧u‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdepjəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural deputies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also Deputy) someone who is directly below another person in rank, and who is officially in charge when that person is not there</div><ul class=\"examples\"><li><strong><em>deputy director/chairman/governor etc</strong>: the Deputy Secretary of State</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone whose job is to help a sheriff in the US</div><div class=\"sense\"><span class=\"snum\">3</span> a member of parliament in some countries, for example France</div></div>","1912":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧rive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈraɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to get something, especially an advantage or a pleasant feeling, from something</div><ul class=\"examples\"><li><strong><em>derive something from something</strong>: Medically, we will derive great benefit from this technique.</em></li><li><strong><em>derive pleasure/enjoyment etc</strong>: Many students derived enormous satisfaction from the course.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also be derived) <span class=\"gram\">[intransitive, transitive]</span> to develop or come from something else → derivation RegisterIn everyday English, people usually say that something comes from something rather than is derived from something:· This word comes from Latin.</div><ul class=\"examples\"><li><strong><em>derive from</strong>: This word is derived from Latin. / patterns of behaviour that derive from basic beliefs</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>technical</em> to get a chemical substance from another substance</div><ul class=\"examples\"><li><strong><em>be derived from something</strong>: The enzyme is derived from human blood.</em></li></ul></div>","1913":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧scend</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to move from a higher level to a lower one <em>OPP ascend</em> → descent: RegisterIn everyday English, people usually say go down or come down rather than descend:· They went down into the lobby.· I heard his footsteps coming down the stairs.</div><ul class=\"examples\"><li><em>Our plane started to descend.</em></li><li><em>I heard his footsteps descending the stairs.</em></li><li><strong><em>descend to/from/into etc</strong>: The path continues for some way before descending to Garsdale Head.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> <em>literary</em> if darkness, silence, a feeling etc descends, it becomes dark etc or you start to feel something, especially suddenly</div><ul class=\"examples\"><li><strong><em>descend on/upon/over</strong>: Total silence descended on the room. / An air of gloom descended over the party headquarters.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in descending order (of something)</strong> numbers, choices etc that are in descending order are arranged from the highest or most important to the lowest or least important:</div><ul class=\"examples\"><li><em>The hotels are listed in descending order of price.</em></li></ul></div>","1914":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧scen‧dant</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsendənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is related to a person who lived a long time ago, or to a family, group of people etc that existed in the past → ancestor ► see thesaurus at relative</div><ul class=\"examples\"><li><strong><em>somebody’s descendants/the descendants of somebody</strong>: The coastal areas were occupied by the descendants of Greek colonists. / He was a direct descendant of Napoleon Bonaparte.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that has developed from something else</div><ul class=\"examples\"><li><strong><em>descendant of</strong>: Quechua is a descendant of the Inca language.</em></li></ul></div>","1915":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧scent</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> the process of going down <em>OPP ascent</em>:</div><ul class=\"examples\"><li><em>Passengers must fasten their seat belts prior to descent.</em></li><li><strong><em>descent from/to</strong>: The descent to Base Camp took about two days.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> your family origins, especially your nationality or relationship to someone important who lived a long time ago</div><ul class=\"examples\"><li><strong><em>of Russian/Italian etc descent</strong>: young men and women of Asian descent</em></li><li><strong><em>descent from</strong>: The emperor claimed descent from David.</em></li><li><strong><em>by descent</strong>: They’re Irish by descent.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a path or road that goes down a slope <em>OPP ascent</em></div><ul class=\"examples\"><li><strong><em>descent from/to</strong>: There is no direct descent from the summit.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular]</span> a gradual change towards behaviour or a situation that is very bad</div><ul class=\"examples\"><li><strong><em>descent into alcoholism/chaos/madness etc</strong>: his descent into drug abuse</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[singular]</span> <em>British English</em> a sudden unwanted visit or attack:</div><ul class=\"examples\"><li><em>the descent on the town by a motorcycle gang</em></li></ul></div>","1916":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧scribe</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskraɪb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to say what something or someone is like by giving details about them:</div><ul class=\"examples\"><li><em>The police asked her to describe the man.</em></li><li><em>Another approach to the problem is described in Chapter 3.</em></li><li><strong><em>describe somebody/something as (being/having) something</strong>: After the operation her condition was described as comfortable. / The youth is described as being 18 to 19 years old.</em></li><li><strong><em>describe how/why/what etc</strong>: It’s difficult to describe how I feel.</em></li><li><strong><em>describe somebody/something to somebody</strong>: So describe this new boyfriend to me!</em></li><li><strong><em>describe doing something</strong>: He described finding his mother lying on the floor.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>describe a circle/an arc etc</strong> <em>formal</em> to make a movement which forms the shape of a circle etc:</div><ul class=\"examples\"><li><em>Her hand described a circle in the air.</em></li></ul></div>","1917":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧scrip‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskrɪpʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of writing or speech that gives details about what someone or something is like → job description</div><ul class=\"examples\"><li><strong><em>description of</strong>: an accurate description of the event</em></li><li><em>The booklet gives a brief description of each place.</em></li><li><em>Berlin sounds fascinating from your description.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be beyond/past description</strong> to be too good, bad, big etc to be described easily:</div><ul class=\"examples\"><li><em>The death and destruction were beyond description.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>of every/some/any etc description</strong> (also of all descriptions) people or things of every type, some type etc:</div><ul class=\"examples\"><li><em>People of all descriptions came to see the show.</em></li></ul></div>","1918":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧scrip‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskrɪptɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> giving a description of something:</div><ul class=\"examples\"><li><em>the descriptive passages in the novel</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> describing how the words of a language are actually used, rather than saying how they ought to be used <em>OPP prescriptive</em></div></div>","1919":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧ert</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdezət $ -ərt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a large area of land where it is always very dry, there are few plants, and there is a lot of sand or rocks:</div><ul class=\"examples\"><li><em>the Sahara Desert</em></li><li><em>This area of the country is mostly desert.</em></li><li><strong><em>in the desert</strong>: The plane crash-landed in the desert.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a place where there is no activity or where nothing interesting happens:</div><ul class=\"examples\"><li><em>The railroad yard was a desert now.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧sert</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɜːt $ -ˈzɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to leave someone or something and no longer help or support them <em>SYN abandon</em>:</div><ul class=\"examples\"><li><em>Helen was deserted by her husband.</em></li><li><em>Many of the party’s traditional voters deserted it at the last election.</em></li><li><em>The price rise caused many readers to desert the magazine.</em></li><li><strong><em>desert somebody for somebody</strong>: He deserted her for another woman.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to leave a place so that it is completely empty <em>SYN abandon</em>:</div><ul class=\"examples\"><li><em>The birds have deserted their nest.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to leave the army, navy etc without permission:</div><ul class=\"examples\"><li><em>Several hundred soldiers have deserted.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> if a feeling, quality, or skill deserts you, you no longer have it, especially at a time when you need it:</div><ul class=\"examples\"><li><em>Mike’s confidence seemed to have deserted him.</em></li></ul></div></div>","1920":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧sert‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɜːtɪd $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> empty and quiet because no people are there: ► see thesaurus at empty</div><ul class=\"examples\"><li><em>The streets were deserted.</em></li><li><em>The old mine now stands completely deserted.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deserted wife/husband/child etc</strong> a wife etc who has been left by her husband etc</div></div>","1921":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧serve</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɜːv $ -ɜːrv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to have earned something by good or bad actions or behaviour: GRAMMAR: Using the progressiveDeserve is not used in the progressive. You say: · She deserves a prize. ✗Don’t say: She is deserving a prize.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>What have I done to deserve this?</em></li><li><strong><em>deserve to do something</strong>: We didn’t deserve to win.</em></li><li><strong><em>richly/fully/thoroughly etc deserve something</strong>: the success he so richly deserves</em></li><li><em>I’m sorry for the kids. They deserve better (=deserve to be treated in a better way).</em></li><li><strong><em>deserve a rest/break/holiday etc</strong>: I think we deserve a rest after all that hard work.</em></li><li><em>Ledley deserves a place in the team.</em></li><li><em>Paula deserves a special mention for all the help she has given us.</em></li><li><em>I would never hit anyone, even if they deserved it.</em></li><li><em>What has he done to deserve this punishment?</em></li><li><strong><em>deserve all/everything you get</strong> (=deserve any bad things that happen to you): He deserves all he gets for being so dishonest.</em></li><li><em>People who are sent to prison for drunk-driving get what they deserve.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deserve consideration/attention etc</strong> if a suggestion, idea, or plan deserves consideration, attention etc, it is good enough to be considered, paid attention to etc <em>SYN merit</em>:</div><ul class=\"examples\"><li><em>This proposal deserves serious consideration.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>somebody deserves a medal</strong> <em>spoken</em> used to say that you admire the way someone dealt with a situation or problem</div><ul class=\"examples\"><li><strong><em>deserve for</strong>: You deserve a medal for putting up with Ian’s constant demands.</em></li></ul></div>","1922":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧sign</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[process of planning]</strong> <span class=\"gram\">[uncountable]</span> the art or process of making a drawing of something to show how you will make it or what it will look like:</div><ul class=\"examples\"><li><em>The new plane is in its final design stage.</em></li><li><em>the design process</em></li><li><em>the design team</em></li><li><em>a course in graphic design</em></li><li><em>computer-aided design</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[arrangement of parts]</strong> <span class=\"gram\">[countable, uncountable]</span> the way that something has been planned and made, including its appearance, how it works etc:</div><ul class=\"examples\"><li><em>The car’s design has been greatly improved.</em></li><li><strong><em>design of</strong>: the design of the new building</em></li><li><em>Some changes have been made to the computer’s basic design.</em></li><li><em>a design fault</em></li><li><em>The electric windows are an important design feature of this model.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[pattern]</strong> <span class=\"gram\">[countable]</span> a pattern for decorating something:</div><ul class=\"examples\"><li><em>a floral design</em></li><li><em>Vinyl flooring is available in a wide range of designs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[drawing]</strong> <span class=\"gram\">[countable]</span> a drawing that shows how something will be made or what it will look like</div><ul class=\"examples\"><li><strong><em>design for</strong>: the design for the new sports centre</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[intention]</strong> <span class=\"gram\">[countable, uncountable]</span> a plan that someone has in their mind</div><ul class=\"examples\"><li><strong><em>by design</strong> (=intentionally): We shall never know whether this happened by accident or by design.</em></li><li><em>He has some grand designs for the company.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>have designs on something</strong> to want something for yourself, especially because it will bring you money:</div><ul class=\"examples\"><li><em>Several developers have designs on the property.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>have designs on somebody</strong> <em>formal</em> to want a sexual relationship with someone:</div><ul class=\"examples\"><li><em>He had designs on her.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a drawing or plan of something that will be made or built:</div><ul class=\"examples\"><li><em>The tower was designed by Gilbert Scott.</em></li><li><strong><em>design something for something</strong>: She designed a new logo for the company.</em></li><li><strong><em>well/badly etc designed</strong>: a badly designed office</em></li><li><em>specially designed software</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to plan or develop something for a specific purpose GRAMMAR Design is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be designed to do something</strong>: These exercises are designed to strengthen muscles.</em></li><li><strong><em>be designed for somebody/something</strong>: The course is designed for beginners.</em></li><li><strong><em>be designed as something</strong>: The book is designed as a reference manual.</em></li></ul></div></div>","1923":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧ig‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdezɪɡneɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to choose someone or something for a particular job or purpose</div><ul class=\"examples\"><li><strong><em>be designated something</strong>: The lake was recently designated a conservation area.</em></li><li><strong><em>be designated as/for something</strong>: Funds were designated for projects in low-income areas.</em></li><li><strong><em>be designated to do something</strong>: She has been designated to take over the position of treasurer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to represent or refer to something using a particular sign, name etc:</div><ul class=\"examples\"><li><em>Buildings are designated by red squares on the map.</em></li></ul></div>","1924":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧sign‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzaɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to make plans or patterns for clothes, furniture, equipment etc:</div><ul class=\"examples\"><li><em>an interior designer</em></li><li><em>a software designer</em></li><li><strong><em>dress/fashion designer</em></strong></li></ul></div>","1925":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧sir‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzaɪərəbəl $ -ˈzaɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> something that is desirable is worth having or doing:</div><ul class=\"examples\"><li><em>The ability to speak a foreign language is highly desirable.</em></li><li><em>a desirable neighborhood</em></li><li><em>It is desirable that you should have some familiarity with computers.</em></li><li><em>It is desirable to keep the cost as low as possible.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> sexually attractive:</div><ul class=\"examples\"><li><em>a desirable young woman</em></li></ul></div>","1926":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧sire</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzaɪə $ -ˈzaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a strong hope or wish</div><ul class=\"examples\"><li><strong><em>desire to do something</strong>: a strong desire to win</em></li><li><strong><em>desire for</strong>: a desire for knowledge</em></li><li><strong><em>desire that</strong>: It was Harold’s desire that he should be buried next to his wife.</em></li><li><strong><em>express/show a desire</strong>: She expressed a desire to visit us.</em></li><li><strong><em>have no desire to do something</strong> (=used to emphasize that you do not want to do something): I have no desire to cause any trouble.</em></li><li><strong><em>overwhelming/burning desire</strong> (=very strong desire): Paul had a burning desire to visit India.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> a strong wish to have sex with someone:</div><ul class=\"examples\"><li><em>female sexual desire</em></li><li><strong><em>desire for</strong>: He tried to hide his desire for her.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> to want something very much: RegisterIn everyday English, people usually say want rather than desire, although the meaning of desire is stronger than want:· You can have anything you want.· I wanted to meet her.</div><ul class=\"examples\"><li><em>The hotel has everything you could possibly desire.</em></li><li><strong><em>desire to do something</strong>: He desired to return to Mexico.</em></li><li><em>Add lemon juice if desired.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>literary</em> to want to have sex with someone</div></div></div>","1927":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /desk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of furniture like a table, usually with drawers in it, that you sit at to write and work:</div><ul class=\"examples\"><li><em>Marie was sitting at her desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a place where you can get information or use a particular service in a hotel, airport etc:</div><ul class=\"examples\"><li><em>the reception desk</em></li><li><em>the check-in desk</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an office that deals with a particular subject, especially in newspapers or television</div><ul class=\"examples\"><li><strong><em>the news/sports desk</em></strong></li></ul></div>","1928":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> desk‧top</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdesktɒp $ -tɑːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the main area on a computer where you can find the icons that represent programs, and where you can do things to manage the information on the computer</div><div class=\"sense\"><span class=\"snum\">2</span> the top surface of a desk</div></div>","1929":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧spair</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspeə $ -ˈsper/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a feeling that you have no hope at all</div><ul class=\"examples\"><li><strong><em>in despair</strong>: She killed herself in despair.</em></li><li><strong><em>the depths of despair</strong> (=very strong feelings of despair)</em></li><li><em>The noise from the neighbours used to drive him to despair.</em></li><li><strong><em>to the despair of somebody</strong>: To the despair of the workers, the company announced the closure of the factory.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be the despair of somebody</strong> <em>old-fashioned</em> to make someone feel very worried, upset, or unhappy:</div><ul class=\"examples\"><li><em>She is the despair of her teachers.</em></li></ul></div>","1930":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧per‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdespərət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> willing to do anything to change a very bad situation, and not caring about danger:</div><ul class=\"examples\"><li><em>I had no money left and was desperate.</em></li><li><em>Time was running out and we were getting desperate.</em></li><li><em>the missing teenager’s desperate parents</em></li><li><strong><em>desperate with</strong>: She was desperate with fear.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> needing or wanting something very much</div><ul class=\"examples\"><li><strong><em>desperate for</strong>: The team is desperate for a win. / I was desperate for a cigarette.</em></li><li><strong><em>desperate to do something</strong>: He was desperate to get a job.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a desperate situation is very bad or serious: ► see thesaurus at serious</div><ul class=\"examples\"><li><em>a desperate shortage of doctors</em></li><li><em>We’re in desperate need of help.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a desperate action is something that you only do because you are in a very bad situation</div><ul class=\"examples\"><li><strong><em>desperate attempt/bid/effort</strong>: a desperate attempt to escape</em></li><li><em>We resorted to desperate measures.</em></li><li><strong><em>desperate battle/struggle/fight</strong>: a desperate struggle to rescue the men</em></li></ul></div>","1931":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧pe‧rate‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdespərətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a desperate way:</div><ul class=\"examples\"><li><em>The doctors tried desperately to save her life.</em></li><li><em>He looked round desperately for someone to help him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very or very much</div><ul class=\"examples\"><li><strong><em>desperately want/need</strong>: The crops desperately need rain.</em></li><li><strong><em>desperately poor/ill/tired etc</strong>: He was desperately ill with a fever.</em></li><li><strong><em>desperately unhappy/lonely/worried etc</em></strong></li></ul></div>","1932":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧per‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdespəˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the state of being desperate:</div><ul class=\"examples\"><li><em>a look of desperation</em></li><li><strong><em>in/out of desperation</strong>: She resorted to stealing food out of desperation. / In desperation, we had to borrow the money.</em></li></ul></div>","1933":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧spise</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to dislike and have a low opinion of someone or something: ► see thesaurus at hate</div><ul class=\"examples\"><li><em>She despised her neighbours.</em></li></ul></div>","1934":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧spite</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say that something happens or is true even though something else might have prevented it <em>SYN in spite of</em>:</div><ul class=\"examples\"><li><em>Despite all our efforts to save the school, the authorities decided to close it.</em></li><li><strong><em>despite the fact (that)</strong>: She went to Spain despite the fact that her doctor had told her to rest.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>despite yourself</strong> if you do something despite yourself, you do it although you did not intend to:</div><ul class=\"examples\"><li><em>Liz realized that, despite herself, she cared about Edward.</em></li></ul></div>","1935":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧sert</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">sweet food served after the main part of a meal</div><ul class=\"examples\"><li><strong><em>for dessert</strong>: What are we having for dessert?</em></li></ul></div>","1936":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧ti‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdestəˈneɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the place that someone or something is going to</div><ul class=\"examples\"><li><strong><em>somebody’s destination</strong>: Allow plenty of time to get to your destination.</em></li><li><strong><em>holiday/tourist destination</strong>: Maui is a popular tourist destination.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>destination hotel/resort</strong> a place to stay that is the reason for visiting a country or area because it is special or provides many services or activities</div></div>","1937":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧tined</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdestɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[not before noun]</span> seeming certain to happen at some time in the future</div><ul class=\"examples\"><li><strong><em>destined for</strong>: She seemed destined for a successful career.</em></li><li><strong><em>destined to do something</strong>: We were destined never to meet again.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>destined for something</strong> to be travelling to a particular place, or intended to go there:</div><ul class=\"examples\"><li><em>The flight was destined for Cairo.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> <em>literary</em> a destined person or thing is one that you will have in the future:</div><ul class=\"examples\"><li><em>the King’s destined bride</em></li></ul></div>","1938":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> des‧ti‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdestɪni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural destinies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> the things that will happen to someone in the future, especially those that cannot be changed or controlled <em>SYN fate</em> ► see thesaurus at future</div><ul class=\"examples\"><li><strong><em>somebody’s destiny</strong>: Nancy wondered whether it was her destiny to live in England and marry Melvyn.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the power that some people believe decides what will happen to them in the future:</div><ul class=\"examples\"><li><em>She always had a strong sense of destiny.</em></li></ul></div>","1939":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧stroy</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrɔɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to damage something so badly that it no longer exists or cannot be used or repaired → destruction</div><ul class=\"examples\"><li><strong><em>completely/totally destroy</strong>: The school was completely destroyed by fire.</em></li><li><em>companies that are polluting and destroying the environment</em></li><li><strong><em>destroy somebody’s confidence/hope/faith etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something destroys someone, it ruins their life completely:</div><ul class=\"examples\"><li><em>The scandal destroyed Simmons and ended his political career.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> to defeat an opponent easily:</div><ul class=\"examples\"><li><em>The Bears destroyed the Detroit Lions 35–3.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to kill an animal, especially because it is ill or dangerous:</div><ul class=\"examples\"><li><em>One of the bulls had to be destroyed.</em></li></ul></div>","1940":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧struc‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrʌkʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the act or process of destroying something or of being destroyed → destroy</div><ul class=\"examples\"><li><strong><em>destruction of</strong>: the destruction of the rainforest</em></li><li><em>weapons of mass destruction</em></li><li><em>the environmental destruction caused by the road building programme</em></li><li><em>The floods brought death and destruction to the area.</em></li></ul></div>","1941":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧struc‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrʌktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">causing damage to people or things → destroy:</div><ul class=\"examples\"><li><em>the destructive power of modern weapons</em></li><li><strong><em>destructive to</strong>: What is good for the individual can be destructive to the family.</em></li></ul></div>","1942":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tach</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtætʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if you detach something, or if it detaches, it becomes separated from the thing it was attached to <em>OPP attach</em></div><ul class=\"examples\"><li><strong><em>detach something from something</strong>: You can detach the hood from the jacket.</em></li><li><em>Please detach and fill out the application form.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>detach yourself from somebody/something</strong> to try to be less involved in or less concerned about a situation:</div><ul class=\"examples\"><li><em>Doctors have to detach themselves from their feelings.</em></li></ul></div>","1943":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tail</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːteɪl $ dɪˈteɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a single feature, fact, or piece of information about something</div><ul class=\"examples\"><li><strong><em>detail of</strong>: She told me every detail of her trip.</em></li><li><strong><em>down to the smallest/last detail</strong> (=completely): Todd had planned the journey down to the smallest detail.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> all the separate features and pieces of information about something</div><ul class=\"examples\"><li><strong><em>in detail</strong>: He described the process in detail (=using a lot of details).</em></li><li><em>This issue will be discussed in more detail in Chapter 5.</em></li><li><em>McDougal was reluctant to go into detail (=give a lot of details) about the new deal.</em></li><li><em>Editing requires great attention to detail.</em></li><li><em>the fine detail of the plan</em></li><li><strong><em>have an eye for detail</strong> (=be skilled at noticing details): Photographers need to have an eye for detail.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>details</strong> <span class=\"gram\">[plural]</span> information that helps to complete what you know about something</div><ul class=\"examples\"><li><strong><em>detail of</strong>: Full details of the incident were recently revealed.</em></li><li><strong><em>detail about</strong>: She refused to give any details about what had happened.</em></li><li><em>Details of the course can be found on our website.</em></li><li><strong><em>further/more details</strong>: For further details, contact the personnel department.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular, uncountable]</span> <em>technical</em> a specific duty in the army, or the person or group with that duty:</div><ul class=\"examples\"><li><em>the security detail</em></li></ul></div>","1944":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tailed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːteɪld $ dɪˈteɪld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> containing or including a lot of information or details</div><ul class=\"examples\"><li><strong><em>detailed description/account/analysis etc</strong>: a detailed study of crime in Seattle</em></li><li><em>More detailed information is available on request.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having a lot of decorations or small features that are difficult to produce <em>SYN intricate</em>:</div><ul class=\"examples\"><li><em>a beautifully detailed carving</em></li></ul></div>","1945":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tain</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈteɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially prevent someone from leaving a place:</div><ul class=\"examples\"><li><em>Two suspects have been detained by the police for questioning.</em></li><li><em>She was detained in hospital with a suspected broken leg.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to stop someone from leaving as soon as they expected <em>SYN delay</em>: GRAMMAR Detain is often passive in this meaning.</div><ul class=\"examples\"><li><em>He was detained in Washington on urgent business.</em></li></ul></div>","1946":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tect</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to notice or discover something, especially something that is not easy to see, hear etc: ► see thesaurus at notice</div><ul class=\"examples\"><li><em>Many forms of cancer can be cured if detected early.</em></li><li><strong><em>difficult/impossible/easy/possible etc to detect</em></strong></li><li><strong><em>detect a change/difference</strong>: Dan detected a change in her mood.</em></li><li><strong><em>detect a note of sarcasm/irony/excitement etc</strong>: Do I detect a note of sarcasm in your voice?</em></li></ul></div>","1947":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtekʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when something is found that is not easy to see, hear etc, or the process of looking for it</div><ul class=\"examples\"><li><strong><em>detection of</strong>: Early detection of the disease is vital.</em></li><li><strong><em>escape/avoid detection</strong>: By flying low, the plane avoided detection by enemy radar.</em></li></ul></div>","1948":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tec‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtektɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a police officer whose job is to discover information about crimes and catch criminals → store detective</div><div class=\"sense\"><span class=\"snum\">2</span> (also private detective) someone who is paid to discover information about someone or something:</div><ul class=\"examples\"><li><em>She hired a detective to find out if her husband was having an affair.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>detective work</strong> efforts to discover information, find out how something works, answer a difficult question etc:</div><ul class=\"examples\"><li><em>It took a lot of detective work to discover the cause of the problem.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>detective story/novel etc</strong> a story etc about a crime, often a murder, and a detective who tries to find out who did it</div></div>","1949":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧tec‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtektə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a machine or piece of equipment that finds or measures something:</div><ul class=\"examples\"><li><em>a smoke detector</em></li><li><em>a metal detector</em></li></ul></div>","1950":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ten‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtenʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the state of being kept in prison</div><ul class=\"examples\"><li><strong><em>in detention</strong>: Willis was held in detention for five years.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a punishment in which children who have behaved badly are forced to stay at school for a short time after the others have gone home</div><ul class=\"examples\"><li><strong><em>in detention</strong>: She was always getting put in detention.</em></li></ul></div>","1951":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtɜː $ -ˈtɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle deterred, present participle deterring)</span></div><div class=\"entry-body\"><div class=\"sense\">to stop someone from doing something, by making them realize it will be difficult or have bad results → deterrent: RegisterIn everyday English, people usually say put someone off rather than deter someone:· Don’t let a few problems put you off.</div><ul class=\"examples\"><li><em>The company’s financial difficulties have deterred potential investors.</em></li><li><strong><em>deter somebody from (doing) something</strong>: The security camera was installed to deter people from stealing.</em></li></ul></div>","1952":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧te‧ri‧o‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtɪəriəreɪt $ -ˈtɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to become worse: RegisterIn everyday English, people usually say get worse rather than deteriorate:· Her health got worse.· The situation is getting worse.</div><ul class=\"examples\"><li><em>Ethel’s health has deteriorated.</em></li><li><em>America’s deteriorating economy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>deteriorate into something</strong> to develop into a bad or worse situation:</div><ul class=\"examples\"><li><em>The argument deteriorated into a fight.</em></li></ul></div>","1953":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ter‧mi‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˌtɜːməˈneɪʃən $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the quality of trying to do something even when it is difficult</div><ul class=\"examples\"><li><strong><em>determination to do something</strong>: Yuri shows great determination to learn English.</em></li><li><em>his dogged determination (=very strong determination) to succeed</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> the act of deciding something officially</div><ul class=\"examples\"><li><strong><em>determination of</strong>: the determination of government policy</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>formal</em> the act of finding the exact level, amount, or cause of something</div><ul class=\"examples\"><li><strong><em>determination of</strong>: accurate determination of the temperature</em></li></ul></div>","1954":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ter‧mine</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtɜːmɪn $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to find out the facts about something <em>SYN establish</em>:</div><ul class=\"examples\"><li><em>Investigators are still trying to determine the cause of the fire.</em></li><li><strong><em>determine how/what/who etc</strong>: The aim of the inquiry was to determine what had caused the accident.</em></li><li><strong><em>determine that</strong>: Experts have determined that the signature was forged.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something determines something else, it directly influences or decides it:</div><ul class=\"examples\"><li><em>The amount of available water determines the number of houses that can be built.</em></li><li><em>The age of a wine is a determining factor as to how it tastes.</em></li><li><strong><em>determine how/whether/what etc</strong>: How hard the swimmers work now will determine how they perform in the Olympics.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to officially decide something: ► see thesaurus at decide</div><ul class=\"examples\"><li><em>The date of the court case has not yet been determined.</em></li><li><strong><em>determine how/what/who etc</strong>: The tests will help the doctors determine what treatment to use.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>determine to do something</strong> <em>formal</em> to decide to do something:</div><ul class=\"examples\"><li><em>We determined to leave at once.</em></li></ul></div>","1955":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ter‧mined</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈtɜːmɪnd $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having a strong desire to do something, so that you will not let anyone stop you:</div><ul class=\"examples\"><li><em>Gwen is a very determined woman.</em></li><li><strong><em>determined to do something</strong>: She was determined to win.</em></li><li><strong><em>determined (that)</strong>: He was determined that the same mistakes would not be repeated.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> showing determination, especially in a difficult situation</div><ul class=\"examples\"><li><strong><em>determined attempt/effort</strong>: She was making a determined effort to give up smoking.</em></li><li><em>The library was closed down despite determined opposition.</em></li></ul></div>","1956":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧ter‧rent</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈterənt $ -ˈtɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that makes someone less likely to do something, by making them realize it will be difficult or have bad results:</div><ul class=\"examples\"><li><em>The small fines for this type of crime do not act as much of a deterrent.</em></li><li><strong><em>deterrent to/for/against</strong>: Window locks are an effective deterrent against burglars.</em></li><li><em>the deterrent effect of prison sentences</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>nuclear deterrent</strong> the nuclear weapons that a country has in order to prevent other countries from attacking it</div></div>","1957":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> det‧ri‧men‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdetrəˈmentl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">causing harm or damage <em>SYN harmful</em> <em>, damaging</em> ► see thesaurus at harmful</div><ul class=\"examples\"><li><strong><em>detrimental to</strong>: Smoking is detrimental to your health.</em></li><li><em>the detrimental effect of pollution on the environment</em></li></ul></div>","1958":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dev‧a‧state</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdevəsteɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone feel extremely shocked and sad:</div><ul class=\"examples\"><li><em>Rob was devastated by the news of her death.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to damage something very badly or completely: ► see thesaurus at destroy</div><ul class=\"examples\"><li><em>The city centre was devastated by the bomb.</em></li></ul></div>","1959":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dev‧a‧stat‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdevəsteɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">feeling extremely shocked and sad: ► see thesaurus at sad, shocked</div><ul class=\"examples\"><li><em>She was left feeling totally devastated.</em></li></ul></div>","1960":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dev‧a‧stat‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdevəsteɪtɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> badly damaging or destroying something</div><ul class=\"examples\"><li><strong><em>devastating effect/impact</strong>: Acid rain has a devastating effect on the forest.</em></li><li><strong><em>devastating results/consequences</strong>: The oil spill had devastating consequences for wildlife.</em></li><li><em>It will be a devastating blow for the town if the factory closes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> making someone feel extremely sad or shocked:</div><ul class=\"examples\"><li><em>He was in Nice when he heard the devastating news.</em></li><li><em>Long-term unemployment can be devastating.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> very impressive or effective:</div><ul class=\"examples\"><li><em>In a devastating display of military muscle, soldiers seized the town.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> extremely attractive:</div><ul class=\"examples\"><li><em>a devastating smile</em></li></ul></div>","1961":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vel‧op</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈveləp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[grow]</strong> <span class=\"gram\">[intransitive, transitive]</span> to grow or change into something bigger, stronger, or more advanced, or to make someone or something do this → advance:</div><ul class=\"examples\"><li><em>Knowledge in the field of genetics has been developing very rapidly.</em></li><li><em>Corsica has developed its economy around the tourist industry.</em></li><li><strong><em>develop into</strong>: Chicago developed into a big city in the late 1800s.</em></li><li><strong><em>develop from</strong>: It’s hard to believe that a tree can develop from a small seed.</em></li><li><em>exercises to develop muscle strength</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[new idea/product]</strong> <span class=\"gram\">[transitive]</span> to design or make a new idea, product, system etc over a period of time: ► see thesaurus at make</div><ul class=\"examples\"><li><em>Scientists are developing new drugs to treat arthritis.</em></li><li><em>She should have developed her own style instead of copying him.</em></li><li><em>Researchers are developing technology for the US military.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[feeling]</strong> <span class=\"gram\">[transitive]</span> to start to have a feeling or quality that then becomes stronger:</div><ul class=\"examples\"><li><em>He had developed a certain affection for me.</em></li><li><strong><em>develop a sense/awareness/knowledge of something</strong>: The children are beginning to develop a sense of responsibility.</em></li><li><em>It was in college that he developed a taste for (=started to like) rugby football.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[skill/ability]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you develop a skill or ability, or if it develops, it becomes stronger or more advanced:</div><ul class=\"examples\"><li><em>The course is designed to help students develop their speaking skills.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[disease]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you develop a disease or illness, or if it develops, you start to have it:</div><ul class=\"examples\"><li><em>Some alcoholics develop liver disease.</em></li><li><em>Pneumonia can develop very quickly.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[fault/problem]</strong> <span class=\"gram\">[transitive]</span> to begin to have a physical fault:</div><ul class=\"examples\"><li><em>The oil tank had developed a small crack.</em></li><li><em>The plane developed engine trouble and was forced to land.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[problem/difficulty]</strong> <span class=\"gram\">[intransitive]</span> if a problem or difficult situation develops, it begins to happen or exist, or it gets worse:</div><ul class=\"examples\"><li><em>Trouble is developing in the cities.</em></li><li><strong><em>develop into</strong>: Regional clashes could develop into larger quarrels.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[idea/argument]</strong> <span class=\"gram\">[transitive]</span> to make an argument or idea clearer, by studying it more or by speaking or writing about it in more detail:</div><ul class=\"examples\"><li><em>We will develop a few of these points in the seminar.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[land]</strong> <span class=\"gram\">[transitive]</span> to use land for the things that people need, for example by taking minerals out of it or by building on it:</div><ul class=\"examples\"><li><em>The land was developed for low-cost housing.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[photography]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a photograph out of a photographic film, using chemicals:</div><ul class=\"examples\"><li><em>Did you ever get the pictures developed?</em></li></ul></div>","1962":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vel‧oped</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈveləpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a developed country is one of the rich countries of the world with many industries, comfortable living for most people, and usually an elected government → developing, underdeveloped:</div><ul class=\"examples\"><li><em>energy consumption in the developed world</em></li><li><strong><em>developed countries/nations</em></strong></li><li><em>The charity works with children in less developed countries.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a developed sense, system etc, is better, larger, or more advanced than others:</div><ul class=\"examples\"><li><em>Dogs have a highly developed sense of smell.</em></li><li><em>plants with well-developed root systems</em></li><li><em>Labour has a more fully developed programme for the unemployed.</em></li></ul></div>","1963":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vel‧op‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈveləpə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a person or company that makes money by buying land and then building houses, factories etc on it:</div><ul class=\"examples\"><li><em>a Florida property developer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a person or an organization that works on a new idea, product etc to make it successful:</div><ul class=\"examples\"><li><em>software developers</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a chemical substance used for making images appear on film or photographic paper</div></div>","1964":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vel‧op‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈveləpɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a developing country is a poor country that is trying to increase its industry and trade and improve life for its people → developed, underdeveloped</div><ul class=\"examples\"><li><strong><em>developing countries/nations</strong>: aid to developing countries</em></li><li><em>poverty and hunger in the developing world</em></li><li><strong><em>developing economies/markets</strong>: the developing economies in Eastern Europe</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> growing or changing:</div><ul class=\"examples\"><li><em>the growth of the developing embryo</em></li><li><em>a developing crisis in Washington</em></li></ul></div>","1965":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vel‧op‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈveləpmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[growth]</strong> <span class=\"gram\">[uncountable]</span> the process of gradually becoming bigger, better, stronger, or more advanced:</div><ul class=\"examples\"><li><em>child development</em></li><li><strong><em>development of</strong>: a course on the development of Greek thought</em></li><li><strong><em>professional/personal development</strong>: opportunities for professional development</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[economic activity]</strong> <span class=\"gram\">[uncountable]</span> the process of increasing business, trade, and industrial activity</div><ul class=\"examples\"><li><strong><em>economic/industrial/business etc development</strong>: economic development in Russia</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[event]</strong> <span class=\"gram\">[countable]</span> a new event or piece of news that changes a situation:</div><ul class=\"examples\"><li><em>recent political developments in the former Soviet Union</em></li><li><em>We will keep you informed of developments.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[new plan/product]</strong> <span class=\"gram\">[uncountable]</span> the process of working on a new product, plan, idea etc to make it successful:</div><ul class=\"examples\"><li><em>The funds will be used for marketing and product development.</em></li><li><strong><em>under/in development</strong>: Spielberg has several interesting projects under development.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[improvement]</strong> <span class=\"gram\">[countable]</span> a change that makes a product, plan, idea etc better:</div><ul class=\"examples\"><li><em>There have been significant computer developments during the last decade.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[building process]</strong> <span class=\"gram\">[uncountable]</span> the process of planning and building new houses, streets etc on land</div><ul class=\"examples\"><li><strong><em>for development</strong>: The land was sold for development.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[houses/offices etc]</strong> <span class=\"gram\">[countable]</span> a group of new buildings that have all been planned and built together on the same piece of land:</div><ul class=\"examples\"><li><em>a new housing development</em></li></ul></div>","1966":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vel‧op‧men‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˌveləpˈmentl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">relating to the development of someone or something:</div><ul class=\"examples\"><li><em>the developmental stages of childhood</em></li><li><em>Higher education is a continuing developmental process.</em></li></ul></div>","1967":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vi‧a‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdiːviˈeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a noticeable difference from what is expected or acceptable</div><ul class=\"examples\"><li><strong><em>deviation from</strong>: deviation from the normal procedure</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>technical</em> the difference between a number or measurement in a set and the average of all the numbers or measurements in that set</div></div>","1968":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vice</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈvaɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a machine or tool that does a special job <em>SYN gadget</em>:</div><ul class=\"examples\"><li><em>modern labour-saving devices</em></li><li><strong><em>device for doing something</strong>: a device for separating metal from garbage</em></li><li><strong><em>device to do something</strong>: The company makes devices to detect carbon monoxide.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a special way of doing something that makes it easier to do</div><ul class=\"examples\"><li><strong><em>device for doing something</strong>: Testing yourself with information on cards is a useful device for studying.</em></li><li><em>a memory device</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a plan or trick, especially for a dishonest purpose</div><ul class=\"examples\"><li><strong><em>device to do something</strong>: Their proposal was only a device to confuse the opposition.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a bomb or other explosive weapon</div><ul class=\"examples\"><li><strong><em>explosive/nuclear/incendiary etc device</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">5</span> the special use of words in literature, or of words, lights etc in a play, to achieve an effect:</div><ul class=\"examples\"><li><em>Metaphor is a common literary device.</em></li></ul></div>","1969":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dev‧il</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdevəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the devil</strong> (also the Devil) the most powerful evil spirit in some religions, especially in Christianity <em>SYN Satan</em></div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an evil spirit <em>SYN demon</em>:</div><ul class=\"examples\"><li><em>The villagers believed a devil had taken control of his body.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>speak of the devil</strong> (also talk of the devil<em>British English</em>) <em>spoken</em> used when someone you have just been talking about walks into the room where you are</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>poor/lucky/handsome etc devil</strong> <em>spoken</em> used to talk about someone who you feel sorry for, who is lucky etc:</div><ul class=\"examples\"><li><em>What on earth is wrong with the poor devil?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>little/old devil</strong> <em>spoken</em> used to talk about a child or an older man who behaves badly, but who you like:</div><ul class=\"examples\"><li><em>He’s a naughty little devil.</em></li><li><em>I really miss the old devil.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be a devil</strong> <em>British English</em> <em>spoken</em> used to persuade someone to do something they are not sure they should do:</div><ul class=\"examples\"><li><em>Go on, be a devil, have another gin and tonic.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>what/who/why etc the devil?</strong> <em>old-fashioned</em> <em>spoken</em> used to show that you are surprised or annoyed:</div><ul class=\"examples\"><li><em>How the devil should I know what she’s thinking?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>a devil of a time/job etc</strong> <em>old-fashioned</em> <em>spoken</em> a difficult or unpleasant time, job etc:</div><ul class=\"examples\"><li><em>We had a devil of a job trying to get the carpet clean again.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>go to the devil!</strong> <em>old-fashioned</em> <em>spoken</em> used to tell someone rudely to go away or stop annoying you</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>do something like the devil</strong> <em>old-fashioned</em> <em>spoken</em> to do something very fast or using a lot of force:</div><ul class=\"examples\"><li><em>They rang the bell and ran like the devil.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>better the devil you know (than the devil you don’t)</strong> used to say that it is better to deal with someone or something you know, even if you do not like them, than to deal with someone or something new that might be worse</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>between the devil and the deep blue sea</strong> in a difficult situation because there are only two choices you can make and both of them are unpleasant</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>... and the devil take the hindmost</strong> used to say that everyone in a situation only cares about what happens to themselves and does not care about other people</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>the devil makes/finds work for idle hands</strong> used to say that people who do not have enough to do will start to do bad things</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>the devil is in the detail</strong> used to say that the details of a plan, agreement etc are very important and may result in problems</div></div>","1970":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vi‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːviəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> using dishonest tricks and deceiving people in order to get what you want → deceitful: ► see thesaurus at dishonest</div><ul class=\"examples\"><li><em>a devious politician</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> not going in the most direct way to get to a place <em>SYN circuitous</em>:</div><ul class=\"examples\"><li><em>a devious route</em></li></ul></div>","1971":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vise</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈvaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to plan or invent a new way of doing something: ► see thesaurus at invent</div><ul class=\"examples\"><li><em>She devised a method for quicker communications between offices.</em></li></ul></div>","1972":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vote</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈvəʊt $ -ˈvoʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to use all or most of your time, effort etc in order to do something or help someone <em>SYN dedicate</em> RegisterIn everyday English, people usually say put time/energy etc into something rather than devote time/energy etc to something:· He put a lot of time into the project.</div><ul class=\"examples\"><li><strong><em>devote your time/energy/attention etc to something</strong>: He devoted his energies to writing films.</em></li><li><strong><em>devote yourself to something</strong>: She devoted herself full-time to her business.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to use a particular area, period of time, or amount of space for a specific purpose</div><ul class=\"examples\"><li><strong><em>devote something to something</strong>: The meeting will be devoted to health and safety issues.</em></li></ul></div>","1973":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vot‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈvəʊtɪd $ -ˈvoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> giving someone or something a lot of love and attention:</div><ul class=\"examples\"><li><em>a devoted father</em></li><li><strong><em>devoted to</strong>: Isabella was devoted to her brother.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> dealing with, containing, or being used for only one thing <em>SYN dedicated</em></div><ul class=\"examples\"><li><strong><em>devoted to</strong>: a museum devoted to photography</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> strongly supporting someone or something because you admire or enjoy them:</div><ul class=\"examples\"><li><em>Beckham’s devoted fans</em></li><li><em>The journal had a devoted following of around 1,000 subscribers.</em></li></ul></div>","1974":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vo‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈvəʊʃən $ -ˈvoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the strong love that you show when you pay a lot of attention to someone or something</div><ul class=\"examples\"><li><strong><em>devotion to</strong>: Alanna has always shown intense devotion to her children.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the loyalty that you show towards a person, job etc, especially by working hard → dedication</div><ul class=\"examples\"><li><strong><em>devotion to</strong>: the soldier’s courage and devotion to duty / his integrity and devotion to his patients</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> strong religious feeling</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>devotions</strong> <span class=\"gram\">[plural]</span> prayers and other religious acts</div></div>","1975":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> de‧vour</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈvaʊə $ -ˈvaʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to eat something quickly because you are very hungry: ► see thesaurus at eat</div><ul class=\"examples\"><li><em>The boys devoured their pancakes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to read something quickly and eagerly, or watch something with great interest:</div><ul class=\"examples\"><li><em>He devoured science fiction books.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be devoured by something</strong> to be filled with a strong feeling that seems to control you:</div><ul class=\"examples\"><li><em>Cindy felt devoured by jealousy.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> to destroy someone or something:</div><ul class=\"examples\"><li><em>Her body had been almost entirely devoured by the disease.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to use up all of something:</div><ul class=\"examples\"><li><em>a job that devours all my energy</em></li></ul></div>","1976":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ag‧nose</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪəɡnəʊz $ -noʊs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to find out what illness someone has, or what the cause of a fault is, after doing tests, examinations etc</div><ul class=\"examples\"><li><strong><em>diagnose somebody as (having) something</strong>: Joe struggled in school before he was diagnosed as dyslexic.</em></li><li><strong><em>diagnose something as something</strong>: The illness was diagnosed as mumps.</em></li><li><strong><em>diagnose somebody with something</strong>: She was diagnosed with breast cancer.</em></li></ul></div>","1977":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ag‧no‧sis</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdaɪəɡˈnəʊsɪs $ -ˈnoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural diagnoses /-siːz/)</span></div><div class=\"entry-body\"><div class=\"sense\">the process of discovering exactly what is wrong with someone or something, by examining them closely → prognosis</div><ul class=\"examples\"><li><strong><em>diagnosis of</strong>: diagnosis of kidney disease</em></li><li><em>An exact diagnosis can only be made by obtaining a blood sample.</em></li></ul></div>","1978":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ag‧nos‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdaɪəɡˈnɒstɪk◂ $ -ˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">relating to or used for discovering what is wrong with someone or something</div><ul class=\"examples\"><li><strong><em>diagnostic tests/tools</strong>: Doctors depend on accurate diagnostic tools.</em></li></ul></div>","1979":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ag‧o‧nal</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈæɡənəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a diagonal line is straight and joins two opposite corners of a flat shape, usually a square → horizontal, vertical</div><div class=\"sense\"><span class=\"snum\">2</span> following a sloping angle:</div><ul class=\"examples\"><li><em>diagonal parking spaces</em></li></ul></div>","1980":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧a‧gram</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪəɡræm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a simple drawing or plan that shows exactly where something is, what something looks like, or how something works</div><ul class=\"examples\"><li><strong><em>diagram of</strong>: a diagram of the heating system</em></li></ul></div>","1981":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the round part of a clock, watch, machine etc that has numbers that show you the time or a measurement:</div><ul class=\"examples\"><li><em>The lighted dial of her watch said 1.20.</em></li><li><em>She looked at the dial to check her speed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the part of a piece of equipment such as a radio or thermostat that you turn around to do something, such as find a different station or change the temperature:</div><ul class=\"examples\"><li><em>The dial on the heater was set to ‘HOT’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the wheel on an older telephone with numbered holes for your fingers that you move around in order to make a call</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle dialled, present participle dialling British English, dialed, dialing American English)</span></div><div class=\"entry-body\"><div class=\"sense\">to press the buttons or turn the dial on a telephone in order to make a telephone call:</div><ul class=\"examples\"><li><em>I think I dialed the wrong number.</em></li></ul></div></div>","1982":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧a‧lect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪəlekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a form of a language which is spoken only in one area, with words or grammar that are slightly different from other forms of the same language → accent</div><ul class=\"examples\"><li><strong><em>Chinese/Yorkshire etc dialect</strong>: The people up there speak a Tibetan dialect.</em></li><li><em>the local dialect</em></li></ul></div>","1983":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧a‧logue</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪəlɒɡ $ -lɒːɡ, -lɑːɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a conversation in a book, play, or film:</div><ul class=\"examples\"><li><em>a boring movie full of bad dialog</em></li><li><em>Students were asked to read simple dialogues out loud.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> a discussion between two groups, countries etc</div><ul class=\"examples\"><li><strong><em>dialogue between/with</strong>: There is a need for constructive dialogue between leaders.</em></li></ul></div>","1984":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧am‧e‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈæmɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a straight line from one side of a circle to the other side, passing through the centre of the circle, or the length of this line</div><ul class=\"examples\"><li><strong><em>3 inches/1 metre etc in diameter</strong>: Draw a circle six centimetres in diameter.</em></li><li><strong><em>diameter of</strong>: The diameter of the Earth is about 13,000 km.</em></li></ul></div>","1985":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧a‧mond</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪəmənd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a clear, very hard valuable stone, used in jewellery and in industry:</div><ul class=\"examples\"><li><em>a diamond engagement ring</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a shape with four straight but sloping sides of equal length, with one point facing directly up and the other directly down:</div><ul class=\"examples\"><li><em>Cut the cookie dough into diamonds.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>diamonds</strong> one of the four suits (=types of cards) in a set of playing cards, which has the design of a red diamond shape on it</div><ul class=\"examples\"><li><strong><em>two/queen etc of diamonds</strong>: the ace of diamonds</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> a card from this suit:</div><ul class=\"examples\"><li><em>You have to play a diamond.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the area in a baseball field that is within the diamond shape formed by the four bases</div><div class=\"subsense\"><span class=\"subnum\">b)</span> the whole playing field used in baseball</div></div>","1986":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧a‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪəri $ ˈdaɪri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural diaries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a book in which you write down the things that happen to you each day <em>SYN journal</em>:</div><ul class=\"examples\"><li><em>Inge kept a diary (=wrote in a diary) during the war years.</em></li><li><strong><em>diary entry</strong> (=what you have written for a particular day)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>especially British English</em> a book with separate spaces for each day of the year, in which you write down the meetings, events etc that are planned for each day SYN calendar<em>American English</em>:</div><ul class=\"examples\"><li><em>Did you put the meeting date in your diary?</em></li></ul></div>","1987":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural dice)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> (also die) a small block of wood, plastic etc that has six sides with a different number of spots on each side, used in games</div><ul class=\"examples\"><li><strong><em>throw/roll the dice</strong>: It’s your turn to roll the dice.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> any game of chance that is played with dice</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the dice are loaded</strong> the situation is arranged so that a particular person will win or gain an advantage</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>no dice</strong> <em>especially American English</em> <em>old-fashioned</em> <em>spoken</em> used to refuse to do something or to say that something is not possible:</div><ul class=\"examples\"><li><em>‘Can I borrow some cash?’ ‘Sorry, no dice.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a throw of the dice</strong> something you do that you hope will have an effect on a situation, but is not certain to do so:</div><ul class=\"examples\"><li><em>a last desperate throw of the dice to try and win his wife back</em></li></ul></div>","1988":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dic‧tate</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪkˈteɪt $ ˈdɪkteɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to say words for someone else to write down</div><ul class=\"examples\"><li><strong><em>dictate a letter/memo etc to somebody</strong>: She’s dictating a letter to her secretary right now.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to tell someone exactly what they must do or how they must behave</div><ul class=\"examples\"><li><strong><em>dictate to</strong>: The media cannot be allowed to dictate to the government.</em></li><li><strong><em>dictate who/what/how etc</strong>: Can they dictate how the money will be spent?</em></li><li><em>Federal funds have to be used as dictated by Washington.</em></li><li><strong><em>dictate that</strong>: Islamic custom dictates that women should be fully covered.</em></li><li><em>The US government attempted to dictate the terms of the agreement.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to control or influence something <em>SYN determine</em></div><ul class=\"examples\"><li><strong><em>dictate what/how etc</strong>: Funds dictate what we can do.</em></li><li><strong><em>dictate that</strong>: The laws of physics dictate that what goes up must come down.</em></li><li><em>The massive publicity dictated a response from the city government.</em></li></ul></div>","1989":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dic‧ta‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪkˈteɪtə $ ˈdɪkteɪtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a ruler who has complete power over a country, especially one whose power has been gained by force:</div><ul class=\"examples\"><li><em>the downfall of the hated dictator</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who tells other people what they should do, in a way that seems unreasonable:</div><ul class=\"examples\"><li><em>a real little dictator</em></li></ul></div>","1990":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dic‧ta‧tor‧ship</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪkˈteɪtəʃɪp $ -ˈteɪtər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> government by a ruler who has complete power ► see thesaurus at government</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a country that is ruled by one person who has complete power</div></div>","1991":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dic‧tion‧a‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪkʃənəri $ -neri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural dictionaries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a book that gives a list of words in alphabetical order and explains their meanings in the same language, or another language:</div><ul class=\"examples\"><li><em>a German – English dictionary</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a book that explains the words and phrases used in a particular subject:</div><ul class=\"examples\"><li><em>a science dictionary</em></li></ul></div>","1992":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span><span class=\"meta-item\">(past tense and past participle died, present participle dying, third person singular dies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[become dead]</strong> to stop living and become dead: GRAMMAR: Prepositions with die• Someone dies of or from a disease or injury: · He died of a heart attack.· He died from a heart attack. Die of is more common than die from. ✗Don’t say: He died because of a heart attack.• Someone dies in an accident: · He died in a car crash. ✗Don’t say: He died by a car crash.• Someone dies for a person, place, or idea that they want to protect: · These men died for our freedom.</div><ul class=\"examples\"><li><em>He died in 1985 at the age of 76.</em></li><li><em>Her father died suddenly in an accident when she was only ten.</em></li><li><strong><em>die of/from</strong>: The animals died of starvation in the snow. / patients who are dying from cancer</em></li><li><em>She died peacefully in her sleep at the age of 98.</em></li><li><strong><em>die for something</strong> (=be killed while fighting to defend something): Do you believe in anything enough to die for it?</em></li><li><strong><em>die young/happy/poor</strong>: She died young, at the age of 27.</em></li><li><em>The bullet went straight through his head, and he died instantly.</em></li><li><strong><em>to your dying day/until the day you die</strong> (=until you die): It must remain a secret until the day I die.</em></li><li><strong><em>somebody’s dying breath/wish</strong> (=someone’s last breath or wish): It was his dying wish that the house be opened to the public.</em></li><li><strong><em>die a hero/martyr/rich man etc</strong>: My uncle died a hero.</em></li><li><strong><em>die a natural/violent/agonizing death</strong>: Did she die a natural death? (=did she die naturally, or did someone kill her?)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[disappear]</strong> to disappear or stop existing:</div><ul class=\"examples\"><li><em>Our love will never die.</em></li><li><em>The family name will die with him (=disappear when he dies).</em></li><li><em>He’s one of a dying breed (=a type of person that is no longer common).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[machines]</strong> <em>informal</em> to stop working <em>SYN break down</em>:</div><ul class=\"examples\"><li><em>The engine spluttered and died.</em></li><li><strong><em>die on somebody</strong> (=stop working while they are using it): The mower just died on me.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be dying for something/to do something</strong> <em>spoken</em> to want something very much:</div><ul class=\"examples\"><li><em>I’m dying for a cup of tea.</em></li><li><em>She was dying to ask where he’d got it.</em></li><li><em>I’m dying to see what it is.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be dying of hunger/thirst/boredom</strong> <em>spoken</em> to be very hungry, thirsty, bored etc:</div><ul class=\"examples\"><li><em>Do you fancy a cup of tea? I’m dying of thirst.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>I nearly died/I could have died</strong> <em>spoken</em> used to say that you felt very surprised or embarrassed:</div><ul class=\"examples\"><li><em>I nearly died when I saw it was my ex-husband!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>die of embarrassment/shame</strong> to be very embarrassed or ashamed:</div><ul class=\"examples\"><li><em>The room was such a mess, I just died of embarrassment.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>I’d rather die</strong> <em>spoken</em> used to say very strongly that you do not want to do something:</div><ul class=\"examples\"><li><em>I’d rather die than work for him!</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>in the dying minutes/seconds/moments (of something)</strong> during the last minutes or seconds before the end of something:</div><ul class=\"examples\"><li><em>United scored an equaliser in the dying minutes of the game.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>old habits/traditions/customs die hard</strong> used to say that it takes a long time to change to a new way of doing something</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>never say die</strong> <em>spoken</em> used to encourage someone to continue doing something that is difficult</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>die a/the death</strong> <em>informal</em> to gradually fail or be forgotten:</div><ul class=\"examples\"><li><em>The rumour gradually died a death.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>die laughing</strong> <em>spoken</em> to laugh a lot:</div><ul class=\"examples\"><li><em>We nearly died laughing when he told us.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>to die for</strong> <em>informal</em> extremely nice, attractive, or desirable:</div><ul class=\"examples\"><li><em>She had hair to die for.</em></li></ul></div>","1993":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> die‧sel</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdiːzəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a type of heavy oil used instead of petrol in engines, especially in trucks, buses, and trains:</div><ul class=\"examples\"><li><em>a 1.9 litre diesel engine</em></li><li><strong><em>diesel car/truck etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>informal</em> a vehicle that uses diesel</div></div>","1994":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧et</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a way of eating in which you only eat certain foods, in order to lose weight, or to improve your health:</div><ul class=\"examples\"><li><em>Lyn always seems to be on a diet.</em></li><li><em>a salt-free diet</em></li><li><em>Not all diets are good for you.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the kind of food that a person or animal eats each day</div><ul class=\"examples\"><li><em>She doesn’t eat a very healthy diet.</em></li><li><em>It is important to have a balanced diet.</em></li><li><em>the effects of poor diet and lack of exercise</em></li><li><em>Rice is the staple diet (=the main food that a group of people usually eat).</em></li><li><em>Studies have shown the benefits of a vegetarian diet.</em></li><li><strong><em>diet of</strong>: They exist on a diet of fish.</em></li><li><strong><em>in somebody’s diet</strong>: the importance of vitamins and minerals in your diet</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a diet of something</strong> too much of an activity that you think is boring or has bad effects:</div><ul class=\"examples\"><li><em>Kids today are raised on a constant diet of pop music and television.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>old-fashioned</em> an official meeting to discuss political or church matters</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to limit the amount and type of food that you eat, in order to become thinner <em>SYN slim</em></div></div></div>","1995":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧e‧ta‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪətəri $ -teri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">related to the food someone eats → nutritional:</div><ul class=\"examples\"><li><em>special dietary requirements</em></li></ul></div>","1996":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dif‧fer</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪfə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to be different from something in some way:</div><ul class=\"examples\"><li><em>The two systems differ in many respects.</em></li><li><strong><em>differ from</strong>: People differ from one another in their ability to handle stress.</em></li><li><strong><em>differ between</strong>: The symptoms did not differ between the two groups.</em></li><li><strong><em>differ widely/greatly/significantly etc</strong>: We soon found that prices differed enormously.</em></li><li><em>Experts have differing views on the subject.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if two people or groups differ about something, they have opposite opinions <em>SYN disagree</em> ► see thesaurus at disagree</div><ul class=\"examples\"><li><strong><em>differ about/on/over</strong>: The two lawyers differed about how to present the case.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>agree to differ</strong> to stop arguing with someone and accept that you will never agree</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>I beg to differ</strong> <em>spoken</em> <em>formal</em> used to say that you disagree with someone</div></div>","1997":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dif‧fe‧rence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪfərəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a way in which two or more people or things are not like each other <em>OPP similarity</em></div><ul class=\"examples\"><li><strong><em>difference between</strong>: There’s a big difference between knowing that something is true, and being able to prove it. / There is very little difference between the parties on green issues. / Do children know the difference between right and wrong?</em></li><li><strong><em>difference in</strong>: Researchers found a number of important differences in the way boys and girls learn.</em></li><li><em>There’s a world of difference (=there’s a very big difference) between being alone and being lonely.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> the amount by which one thing is greater or smaller than another → split the difference at split1(9)</div><ul class=\"examples\"><li><strong><em>difference in age/size etc</strong>: There’s not much difference in price.</em></li><li><em>There’s a five-hour time difference between London and New York.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>make a/the difference</strong> to have an important effect or influence on something or someone:</div><ul class=\"examples\"><li><em>Whatever she did, it made no difference.</em></li><li><strong><em>difference to</strong>: One more person wouldn’t make any difference to the arrangements.</em></li><li><strong><em>difference between</strong>: It could make the difference between missing your train and getting to work on time.</em></li><li><em>Having a good teacher has made all the difference for Alex (=had an important influence).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>it makes no difference to somebody</strong> used to say that it does not matter to someone which thing happens, is chosen etc:</div><ul class=\"examples\"><li><em>Morning or afternoon. It makes no difference to me.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>our/your/their differences</strong> disagreements:</div><ul class=\"examples\"><li><em>We’ve had our differences in the past.</em></li><li><strong><em>settle/resolve your differences</strong> (=agree not to argue anymore)</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>difference of opinion</strong> a slight disagreement:</div><ul class=\"examples\"><li><em>There have been some differences of opinion as to exactly how the money should be spent.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>with a difference</strong> <em>informal</em> used to describe something which is interesting or unusual, especially in a good way:</div><ul class=\"examples\"><li><em>an adventure holiday with a difference</em></li></ul></div>","1998":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dif‧fe‧rent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪfərənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not like something or someone else, or not like before <em>OPP similar</em> GRAMMAR: Prepositions with different• You usually say different from: · Their home is different from ours.• In American English, people also say different than: · Their home is different than ours.• In spoken British English, people also say different to: · Their home is different to ours. ✗Don’t say: Their home is different of ours.</div><ul class=\"examples\"><li><strong><em>different from</strong>: Our sons are very different from each other.</em></li><li><strong><em>different to</strong>: Her jacket’s different to mine.</em></li><li><strong><em>different than<em>American English</em></strong>: He seemed different than he did in New York.</em></li><li><em>The place looks completely different now.</em></li><li><em>They decided to try a radically different approach.</em></li><li><em>We found women had significantly different political views from men.</em></li><li><em>a slightly different way of doing things</em></li><li><em>What actually happened was subtly different from the PR people’s version.</em></li><li><em>The show is refreshingly different from most exhibitions of modern art.</em></li><li><em>The publishing business is no different from any other business in this respect.</em></li><li><em>It’s a different world here in London.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> used to talk about two or more separate things of the same basic kind <em>SYN various</em>:</div><ul class=\"examples\"><li><em>Different people reacted in different ways.</em></li><li><strong><em>different types/kinds etc</strong>: There are many different types of fabric.</em></li><li><em>I looked in lots of different books but couldn’t find anything about it.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> another:</div><ul class=\"examples\"><li><em>I think she’s moved to a different job now.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>spoken</em> unusual, often in a way that you do not like:</div><ul class=\"examples\"><li><em>‘What did you think of the film?’ ‘Well, it was certainly different.’</em></li></ul></div>","1999":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dif‧fe‧ren‧ti‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪfəˈrenʃieɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to recognize or express the difference between things or people <em>SYN distinguish</em></div><ul class=\"examples\"><li><strong><em>differentiate between</strong>: It’s important to differentiate between fact and opinion.</em></li><li><strong><em>differentiate something from something</strong>: It’s sometimes hard to differentiate one sample from another.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to be the quality, feature etc that makes one thing or person clearly different from another <em>SYN distinguish</em>:</div><ul class=\"examples\"><li><em>What differentiates these two periods of history?</em></li><li><strong><em>differentiate something from something</strong>: Its unusual nesting habits differentiate this bird from others.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to behave differently towards someone or something, especially in an unfair way <em>SYN discriminate</em></div><ul class=\"examples\"><li><strong><em>differentiate between</strong>: a policy which differentiates between men and women</em></li></ul></div>","2000":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dif‧fi‧cult</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪfɪkəlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> hard to do, understand, or deal with <em>OPP easy</em>:</div><ul class=\"examples\"><li><em>a difficult question</em></li><li><em>an immensely difficult task</em></li><li><em>Was the exam very difficult?</em></li><li><em>It’s difficult to see how more savings can be made.</em></li><li><strong><em>difficult (for somebody) to understand/find/obtain etc</strong>: That’s rather difficult for me to explain. / He’s finding it difficult to get a job.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> involving a lot of problems and causing a lot of trouble or worry:</div><ul class=\"examples\"><li><em>a difficult situation</em></li><li><em>Things are a bit difficult at home at the moment.</em></li><li><em>There could be difficult times ahead.</em></li><li><strong><em>make life/things difficult for somebody</strong> (=cause problems for someone): She’s doing everything she can to make life difficult for him.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is difficult never seems pleased or satisfied <em>SYN awkward</em>:</div><ul class=\"examples\"><li><em>Don’t be so difficult!</em></li><li><em>a difficult customer</em></li></ul></div>","2001":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dif‧fi‧cul‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪfɪkəlti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(plural difficulties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> if you have difficulty doing something, it is difficult for you to do ► Do not say that someone ‘has difficulty to do something’. Say that someone has difficulty doing something or has difficulty in doing something.</div><ul class=\"examples\"><li><strong><em>have/experience difficulty (in) doing something</strong>: They had great difficulty in finding a replacement.</em></li><li><strong><em>with/without difficulty</strong>: He got to his feet with difficulty.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> a problem or something that causes trouble</div><ul class=\"examples\"><li><strong><em>difficulty with</strong>: There are several difficulties with this theory.</em></li><li><em>If you have any difficulties, give me a call.</em></li><li><em>The project soon ran into difficulties.</em></li><li><em>Difficulties can arise when there is more than one defendant.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> if you are in difficulty, you are in a situation in which you have problems</div><ul class=\"examples\"><li><strong><em>in difficulty</strong>: The business is in financial difficulty.</em></li><li><strong><em>get/run into difficulty</strong> (=get into a difficult situation): She soon got into difficulty with debt.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the quality of being difficult to do</div><ul class=\"examples\"><li><strong><em>the difficulty of (doing) something</strong>: the difficulty of solving such problems</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> how difficult something is:</div><ul class=\"examples\"><li><em>The tests vary in difficulty.</em></li></ul></div>","2002":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\">(past tense and past participle dug /dʌɡ/, present participle digging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to move earth, snow etc, or to make a hole in the ground, using a spade or your hands</div><ul class=\"examples\"><li><strong><em>dig a hole/trench/grave etc</strong>: They dig a small hole in the sand to bury their eggs.</em></li><li><strong><em>dig down</strong>: Dig down about 6 inches.</em></li><li><strong><em>dig for</strong>: birds digging for worms</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to remove something, especially vegetables, from the ground using a spade:</div><ul class=\"examples\"><li><em>freshly dug carrots</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to put your hand into something, especially in order to search for something:</div><ul class=\"examples\"><li><em>She dug around in her bag for a pen.</em></li><li><em>He dug his hands deep into his pockets.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>dig your heels in</strong> to refuse to do something in spite of other people’s efforts to persuade you</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>dig deep</strong> to use something which you have, especially money or effort, which you would not normally need:</div><ul class=\"examples\"><li><em>With one man sent off, the team had to dig deep and hang on for a draw.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>dig a hole for yourself</strong> (also dig yourself into a hole) to get yourself into a difficult situation by doing or saying the wrong thing</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>dig somebody out of trouble/a mess/a hole etc</strong> to help a person or organization get out of trouble</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>dig your own grave</strong> to do something that will cause serious problems for you in the future</div><div class=\"sense\"><span class=\"snum\">9</span> <span class=\"gram\">[transitive]</span> <em>old-fashioned</em> to like something:</div><ul class=\"examples\"><li><em>I dig that hat!</em></li></ul></div>","2003":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧gest</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈdʒest, də-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to change food that you have just eaten into substances that your body can use: → ingest</div><ul class=\"examples\"><li><em>Most babies can digest a wide range of food easily.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to understand new information, especially when there is a lot of it or it is difficult to understand <em>SYN take in</em>:</div><ul class=\"examples\"><li><em>I struggled to digest the news.</em></li></ul></div>","2004":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ges‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈdʒestʃən, də-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the process of digesting food</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> your ability to digest food easily → indigestion:</div><ul class=\"examples\"><li><em>Too much tea is bad for your digestion.</em></li></ul></div>","2005":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧git</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪdʒɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of the written signs that represent the numbers 0 to 9</div><ul class=\"examples\"><li><strong><em>three-digit/four-digit etc number</strong>: 4305 is a four-digit number.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> a finger or toe</div></div>","2006":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧gi‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪdʒətl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> using a system in which information is recorded or sent out electronically in the form of numbers, usually ones and zeros:</div><ul class=\"examples\"><li><em>digital TV</em></li><li><em>a digital signal</em></li><li><em>a digital camera</em></li><li><em>digital recording</em></li><li><strong><em>digital cassette/audiotape etc</strong>: a recording on digital audiotape</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> giving information in the form of numbers → analogue:</div><ul class=\"examples\"><li><em>a digital watch</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> relating to the fingers and toes</div></div>","2007":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dig‧ni‧fied</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪɡnɪfaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">behaving in a calm and serious way, even in a difficult situation, which makes people respect you:</div><ul class=\"examples\"><li><em>a dignified old lady</em></li><li><em>She made a dignified departure.</em></li></ul></div>","2008":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dig‧ni‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪɡnəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the ability to behave in a calm controlled way even in a difficult situation</div><ul class=\"examples\"><li><strong><em>with dignity</strong>: The family faced their ordeal with dignity.</em></li><li><em>an appearance of quiet dignity</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>your dignity</strong> your sense of your own value or importance</div><ul class=\"examples\"><li><strong><em>retain/lose your dignity</strong>: Old people need to retain their dignity and independence.</em></li><li><em>Arguing was beneath her dignity (=was something she thought she was too important to do).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the fact of being respected or deserving respect</div><ul class=\"examples\"><li><strong><em>with dignity</strong>: Patients should be allowed to die with dignity.</em></li><li><em>Prisoners should be treated with regard for human dignity.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a calm and serious quality</div><ul class=\"examples\"><li><strong><em>dignity of</strong>: the dignity of the occasion</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>stand on your dignity</strong> <em>formal</em> to demand to be treated with proper respect</div></div>","2009":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧lem‧ma</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈlemə, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a situation in which it is very difficult to decide what to do, because all the choices seem equally good or equally bad:</div><ul class=\"examples\"><li><em>a moral dilemma</em></li><li><strong><em>in a dilemma</strong>: I’m in a dilemma about this job offer. / This placed Robert Kennedy in a dilemma.</em></li><li><em>Many women are faced with the dilemma of choosing between work and family commitments.</em></li></ul></div>","2010":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧lute</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈluːt $ dɪˈluːt, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a liquid weaker by adding water or another liquid → water down: ► see thesaurus at mix</div><ul class=\"examples\"><li><em>diluted fruit juice</em></li><li><strong><em>dilute something with/in something</strong>: Dilute the paint with a little oil.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make a quality, belief etc weaker or less effective <em>SYN water down</em>:</div><ul class=\"examples\"><li><em>an attempt to dilute the proposals</em></li></ul></div>","2011":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(comparative dimmer, superlative dimmest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[dark]</strong> fairly dark or not giving much light, so that you cannot see well <em>OPP bright</em>: ► see thesaurus at dark</div><ul class=\"examples\"><li><em>in the dim light of the early dawn</em></li><li><em>a dim glow</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[shape]</strong> a dim shape is one which is not easy to see because it is too far away, or there is not enough light:</div><ul class=\"examples\"><li><em>The dim outline of a building loomed up out of the mist.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take a dim view of something</strong> to disapprove of something:</div><ul class=\"examples\"><li><em>Miss Watson took a dim view of Paul’s behaviour.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>dim recollection/awareness etc</strong> a memory or understanding of something that is not clear in your mind <em>SYN vague</em>:</div><ul class=\"examples\"><li><em>Laura had a dim recollection of someone telling her this before.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[eyes]</strong> <em>literary</em> dim eyes are weak and cannot see well:</div><ul class=\"examples\"><li><em>Isaac was old and his eyes were dim.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[future chances]</strong> if your chances of success in the future are dim, they are not good:</div><ul class=\"examples\"><li><em>Prospects for an early settlement of the dispute are dim.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>in the dim and distant past</strong> a very long time ago – used humorously</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[not intelligent]</strong> <em>informal</em> not intelligent:</div><ul class=\"examples\"><li><em>You can be really dim sometimes!</em></li></ul></div>","2012":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧men‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈmenʃən, də-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a part of a situation or a quality involved in it <em>SYN aspect</em></div><ul class=\"examples\"><li><strong><em>dimension of</strong>: the moral dimension of world politics</em></li><li><strong><em>add a new/an extra/another etc dimension (to something)</strong>: His coaching has added another dimension to my game.</em></li><li><strong><em>political/social/economic etc dimension</strong>: It is important to keep in mind the historical dimension to these issues.</em></li><li><em>You can have a spiritual dimension to your life without being religious.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> the length, height, width, depth, or diameter of something <em>SYN measurement</em>:</div><ul class=\"examples\"><li><em>a rectangle with the dimensions 5cm x 2cm</em></li><li><strong><em>dimension of</strong>: We’ll need to know the exact dimensions of the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a direction in space that is at an angle of 90 degrees to two other directions: → fourth dimension, three-dimensional(1), two-dimensional(1)</div><ul class=\"examples\"><li><em>A diagram represents things in only two dimensions.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>dimensions</strong> <span class=\"gram\">[plural]</span> how great or serious a problem is:</div><ul class=\"examples\"><li><em>a catastrophe of enormous dimensions</em></li></ul></div>","2013":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧min‧ish</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈmɪnɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to become or make something become smaller or less <em>SYN reduce</em>: ► see thesaurus at decrease</div><ul class=\"examples\"><li><em>The party’s share of the electorate has diminished steadily.</em></li><li><em>These drugs diminish blood flow to the brain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to deliberately make someone or something appear less important or valuable than they really are:</div><ul class=\"examples\"><li><em>Don’t let him diminish your achievements.</em></li><li><em>But that’s not to diminish the importance of his discoveries.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>diminishing returns</strong> when the profits or advantages you are getting from something stop increasing in relation to the effort you are making</div></div>","2014":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to eat dinner:</div><ul class=\"examples\"><li><em>He was dining with friends at the Ritz.</em></li></ul></div>","2015":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> din‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is eating in a restaurant</div><div class=\"sense\"><span class=\"snum\">2</span> <em>especially American English</em> a small restaurant that serves cheap meals</div></div>","2016":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈdining room</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a room where you eat meals in a house or hotel</div></div>","2017":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> din‧ner</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the main meal of the day, eaten in the middle of the day or the evening:</div><ul class=\"examples\"><li><em>What time do you usually have dinner?</em></li><li><em>We’re having fish for dinner tonight.</em></li><li><em>What&#x27;s for dinner?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a formal occasion when an evening meal is eaten, often to celebrate something:</div><ul class=\"examples\"><li><em>the Club’s annual dinner</em></li></ul></div>","2018":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧no‧saur</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪnəsɔː $ -sɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of a group of reptiles that lived millions of years ago</div><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> someone or something that is old-fashioned and no longer effective or suitable for modern times:</div><ul class=\"examples\"><li><em>lengthy speeches by some of the party’s dinosaurs</em></li></ul></div>","2019":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle dipped, present participle dipping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[put something in liquid]</strong> <span class=\"gram\">[transitive]</span> to put something into a liquid and lift it out again ► see thesaurus at put</div><ul class=\"examples\"><li><strong><em>dip something in/into something</strong>: He dipped his hand in the water. / Dip the strawberries into melted chocolate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move down]</strong> <span class=\"gram\">[intransitive, transitive]</span> to move down, or to make something move down, usually for just a short time:</div><ul class=\"examples\"><li><em>We watched the sun dip below the horizon.</em></li><li><em>She dipped her head and spoke into the microphone.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[become less]</strong> <span class=\"gram\">[intransitive]</span> if an amount or level dips, it becomes less, usually for just a short time <em>SYN fall</em>:</div><ul class=\"examples\"><li><em>Profits dipped slightly last year.</em></li><li><em>Temperatures dipped to -10°C last night.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[road/path]</strong> <span class=\"gram\">[countable]</span> if land or a road or path dips, it slopes down and then goes up again</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>dip your headlights/lights</strong> <em>British English</em> to lower the angle of the front lights of your car when someone is driving towards you</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[animals]</strong> <span class=\"gram\">[transitive]</span> to put animals in a chemical that kills insects on their skin</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[swim]</strong> <span class=\"gram\">[countable]</span> <em>informal</em> a quick swim:</div><ul class=\"examples\"><li><em>Are you coming in for a dip?</em></li><li><strong><em>take/have a dip</strong>: Let’s take a dip in the lake.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[decrease]</strong> <span class=\"gram\">[countable]</span> a slight decrease in the amount of something</div><ul class=\"examples\"><li><strong><em>dip in</strong>: an unexpected dip in profits</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[food]</strong> <span class=\"gram\">[countable, uncountable]</span> a thick mixture that you can dip food into before you eat it:</div><ul class=\"examples\"><li><em>sour cream and onion dip</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in a surface]</strong> <span class=\"gram\">[countable]</span> a place where the surface of something goes down suddenly, then goes up again</div><ul class=\"examples\"><li><strong><em>dip in</strong>: a dip in the road</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[for animals]</strong> <span class=\"gram\">[countable, uncountable]</span> a chemical that kills insects on sheep and other animals:</div><ul class=\"examples\"><li><em>sheep dip</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[person]</strong> <span class=\"gram\">[countable]</span> <em>American English</em> <em>spoken</em> a stupid person</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>a dip into something</strong> a quick look at information, a book, magazine etc:</div><ul class=\"examples\"><li><em>People interested in history would enjoy a dip into this book.</em></li></ul></div></div>","2020":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧plo‧ma</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈpləʊmə $ -ˈploʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a document showing that someone has successfully completed a course of study or passed an examination:</div><ul class=\"examples\"><li><em>I’m hoping to get my teaching diploma this year.</em></li><li><strong><em>diploma in</strong>: a diploma in catering</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a document showing that a student has successfully completed their high school or university education</div><ul class=\"examples\"><li><strong><em>high school/college diploma</em></strong></li></ul></div>","2021":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧plo‧ma‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈpləʊməsi $ -ˈploʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the job or activity of managing the relationships between countries:</div><ul class=\"examples\"><li><em>international diplomacy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> skill in dealing with people without upsetting them:</div><ul class=\"examples\"><li><em>The job requires tact and diplomacy.</em></li></ul></div>","2022":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dip‧lo‧mat</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪpləmæt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who officially represents their government in a foreign country → ambassador:</div><ul class=\"examples\"><li><em>French diplomats</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is good at dealing with people without upsetting them</div></div>","2023":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dip‧lo‧mat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪpləˈmætɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to or involving the work of diplomats:</div><ul class=\"examples\"><li><em>Diplomatic efforts to end the fighting began on October 25.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>diplomatic relations/ties</strong> the arrangement between two countries that each should keep representatives at an embassy in the other’s country</div><ul class=\"examples\"><li><strong><em>establish/break off diplomatic relations</strong>: The two countries established diplomatic relations last year.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> dealing with people politely and skilfully without upsetting them <em>SYN tactful</em>:</div><ul class=\"examples\"><li><em>They were always very diplomatic with awkward clients.</em></li><li><em>a diplomatic answer</em></li></ul></div>","2024":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪə $ daɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely serious or terrible:</div><ul class=\"examples\"><li><em>warnings of dire consequences that often don’t come true</em></li><li><em>The country is in dire need of food aid.</em></li><li><em>The situation looked dire.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be in dire straits</strong> to be in an extremely difficult or serious situation:</div><ul class=\"examples\"><li><em>Everyone agrees the sport is in dire straits.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>dire warning/prediction/forecast</strong> a warning about something terrible that will happen in the future:</div><ul class=\"examples\"><li><em>Last night there were dire warnings of civil war.</em></li></ul></div>","2025":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧rect</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈrekt, ˌdaɪˈrekt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[without involving others]</strong> done without any other people, actions, processes etc coming between <em>OPP indirect</em>:</div><ul class=\"examples\"><li><em>Experienced users have direct access to the main data files.</em></li><li><em>I’m not in direct contact with them.</em></li><li><em>Few policy-makers have had direct experience of business.</em></li><li><strong><em>direct effect/impact/influence etc</strong>: Educational level has a sizeable direct effect on income.</em></li><li><strong><em>direct link/connection/relationship etc</strong>: There is a direct link between poverty and ill-health.</em></li><li><strong><em>direct result/consequence</strong>: The decision to close the hospital is a direct result of Government health policy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[from one place to another]</strong> going straight from one place to another without stopping or changing direction <em>OPP indirect</em>:</div><ul class=\"examples\"><li><em>Which is the most direct route to London?</em></li><li><em>a direct flight to New York</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[exact]</strong> <span class=\"gram\">[only before noun]</span> exact or total:</div><ul class=\"examples\"><li><em>Weight increases in direct proportion to mass.</em></li><li><em>For Lawrence, in direct contrast to Adam, everything seemed to come so easily.</em></li><li><em>a direct quote (=exact words) from the book</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[behaviour/attitude]</strong> saying exactly what you mean in an honest clear way <em>OPP indirect</em>: ► see thesaurus at honest</div><ul class=\"examples\"><li><em>Women often feel men are too direct and not sympathetic enough.</em></li><li><em>Now, let me ask you a direct question, and I expect a direct answer.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>direct descendant</strong> someone who is related to someone else through their parents and grandparents, not through their aunts, uncles etc</div><ul class=\"examples\"><li><strong><em>direct of</strong>: She claimed to be a direct descendant of Wordsworth.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>direct hit</strong> an occasion on which something such as a bomb hits a place exactly, causing a lot of damage:</div><ul class=\"examples\"><li><em>During the war, the cathedral suffered many direct hits.</em></li><li><em>One of the bombers scored a direct hit.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>direct heat/sunlight</strong> strong heat or light that someone or something is not protected from <em>OPP indirect</em>:</div><ul class=\"examples\"><li><em>Never change the film in direct sunlight.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[aim]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to aim something in a particular direction or at a particular person, group etc</div><ul class=\"examples\"><li><strong><em>direct something at/towards etc something</strong>: The machine directs an X-ray beam at the patient’s body. / The new route directs lorries away from the town centre.</em></li><li><em>I’d like to direct your attention to paragraph four.</em></li><li><em>I want to direct my efforts more towards my own projects.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[be in charge]</strong> <span class=\"gram\">[transitive]</span> to be in charge of something or control it:</div><ul class=\"examples\"><li><em>Mr Turner was directing the investigation from a very early stage.</em></li><li><em>The choir was directed by Sir David Willcocks.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[film/play]</strong> <span class=\"gram\">[intransitive, transitive]</span> to give the actors in a play, film, or television programme instructions about what they should do:</div><ul class=\"examples\"><li><em>The play was directed by Frank Hauser.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[way/route]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to tell someone how to get to a place ► see thesaurus at lead</div><ul class=\"examples\"><li><strong><em>direct somebody to something</strong>: Could you direct me to Trafalgar Square, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[tell somebody to do something]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to tell someone what they should do <em>SYN order</em> ► see thesaurus at order</div><ul class=\"examples\"><li><strong><em>direct somebody to do something</strong>: The judge directed the jury to find Mr Baggs not guilty.</em></li><li><strong><em>direct that</strong>: He directed that his body should be buried in Upton.</em></li></ul></div></div>","2026":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧rec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈrekʃən, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[towards]</strong> <span class=\"gram\">[countable]</span> the way something or someone moves, faces, or is aimed: RegisterIn everyday English, people usually use which way...? when asking where something is rather than using the noun direction: Which direction did they go in? ➔ Which way did they go? | Which direction is north? ➔ Which way is north?</div><ul class=\"examples\"><li><em>Which direction did they go in?</em></li><li><strong><em>in the direction of something</strong>: The suspects were last seen heading in the direction of Miami.</em></li><li><strong><em>in somebody’s direction</strong>: Tony glanced in her direction and their eyes met.</em></li><li><em>The girls pointed in the opposite direction.</em></li><li><em>On seeing me, Maurice changed direction and went along the wharf instead.</em></li><li><em>As shots rang out, the crowd ran screaming in all directions.</em></li><li><strong><em>from the direction of something</strong>: There was a loud scream from the direction of the children’s pool.</em></li><li><strong><em>in a southerly/easterly etc direction</strong>: Continue in a southerly direction until you reach the road.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>directions</strong> <span class=\"gram\">[plural]</span>:</div><ul class=\"examples\"><li><em>Be sure you read the directions before using any piece of equipment.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">a)</span> instructions about how to get from one place to another:</div><ul class=\"examples\"><li><em>A very helpful woman gave me directions to the police station.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> instructions about what to do</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[way something develops]</strong> <span class=\"gram\">[countable]</span> the general way in which someone or something changes or develops:</div><ul class=\"examples\"><li><em>We are happy with the direction the club is taking.</em></li><li><strong><em>move/head/go in the right direction</strong>: I believe that things are heading in the right direction in South Africa.</em></li><li><strong><em>new/different/exciting etc direction</strong>: The company is hoping to extend its operations in new directions.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[control]</strong> <span class=\"gram\">[uncountable]</span> control, management, or advice</div><ul class=\"examples\"><li><strong><em>under somebody’s direction</strong>: Under Thompson’s direction, the college has developed an international reputation.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[where from or where to]</strong> <span class=\"gram\">[countable]</span> where something comes from or where something leads</div><ul class=\"examples\"><li><strong><em>in a direction</strong>: The evidence all points in this direction.</em></li><li><strong><em>from a direction</strong>: Help came from a wholly unexpected direction.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[purpose]</strong> <span class=\"gram\">[uncountable]</span> a general purpose or aim:</div><ul class=\"examples\"><li><em>Her mother felt that Rachel’s life lacked direction.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[film/play]</strong> <span class=\"gram\">[uncountable]</span> the instructions given to the actors and other people working on a film, play etc</div></div>","2027":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧rec‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈrektɪv, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an official order or instruction</div><ul class=\"examples\"><li><strong><em>directive on</strong>: proposals for implementing the EU directive on paternity leave</em></li></ul></div>","2028":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧rect‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈrektli, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> with no other person, action, process etc between <em>OPP indirectly</em>: ► see thesaurus at exactly</div><ul class=\"examples\"><li><em>The new property tax law won’t directly affect us.</em></li><li><em>We hope to bring together the countries directly involved in the conflict.</em></li><li><strong><em>directly to/from</strong>: Application for admission to this course should be made directly to the University.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> exactly in a particular position or direction <em>SYN right</em></div><ul class=\"examples\"><li><strong><em>directly in front of/behind/under etc something</strong>: It was a small house, directly behind the church.</em></li><li><em>The girl was sitting directly opposite him.</em></li><li><em>Have you noticed how he never looks directly at you?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>speak/ask/answer etc directly</strong> to say exactly what you mean without trying to hide anything:</div><ul class=\"examples\"><li><em>Jeff has a job in mind, but refuses to say directly what it is.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> <em>old-fashioned</em> very soon:</div><ul class=\"examples\"><li><em>He should be here directly, if you don’t mind waiting.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>British English</em> <em>old-fashioned</em> immediately</div></div>","2029":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧rec‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈrektə, daɪ- $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who controls or manages a company → executive</div><ul class=\"examples\"><li><strong><em>director of</strong>: a former director of Gartmore Pensions Ltd</em></li><li><em>The company is run by a board of directors (=a group of directors).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is in charge of a particular activity or organization</div><ul class=\"examples\"><li><strong><em>director of</strong>: the director of education</em></li><li><strong><em>finance/marketing/sales etc director</strong> (=the person in charge of the financial department etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the person who gives instructions to the actors and other people working on a film or play → producer</div></div>","2030":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧rec‧to‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈrektəri, də-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural directories)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a book or list of names, facts etc, usually arranged in alphabetical order:</div><ul class=\"examples\"><li><em>I couldn’t find your number in the telephone directory.</em></li><li><em>a new business directory</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a place in a computer where files or programs are organized</div></div>","2031":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɜːt $ dɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> any substance that makes things dirty, such as mud or dust:</div><ul class=\"examples\"><li><em>You should have seen the dirt on that car!</em></li><li><em>His face and hands were black with dirt.</em></li><li><em>a patch of grass, covered in dog dirt (=waste from a dog’s bowels)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>especially American English</em> earth or soil:</div><ul class=\"examples\"><li><em>Michael threw his handful of dirt onto the coffin.</em></li><li><strong><em>in (the) dirt</strong>: The children had been sitting in the dirt.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> information about someone’s private life or activities which could give people a bad opinion of them if it became known:</div><ul class=\"examples\"><li><em>The newspapers had been digging up dirt on the president.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> talk, writing, a film etc that is considered bad or immoral because it is about sex</div></div>","2032":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dirt‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɜːti $ ˈdɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(comparative dirtier, superlative dirtiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not clean]</strong> covered in or marked by an unwanted substance <em>OPP clean</em>:</div><ul class=\"examples\"><li><em>a stack of dirty dishes in the sink</em></li><li><em>How did you get so dirty?</em></li><li><strong><em>dirty clothes/washing/laundry</strong>: She circled the bedroom, picking up dirty clothes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sex]</strong> relating to sex, in a way that is considered immoral or unpleasant:</div><ul class=\"examples\"><li><em>kids telling dirty jokes</em></li><li><em>a dirty magazine</em></li><li><em>She looked at me as if I had said a dirty word.</em></li><li><strong><em>have a dirty mind<em>British English</em></strong> (=think about sex a lot)</em></li><li><strong><em>dirty weekend<em>British English</em></strong> (=a weekend when a man and woman who are not married to each other go away to have sex)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bad/immoral]</strong> used to emphasize that you think someone or something is bad, dishonest, or immoral:</div><ul class=\"examples\"><li><em>You’re a dirty liar!</em></li><li><em>a dirty fighter</em></li><li><em>you and your dirty little deals</em></li><li><strong><em>do the dirty on somebody<em>British English</em></strong> (=treat someone in a way that is unfair or dishonest)</em></li><li><em>What a dirty trick!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>something is a dirty word</strong> if something is a dirty word, people believe it is a bad thing even if they do not know or think much about it <em>SYN swear word</em>:</div><ul class=\"examples\"><li><em>‘Liberal’ has somehow become a dirty word in America.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>give somebody a dirty look</strong> to look at someone in a very disapproving way:</div><ul class=\"examples\"><li><em>Susan gave her brother a dirty look.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>dirty trick</strong> a dishonest or unfair action, especially done by a government, company, or organization:</div><ul class=\"examples\"><li><em>political dirty tricks</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>wash your dirty linen/laundry</strong> (also air your dirty laundry<em>American English</em>) to discuss something embarrassing or bad about yourself where everyone can see, know, or hear:</div><ul class=\"examples\"><li><em>The divorce has meant airing their dirty laundry in court.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>do somebody’s dirty work</strong> to do an unpleasant or dishonest action for someone, so that they do not have to do it themselves:</div><ul class=\"examples\"><li><em>I’m not talking to him; you do your own dirty work!</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>it’s a dirty job, but someone has to do it</strong> used to say that something is unpleasant to do, but that it is necessary – often used humorously</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[drugs]</strong> <em>American English</em> <em>informal</em> containing or possessing illegal drugs</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>dirty bomb</strong> a bomb that contains a radioactive substance which makes the bomb more dangerous than bombs containing only traditional explosives</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[sport]</strong> a dirty sports event is one in which people competing in the event have illegally used drugs to improve their performance:</div><ul class=\"examples\"><li><em>Many people think that the race has been a dirty event for years.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[environment]</strong> producing pollution or carbon dioxide:</div><ul class=\"examples\"><li><em>dirty forms of energy</em></li></ul></div>","2033":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧a‧bil‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈbɪləti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural disabilities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a physical or mental condition that makes it difficult for someone to use a part of their body properly, or to learn normally</div><ul class=\"examples\"><li><strong><em>with a disability</strong>: Public places are becoming more accessible to people with disabilities.</em></li><li><strong><em>learning/physical/mental etc disability</strong>: children with severe learning disabilities</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when you have a physical or mental disability:</div><ul class=\"examples\"><li><em>learning to cope with disability</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>American English</em> money that is given by the government to people who have physical disabilities</div><ul class=\"examples\"><li><strong><em>on disability</strong>: Evans lives on disability because of an accident that left her paralyzed.</em></li></ul></div>","2034":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧a‧bled</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈeɪbəld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is disabled cannot use a part of their body properly, or cannot learn easily → handicapped:</div><ul class=\"examples\"><li><em>a support group for parents of disabled children</em></li><li><em>a severely disabled polio patient</em></li><li><strong><em>physically/mentally disabled</strong>: If you are elderly or physically disabled, massage can be beneficial.</em></li><li><em>teachers who work with learning disabled children (=children who have problems learning)</em></li><li><strong><em>disabled parking/toilet/access etc</strong> (=for physically disabled people)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the disabled</strong> <span class=\"gram\">[plural]</span> people who are disabled:</div><ul class=\"examples\"><li><em>The theatre has good access for the disabled.</em></li></ul></div>","2035":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ad‧van‧tage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsədˈvɑːntɪdʒ $ -ˈvæn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something that causes problems, or that makes someone or something less likely to be successful or effective <em>OPP advantage</em></div><ul class=\"examples\"><li><strong><em>disadvantage of</strong>: The disadvantage of the material is that it fades in strong sunlight.</em></li><li><strong><em>disadvantage to</strong>: There are some big disadvantages to marriage – you do lose a lot of your freedom.</em></li><li><em>Criminal behaviour can be linked to economic disadvantage.</em></li></ul></div>","2036":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ad‧van‧taged</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsədˈvɑːntɪdʒd◂ $ -ˈvæn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having social problems, such as a lack of money or education, which make it difficult for you to succeed: ► see thesaurus at poor</div><ul class=\"examples\"><li><em>disadvantaged areas of the city</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the disadvantaged</strong> <span class=\"gram\">[plural]</span> people who are disadvantaged:</div><ul class=\"examples\"><li><em>health programs for the disadvantaged</em></li></ul></div>","2037":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧a‧gree</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈɡriː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to have or express a different opinion from someone else <em>OPP agree</em></div><ul class=\"examples\"><li><strong><em>disagree with</strong>: He is tolerant of those who disagree with him.</em></li><li><strong><em>disagree about/on/over</strong>: Experts disagree on how much the program will cost.</em></li><li><em>Barr strongly disagreed with Kronfeld’s statement.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if statements, numbers, or reports about the same event or situation disagree, they are different from each other <em>OPP agree</em>:</div><ul class=\"examples\"><li><em>The statements of several witnesses disagree.</em></li></ul></div>","2038":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧a‧gree‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈɡriːmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a situation in which people express different opinions about something and sometimes argue <em>OPP agreement</em>: ► see thesaurus at argument</div><ul class=\"examples\"><li><em>We’ve had a few disagreements, but we’re still good friends.</em></li><li><strong><em>disagreement about/over/as to/on</strong>: disagreements about who will be allowed to vote</em></li><li><strong><em>disagreement among/between</strong>: There were disagreements among doctors about the best way to treat the disease.</em></li><li><strong><em>disagreement with</strong>: Connor’s disagreements with school administrators</em></li><li><strong><em>sharp/fundamental/profound etc disagreement</strong> (=serious disagreement)</em></li><li><strong><em>be in disagreement</strong> (=disagree): Scientists are in disagreement about the significance of the data.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> differences between two statements, reports, numbers etc that ought to be similar <em>OPP agreement</em></div><ul class=\"examples\"><li><strong><em>disagreement between</strong>: There is disagreement between these two estimates.</em></li></ul></div>","2039":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧pear</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpɪə $ -ˈpɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to become impossible to see any longer <em>SYN vanish</em> <em>OPP appear</em></div><ul class=\"examples\"><li><strong><em>disappear behind/under/into etc</strong>: The sun had disappeared behind a cloud.</em></li><li><strong><em>disappear from view/sight</strong>: David watched her car until it disappeared from view.</em></li><li><em>At this point the path seemed to disappear altogether (=disappear completely).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be lost, or to become impossible to find <em>SYN vanish</em>:</div><ul class=\"examples\"><li><em>The two girls disappeared while walking home from school.</em></li><li><em>My keys have disappeared again.</em></li><li><strong><em>disappear without trace<em>British English,</em></strong> <strong>without a trace</em>American English</strong><em> (=without any way of finding them): 75,000 soldiers simply disappeared without trace.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to stop existing:</div><ul class=\"examples\"><li><em>The rain forest may disappear forever.</em></li></ul></div>","2040":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧pear‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpɪərəns $ -ˈpɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when someone or something becomes impossible to see or find:</div><ul class=\"examples\"><li><em>Police are investigating the woman’s disappearance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when something stops existing → extinction:</div><ul class=\"examples\"><li><em>the disappearance of ancient forests</em></li></ul></div>","2041":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧point</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpɔɪnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone feel unhappy because something they hoped for did not happen or was not as good as they expected:</div><ul class=\"examples\"><li><em>I hated to disappoint her.</em></li><li><em>Great things were expected of this band, and they didn’t disappoint.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>disappoint somebody’s hopes/expectations/plans</strong> to prevent something from happening that someone hoped for or expected:</div><ul class=\"examples\"><li><em>The Berlin settlement of 1878 disappointed Russian hopes in the Balkans.</em></li></ul></div>","2042":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧point‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpɔɪntɪd◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\">unhappy because something you hoped for did not happen, or because someone or something was not as good as you expected:</div><ul class=\"examples\"><li><em>Dad seemed more disappointed than angry.</em></li><li><em>disappointed customers</em></li><li><strong><em>disappointed (that)</strong>: I was disappointed that we played so well yet still lost.</em></li><li><strong><em>disappointed at/with/about something</strong>: Local residents were disappointed with the decision.</em></li><li><strong><em>disappointed by something</strong>: People are disappointed by the lack of political change.</em></li><li><strong><em>disappointed in somebody</strong>: I’m very disappointed in you.</em></li><li><strong><em>disappointed to hear/see/find etc</strong>: Visitors were disappointed to find the museum closed.</em></li><li><strong><em>bitterly/deeply/terribly disappointed</strong>: The girl’s parents were bitterly disappointed at the jury’s verdict.</em></li></ul></div>","2043":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧point‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpɔɪntɪŋ◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">not as good as you hoped or expected: ► see thesaurus at bad</div><ul class=\"examples\"><li><em>disappointing profit figures</em></li><li><em>The Lakers’ loss in the playoffs was very disappointing.</em></li></ul></div>","2044":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧point‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpɔɪntmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a feeling of unhappiness because something is not as good as you expected, or has not happened in the way you hoped:</div><ul class=\"examples\"><li><em>He could see the disappointment in her eyes.</em></li><li><strong><em>to somebody’s (great) disappointment</strong>: To Edward’s disappointment, Gina never turned up at the party.</em></li><li><strong><em>disappointment at/with/over etc</strong>: the managers’ disappointment with the results / Several people expressed disappointment at the delay.</em></li><li><strong><em>disappointment that</strong>: her disappointment that she hadn’t been picked</em></li><li><em>She hid her bitter disappointment.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone or something that is not as good as you hoped or expected:</div><ul class=\"examples\"><li><em>The movie was kind of a disappointment.</em></li><li><strong><em>great/bitter disappointment</strong>: The loss was a bitter disappointment.</em></li><li><strong><em>disappointment to</strong>: She felt she was a disappointment to her family.</em></li><li><strong><em>disappointment for</strong>: The team’s performance has been a disappointment for the fans.</em></li></ul></div>","2045":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧prov‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpruːvəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an attitude that shows you think that someone or their behaviour, ideas etc are bad or not suitable <em>OPP approval</em></div><ul class=\"examples\"><li><strong><em>disapproval of</strong>: strong disapproval of the country’s human rights record</em></li><li><strong><em>with/in disapproval</strong>: Baxter eyed our clothes with obvious disapproval. / Clarissa shook her head in disapproval.</em></li></ul></div>","2046":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ap‧prove</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈpruːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to think that someone or their behaviour, ideas etc are bad or wrong <em>OPP approve</em>: RegisterIn everyday English, people often say they don’t agree with an idea rather than disapprove of it: · I don’t agree with capital punishment.</div><ul class=\"examples\"><li><em>I knew my parents would disapprove, but I went anyway.</em></li><li><strong><em>disapprove of</strong>: I disapprove of diets; it’s better to eat sensibly.</em></li><li><em>Her family strongly disapproved of her behaviour.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to not agree to something that has been suggested <em>OPP approve</em>:</div><ul class=\"examples\"><li><em>The board of directors disapproved the sale.</em></li></ul></div>","2047":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧sas‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɑːstə $ dɪˈzæstər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a sudden event such as a flood, storm, or accident which causes great damage or suffering → catastrophe: ► see thesaurus at accident</div><ul class=\"examples\"><li><em>One hundred and twenty people died in China’s worst air disaster.</em></li><li><em>the economic consequences of the Chernobyl nuclear disaster</em></li><li><strong><em>disaster for</strong>: The oil spill was a disaster for Alaskan sea animals.</em></li><li><em>The 1987 hurricane was the worst natural disaster to hit England for decades.</em></li><li><em>Their expedition nearly ended in disaster, when one of the climbers slid off the mountain.</em></li><li><em>The drought could spell disaster for wildlife.</em></li><li><em>Disaster struck when two men were killed during their parachute jumps.</em></li><li><em>The peace process was on the brink of disaster.</em></li><li><em>Luckily the pilot saw the other plane just in time, and a disaster was narrowly averted.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that is very bad or a failure, especially when this is very annoying or disappointing</div><ul class=\"examples\"><li><strong><em>something is a complete/total/disaster</strong>: Because of the weather, the parade was a total disaster.</em></li><li><em>The evening was an unmitigated disaster (=a complete failure).</em></li><li><strong><em>disaster for</strong>: The cuts in funding will be a disaster for the schools.</em></li><li><em>Five small boys on skis is a recipe for disaster (=is very likely to end badly).</em></li></ul></div>","2048":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧sas‧trous</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɑːstrəs $ dɪˈzæ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">very bad, or ending in failure:</div><ul class=\"examples\"><li><em>a disastrous first marriage</em></li><li><strong><em>disastrous effects/consequences/results</strong>: Climate change could have disastrous effects on Earth.</em></li><li><em>The move proved disastrous (=was disastrous) for the company.</em></li></ul></div>","2049":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧be‧lief</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsbəˈliːf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a feeling that something is not true or does not exist → unbelief, belief:</div><ul class=\"examples\"><li><em>The reaction to the murders was one of shock and disbelief.</em></li><li><strong><em>in/with disbelief</strong>: Rosie stared in disbelief.</em></li></ul></div>","2050":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a round flat shape or object:</div><ul class=\"examples\"><li><em>three keys attached to a metal disc</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a compact disc</div><div class=\"sense\"><span class=\"snum\">3</span> a record that you play on a record player</div><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> a computer disk</div><ul class=\"examples\"><li><strong><em>on disc</strong>: The report form is available on disc from Personnel.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a flat piece of cartilage between the bones of your back:</div><ul class=\"examples\"><li><em>He retired early because of a slipped disc (=one that has moved out of its correct place).</em></li></ul></div>","2051":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧card</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkɑːd $ -ɑːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to get rid of something <em>SYN throw away</em>:</div><ul class=\"examples\"><li><em>Discard any old cleaning materials.</em></li><li><em>discarded paper</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to put down unwanted cards in a card game</div></div>","2052":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧scern</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsɜːn $ -ɜːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to notice or understand something by thinking about it carefully ► see thesaurus at recognize</div><ul class=\"examples\"><li><strong><em>discern what/where/why etc</strong>: Officials were keen to discern how much public support there was.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be able to see something by looking carefully <em>SYN perceive</em>:</div><ul class=\"examples\"><li><em>We could just discern a town in the distance.</em></li></ul></div>","2053":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧charge</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈtʃɑːdʒ $ -ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[send somebody away]</strong> <span class=\"gram\">[transitive]</span> to officially allow someone to leave somewhere, especially the hospital or the army, navy etc, or to tell them that they must leave:</div><ul class=\"examples\"><li><em>Hospitals now tend to discharge patients earlier than in the past.</em></li><li><em>The judge discharged the jury.</em></li><li><strong><em>discharge somebody from something</strong>: Several of the recruits were discharged from the Army due to medical problems.</em></li><li><strong><em>discharge yourself<em>British English</em></strong> (=leave hospital before your treatment is complete)</em></li><li><strong><em>conditionally discharge somebody<em>British English</em></strong> (=let someone leave prison if they obey particular rules): Dunning was conditionally discharged for two years.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[gas/liquid/smoke etc]</strong> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to send out gas, liquid, smoke etc, or to allow it to escape</div><ul class=\"examples\"><li><strong><em>discharge something into something</strong>: Sewage is discharged directly into the sea.</em></li><li><strong><em>discharge into</strong>: Rainwater collects here and then discharges into the river Kennett.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[shoot]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to fire a gun or shoot an arrow etc:</div><ul class=\"examples\"><li><em>A soldier accidentally discharged his weapon.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[duty/responsibility/debt etc]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to do or pay what you have a duty to do or pay</div><ul class=\"examples\"><li><strong><em>discharge your duties/responsibilities/obligations etc</strong>: The trustees failed to discharge their duties properly.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[electricity]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a piece of electrical equipment discharges, or if it is discharged, it sends out electricity</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[a wound]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a wound or body part discharges a substance such as pus (=infected liquid), the substance slowly comes out of it</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[goods/passengers]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to take goods or passengers off a ship, plane etc</div></div>","2054":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧sci‧ple</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsaɪpəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who believes in the ideas of a great teacher or leader, especially a religious one</div><ul class=\"examples\"><li><strong><em>disciple of</strong>: He was also an avid reader and a disciple of Tolstoy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> one of the first 12 men to follow Christ</div></div>","2055":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ci‧pline</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪsɪplɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a way of training someone so that they learn to control their behaviour and obey rules:</div><ul class=\"examples\"><li><em>The book gives parents advice on discipline.</em></li><li><em>serious discipline problems in the police force</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the ability to control your own behaviour, so that you do what you are expected to do: → self-discipline</div><ul class=\"examples\"><li><em>Working from home requires a good deal of discipline.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a way of training your mind or learning to control your behaviour:</div><ul class=\"examples\"><li><em>Martial arts teach respect, discipline, and cooperation.</em></li><li><strong><em>discipline for</strong>: Learning poetry is a good discipline for the memory.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> an area of knowledge or teaching, especially one such as history, chemistry, mathematics etc that is studied at a university</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to punish someone in order to keep order and control:</div><ul class=\"examples\"><li><em>The officers were later disciplined.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to teach someone to obey rules and control their behaviour:</div><ul class=\"examples\"><li><em>Different cultures have different ways of disciplining their children.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>discipline yourself (to do something)</strong> to control the way you work, how regularly you do something etc, because you know it is good for you:</div><ul class=\"examples\"><li><em>Try to discipline yourself to write every day.</em></li></ul></div></div>","2056":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧close</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkləʊz $ -ˈkloʊz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make something publicly known, especially after it has been kept secret <em>SYN reveal</em>: ► see thesaurus at reveal</div><ul class=\"examples\"><li><em>Some companies have already voluntarily disclosed similar information.</em></li><li><em>He refused to disclose the identity of the politician.</em></li><li><strong><em>disclose that</strong>: It was disclosed that £3.5 million was needed to modernize the building.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to show something by removing the thing that covers it <em>SYN reveal</em></div></div>","2057":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧clo‧sure</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkləʊʒə $ -ˈkloʊʒər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a secret that someone tells people, or the act of telling this secret:</div><ul class=\"examples\"><li><em>the disclosure of private medical information</em></li></ul></div>","2058":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧com‧fort</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkʌmfət $ -ərt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a feeling of slight pain or of being physically uncomfortable: ► see thesaurus at pain</div><ul class=\"examples\"><li><em>If the exercise causes discomfort, stop immediately.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a feeling of embarrassment, shame, or worry:</div><ul class=\"examples\"><li><em>To her discomfort, he laughed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> something that makes you feel uncomfortable or gives you a slight pain:</div><ul class=\"examples\"><li><em>the discomforts of air travel</em></li></ul></div>","2059":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧con‧nect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪskəˈnekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to remove the supply of power, gas, water etc from a machine or piece of equipment <em>OPP connect</em></div><ul class=\"examples\"><li><strong><em>disconnect something from something</strong>: Always disconnect the machine from the mains first.</em></li><li><em>The family agreed to disconnect her life support system.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to separate something from the thing it is connected to, or to become separated <em>OPP connect</em></div><ul class=\"examples\"><li><strong><em>disconnect from</strong>: Two freight cars disconnected from the train engine.</em></li><li><strong><em>disconnect something from something</strong>: Disconnect part A from part D.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to officially stop supplying a service, such as water, telephone, electricity, or gas, to a house or other building <em>OPP connect</em>:</div><ul class=\"examples\"><li><em>Eleven percent of households were disconnected for non-payment of bills.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> if you disconnect or become disconnected from your feelings, family, society etc, you no longer feel as though you belong or have a relationship with them</div><ul class=\"examples\"><li><strong><em>disconnect from</strong>: Divorced men can too easily become disconnected from their children.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to break the telephone connection between two people <em>OPP connect</em></div></div>","2060":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧count</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪskaʊnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a reduction in the usual price of something</div><ul class=\"examples\"><li><strong><em>10% discount/discount of 25% etc</strong>: Members get a 15% discount.</em></li><li><strong><em>at a discount</strong>: Employees can buy books at a discount.</em></li><li><strong><em>discount on</strong>: The Young Persons Railcard gives you a discount on rail travel.</em></li><li><strong><em>offer/give somebody a discount</em></strong></li><li><strong><em>discount price/fare</strong>: discount airfares to Europe</em></li><li><strong><em>discount store/shop/warehouse</strong> (=a place where you can buy goods cheaply)</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧count</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkaʊnt $ ˈdɪskaʊnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to regard something as unlikely to be true or important:</div><ul class=\"examples\"><li><em>Experts discounted the accuracy of the polls.</em></li><li><em>General Hausken had not discounted the possibility of an aerial attack.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to reduce the price of something:</div><ul class=\"examples\"><li><em>Games were discounted to as little as $5.</em></li></ul></div></div>","2061":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧cour‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkʌrɪdʒ $ -ˈkɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to persuade someone not to do something, especially by making it seem difficult or bad <em>OPP encourage</em>: GRAMMARYou say: · She discouraged me from going. ✗Don’t say: She discouraged me to go.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>attempts to discourage illegal immigration</em></li><li><strong><em>discourage somebody from doing something</strong>: My father is a lawyer, and he discouraged me from entering the field.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone less confident or less willing to do something <em>SYN demoralize</em> <em>OPP encourage</em>:</div><ul class=\"examples\"><li><em>You should not let one failure discourage you.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to make something less likely to happen <em>OPP encourage</em>:</div><ul class=\"examples\"><li><em>Aspirin may discourage tumour growth in some types of cancer.</em></li></ul></div>","2062":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧cour‧aged</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkʌrɪdʒd $ -ˈkɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">no longer having the confidence you need to continue doing something <em>SYN demoralized</em> <em>OPP encouraged</em>: ► see thesaurus at confident</div><ul class=\"examples\"><li><em>A lot of players get discouraged and quit.</em></li></ul></div>","2063":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧course</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪskɔːs $ -ɔːrs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a serious speech or piece of writing on a particular subject</div><ul class=\"examples\"><li><strong><em>discourse on/upon</strong>: a discourse on art</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> serious conversation or discussion between people:</div><ul class=\"examples\"><li><em>Candidates should engage in serious political discourse.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the language used in particular types of speech or writing:</div><ul class=\"examples\"><li><em>a study of spoken discourse</em></li></ul></div>","2064":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧cov‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkʌvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to find someone or something, either by accident or because you were looking for them: ► see thesaurus at find</div><ul class=\"examples\"><li><em>The body was discovered in a field.</em></li><li><em>Forest Service crews often discover campfires that have not been put out completely.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to find out something that you did not know about before: GRAMMARIn more formal English, you say it is discovered that something is true: · It was discovered that lightning was electrical.</div><ul class=\"examples\"><li><em>The exercises let students discover math concepts on their own.</em></li><li><strong><em>discover (that)</strong>: She discovered that she was pregnant.</em></li><li><strong><em>discover who/what/how etc</strong>: His friends were shocked to discover how ill he was.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if someone discovers a new place, fact, substance etc, they are the first person to find it or know that it exists:</div><ul class=\"examples\"><li><em>The Curies are best known for discovering radium.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to notice or try something for the first time and start to enjoy it:</div><ul class=\"examples\"><li><em>At fourteen, Louise discovered boys.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to notice someone who is very good at something and help them to become successful and well known:</div><ul class=\"examples\"><li><em>a band that’s waiting to be discovered</em></li></ul></div>","2065":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧cov‧e‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkʌvəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\">(plural discoveries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a fact or thing that someone finds out about, when it was not known about before</div><ul class=\"examples\"><li><strong><em>discovery about</strong>: The Hubble Telescope allowed astronomers to make significant discoveries about our galaxy.</em></li><li><strong><em>discovery that</strong>: the discovery that bees can communicate with each other</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when someone discovers something</div><ul class=\"examples\"><li><strong><em>discovery of</strong>: the discovery of oil in Alaska</em></li></ul></div>","2066":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧cred‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈkredɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make people stop respecting or trusting someone or something:</div><ul class=\"examples\"><li><em>The company’s lawyers tried to discredit her testimony.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make people stop believing in a particular idea:</div><ul class=\"examples\"><li><em>His theories have now been discredited.</em></li></ul></div>","2067":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧screet</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskriːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> careful about what you say or do, so that you do not offend, upset, or embarrass people or tell secrets <em>OPP indiscreet</em>:</div><ul class=\"examples\"><li><em>He assured her that he would be discreet.</em></li><li><em>I stood back at a discreet distance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> small and showing good taste or judgment – use this to show approval:</div><ul class=\"examples\"><li><em>discreet jewelry</em></li></ul></div>","2068":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧screp‧an‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskrepənsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural discrepancies)</span></div><div class=\"entry-body\"><div class=\"sense\">a difference between two amounts, details, reports etc that should be the same</div><ul class=\"examples\"><li><strong><em>discrepancy in</strong>: Police found discrepancies in the two men’s reports.</em></li><li><strong><em>discrepancy between</strong>: There is a large discrepancy between the ideal image of motherhood and the reality.</em></li></ul></div>","2069":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧scre‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskreʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the ability and right to decide exactly what should be done in a particular situation</div><ul class=\"examples\"><li><strong><em>at somebody’s discretion</strong> (=according to someone’s decision): The awards are made at the discretion of the committee.</em></li><li><em>Promotions are left to the discretion of the supervisor.</em></li><li><strong><em>discretion over/as to</strong>: People want to have more discretion over their working hours.</em></li><li><strong><em>use/exercise your discretion</strong>: The judge exercised his discretion rightly to admit the evidence.</em></li><li><strong><em>discretion to do something</strong>: The committee has the absolute discretion to refuse applications.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the ability to deal with situations in a way that does not offend, upset, or embarrass people or tell any of their secrets → indiscretion:</div><ul class=\"examples\"><li><em>British newspapers no longer feel they must treat the royal family with discretion.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>discretion is the better part of valour</strong> used to say that it is better to be careful than to take unnecessary risks</div></div>","2070":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧scrim‧i‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskrɪməneɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to treat a person or group differently from another in an unfair way</div><ul class=\"examples\"><li><strong><em>discriminate against</strong>: Under federal law, it is illegal to discriminate against minorities and women.</em></li><li><strong><em>discriminate on the grounds/basis of something</strong>: It was found that the company still discriminated on the basis of race in promotions.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to recognize a difference between things <em>SYN differentiate</em></div><ul class=\"examples\"><li><strong><em>discriminate between</strong>: Newborn babies can discriminate between a man’s and a woman’s voice.</em></li><li><strong><em>discriminate something from something</strong>: the process of learning to discriminate fact from opinion</em></li></ul></div>","2071":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧scrim‧i‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˌskrɪməˈneɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the practice of treating one person or group differently from another in an unfair way: → positive discrimination, reverse discrimination ► see thesaurus at prejudice</div><ul class=\"examples\"><li><em>laws to prevent discrimination</em></li><li><strong><em>discrimination against</strong>: widespread discrimination against older people in the job market</em></li><li><strong><em>discrimination in favour of</strong>: discrimination in favour of university graduates</em></li><li><strong><em>racial/sex/religious etc discrimination</strong> (=treating someone unfairly because of their race, sex etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the ability to recognize the difference between two or more things, especially the difference in their quality:</div><ul class=\"examples\"><li><em>shape discrimination</em></li></ul></div>","2072":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧scuss</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskʌs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to talk about something with another person or a group in order to exchange ideas or decide something: ► see thesaurus at talk RegisterIn everyday English, people usually say talk about rather than discuss:· It’s good to be able to talk about these things.</div><ul class=\"examples\"><li><em>Littman refused to discuss the case publicly.</em></li><li><em>If you would like to discuss the matter further, please call me.</em></li><li><strong><em>discuss something with somebody</strong>: Pupils should be given time to discuss the book with their classmates.</em></li><li><strong><em>discuss what/who/where etc</strong>: Your accountant will discuss with you how to complete these forms.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to talk or write about something in detail and consider different ideas or opinions about it:</div><ul class=\"examples\"><li><em>This topic will be discussed in Chapter 4.</em></li></ul></div>","2073":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧scus‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈskʌʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when you discuss something:</div><ul class=\"examples\"><li><em>class discussions</em></li><li><em>the topics suggested for discussion</em></li><li><strong><em>discussion of</strong>: the discussion of important issues</em></li><li><strong><em>discussion about</strong>: high-level discussions about trade and commerce</em></li><li><strong><em>discussion with</strong>: The embassy will continue discussions with the Chinese government.</em></li><li><em>We have had discussions about her legal situation.</em></li><li><strong><em>under discussion</strong> (=being discussed): The project is under discussion as a possible joint venture.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of writing about a subject that considers different ideas or opinions about it</div><ul class=\"examples\"><li><strong><em>discussion of</strong>: the report’s discussion of the legislation</em></li></ul></div>","2074":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ease</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈziːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> an illness which affects a person, animal, or plant ► see thesaurus at illness</div><ul class=\"examples\"><li><strong><em>disease of</strong>: She suffers from a rare disease of the brain.</em></li><li><em>His father died of heart disease.</em></li><li><em>She contracted the disease while she was abroad on holiday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something that is seriously wrong with society or with someone’s mind, behaviour etc:</div><ul class=\"examples\"><li><em>Loneliness is a disease of our urban communities.</em></li></ul></div>","2075":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧grace</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɡreɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the loss of other people’s respect because you have done something they strongly disapprove of: ► see thesaurus at shame</div><ul class=\"examples\"><li><em>Smith faced total public disgrace after the incident.</em></li><li><strong><em>in disgrace</strong>: Toranaga sent us away in disgrace.</em></li><li><em>His actions brought disgrace on the family.</em></li><li><em>There was no disgrace in finishing fourth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be a disgrace</strong> used to say that something or someone is so bad or unacceptable that the people involved with them should feel ashamed:</div><ul class=\"examples\"><li><em>The UK rail system is a national disgrace.</em></li><li><strong><em>disgrace to</strong>: You are a disgrace to the medical profession.</em></li><li><strong><em>absolute/utter disgrace</strong>: It’s an absolute disgrace, the way he treats his wife.</em></li></ul></div>","2076":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧grace‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɡreɪsfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">bad, embarrassing, or unacceptable:</div><ul class=\"examples\"><li><em>It’s a disgraceful waste of taxpayers’ money.</em></li><li><strong><em>absolutely/utterly etc disgraceful</strong>: Their behaviour was absolutely disgraceful.</em></li><li><em>It is disgraceful that anyone should have to live in such conditions.</em></li></ul></div>","2077":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧guise</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɡaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to change someone’s appearance so that people cannot recognize them ► see thesaurus at hide</div><ul class=\"examples\"><li><strong><em>disguise yourself as somebody/something</strong>: Maybe you could disguise yourself as a waiter and sneak in there.</em></li><li><em>He escaped across the border disguised as a priest.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to change the appearance, sound, taste etc of something so that people do not recognize it:</div><ul class=\"examples\"><li><em>There’s no way you can disguise that southern accent.</em></li><li><strong><em>disguise something as something</strong>: a letter bomb disguised as a musical greetings card</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to hide a fact or feeling so that people will not notice it:</div><ul class=\"examples\"><li><em>Try as he might, Dan couldn’t disguise his feelings for Katie.</em></li><li><strong><em>disguise the fact (that)</strong>: There’s no disguising the fact that business is bad.</em></li><li><em>The speech was seen by many as a thinly disguised attack on the president.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> something that you wear to change your appearance and hide who you are, or the act of wearing this:</div><ul class=\"examples\"><li><em>His disguise didn’t fool anyone.</em></li><li><em>She wore dark glasses in an absurd attempt at disguise.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in disguise</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> wearing a disguise:</div><ul class=\"examples\"><li><em>The woman in the park turned out to be a police officer in disguise.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> made to seem like something else that is better:</div><ul class=\"examples\"><li><em>‘Tax reform’ is just a tax increase in disguise.</em></li></ul></div></div>","2078":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧gust</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɡʌst, dɪz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a strong feeling of dislike, annoyance, or disapproval</div><ul class=\"examples\"><li><strong><em>with disgust</strong>: Joan looked at him with disgust.</em></li><li><strong><em>in disgust</strong>: Sam threw his books down in disgust and stormed out of the room.</em></li><li><strong><em>to somebody’s disgust</strong>: Much to my disgust, I found that there were no toilets for the disabled.</em></li><li><strong><em>disgust with</strong>: Nelson’s disgust with US politics</em></li><li><strong><em>disgust at</strong>: The fans didn’t hide their disgust at the umpire’s decision.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a very strong feeling of dislike that almost makes you sick, caused by something unpleasant:</div><ul class=\"examples\"><li><em>He reached into the bin with a look of disgust on his face.</em></li><li><strong><em>with disgust</strong>: Edward tasted the thin, sour wines with disgust.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone feel very annoyed or upset about something that is not acceptable:</div><ul class=\"examples\"><li><em>Many parents claimed to be disgusted by the amount of violence in the film.</em></li><li><strong><em>be disgusted to find/hear/see etc</strong>: Dear Sir, I was disgusted to see the picture on page one of Sunday’s feature section.</em></li><li><strong><em>it disgusts somebody that/how/to do</strong>: It disgusts me that he got away with it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be so unpleasant that it makes you feel almost sick:</div><ul class=\"examples\"><li><em>The thought of eating insects disgusts me.</em></li></ul></div></div>","2079":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧gust‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɡʌstɪd, dɪz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">very annoyed or upset by something that is not acceptable:</div><ul class=\"examples\"><li><em>Disgusted onlookers claimed the driver was more concerned about his car than about the victim.</em></li><li><strong><em>disgusted at/by/with</strong>: Most locals are disgusted by the anti-foreigner violence.</em></li><li><strong><em>disgusted that</strong>: Animal welfare workers were disgusted that anyone could do this to a puppy.</em></li></ul></div>","2080":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧gust‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɡʌstɪŋ, dɪz-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely unpleasant and making you feel sick <em>SYN revolting</em>: ► see thesaurus at bad, horrible, taste</div><ul class=\"examples\"><li><em>Rubbish was piled everywhere – it was disgusting.</em></li><li><em>Smoking is a really disgusting habit.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> shocking and unacceptable:</div><ul class=\"examples\"><li><em>Sixty pounds for a thirty-minute consultation. I think that’s disgusting!</em></li><li><em>That’s a disgusting thing to say.</em></li></ul></div>","2081":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a flat container with low sides, for serving food from or cooking food in → bowl:</div><ul class=\"examples\"><li><em>a serving dish</em></li><li><em>an ovenproof dish</em></li><li><strong><em>dish of</strong>: a large dish of spaghetti</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the dishes</strong> all the plates, cups, bowls etc that have been used to eat a meal and need to be washed RegisterIn everyday English, people often use the expression do the washing-up (BrE) or do the dishes (AmE), rather than wash the dishes.</div><ul class=\"examples\"><li><strong><em>do/wash the dishes</strong>: I’ll just do the dishes before we go.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a type of food that is cooked in a particular way and served as part of a meal: ► see thesaurus at food</div><ul class=\"examples\"><li><em>a wonderful pasta dish</em></li><li><em>The menu includes a wide selection of vegetarian dishes.</em></li><li><em>This soup is substantial enough to serve as a main dish (=the biggest part of a meal).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> something that is shaped like a dish:</div><ul class=\"examples\"><li><em>a soap dish</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>informal</em> <em>old-fashioned</em> someone who is sexually attractive</div></div>","2082":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dish‧wash‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪʃˌwɒʃə $ -ˌwɒːʃər, -ˌwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a machine that washes dishes</div><div class=\"sense\"><span class=\"snum\">2</span> <em>especially American English</em> someone whose job is to wash dirty dishes, plates etc, especially in a restaurant</div></div>","2083":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small flat piece of plastic or metal which is used for storing computer or electronic information</div><div class=\"sense\"><span class=\"snum\">2</span> the usual American spelling of disc</div></div>","2084":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧like</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈlaɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to think someone or something is unpleasant and not like them <em>OPP like</em>: RegisterIn everyday English, people usually say don’t like rather than dislike:· Why don’t you like her?· He doesn’t like being criticized.</div><ul class=\"examples\"><li><em>Why do you dislike her so much?</em></li><li><strong><em>dislike doing something</strong>: I dislike being the centre of attention.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧like</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈlaɪk, ˈdɪslaɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a feeling of not liking someone or something <em>OPP liking</em></div><ul class=\"examples\"><li><strong><em>dislike of</strong>: She shared her mother’s dislike of housework.</em></li><li><strong><em>dislike for</strong>: Truman had a strong dislike for communism.</em></li><li><strong><em>intense/acute/violent etc dislike</strong> (=very strong dislike): His colleagues regarded him with intense dislike.</em></li><li><em>They took an instant dislike to each other (=they disliked each other immediately).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>dislikes</strong> <span class=\"gram\">[plural]</span> the things that you do not like:</div><ul class=\"examples\"><li><em>A good hotel manager should know his regular guests’ likes and dislikes.</em></li></ul></div></div>","2085":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧mal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪzməl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a situation or a place is dismal, it is so bad that it makes you feel very unhappy and hopeless:</div><ul class=\"examples\"><li><em>The future looks pretty dismal right now.</em></li><li><em>a dismal, grey afternoon</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> bad and unsuccessful:</div><ul class=\"examples\"><li><em>The team’s record so far is pretty dismal.</em></li><li><em>Her scheme was a dismal failure.</em></li></ul></div>","2086":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧man‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈmæntl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to take a machine or piece of equipment apart so that it is in separate pieces:</div><ul class=\"examples\"><li><em>Chris dismantled the bike in five minutes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to gradually get rid of a system or organization:</div><ul class=\"examples\"><li><em>an election promise to dismantle the existing tax legislation</em></li></ul></div>","2087":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧may</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈmeɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the worry, disappointment, or unhappiness you feel when something unpleasant happens</div><ul class=\"examples\"><li><strong><em>with/in dismay</strong>: They stared at each other in dismay.</em></li><li><strong><em>to somebody’s dismay</strong>: I found to my dismay that I had left my notes behind.</em></li><li><em>The thought of leaving filled him with dismay.</em></li></ul></div>","2088":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧miss</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈmɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to refuse to consider someone’s idea, opinion etc, because you think it is not serious, true, or important:</div><ul class=\"examples\"><li><em>The government has dismissed criticisms that the country’s health policy is a mess.</em></li><li><strong><em>dismiss something as something</strong>: He just laughed and dismissed my proposal as unrealistic.</em></li><li><em>It’s an idea that shouldn’t be dismissed out of hand (=dismissed immediately and completely).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to remove someone from their job <em>SYN fire</em> <em>, sack</em> RegisterIn everyday British English, people usually say sack someone, and in everyday American English, people usually say fire someone, rather than use dismiss:· He was sacked <em>(BrE)</em> /fired<em>(AmE)</em> for being late all the time.</div><ul class=\"examples\"><li><strong><em>dismiss somebody from something</strong>: Bryant was unfairly dismissed from his post.</em></li><li><strong><em>dismiss somebody for something</strong>: Employees can be dismissed for sending obscene emails.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> to tell someone that they are allowed to go, or are no longer needed:</div><ul class=\"examples\"><li><em>The class was dismissed early today.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if a judge dismisses a court case, he or she stops it from continuing:</div><ul class=\"examples\"><li><em>The case was dismissed owing to lack of evidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to end the innings of a player or team in the game of cricket</div></div>","2089":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧miss‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈmɪsəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when someone is removed from their job:</div><ul class=\"examples\"><li><em>Wilson was claiming compensation for unfair dismissal.</em></li><li><em>No dismissals have been announced yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when someone decides or says that something is not important, serious, or true:</div><ul class=\"examples\"><li><em>Gill’s dismissal of the book as ‘386 pages of rubbish’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a decision by a judge to stop a court case</div></div>","2090":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧o‧be‧di‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈbiːdiənt◂, ˌdɪsəʊ- $ ˌdɪsə-, ˌdɪsoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">deliberately not doing what you are told to do by your parents, teacher etc <em>OPP obedient</em></div></div>","2091":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧o‧bey</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈbeɪ, ˌdɪsəʊ- $ ˌdɪsə-, ˌdɪsoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to refuse to do what someone with authority tells you to do, or refuse to obey a rule or law <em>OPP obey</em>:</div><ul class=\"examples\"><li><em>You disobeyed my orders.</em></li></ul></div>","2092":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧or‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɔːdə $ -ˈɔːrdər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> <em>medical</em> a mental or physical illness which prevents part of your body from working properly ► see thesaurus at illness</div><ul class=\"examples\"><li><strong><em>a disorder of the brain/liver/digestive system etc</strong>: He suffers from a rare disorder of the liver.</em></li><li><strong><em>a stomach/lung/heart etc disorder</em></strong></li><li><strong><em>a mental/psychiatric disorder</strong>: people with mental disorders</em></li><li><em>severe eating disorders such as bulimia and anorexia</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a situation in which a lot of people behave in an uncontrolled, noisy, or violent way in public</div><ul class=\"examples\"><li><strong><em>civil/public/crowd disorder</strong>: A number of stadiums were closed because of crowd disorder.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a situation in which things or people are very untidy or disorganized <em>OPP order</em></div><ul class=\"examples\"><li><strong><em>in/into disorder</strong>: Everything was in disorder, but nothing seemed to be missing.</em></li><li><em>His whole system was thrown into disorder.</em></li></ul></div>","2093":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧or‧gan‧ized</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈɔːɡənaɪzd $ -ˈɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not arranged or planned in a clear order, or lacking any kind of plan or system <em>OPP well-organized</em>:</div><ul class=\"examples\"><li><em>The conference was completely disorganized.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is disorganized is very bad at arranging or planning things <em>OPP organized</em>:</div><ul class=\"examples\"><li><em>He’s an extremely disorganized person.</em></li></ul></div>","2094":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧spar‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspærəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural disparities)</span></div><div class=\"entry-body\"><div class=\"sense\">a difference between two or more things, especially an unfair one → parity</div><ul class=\"examples\"><li><strong><em>disparity in/between</strong>: a disparity between the rates of pay for men and women</em></li></ul></div>","2095":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧spatch</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspætʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> to send someone or something somewhere for a particular purpose</div><ul class=\"examples\"><li><strong><em>dispatch somebody/something to somebody/something</strong>: A reporter was dispatched to Naples to cover the riot.</em></li><li><em>Goods are normally dispatched within 24 hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to deal with someone or to finish a job quickly and effectively:</div><ul class=\"examples\"><li><em>She dispatched (=beat) her opponent 6–2, 6–1.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>old-fashioned</em> to deliberately kill a person or animal</div></div>","2096":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧spense</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspens/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to give something to people, especially in fixed amounts <em>SYN give out</em></div><ul class=\"examples\"><li><strong><em>dispense something to somebody</strong>: Villagers dispensed tea to visitors.</em></li><li><em>a machine for dispensing cash</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to officially provide something for people</div><ul class=\"examples\"><li><strong><em>dispense justice</strong> (=decide whether or not someone is guilty of a crime and what punishment they should receive)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to officially prepare and give medicines to people</div></div>","2097":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧sperse</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspɜːs $ -ɜːrs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a group of people disperse or are dispersed, they go away in different directions:</div><ul class=\"examples\"><li><em>Police used tear gas to disperse the crowd.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something disperses or is dispersed, it spreads in different directions over a wide area:</div><ul class=\"examples\"><li><em>The clouds dispersed as quickly as they had gathered.</em></li></ul></div>","2098":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧place</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈpleɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to take the place or position of something or someone <em>SYN replace</em>:</div><ul class=\"examples\"><li><em>Coal has been displaced by natural gas as a major source of energy.</em></li><li><em>immigrants who displace US workers in the job market</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make a group of people or animals have to leave the place where they normally live:</div><ul class=\"examples\"><li><em>Fifty thousand people have been displaced by the fighting.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to force something out of its usual place or position:</div><ul class=\"examples\"><li><em>The water displaced by the landslides created a tidal wave.</em></li></ul></div>","2099":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧splay</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspleɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[objects]</strong> an arrangement of things for people to look at or buy</div><ul class=\"examples\"><li><strong><em>display of</strong>: a superb display of African masks</em></li><li><em>a dazzling display (=very good display) of flowers</em></li><li><em>The window display caught her eye.</em></li><li><em>display cases containing old photographs</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[entertainment]</strong> a public performance of something that is intended to entertain people:</div><ul class=\"examples\"><li><em>a fireworks display</em></li><li><strong><em>display of</strong>: a display of juggling</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on display</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> something that is on display is in a public place where people can look at it <em>SYN on show</em>:</div><ul class=\"examples\"><li><em>Mapplethorpe’s photographs were first put on display in New York.</em></li><li><strong><em>be/go on display</strong>: One of the world’s oldest cars has gone on display in Brighton today.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a quality, feeling, or skill is on display, it is very clear and easy to notice:</div><ul class=\"examples\"><li><em>The musical talent on display is extremely impressive.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>display of affection/emotion/aggression etc</strong> an occasion when someone clearly shows a particular feeling, attitude, or quality:</div><ul class=\"examples\"><li><em>Unprovoked displays of aggression cannot be tolerated.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[on equipment]</strong> a part of a piece of equipment that shows information, for example a computer screen:</div><ul class=\"examples\"><li><em>This time the display flashed a red warning signal.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to show something to people, or put it in a place where people can see it easily:</div><ul class=\"examples\"><li><em>shop windows displaying the latest fashions</em></li><li><em>All the exam results will be displayed on the noticeboard.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to clearly show a feeling, attitude, or quality by what you do or say:</div><ul class=\"examples\"><li><em>She displayed no emotion on the witness stand.</em></li><li><em>ten piano pieces, each written to display the talents of individual players</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> if a computer or something similar displays information, it shows it on its screen:</div><ul class=\"examples\"><li><em>I pressed ‘return’ and an error message was displayed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> if a male bird or animal displays, it behaves in a particular way as a signal to other birds or animals, especially to attract a female</div></div></div>","2100":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧pos‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspəʊzəl $ -ˈspoʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> when you get rid of something</div><ul class=\"examples\"><li><strong><em>disposal of</strong>: the safe disposal of radioactive waste</em></li><li><em>bomb disposal experts</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>at somebody’s disposal</strong> available for someone to use:</div><ul class=\"examples\"><li><em>Tanner had a lot of cash at his disposal.</em></li><li><strong><em>somebody is at your (complete) disposal</strong> (=someone is ready to help you in any way)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>American English</em> a small machine under the kitchen sink which breaks vegetable waste into small pieces <em>SYN waste disposal</em></div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> <em>technical</em> the sale of something you own such as a house, a business, or land:</div><ul class=\"examples\"><li><em>The profit or loss on the disposal of an asset must be accounted for.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the way in which an amount of money is used:</div><ul class=\"examples\"><li><em>They had complete control over the disposal of the funds.</em></li></ul></div>","2101":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧pose</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspəʊz $ -ˈspoʊz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive always + adverb/preposition]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> to arrange things or put them in their places:</div><ul class=\"examples\"><li><em>Chinese vases are disposed around the gallery.</em></li></ul></div>","2102":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧po‧si‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪspəˈzɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> a particular type of character which makes someone likely to behave or react in a certain way <em>SYN temperament</em></div><ul class=\"examples\"><li><strong><em>of a nervous/sociable/sensitive etc disposition</strong> (=having a nervous etc character): The film is not suitable for people of a nervous disposition.</em></li><li><strong><em>have a cheerful/sunny etc disposition</strong> (=have a happy character)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a tendency or willingness to behave in a particular way <em>SYN inclination</em></div><ul class=\"examples\"><li><strong><em>have/show a disposition to do something</strong>: Neither side shows the slightest disposition to compromise.</em></li><li><strong><em>disposition towards</strong>: Most children have a disposition towards obedience.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> the position or arrangement of something in a particular place</div><ul class=\"examples\"><li><strong><em>disposition of</strong>: a map showing the disposition of American forces</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the way in which something is dealt with or used</div><ul class=\"examples\"><li><strong><em>disposition of</strong>: A solicitor advised him as to the disposition of the money.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable, uncountable]</span> <em>law</em> the act of formally giving property to someone:</div><ul class=\"examples\"><li><em>the disposition of assets on death</em></li></ul></div>","2103":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧pute</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspjuːt, ˈdɪspjuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a serious argument or disagreement ► see thesaurus at argument</div><ul class=\"examples\"><li><strong><em>dispute with</strong>: The firm is involved in a legal dispute with a rival company.</em></li><li><strong><em>dispute over</strong>: He got into a dispute over a taxi fare.</em></li><li><strong><em>dispute between</strong>: the bitter border dispute between the countries</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be beyond dispute</strong> if something is beyond dispute, everyone agrees that it is true or that it really happened:</div><ul class=\"examples\"><li><em>It is beyond dispute that advances in medicine have enabled people to live longer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be open to dispute</strong> if something is open to dispute, it is not completely certain and not everyone agrees about it:</div><ul class=\"examples\"><li><em>His interpretation of the poem is open to dispute.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in dispute</strong> if something is in dispute, people are arguing about it:</div><ul class=\"examples\"><li><em>The facts of the case are still in dispute.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧pute</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈspjuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to say that something such as a fact or idea is not correct or true:</div><ul class=\"examples\"><li><em>The main facts of the book have never been disputed.</em></li><li><strong><em>dispute that</strong>: Few would dispute that travel broadens the mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to argue or disagree with someone</div><ul class=\"examples\"><li><strong><em>dispute (something) with somebody</strong>: Hazlitt, though much younger, was soon disputing with Wordsworth on equal terms.</em></li><li><em>What happened next is hotly disputed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to try to get control of something or win something:</div><ul class=\"examples\"><li><em>Soviet forces disputed every inch of ground.</em></li></ul></div></div>","2104":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧re‧gard</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsrɪˈɡɑːd $ -ɑːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to ignore something or treat it as unimportant:</div><ul class=\"examples\"><li><em>He ordered the jury to disregard the witness’s last statement.</em></li><li><em>Mark totally disregarded my advice.</em></li></ul></div>","2105":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧rupt</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈrʌpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to prevent something from continuing in its usual way by causing problems:</div><ul class=\"examples\"><li><em>Traffic was disrupted by a hoax bomb.</em></li><li><em>Climate change could disrupt the agricultural economy.</em></li></ul></div>","2106":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧rup‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈrʌpʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a situation in which something is prevented from continuing in its usual way:</div><ul class=\"examples\"><li><em>The strike caused widespread disruption.</em></li><li><strong><em>disruption to</strong>: There will be some disruption to traffic while the work is in progress.</em></li></ul></div>","2107":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧sat‧is‧fac‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˌsætəsˈfækʃən, dɪsˌsæ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a feeling of not being satisfied <em>OPP satisfaction</em></div><ul class=\"examples\"><li><strong><em>dissatisfaction with</strong>: 30% of customers expressed dissatisfaction with the service.</em></li></ul></div>","2108":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧sat‧is‧fied</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsætəsfaɪd, dɪsˈsæ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not satisfied because something is not as good as you had expected <em>OPP satisfied</em>:</div><ul class=\"examples\"><li><em>dissatisfied clients</em></li><li><strong><em>dissatisfied with</strong>: If you are dissatisfied with this product, please return it.</em></li></ul></div>","2109":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧sent</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈsent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> refusal to agree with an official decision or accepted opinion <em>SYN opposition</em> → consent, assent:</div><ul class=\"examples\"><li><em>the ruthless suppression of political dissent</em></li><li><em>These voices of dissent grew louder.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>law</em> a statement by a judge giving their reasons for disagreeing with the other judges in a law case</div></div>","2110":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧ser‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪsəˈteɪʃən $ ˌdɪsər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a long piece of writing on a particular subject, especially one written for a university degree → thesis</div></div>","2111":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧solve</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈzɒlv $ dɪˈzɑːlv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[become part of liquid]</strong></div><ul class=\"examples\"><li><span class=\"gram\">[intransitive, transitive]</span> if a solid dissolves, or if you dissolve it, it mixes with a liquid and becomes part of it:</li><li><em>Stir until the sugar dissolves.</em></li><li><strong><em>dissolve in</strong>: Sugar dissolves in water.</em></li><li><strong><em>dissolve something in something</strong>: Dissolve the tablet in water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[end]</strong> <span class=\"gram\">[transitive]</span> to formally end a parliament, business arrangement, marriage etc:</div><ul class=\"examples\"><li><em>The monarch had the power to dissolve parliament.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[emotion]</strong> <strong>dissolve into/in laughter/tears etc</strong> to start laughing or crying:</div><ul class=\"examples\"><li><em>She dissolved into fits of laughter.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[become weaker]</strong> <span class=\"gram\">[intransitive, transitive]</span> to gradually become smaller or weaker before disappearing, or to make something do this:</div><ul class=\"examples\"><li><em>Her enthusiasm dissolved his shyness.</em></li><li><em>A few clouds formed briefly before dissolving again.</em></li></ul></div>","2112":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪstəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[amount of space]</strong> <span class=\"gram\">[countable, uncountable]</span> the amount of space between two places or things RegisterIn everyday English, when talking about how far something is, people often use an expression such as how far or a long/short way rather than the noun distance: What is the distance from Chicago to Detroit? ➔ How far is it from Chicago to Detroit? | The cottage is some distance from the road. ➔ The cottage is a long way from the road.</div><ul class=\"examples\"><li><strong><em>distance from/between</strong>: the distance from Chicago to Detroit / Measure the distance between the two points.</em></li><li><em>The cottage is some distance (=quite a long distance) from the road.</em></li><li><strong><em>at a distance of 2 feet/10 metres etc</strong>: A shark can smell blood at a distance of half a kilometer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[far away]</strong> <span class=\"gram\">[singular]</span> used to talk about a situation when something is far away from you in space or time</div><ul class=\"examples\"><li><strong><em>in the distance</strong>: Church bells rang in the distance (=they were far away).</em></li><li><strong><em>at/from a distance</strong>: We watched from a distance.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[unfriendly feeling]</strong> <span class=\"gram\">[singular]</span> a situation in which two people do not have a close friendly relationship</div><ul class=\"examples\"><li><strong><em>distance between</strong>: There was still a distance between me and my father.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>keep your distance</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stay far enough away from someone or something to be safe:</div><ul class=\"examples\"><li><em>A lighthouse on the cliff warns ships to keep their distance.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also keep somebody at a distance) to avoid becoming too friendly with someone:</div><ul class=\"examples\"><li><em>The neighbours tend to keep their distance.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>go the (full) distance</strong> <em>informal</em> to finish something you have started:</div><ul class=\"examples\"><li><em>Do you think Greg will go the distance this time?</em></li></ul></div>","2113":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪstənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[far away]</strong> far away in space or time: ► see thesaurus at far</div><ul class=\"examples\"><li><em>the sound of distant gunfire</em></li><li><em>Her honeymoon seemed a distant memory.</em></li><li><em>That affair was in the dim and distant past (=a long time ago).</em></li><li><em>The president hopes to visit Ireland in the not too distant future (=quite soon).</em></li><li><strong><em>distant from</strong>: stars that are distant from our galaxy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not friendly]</strong> unfriendly:</div><ul class=\"examples\"><li><em>After the quarrel Sue remained cold and distant.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[not concentrating]</strong> thinking deeply about something private, rather than about what is happening around you:</div><ul class=\"examples\"><li><em>Geri had a distant look in her eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[relative]</strong> <span class=\"gram\">[only before noun]</span> not closely related to you <em>OPP close</em>:</div><ul class=\"examples\"><li><em>a distant cousin</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>distant from something</strong> different from something or not closely connected with it:</div><ul class=\"examples\"><li><em>The reality of independence was distant from the hopes they had had.</em></li></ul></div>","2114":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tinct</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɪŋkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> clearly different or belonging to a different type:</div><ul class=\"examples\"><li><em>two entirely distinct languages</em></li><li><strong><em>distinct types/groups/categories etc</strong>: There are four distinct types.</em></li><li><strong><em>distinct from</strong>: The learning needs of the two groups are quite distinct from each other.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>as distinct from something</strong> used to make it clear that you are not referring to a particular kind of thing, but to something else:</div><ul class=\"examples\"><li><em>a movie star, as distinct from an actor</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> something that is distinct can clearly be seen, heard, smelled etc <em>OPP indistinct</em>:</div><ul class=\"examples\"><li><em>The outline of the ship became more distinct.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[only before noun]</span> a distinct possibility, feeling, quality etc definitely exists and cannot be ignored:</div><ul class=\"examples\"><li><em>I got the distinct impression he was trying to make me angry.</em></li><li><em>There is a distinct possibility that this will eventually be needed.</em></li><li><em>a distinct lack of enthusiasm</em></li></ul></div>","2115":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tinc‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɪŋkʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[difference]</strong> <span class=\"gram\">[countable, uncountable]</span> a clear difference or separation between two similar things RegisterIn written English, people often use draw a distinction rather than make a distinction, because it sounds more formal:· The law draws a distinction between temporary and permanent employees.</div><ul class=\"examples\"><li><strong><em>distinction between</strong>: the distinction between formal and informal language</em></li><li><strong><em>clear/sharp distinction</strong>: There is often no clear distinction between an allergy and food intolerance.</em></li><li><strong><em>make/draw a distinction</strong>: The Act makes no distinction between children and adults (=it treats them as if they were the same).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[excellence]</strong> <span class=\"gram\">[uncountable]</span> the quality of being excellent and important:</div><ul class=\"examples\"><li><em>Eliot’s distinction as a poet</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[being special]</strong> <span class=\"gram\">[singular]</span> the quality of being special in some way</div><ul class=\"examples\"><li><strong><em>have/earn/achieve etc the distinction of doing something</strong>: At that time, it had the distinction of being the largest bridge in the UK. / The US enjoys the dubious distinction of being the lawsuit capital of the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[result]</strong> <span class=\"gram\">[countable, uncountable]</span> a special mark given to a student whose work is excellent</div><ul class=\"examples\"><li><strong><em>with distinction</strong>: He obtained a law doctorate with distinction.</em></li></ul></div>","2116":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tinc‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɪŋktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">having a special quality, character, or appearance that is different and easy to recognize: ► see thesaurus at different</div><ul class=\"examples\"><li><em>a rock band with a distinctive sound</em></li></ul></div>","2117":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tinct‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɪŋktli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> clearly <em>OPP indistinctly</em>:</div><ul class=\"examples\"><li><em>Speak clearly and distinctly.</em></li><li><em>He distinctly remembered the day his father left.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very:</div><ul class=\"examples\"><li><em>Paul was left feeling distinctly foolish.</em></li><li><strong><em>distinctly uncomfortable/uneasy/unhappy etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that something has a particular quality or character that is easy to recognize:</div><ul class=\"examples\"><li><em>dishes with a distinctly Jewish flavor</em></li></ul></div>","2118":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tin‧guish</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɪŋɡwɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to recognize and understand the difference between two or more things or people <em>SYN differentiate</em> ► see thesaurus at recognize RegisterIn everyday English, people usually use the phrases tell the difference between somebody/something or tell somebody/something from somebody/something, rather than distinguish:· He can’t tell the difference between right and wrong.· How do you tell cancer cells from healthy cells?</div><ul class=\"examples\"><li><strong><em>distinguish between</strong>: His attorney argued that Cope could not distinguish between right and wrong.</em></li><li><strong><em>distinguish somebody/something from</strong>: a method of distinguishing cancer cells from normal tissue</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive not in progressive]</span> to be the thing that makes someone or something different or special</div><ul class=\"examples\"><li><strong><em>distinguish somebody/something from</strong>: The factor that distinguishes this company from the competition is customer service.</em></li><li><strong><em>distinguishing feature/mark/characteristic</strong>: The main distinguishing feature of this species is the leaf shape.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive not in progressive]</span> <em>written</em> to be able to see the shape of something or hear a particular sound:</div><ul class=\"examples\"><li><em>The light was too dim for me to distinguish anything clearly.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>distinguish yourself</strong> to do something so well that people notice and remember you:</div><ul class=\"examples\"><li><em>He distinguished himself on several occasions in the civil war.</em></li></ul></div>","2119":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tin‧guished</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɪŋɡwɪʃt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> successful, respected, and admired:</div><ul class=\"examples\"><li><em>a long and distinguished career</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> dressed in neat and attractive clothes that are worn by adults, not looking like a young person:</div><ul class=\"examples\"><li><em>a tall distinguished figure in a dark suit</em></li></ul></div>","2120":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tort</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɔːt $ -ɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to change the appearance, sound, or shape of something so that it is strange or unclear:</div><ul class=\"examples\"><li><em>Tall buildings can distort radio signals.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to report something in a way that is not completely true or correct:</div><ul class=\"examples\"><li><em>His account was badly distorted by the press.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to change a situation from the way it would naturally be:</div><ul class=\"examples\"><li><em>an expensive subsidy which distorts the market</em></li></ul></div>","2121":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tract</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to take someone’s attention away from something by making them look at or listen to something else:</div><ul class=\"examples\"><li><em>Try not to distract the other students.</em></li><li><strong><em>distract somebody/something from something</strong>: Coverage of the war was used to distract attention from other matters.</em></li></ul></div>","2122":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧trac‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrækʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> something that stops you paying attention to what you are doing:</div><ul class=\"examples\"><li><em>I study in the library as there are too many distractions at home.</em></li><li><strong><em>distraction from</strong>: Demands for equality were seen as a distraction from more serious issues.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>drive somebody to distraction</strong> to continue annoying or upsetting someone very much:</div><ul class=\"examples\"><li><em>The baby’s constant crying drove me to distraction.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>old-fashioned</em> a pleasant activity</div></div>","2123":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tress</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstres/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a feeling of extreme unhappiness:</div><ul class=\"examples\"><li><em>Luke’s behaviour caused his parents great distress.</em></li><li><strong><em>in distress</strong>: The girl was crying and clearly in distress.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> suffering and problems caused by a lack of money, food etc:</div><ul class=\"examples\"><li><em>acute financial distress</em></li><li><strong><em>in distress</strong>: charities that aid families in distress</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> great physical pain</div><div class=\"sense\"><span class=\"snum\">4</span> a situation when a ship, aircraft etc is in danger and needs help:</div><ul class=\"examples\"><li><em>We picked up a distress signal 6 km away.</em></li><li><strong><em>in distress</strong>: The ship is in distress.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone feel very upset:</div><ul class=\"examples\"><li><em>The dream had distressed her greatly.</em></li></ul></div></div>","2124":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tressed</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrest/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very upset ► see thesaurus at sad</div><ul class=\"examples\"><li><strong><em>deeply/visibly distressed</strong>: Hannah was deeply distressed by the news.</em></li><li><strong><em>distressed at/by</strong>: My client is very distressed at the treatment she received from your officers.</em></li><li><strong><em>distressed to find/hear/see/learn etc something</strong>: She was distressed to see he was crying.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> in a lot of pain:</div><ul class=\"examples\"><li><em>The animal was clearly distressed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> distressed furniture or clothes have been made to look older than they really are</div><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> having very little money:</div><ul class=\"examples\"><li><em>a family living in distressed circumstances</em></li></ul></div>","2125":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧trib‧ute</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrɪbjuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to share things among a group of people, especially in a planned way <em>SYN give out</em> ► see thesaurus at give</div><ul class=\"examples\"><li><strong><em>distribute something among/to somebody</strong>: Clothes and blankets have been distributed among the refugees. / a man distributing leaflets to passers-by</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to supply goods to shops and companies so that they can sell them:</div><ul class=\"examples\"><li><em>Milk is distributed to the local shops by Herald’s Dairies.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to spread something over a large area:</div><ul class=\"examples\"><li><em>Make sure the weight of the load is evenly distributed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be distributed</strong> to exist in different parts of an area or group</div><ul class=\"examples\"><li><strong><em>be widely/evenly distributed</strong>: This species of dolphin is widely distributed throughout the world.</em></li><li><em>The population is distributed in a very uneven pattern.</em></li></ul></div>","2126":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧tri‧bu‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɪstrəˈbjuːʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the act of sharing things among a large group of people in a planned way</div><ul class=\"examples\"><li><strong><em>distribution of</strong>: the distribution of aid supplies</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when goods are supplied to shops and companies for them to sell:</div><ul class=\"examples\"><li><em>a distribution centre</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> the way in which something exists in different amounts in different parts of an area or group:</div><ul class=\"examples\"><li><em>population distribution</em></li><li><strong><em>distribution of</strong>: the highly unequal distribution of economic power</em></li></ul></div>","2127":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧trib‧u‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstrɪbjətə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a company or person that supplies shops and companies with goods</div><div class=\"sense\"><span class=\"snum\">2</span> the part of an engine that sends an electric current to the spark plugs</div></div>","2128":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧trict</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪstrɪkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an area of a town or the countryside, especially one with particular features ► see thesaurus at area</div><ul class=\"examples\"><li><strong><em>rural/financial/theatre etc district</strong>: a house in a pleasant suburban district</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an area of a country, city etc that has official borders:</div><ul class=\"examples\"><li><em>a postal district</em></li></ul></div>","2129":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧trust</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪsˈtrʌst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a feeling that you cannot trust someone → mistrust:</div><ul class=\"examples\"><li><em>Local people regard the police with suspicion and distrust.</em></li><li><strong><em>distrust of</strong>: Dylan’s deep distrust of journalists made him difficult to interview.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to not trust someone or something <em>OPP trust</em>:</div><ul class=\"examples\"><li><em>She had every reason to distrust him.</em></li></ul></div></div>","2130":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧turb</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɜːb $ -ɜːrb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[interrupt]</strong> to interrupt someone so that they cannot continue what they are doing:</div><ul class=\"examples\"><li><em>Sorry to disturb you, but I have an urgent message.</em></li><li><em>The thieves fled when they were disturbed by a neighbour.</em></li><li><em>Do not disturb (=a sign you put on a door so that people will not interrupt you).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[worry]</strong> to make someone feel worried or upset:</div><ul class=\"examples\"><li><em>What disturbs you most about this latest development?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[move]</strong> to move something or change its position:</div><ul class=\"examples\"><li><em>If you find a bird’s nest, never disturb the eggs.</em></li><li><em>I promise not to disturb anything.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[change]</strong> to change a normal situation in a way that causes problems:</div><ul class=\"examples\"><li><em>My hormone balance is disturbed by my pregnancy.</em></li><li><em>New procedures often disturb the comfortable habits of the workforce.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>disturb the peace</strong> <em>law</em> to behave in a noisy and unpleasant way in public</div></div>","2131":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧turb‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɜːbəns $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> a situation in which people behave violently in public:</div><ul class=\"examples\"><li><em>There were disturbances in the crowd as fans left the stadium.</em></li><li><strong><em>create/cause a disturbance</em></strong></li><li><em>army training on controlling civil disturbance</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> something that interrupts what you are doing, or the act of making this happen:</div><ul class=\"examples\"><li><em>We arrange the work so there’s as little disturbance as possible.</em></li><li><strong><em>disturbance to</strong>: When a helicopter lands, it can cause a disturbance to local residents.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a medical condition in which someone is mentally ill and does not behave normally:</div><ul class=\"examples\"><li><em>a history of mental disturbance</em></li></ul></div>","2132":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dis‧turb‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /dɪˈstɜːbɪŋ $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">worrying or upsetting:</div><ul class=\"examples\"><li><em>a disturbing increase in the crime rate</em></li></ul></div>","2133":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɪtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a long narrow hole dug at the side of a field, road etc to hold or remove unwanted water</div></div>","2134":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dit‧to</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪtəʊ $ -toʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say that you have exactly the same opinion as someone else:</div><ul class=\"examples\"><li><em>‘I hated school.’ ‘Ditto.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that what is true of one thing is also true of another:</div><ul class=\"examples\"><li><em>Where should she go? Mississippi? Too hot. Ditto Alabama.</em></li></ul></div>","2135":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span><span class=\"meta-item\">(past tense dived also dove /dəʊv $ doʊv/ American English, past participle dived)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[jump into water]</strong> to jump into deep water with your head and arms going in first ► see thesaurus at jump</div><ul class=\"examples\"><li><strong><em>dive into/off etc</strong>: She dived into a pool. / Diving off the cliffs is dangerous.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[swim under water]</strong> to swim under water using special equipment to help you breathe:</div><ul class=\"examples\"><li><em>The first time you dive on a coral reef is an experience you will never forget.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[go deeper/lower]</strong> to travel down through the air or through water to a lower level:</div><ul class=\"examples\"><li><em>The submarine began to dive.</em></li><li><em>The aircraft appeared to dive vertically towards the crowd.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[move quickly]</strong> <span class=\"gram\">[always + adverb/preposition]</span> to move or jump quickly in a particular direction or into a particular place:</div><ul class=\"examples\"><li><em>Jackson dived after the ball.</em></li><li><em>We dived into a shop to avoid the rain.</em></li><li><em>The soldiers were diving for cover (=to protect themselves behind something).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>dive into your bag/pocket etc</strong> to put your hand quickly in your bag, pocket etc in order to get something out:</div><ul class=\"examples\"><li><em>He dived into his pocket and produced a packet of cigarettes.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[numbers]</strong> if numbers, prices etc dive, they suddenly become much lower than before:</div><ul class=\"examples\"><li><em>The dollar dived against the yen in Tokyo today.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[soccer]</strong> to fall down deliberately in order to unfairly win a free kick or a penalty</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[sudden movement]</strong> a sudden movement in a particular direction or into a particular place:</div><ul class=\"examples\"><li><em>She made a dive for the bathroom.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sudden fall]</strong> a sudden fall in the amount, value, or success of something:</div><ul class=\"examples\"><li><em>The news put shares in a dive.</em></li><li><em>The team’s fortunes have taken a dive this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[movement downwards]</strong> when something moves down through the air or water:</div><ul class=\"examples\"><li><em>Thankfully, the pilot managed to pull out of the dive and regain control.</em></li><li><strong><em>steep/vertical dive</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[jump]</strong> a jump into deep water with your head and arms going in first</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[swim]</strong> the act of going under water to swim, using special equipment to help you breathe</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[place]</strong> <em>informal</em> a bar, club etc that is cheap and dirty</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[soccer]</strong> the act of falling down deliberately in order to unfairly win a freekick or a penalty</div></div></div>","2136":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> div‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaɪvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who swims or works under water using special equipment to help them breathe</div><div class=\"sense\"><span class=\"snum\">2</span> someone who jumps into water with their head and arms first</div></div>","2137":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧verse</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈvɜːs $ dəˈvɜːrs, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">very different from each other:</div><ul class=\"examples\"><li><em>subjects as diverse as pop music and archaeology</em></li></ul></div>","2138":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ver‧si‧fy</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈvɜːsɪfaɪ $ dəˈvɜːr-, daɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\">(past tense and past participle diversified, present participle diversifying, third person singular diversifies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if a business, company, country etc diversifies, it increases the range of goods or services it produces</div><ul class=\"examples\"><li><strong><em>diversify (away) from</strong>: farmers forced to diversify away from their core business</em></li><li><strong><em>diversify into</strong>: The company is planning to diversify into other mining activities.</em></li><li><em>We need to diversify the economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to change something or to make it change so that there is more variety:</div><ul class=\"examples\"><li><em>User requirements have diversified over the years.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> <em>technical</em> to put money into several different types of investment instead of only one or two</div><ul class=\"examples\"><li><strong><em>diversify into</strong>: Spread the risk by diversifying into dollar bonds.</em></li></ul></div>","2139":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ver‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈvɜːʃən, də- $ -ɜːrʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a change in the direction or use of something, or the act of changing it</div><ul class=\"examples\"><li><strong><em>diversion of</strong>: the diversion of the river / the diversion of funds into the military budget</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> an enjoyable activity that you do to stop yourself from becoming bored</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> something that stops you from paying attention to what you are doing or what is happening:</div><ul class=\"examples\"><li><em>Two prisoners created a diversion to give the men time to escape.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>British English</em> a different way that traffic is sent when the usual roads are closed</div></div>","2140":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧ver‧si‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈvɜːsəti, də- $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the fact of including many different types of people or things</div><ul class=\"examples\"><li><strong><em>cultural/ethnic/linguistic etc diversity</strong>: The curriculum will take account of the ethnic diversity of the population.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a range of different people, things, or ideas <em>SYN variety</em></div><ul class=\"examples\"><li><strong><em>diversity of</strong>: a diversity of opinions</em></li></ul></div>","2141":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧vert</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈvɜːt, də- $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to change the use of something such as time or money</div><ul class=\"examples\"><li><strong><em>divert something into/to/(away) from etc something</strong>: The company should divert more resources into research. / Officials diverted revenue from arms sales to the rebels.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to change the direction in which something travels</div><ul class=\"examples\"><li><strong><em>divert a river/footpath/road etc</strong>: Canals divert water from the Truckee River into the lake.</em></li><li><em>The high street is closed and traffic is being diverted.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if you divert your telephone calls, you arrange for them to go directly to another number, for example because you are not able to answer them yourself for some time:</div><ul class=\"examples\"><li><em>Remember to divert your phone when you are out of the office.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to deliberately take someone’s attention from something by making them think about or notice other things</div><ul class=\"examples\"><li><strong><em>divert (somebody’s) attention (away from somebody/something)</strong>: The crime crackdown is an attempt to divert attention from social problems.</em></li><li><em>He’d been trying to divert suspicion away from himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>formal</em> to amuse or entertain someone</div></div>","2142":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧vide</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈvaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[separate]</strong> <span class=\"gram\">[intransitive, transitive]</span> if something divides, or if you divide it, it separates into two or more parts ► see thesaurus at separate</div><ul class=\"examples\"><li><strong><em>divide something into something</strong>: Scientists traditionally divide the oceans into zones. / The book is divided into six sections.</em></li><li><strong><em>divide into</strong>: Here, the river divides into three channels.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[keep separate]</strong> (also divide off) <span class=\"gram\">[transitive]</span> to keep two areas separate from each other:</div><ul class=\"examples\"><li><em>The Wall used to divide East and West Berlin.</em></li><li><strong><em>divide something from something</strong>: Only a thin curtain divided her cabin from his.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[share]</strong> (also divide up) <span class=\"gram\">[transitive]</span> to separate something into parts and share them between people</div><ul class=\"examples\"><li><strong><em>divide something between/among somebody/something</strong>: The money will be divided equally among the charities.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[spend time/energy]</strong> <span class=\"gram\">[transitive]</span> if you divide your time, energy etc between different activities or places, you spend part of your time doing each activity or in each place</div><ul class=\"examples\"><li><strong><em>divide something between something/somebody</strong>: She divides her time between New York and Paris.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[mathematics]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> to calculate how many times one number contains a smaller number → multiply</div><ul class=\"examples\"><li><strong><em>divide something by something</strong>: If you divide 21 by 3, you get 7. / ‘What’s six divided by three?’ ‘Two’.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> to be contained exactly in a number one or more times</div><ul class=\"examples\"><li><strong><em>divide into</strong>: 8 divides into 64.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[disagree]</strong> <span class=\"gram\">[transitive]</span> to make people disagree so that they form groups with different opinions:</div><ul class=\"examples\"><li><em>The issue of cloning has sharply divided voters.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>divide and rule/conquer</strong> to defeat or control people by making them argue with each other instead of opposing you</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>divided loyalties</strong> a feeling you have when two people you like have argued and you are not sure which person you should support:</div><ul class=\"examples\"><li><em>Divorce is an agony of divided loyalties for children.</em></li></ul></div>","2143":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧vine</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈvaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> coming from or relating to God or a god</div><ul class=\"examples\"><li><strong><em>divine intervention/providence/revelation/guidance etc</strong>: faith in divine providence / divine power / divine love</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>old-fashioned</em> very pleasant or good</div></div>","2144":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧vi‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈvɪʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[separating]</strong> <span class=\"gram\">[countable, uncountable]</span> the act of separating something into two or more different parts, or the way these parts are separated or shared</div><ul class=\"examples\"><li><strong><em>division of something between/among/into something</strong>: the division of words into syllables / the traditional division of labour (=the way that particular tasks are shared) between husband and wife</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[disagreement]</strong> <span class=\"gram\">[countable, uncountable]</span> disagreement among the members of a group that makes them form smaller opposing groups</div><ul class=\"examples\"><li><strong><em>division between/within/among something</strong>: Can he heal the deep divisions among Republican ranks?</em></li><li><strong><em>racial/class/gender etc division</strong>: The old class divisions had begun to break down.</em></li><li><em>The Army was plagued by internal divisions.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[mathematics]</strong> <span class=\"gram\">[uncountable]</span> the process of finding out how many times one number is contained in another → multiplication, long division</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[part of an organization]</strong> <span class=\"gram\">[countable]</span> a group that does a particular job within a large organization:</div><ul class=\"examples\"><li><em>the Computer Services Division</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[military]</strong> <span class=\"gram\">[countable]</span> a large military group:</div><ul class=\"examples\"><li><em>a tank division</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sport]</strong> <span class=\"gram\">[countable]</span> one of the groups of teams that a sports competition is divided into, often based on the number of games they have won</div><ul class=\"examples\"><li><strong><em>the Premier/First/Second/Third/Fourth Division</strong>: a second-division club</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[in parliament]</strong> <span class=\"gram\">[countable]</span> a process in which members of the British parliament vote for something by dividing into groups:</div><ul class=\"examples\"><li><em>MPs forced a division on the bill.</em></li><li><em>Some members supported the opposition in the division lobbies (=the rooms where the vote takes place).</em></li></ul></div>","2145":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧vorce</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈvɔːs $ -ɔːrs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the legal ending of a marriage → separation:</div><ul class=\"examples\"><li><em>Why doesn’t she get a divorce?</em></li><li><em>One in three marriages ends in divorce.</em></li><li><strong><em>file/sue/petition for divorce</strong> (=start the legal divorce process)</em></li><li><em>His wife has started divorce proceedings.</em></li><li><em>the rise in the divorce rate</em></li><li><em>She received the house as part of the divorce settlement (=the amount of money, property etc each person receives in a divorce case).</em></li><li><em>The Act extended the grounds (=legal reasons) for divorce.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually singular]</span> <em>formal</em> the fact of separating two related things</div><ul class=\"examples\"><li><strong><em>divorce between</strong>: the divorce between theory and method</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if someone divorces their husband or wife, or if two people divorce, they legally end their marriage → separate:</div><ul class=\"examples\"><li><em>David’s parents divorced when he was six.</em></li><li><em>My father threatened to divorce her.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to separate two ideas, subjects etc completely</div><ul class=\"examples\"><li><strong><em>divorce something from something</strong>: It is difficult to divorce sport from politics.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to stop being involved in an activity, organization, situation etc</div><ul class=\"examples\"><li><strong><em>divorce yourself from something</strong>: Our society has divorced itself from religion.</em></li></ul></div></div>","2146":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> di‧vorced</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈvɔːst $ -ɔːrst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> no longer married to your wife or husband: ► see thesaurus at married</div><ul class=\"examples\"><li><em>Are you married, single, or divorced?</em></li><li><em>a divorced woman</em></li><li><strong><em>divorced from</strong>: Anne is divorced from Simon’s father.</em></li><li><em>My parents are getting divorced.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> separate from and not connected in any way to an idea, subject etc</div><ul class=\"examples\"><li><strong><em>divorced from</strong>: His ideas are completely divorced from reality.</em></li></ul></div>","2147":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> diz‧zy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪzi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling unable to stand steadily, for example because you are looking down from a high place or because you are ill:</div><ul class=\"examples\"><li><em>The heat and the champagne made him feel dizzy.</em></li><li><em>She started to suffer from dizzy spells (=a short period when you feel dizzy).</em></li><li><strong><em>dizzy with</strong>: Ruth felt dizzy with relief.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the dizzy heights (of something)</strong> an important position – used humorously:</div><ul class=\"examples\"><li><em>Naomi had reached the dizzy heights of manageress.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> stupid and forgetful:</div><ul class=\"examples\"><li><em>a dizzy blonde</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> very busy and exciting:</div><ul class=\"examples\"><li><em>Hong Kong buzzes from dawn to dusk at a dizzy pace.</em></li></ul></div>","2148":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌdiː en ˈeɪ◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">(deoxyribonucleic acid) a substance that carries genetic information in the cells of the body:</div><ul class=\"examples\"><li><em>A DNA test showed that he was not the baby&#x27;s father.</em></li></ul></div>","2149":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">auxiliary verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /duː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense did /dɪd/, past participle done /dʌn/, third person singular does /dəz; strong dʌz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used with another verb to form questions or negatives:</div><ul class=\"examples\"><li><em>Do you like bananas?</em></li><li><em>I don’t feel like going out tonight.</em></li><li><em>Ian didn’t answer.</em></li><li><em>Where do you live?</em></li><li><em>Doesn’t Rosie look wonderful?</em></li><li><em>Don’t listen to her!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>spoken</em> used to form question tags (=short questions that you add to the end of statements):</div><ul class=\"examples\"><li><em>You know Tony, don’t you?</em></li><li><em>She didn’t understand, did she?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used instead of repeating a verb that has already been used:</div><ul class=\"examples\"><li><em>‘Will Kay come?’ ‘She may do.’</em></li><li><em>So now you know as much as I do.</em></li><li><em>‘You forgot all about it.’ ‘No, I didn’t.’</em></li><li><em>‘I want to go home.’ ‘So do I.’</em></li><li><em>I didn’t believe the story and neither did he.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to emphasize the main verb in a sentence:</div><ul class=\"examples\"><li><em>Do be careful.</em></li><li><em>You do look nice in that hat.</em></li><li><em>I do think she’s behaved badly.</em></li><li><em>‘You should have warned me.’ ‘But I did warn you.’</em></li><li><em>He owns, or did own (=emphasizing past tense), a yacht.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>spoken</em> used when politely offering someone something:</div><ul class=\"examples\"><li><em>Do have another sandwich.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense did, past participle done, third person singular does)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[action/activity]</strong> <span class=\"gram\">[transitive]</span> to perform an action or activity: RegisterIn written English, people often use the verb act rather than the phrase do something, as it sounds more formal:· The government needs to act to help these people.</div><ul class=\"examples\"><li><em>Have you done your homework yet?</em></li><li><em>You need to do more exercise.</em></li><li><em>It’s a pleasure doing business with you.</em></li><li><em>I didn’t know what to do.</em></li><li><em>All he does is sit in front of the television all day.</em></li><li><strong><em>do something/nothing/anything etc</strong>: We should do something to help him. / It all happened so quickly that I couldn’t do anything about it. / bored teenagers with nothing to do</em></li><li><strong><em>do the laundry/ironing/dishes etc</strong>: It’s your turn to do the dishes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[succeed]</strong> <span class=\"gram\">[intransitive]</span> used to ask or talk about how successful someone is at something</div><ul class=\"examples\"><li><strong><em>do well/badly</strong>: Students are under considerable pressure to do well.</em></li><li><strong><em>how somebody/something is doing (with/in something)</strong>: You should get promoted after about a year, depending on how you’re doing. / How’s he doing in trying to give up smoking?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[have an effect]</strong> <span class=\"gram\">[transitive]</span> to have a particular effect on something or someone:</div><ul class=\"examples\"><li><em>The scandal will do serious damage to his reputation.</em></li><li><em>This will do nothing for (=will not improve) Jamie’s confidence.</em></li><li><em>The colour does nothing for her (=does not improve her appearance).</em></li><li><em>Getting the job has done a lot for (=had a good effect on) her self-esteem.</em></li><li><em>A week in the countryside will do you good (=make you feel better).</em></li><li><em>Exercise can do wonders for (=have a very good effect on) body, mind, and spirit.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[job]</strong> <span class=\"gram\">[transitive]</span> to have a particular job:</div><ul class=\"examples\"><li><em>What do you want to do after you leave school?</em></li><li><em>What do you do for a living (=as your job)?</em></li><li><em>She’s very good at what she does.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[enough/acceptable]</strong> <span class=\"gram\">[intransitive, transitive not in progressive]</span> used to say that something will be enough or be acceptable:</div><ul class=\"examples\"><li><em>We don’t have a lot of wine for the party, but it should just about do.</em></li><li><em>I can’t find my black shoes so these will have to do.</em></li><li><em>A few sandwiches will do me for lunch.</em></li><li><em>It won’t do (=it is not acceptable) to say that the situation couldn’t have been avoided.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>what somebody will do for something</strong> used to talk about what arrangements someone has made to get something they need:</div><ul class=\"examples\"><li><em>What will you do for money if you leave your job?</em></li><li><em>I’m not sure what we’ll do for transport yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>what is somebody/something doing?</strong> <em>spoken</em> used to ask why someone or something is in a particular place or doing a particular thing, especially when you are surprised or annoyed by this:</div><ul class=\"examples\"><li><em>What’s my coat doing on the floor?</em></li><li><em>What are you doing walking around at this time of night?</em></li><li><em>What on earth do you think you’re doing?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>do your/somebody’s hair/nails/make-up etc</strong> to do something that improves your appearance or someone else’s appearance:</div><ul class=\"examples\"><li><em>It must take her ages to do her make-up in the mornings.</em></li><li><em>Who does your hair?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[spend time]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to spend a period of time doing something:</div><ul class=\"examples\"><li><em>She did a year backpacking around the world.</em></li><li><em>Oh yes, I certainly did my time in the army (=spent time in the army).</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[study]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> to study a particular subject in a school or university: ► see thesaurus at study</div><ul class=\"examples\"><li><em>I did French for five years.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[cook]</strong> <span class=\"gram\">[transitive]</span> to cook a particular type of food: ► see thesaurus at cook</div><ul class=\"examples\"><li><em>I was thinking of doing a casserole tonight.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>do 10 miles/20 kms etc</strong> to achieve a particular distance, speed etc:</div><ul class=\"examples\"><li><em>We did 300 kilometres on the first day.</em></li><li><em>The car can do 120 mph.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[provide a service]</strong> <span class=\"gram\">[transitive]</span> to provide a particular service or sell a particular product:</div><ul class=\"examples\"><li><em>They do interior and exterior design.</em></li><li><em>We don’t do food after two o&#x27;clock.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[perform a play]</strong> <span class=\"gram\">[transitive]</span> to perform a particular play, show etc:</div><ul class=\"examples\"><li><em>We did ‘Guys and Dolls’ last year.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[decorate]</strong> <span class=\"gram\">[transitive]</span> to paint or decorate a room, house etc:</div><ul class=\"examples\"><li><em>How are you going to do your living room?</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[behave]</strong> <span class=\"gram\">[intransitive]</span> to behave in a particular way:</div><ul class=\"examples\"><li><em>In the evenings students are free to do as they please (=do what they want).</em></li><li><em>I wish you’d do as you’re told (=do what you are told to do)!</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>somebody doesn’t do nice/funny/sensible etc</strong> <em>spoken</em> <em>informal</em> used humorously to say that someone cannot or does not behave in a particular way:</div><ul class=\"examples\"><li><em>Sensible? I don’t do sensible.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[copy behaviour]</strong> <span class=\"gram\">[transitive]</span> to copy someone’s behaviour or the way they talk, especially in order to entertain people:</div><ul class=\"examples\"><li><em>He does a brilliant George Bush (=copies him in a very funny way).</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>do lunch/do a movie etc</strong> <em>informal</em> to have lunch, go to see a film etc with someone:</div><ul class=\"examples\"><li><em>Let’s do lunch next week.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[drugs]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to use an illegal drug:</div><ul class=\"examples\"><li><em>He says he’s never done hard drugs in his life.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[visit]</strong> <span class=\"gram\">[transitive]</span> to visit a particular place, especially as a tourist:</div><ul class=\"examples\"><li><em>Let’s do the Eiffel Tower today.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>that’ll do!</strong> <em>spoken</em> used to tell a child to stop behaving badly</div><div class=\"sense\"><span class=\"snum\">23</span> <strong>that does it!</strong> <em>spoken</em> used to say angrily that you will not accept a situation anymore:</div><ul class=\"examples\"><li><em>Right, that does it! I’m not going to listen to any more of this!</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>that should do it</strong> (also that ought to do it) <em>spoken</em> used to say that you will have finished doing something if you just do one more thing:</div><ul class=\"examples\"><li><em>I’ve just got to prepare the dessert and that should do it.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>do it</strong> <em>informal</em> to have sex – used humorously or when you want to avoid saying the word ‘sex’</div><div class=\"sense\"><span class=\"snum\">26</span> <strong>somebody would do well to do something</strong> used to advise someone that they should do something:</div><ul class=\"examples\"><li><em>Most people would do well to reduce the amount of salt in their diet.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>[punish]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> <em>spoken</em> to punish or attack someone → be/get done at done2(8)</div><div class=\"sense\"><span class=\"snum\">28</span> <strong>[deceive]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> <em>informal</em> to deceive or trick someone → be done at done2(7)</div><div class=\"sense\"><span class=\"snum\">29</span> <strong>what’s doing...?</strong> <em>spoken</em> used to ask what is happening:</div><ul class=\"examples\"><li><em>What’s doing at your place tonight?</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>do or die</strong> used to say that someone is determined to do something very brave or dangerous even if they die attempting it</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>how (are) you doing?</strong> <em>spoken</em> used when you meet someone to ask them if they are well, happy etc:</div><ul class=\"examples\"><li><em>Hi Bob, how you doing?</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>what can I do you for?</strong> <em>spoken</em> used humorously to ask someone how you can help them, especially when you are trying to sell them something</div><div class=\"sense\"><span class=\"snum\">33</span> <strong>do well by somebody</strong> to treat someone well:</div><ul class=\"examples\"><li><em>His relations always did pretty well by him.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>do one</strong> <em>spoken</em> <em>informal</em> used to tell someone who is making you feel upset or angry to go away:</div><ul class=\"examples\"><li><em>Oh, just go and do one!</em></li></ul></div></div>","2150":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɒk $ dɑːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a place in a port where ships are loaded, unloaded, or repaired → dry dock:</div><ul class=\"examples\"><li><em>A crowd was waiting at the dock to greet them.</em></li><li><strong><em>in dock</strong>: The ship is in dock for repairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the docks</strong> <span class=\"gram\">[plural]</span> the area of a port where there are docks:</div><ul class=\"examples\"><li><em>James arrived at the docks expecting to see a luxury liner.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>American English</em> a jetty</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>the dock</strong> the part of a law court where the person who is charged with a crime stands</div><ul class=\"examples\"><li><strong><em>in the dock</strong>: Three defendants stood in the dock.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>in the dock</strong> <em>especially British English</em> thought to have done something dishonest, harmful, or wrong:</div><ul class=\"examples\"><li><em>These chemicals remain in the dock until we have more scientific evidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable, uncountable]</span> a plant with thick green leaves that grows wild in Britain:</div><ul class=\"examples\"><li><em>a dock leaf</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[countable]</span> a piece of equipment that connects a portable media player to a computer, television etc</div></div>","2151":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doc‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒktə $ ˈdɑːktər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (written abbreviation Dr) someone who is trained to treat people who are ill → GP:</div><ul class=\"examples\"><li><em>She was treated by her local doctor.</em></li><li><em>I’d like to make an appointment to see Dr Pugh.</em></li><li><strong><em>the doctor’s<em>informal</em></strong> (=the place where your doctor works): ‘Where’s Sandy today?’ ‘I think she’s at the doctor’s.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who holds the highest level of degree given by a university → doctoral:</div><ul class=\"examples\"><li><em>a Doctor of Law</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be just what the doctor ordered</strong> <em>informal</em> to be exactly what someone needs or wants:</div><ul class=\"examples\"><li><em>A 2–0 victory is just what the doctor ordered.</em></li></ul></div>","2152":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doc‧trine</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒktrɪn $ ˈdɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a set of beliefs that form an important part of a religion or system of ideas:</div><ul class=\"examples\"><li><em>traditional doctrines of divine power</em></li><li><em>Marxist doctrine</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>Doctrine</strong> <span class=\"gram\">[countable]</span> <em>American English</em> a formal statement by a government about its future plans:</div><ul class=\"examples\"><li><em>the announcement of the Truman Doctrine</em></li></ul></div>","2153":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doc‧u‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒkjəmənt $ ˈdɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of paper that has official information on it</div><div class=\"sense\"><span class=\"snum\">2</span> a piece of written work that is stored on a computer</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doc‧u‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒkjəment $ ˈdɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to write about something, film it, or take photographs of it, in order to record information about it</div><ul class=\"examples\"><li><strong><em>document how/what etc</strong>: His research documents how the crisis occurred.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to support an opinion, argument etc with recorded facts</div><ul class=\"examples\"><li><strong><em>be well/extensively/poorly etc documented</strong>: It is well documented that men die younger than women.</em></li></ul></div></div>","2154":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doc‧u‧men‧ta‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɒkjəˈmentəri◂ $ ˌdɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural documentaries)</span></div><div class=\"entry-body\"><div class=\"sense\">a film or a television or radio programme that gives detailed information about a particular subject ► see thesaurus at movie, programme</div><ul class=\"examples\"><li><strong><em>documentary on/about</strong>: A local film crew is making a documentary about volcanoes.</em></li></ul></div>","2155":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doc‧u‧men‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɒkjəmənˈteɪʃən, -men- $ ˌdɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> official documents, reports etc that are used to prove that something is true or correct:</div><ul class=\"examples\"><li><em>Applicants must provide supporting documentation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the act of recording information in writing, on film etc</div><ul class=\"examples\"><li><strong><em>documentation of</strong>: a careful documentation of the costs</em></li></ul></div>","2156":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɒdʒ $ dɑːdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to move quickly to avoid someone or something:</div><ul class=\"examples\"><li><em>He ran across the courtyard, dodging a storm of bullets.</em></li><li><strong><em>dodge between/through/into etc</strong>: Helen clutched Edward’s arm as they dodged through the traffic.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to deliberately avoid discussing something or doing something <em>SYN evade</em></div><ul class=\"examples\"><li><strong><em>dodge an issue/question</strong>: Senator O&#x27;Brian skillfully dodged the crucial question.</em></li><li><strong><em>draft dodging</strong> (=when someone avoids an order to join the army, navy etc)</em></li></ul></div>","2157":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dodg‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒdʒi $ ˈdɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not working properly or not in good condition:</div><ul class=\"examples\"><li><em>Norton Disk Doctor can perform miracles on a dodgy hard disk.</em></li><li><em>Simon was rushed to hospital after eating what must have been dodgy prawns.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> seeming to be false, dishonest, or not to be trusted:</div><ul class=\"examples\"><li><em>One girl thought the men looked dodgy.</em></li><li><em>dodgy share dealings</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> involving risk or danger:</div><ul class=\"examples\"><li><em>There were a few dodgy moments.</em></li></ul></div>","2158":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɒɡ $ dɒːɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[animal]</strong> a common animal with four legs, fur, and a tail. Dogs are kept as pets or trained to guard places, find drugs etc → puppy:</div><ul class=\"examples\"><li><em>I could hear a dog barking.</em></li><li><em>He&#x27;s taken the dog for a walk.</em></li><li><em>We used to have a dog when I was young.</em></li><li><em>the most popular breed of dog</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[male animal]</strong> a male dog, fox, or wolf → bitch</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[woman]</strong> <em>informal</em> <em>not polite</em> an offensive word meaning an unattractive woman</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>dog eat dog</strong> when people compete against each other and will do anything to get what they want:</div><ul class=\"examples\"><li><em>It’s a dog eat dog world out there.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be going to the dogs</strong> <em>informal</em> if a country or organization is going to the dogs, it is getting worse and will be difficult to improve</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[dishonest]</strong> <em>informal</em> <em>not polite</em> an offensive word for an unpleasant or dishonest man:</div><ul class=\"examples\"><li><em>· You dirty dog!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>a dog’s life</strong> <em>spoken</em> a life that is difficult and unpleasant, with very little pleasure:</div><ul class=\"examples\"><li><em>His wife’s a nag who leads him a dog’s life (=makes his life unpleasant).</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>make a dog’s breakfast of something</strong> <em>British English</em> <em>informal</em> to do something very badly:</div><ul class=\"examples\"><li><em>The orchestra made a complete dog’s breakfast of the fourth movement.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a dog’s dinner</strong> <em>British English</em> <em>informal</em> something that is meant to be impressive or fashionable but that other people think is not:</div><ul class=\"examples\"><li><em>She was dressed up like a dog’s dinner.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>not have a dog’s chance</strong> <em>British English</em> <em>informal</em> to have no chance of being successful</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>every dog has its/his day</strong> used to say that even the most unimportant person has a time in their life when they are successful and important</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>like a dog with two tails</strong> <em>British English</em> <em>informal</em> very pleased and happy because something good has happened</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>a dog in the manger</strong> someone who cannot have or does not need something, but does not want anyone else to have it</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>[feet]</strong> <strong>dogs</strong> <span class=\"gram\">[plural]</span> <em>American English</em> <em>informal</em> feet:</div><ul class=\"examples\"><li><em>Boy, my dogs really hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[poor quality]</strong> <em>American English</em> <em>informal</em> something that is of very poor quality</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>dog and pony show</strong> <em>American English</em> an event that has only been organized so that people can admire it and think that it is impressive, not for any real purpose</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>be the dog’s bollocks</strong> <em>British English</em> <em>informal</em> a very rude expression used to say that something is very good</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>put on the dog</strong> <em>American English</em> <em>old-fashioned</em> to pretend to be richer, more clever etc than you really are</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>the dogs</strong> <em>British English</em> <em>informal</em> a sports event consisting of a series of races for dogs</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle dogged, present participle dogging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a problem or bad luck dogs you, it causes trouble for a long time:</div><ul class=\"examples\"><li><em>He has been dogged by injury all season.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to follow close behind someone</div></div></div>","2159":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɒl $ dɑːl, dɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a child’s toy that looks like a small person or baby:</div><ul class=\"examples\"><li><em>a small wooden doll</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>old-fashioned</em> <em>informal</em> a word meaning an attractive young woman – now usually considered offensive:</div><ul class=\"examples\"><li><em>Hey, doll, why don’t you get me a cup of coffee?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> <em>American English</em> <em>informal</em> a very nice person:</div><ul class=\"examples\"><li><em>Thanks, you’re a doll.</em></li></ul></div>","2160":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dol‧lar</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒlə $ ˈdɑːlər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the standard unit of money in the US, Canada, Australia, and some other countries, divided into 100 cents: symbol $:</div><ul class=\"examples\"><li><em>It cost three dollars.</em></li><li><em>a ten-dollar bill</em></li><li><em>You can pay in dollars or euros at the airport.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the dollar</strong> the value of US money in relation to the money of other countries:</div><ul class=\"examples\"><li><em>The pound has risen against the dollar (=increased in value in relation to the dollar).</em></li></ul></div>","2161":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dol‧phin</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒlfɪn $ ˈdɑːl-, ˈdɒːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a very intelligent sea animal like a fish with a long grey pointed nose</div></div>","2162":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> do‧main</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈmeɪn, dəʊ- $ də-, doʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an area of activity, interest, or knowledge, especially one that a particular person, organization etc deals with → public domain</div><ul class=\"examples\"><li><strong><em>outside/within the domain of something/somebody</strong>: This problem is outside the domain of medical science.</em></li><li><em>Looking after the house was viewed as a woman’s domain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an area of land owned and controlled by one person or government, especially in the past:</div><ul class=\"examples\"><li><em>the extent of the royal domain</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> the set of possible quantities by which something can vary in mathematics</div><div class=\"sense\"><span class=\"snum\">4</span> a domain name</div></div>","2163":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dəʊm $ doʊm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a round roof on a building</div><div class=\"sense\"><span class=\"snum\">2</span> a shape or building like a ball cut in half</div></div>","2164":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> do‧mes‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /dəˈmestɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to or happening in one particular country and not involving any other countries → foreign</div><ul class=\"examples\"><li><strong><em>domestic market/economy/demand etc</strong>: the booming domestic economy</em></li><li><em>US foreign and domestic policy</em></li><li><em>our nation’s domestic affairs</em></li><li><em>Domestic flights (=flights that stay inside a particular country) go from Terminal 1.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> relating to family relationships and life at home:</div><ul class=\"examples\"><li><em>Unfortunately his domestic life wasn’t very happy.</em></li><li><strong><em>domestic tasks/chores/responsibilities etc</strong>: Nowadays there is more sharing of domestic chores.</em></li><li><em>families that can afford domestic help (=help with cleaning, washing etc)</em></li><li><em>an organization that supports women facing domestic violence (=violence in a family, especially from a husband to his wife)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used in people’s homes:</div><ul class=\"examples\"><li><em>a new tax on domestic fuel</em></li><li><em>domestic appliances such as washing machines</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> someone who is domestic enjoys spending time at home and is good at cooking, cleaning etc:</div><ul class=\"examples\"><li><em>No, I’m not very domestic.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[only before noun]</span> a domestic animal lives on a farm or in someone’s home <em>OPP wild</em>:</div><ul class=\"examples\"><li><em>domestic pets</em></li></ul></div>","2165":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dom‧i‧nance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒmənəns $ ˈdɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the fact of being more powerful, more important, or more noticeable than other people or things → dominate</div><ul class=\"examples\"><li><strong><em>dominance of</strong>: the continuing dominance of the army in Uganda</em></li><li><strong><em>political/economic/cultural etc dominance</strong>: the economic and political dominance of Western countries</em></li><li><strong><em>dominance over</strong>: television’s dominance over other media</em></li></ul></div>","2166":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dom‧i‧nant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒmɪnənt $ ˈdɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> more powerful, important, or noticeable than other people or things → dominate: ► see thesaurus at powerful</div><ul class=\"examples\"><li><em>The dominant male gorilla is the largest in the group.</em></li><li><em>Japan became dominant in the mass market during the 1980s.</em></li><li><em>its dominant position within the group</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> controlling or trying to control other people or things – used to show disapproval <em>SYN domineering</em>:</div><ul class=\"examples\"><li><em>a dominant personality</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> a dominant gene causes a child to have a particular physical feature or illness, even if it has been passed on from only one parent → recessive:</div><ul class=\"examples\"><li><em>The disease is under the control of a single dominant gene.</em></li></ul></div>","2167":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dom‧i‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒməneɪt $ ˈdɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to control someone or something or to have more importance than other people or things:</div><ul class=\"examples\"><li><em>The industry is dominated by five multinational companies.</em></li><li><em>New Orleans dominated throughout the game.</em></li><li><em>Her loud voice totally dominated the conversation.</em></li><li><em>Education issues dominated the election campaign.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to be larger and more noticeable than anything else in a place:</div><ul class=\"examples\"><li><em>The cathedral dominates the city.</em></li></ul></div>","2168":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dom‧i‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdɒmɪˈneɪʃən $ ˌdɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">control or power over someone or something:</div><ul class=\"examples\"><li><em>the desire for political domination</em></li><li><em>The company is still aiming for world domination.</em></li></ul></div>","2169":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> do‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /dəʊˈneɪt $ ˈdoʊneɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to give something, especially money, to a person or an organization in order to help them → donor ► see thesaurus at give</div><ul class=\"examples\"><li><strong><em>donate something to somebody/something</strong>: Last year he donated $1,000 to cancer research.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to allow some blood or a body organ to be removed from your body so that it can be used in a hospital to help someone who is ill or injured → donor:</div><ul class=\"examples\"><li><em>people who volunteer to donate blood</em></li></ul></div>","2170":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> do‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /dəʊˈneɪʃən $ doʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something, especially money, that you give to a person or an organization in order to help them</div><ul class=\"examples\"><li><strong><em>donation to/from</strong>: Would you like to make a donation (=give money) to our charity appeal? / There have been generous donations from EEC funds.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of giving something, especially money, to help a person or an organization</div><ul class=\"examples\"><li><strong><em>donation of</strong>: the donation of a quarter of a million pounds</em></li><li><strong><em>blood/organ donation</em></strong></li></ul></div>","2171":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> don‧key</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɒŋki $ ˈdɑːŋki/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a grey or brown animal like a horse, but smaller and with long ears</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>donkey’s years</strong> <em>British English</em> <em>spoken</em> a very long time</div><ul class=\"examples\"><li><strong><em>for donkey’s years</strong>: I’ve had this jacket for donkey’s years.</em></li></ul></div>","2172":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> do‧nor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdəʊnə $ ˈdoʊnər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a person, group etc that gives something, especially money, to help an organization or country → donate:</div><ul class=\"examples\"><li><em>We urgently need more assistance from donor countries (=countries that give money, food etc to help in poor countries or disaster areas).</em></li><li><em>An anonymous donor (=whose name is unknown) has given £500 towards the restoration fund.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who gives blood or a body organ so that it can be used in the medical treatment of someone else → donate:</div><ul class=\"examples\"><li><em>Some patients die before a suitable donor is found.</em></li><li><strong><em>blood/organ/kidney etc donor</strong>: the shortage of blood donors</em></li></ul></div>","2173":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /duːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone or something certain to fail, die, be destroyed etc GRAMMAR Doom is usually passive.</div><ul class=\"examples\"><li><strong><em>be doomed to failure/defeat/extinction etc</strong>: Many species are doomed to extinction.</em></li><li><em>The plan was doomed from the start.</em></li><li><strong><em>be doomed to do something</strong>: We are all doomed to die in the end.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something very bad that is going to happen, or the fact that it is going to happen:</div><ul class=\"examples\"><li><em>A sense of impending doom (=coming very soon) gripped her.</em></li><li><strong><em>sense/feeling of doom</em></strong></li><li><strong><em>spell doom for something</strong> (=mean that something will be unable to continue or survive): The recession spelled doom for many small businesses.</em></li><li><em>Thousands of soldiers met their doom (=died) on this very field.</em></li><li><strong><em>doom and gloom/gloom and doom</strong> (=when there seems to be no hope for the future): Despite these poor figures, it’s not all doom and gloom.</em></li></ul></div></div>","2174":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɔː $ dɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the large flat piece of wood, glass etc that you move when you go into or out of a building, room, vehicle etc, or when you open a cupboard → gate: → fire door, French doors, revolving door(1), sliding door, stage door, swing door, trapdoor</div><ul class=\"examples\"><li><em>Could you open the door for me?</em></li><li><em>The door flew open and Ruth stormed in.</em></li><li><em>Don’t forget to lock the garage door.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the space made by an open door <em>SYN doorway</em></div><ul class=\"examples\"><li><strong><em>in/out (of)/through the door</strong>: Rick turned and ran out of the door.</em></li><li><em>I glanced through the open door.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>at the door</strong> if someone is at the door, they are waiting for you to open the door of a building so they can come inside:</div><ul class=\"examples\"><li><em>There’s somebody at the front door.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>out of doors</strong> outside <em>SYN outdoors</em>:</div><ul class=\"examples\"><li><em>I prefer working out of doors.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>show/see somebody to the door</strong> to take someone to the main way out of a building:</div><ul class=\"examples\"><li><em>My secretary will show you to the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>two/three etc doors away/down/up</strong> used to say how many houses or buildings there are between your house, office etc and another building</div><ul class=\"examples\"><li><strong><em>door from</strong>: Patrick lived two doors away from me.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>(from) door to door</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>especially British English</em> from one place to another:</div><ul class=\"examples\"><li><em>How long is the journey, door to door?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> going to each house in a street or area to sell something, collect money, or ask for votes: → door-to-door</div><ul class=\"examples\"><li><em>Joe sold vacuum cleaners door to door for years.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be on the door</strong> to work at the entrance to a theatre, club etc, collecting tickets</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>shut/close the door on something</strong> to make something impossible:</div><ul class=\"examples\"><li><em>The accident shut the door on her ballet career.</em></li></ul></div>","2175":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> door‧step</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɔːstep $ ˈdɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a step just outside a door to a house or building</div><ul class=\"examples\"><li><strong><em>on the doorstep</strong>: He stood on the doorstep, straightening his tie. / the front doorstep</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>on somebody’s/the doorstep</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> very near someone’s home:</div><ul class=\"examples\"><li><em>Wow! You’ve got the beach right on your doorstep!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> at someone’s home:</div><ul class=\"examples\"><li><em>I got a shock when he just turned up on the doorstep.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>informal</em> a very thick piece of bread</div></div>","2176":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> door‧way</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɔːweɪ $ ˈdɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the space where a door opens into a room or building</div><ul class=\"examples\"><li><strong><em>in the doorway</strong>: There was Paolo, standing in the doorway.</em></li></ul></div>","2177":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dəʊs $ doʊs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the amount of a medicine or a drug that you should take</div><ul class=\"examples\"><li><strong><em>dose of</strong>: Never exceed the recommended dose of painkillers.</em></li><li><strong><em>high/low dose</strong>: Start with a low dose and increase it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an amount of something that you do or experience at one time, especially something unpleasant</div><ul class=\"examples\"><li><strong><em>a bad/mild dose of flu<em>British English</em></strong> (=making you feel very ill or only slightly ill): Dave had a bad dose of flu.</em></li><li><strong><em>lethal/fatal dose (of something)</strong> (=an amount that kills): a lethal dose of radiation</em></li><li><em>I quite like Jamie in small doses (=in limited amounts but not a lot or often).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>like a dose of salts</strong> <em>British English</em> <em>informal</em> very quickly and easily:</div><ul class=\"examples\"><li><em>The cleaners went through the house like a dose of salts.</em></li></ul></div>","2178":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dɒt $ dɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small round mark or spot:</div><ul class=\"examples\"><li><em>a pattern of dots</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>on the dot</strong> <em>informal</em> exactly on time or at a particular time:</div><ul class=\"examples\"><li><em>I’ll be there on the dot.</em></li><li><strong><em>at three o&#x27;clock/seven thirty etc on the dot</strong> (=at exactly 3:00/7:30 etc): Mr Green arrived at six on the dot.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> something that looks like a small spot because it is so far away:</div><ul class=\"examples\"><li><em>The plane was just a dot on the horizon.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a short sound or flash of light used when sending messages by Morse code → dash</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle dotted, present participle dotting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to mark something by putting a dot on it or above it:</div><ul class=\"examples\"><li><em>She never dots her i’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually passive]</span> if an area is dotted with things, there are a lot of them there but they are spread far apart GRAMMAR Dot is often passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be dotted with something</strong>: The lake was dotted with sailboats.</em></li><li><strong><em>be dotted about/around etc something</strong>: The company has over 20 stores dotted around the country.</em></li><li><em>Poppies dotted the field.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to put a very small amount of something on a surface, especially in several places</div><ul class=\"examples\"><li><strong><em>dot something with something</strong>: Dot the apples with butter.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>dot the i’s and cross the t’s</strong> <em>informal</em> to pay careful attention to all the details when you are finishing something</div></div></div>","2179":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doub‧le</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdʌbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[of two parts]</strong> consisting of two parts that are similar or exactly the same:</div><ul class=\"examples\"><li><em>a double sink</em></li><li><em>a double wardrobe</em></li><li><em>the great double doors of the cathedral</em></li><li><em>Don’t park your car on double yellow lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[two different uses]</strong> combining or involving two things of the same type:</div><ul class=\"examples\"><li><em>a double murder case</em></li><li><em>A lot of the jokes were based on double meaning.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[twice as big]</strong> twice as big, twice as much, or twice as many as usual:</div><ul class=\"examples\"><li><em>a double whisky</em></li><li><em>The city was enclosed by walls of double thickness.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[for two people]</strong> made for two people or things to use → single:</div><ul class=\"examples\"><li><em>Do you need a double bed or two singles?</em></li><li><em>a double room</em></li><li><em>a double garage</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[two letters/numbers]</strong> <em>British English</em> <em>spoken</em> used to say that a particular letter or number is repeated:</div><ul class=\"examples\"><li><em>My name’s Robbins with a double ‘b’.</em></li><li><em>The number is 869 double 2 (=86922).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[flower]</strong> a double flower has more than the usual number of petals</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[twice the size]</strong> <span class=\"gram\">[countable, uncountable]</span> something that is twice as big, as much etc as usual or as something else:</div><ul class=\"examples\"><li><em>Scotch and water, please – make it a double.</em></li><li><em>‘They offered me £10,000.’ ‘I’ll give you double.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[room]</strong> <span class=\"gram\">[countable]</span> a room for two people in a hotel → single:</div><ul class=\"examples\"><li><em>A double costs $95 a night.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[tennis]</strong> <strong>doubles</strong> <span class=\"gram\">[uncountable]</span> a game played between two pairs of players, especially in tennis → singles: → mixed doubles</div><ul class=\"examples\"><li><em>the men’s doubles</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[baseball]</strong> <span class=\"gram\">[countable]</span> a hit in baseball which allows the batter to reach second base:</div><ul class=\"examples\"><li><em>Walker led the inning with a double.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[similar person]</strong> <strong>somebody’s double</strong> someone who looks very like someone else:</div><ul class=\"examples\"><li><em>She’s her mother’s double.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[in films]</strong> <span class=\"gram\">[countable]</span> an actor who takes the place of a more famous actor in a film, especially because the acting involves doing something dangerous:</div><ul class=\"examples\"><li><em>I think they used a double in the shower scene.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>at the double</strong> <em>British English</em>, on the double <em>American English</em> <em>informal</em> very quickly and without any delay:</div><ul class=\"examples\"><li><em>He was told to get back to Washington on the double.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>double or quits</strong> <em>British English</em>, double or nothing<em>American English</em> a situation in a game when you must do something that could either win you twice as much money or make you lose it all</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to become twice as big or twice as much, or to make something twice as big or twice as much ► see thesaurus at increase</div><ul class=\"examples\"><li><strong><em>double in size/number/value etc</strong>: Within two years the company had doubled in size.</em></li><li><em>The church has doubled its membership in the last five years.</em></li><li><strong><em>double the size/number/amount etc (of something)</strong>: A promise was given to double the number of police on duty.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> (also double over/up) to fold something in half:</div><ul class=\"examples\"><li><em>Take a sheet of paper and double it over.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to hit the ball far enough to get to second base in a game of baseball</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>be bent double</strong> to be bent over a long way: → see double at see1(28)</div><ul class=\"examples\"><li><em>The trees were almost bent double in the wind.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">predeterminer</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">twice as big, twice as much, or twice as many</div><ul class=\"examples\"><li><strong><em>double the amount/number/size etc</strong>: We’ll need double this amount for eight people.</em></li><li><em>The value of the house is double what it was.</em></li></ul></div></div>","2180":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌdouble ˈclick</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to press a button on a computer mouse twice in order to send an instruction to the computer</div></div>","2181":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a feeling of being not sure whether something is true or right</div><ul class=\"examples\"><li><strong><em>doubt about</strong>: The incident raises doubts about the safety of nuclear power.</em></li><li><strong><em>doubt as to</strong>: Some government ministers had serious doubts as to whether the policy would work.</em></li><li><em>There was still one little nagging doubt at the back of his mind.</em></li><li><em>There’s no doubt that he was a major artist.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>no doubt</strong> used when you are saying that you think something is probably true:</div><ul class=\"examples\"><li><em>No doubt you’ll have your own ideas.</em></li><li><em>She was a top student, no doubt about it (=it is certainly true).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>if/when (you’re) in doubt</strong> used when advising someone what to do if they are uncertain about something:</div><ul class=\"examples\"><li><em>If in doubt, consult your doctor.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in doubt</strong> if something is in doubt, it may not happen, continue, exist, or be true:</div><ul class=\"examples\"><li><em>The future of the peace talks is in doubt.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>beyond doubt</strong> if something is beyond doubt, it is completely certain:</div><ul class=\"examples\"><li><em>The prosecution must prove beyond reasonable doubt that the accused is guilty of the crime.</em></li><li><strong><em>put the game/result/match beyond doubt</strong> (=do something which makes it certain that a particular player or team will win a match): Ferdinand’s second goal put the game beyond doubt.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>without doubt</strong> used to emphasize an opinion:</div><ul class=\"examples\"><li><em>Jo is without doubt one of the finest swimmers in the school.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>open to doubt</strong> something that is open to doubt has not been proved to be definitely true or real:</div><ul class=\"examples\"><li><em>The authenticity of the relics is open to doubt.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[transitive not in progressive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to think that something may not be true or that it is unlikely:</div><ul class=\"examples\"><li><em>Kim never doubted his story.</em></li><li><strong><em>doubt (that)</strong>: I doubt we’ll ever see him again.</em></li><li><strong><em>doubt if/whether</strong>: You can complain, but I doubt if it’ll make any difference.</em></li><li><em>‘Do you think there’ll be any tickets left?’ ‘I doubt it (=I don’t think so).’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to not trust or have confidence in someone:</div><ul class=\"examples\"><li><em>I never doubted myself. I always knew I could play tennis at this level.</em></li><li><em>She loved him, and had never doubted him.</em></li><li><em>I have no reason to doubt his word (=think that he is lying).</em></li></ul></div></div>","2182":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doubt‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaʊtfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> probably not true or not likely to happen:</div><ul class=\"examples\"><li><em>Prospects for a lasting peace remain doubtful.</em></li><li><strong><em>it is doubtful if/whether</strong>: It was doubtful whether the patient would survive the operation.</em></li><li><strong><em>it is doubtful that</strong>: It is doubtful that the missing airmen will ever be found.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not sure that something is true or right:</div><ul class=\"examples\"><li><em>‘Everything’s going to be all right, you’ll see.’ Jenny looked doubtful.</em></li><li><strong><em>doubtful if/whether</strong>: I’m still doubtful whether I should accept this job.</em></li><li><strong><em>doubtful about (doing) something</strong>: At first we were doubtful about employing Charlie.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> unlikely to be successful:</div><ul class=\"examples\"><li><em>Already the whole scheme was looking increasingly doubtful.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> probably not good <em>SYN dubious</em>:</div><ul class=\"examples\"><li><em>Here the tap water is of doubtful quality.</em></li></ul></div>","2183":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doubt‧less</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaʊtləs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">used when saying that something is almost certain to happen or be true:</div><ul class=\"examples\"><li><em>Doubtless there would be lots of rumours.</em></li></ul></div>","2184":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dəʊ $ doʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> a mixture of flour and water ready to be baked into bread, pastry etc</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>informal</em> money</div></div>","2185":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[to a lower position]</strong> to or towards a lower place or position <em>OPP up</em>:</div><ul class=\"examples\"><li><em>David bent down to tie his shoelace.</em></li><li><em>Get down off the table.</em></li><li><em>Tears were streaming down my face.</em></li><li><em>The sun was going down and it would soon be dark.</em></li><li><em>They came running down the stairs.</em></li><li><em>She stood on a balcony looking down into the courtyard.</em></li><li><em>Glancing down the list of runners, I noticed a familiar name.</em></li><li><em>Her hair came down to her waist.</em></li><li><em>Ken fell asleep face down (=with his face towards the ground) on the couch.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a lower place]</strong> in a lower place or position <em>OPP up</em>:</div><ul class=\"examples\"><li><em>We heard the sound of laughter down below.</em></li><li><em>The bathroom is down those stairs.</em></li><li><em>Halfway down the page, there was the item I was looking for.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[to lie/sit]</strong> into a sitting or lying position:</div><ul class=\"examples\"><li><em>Please sit down.</em></li><li><em>I think I’ll go and lie down for a while.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[along]</strong> at or to a place that is further along something such as a road or path:</div><ul class=\"examples\"><li><em>A young man came hurrying down the street.</em></li><li><em>She looked down the road to see if anyone was coming.</em></li><li><em>There is a pleasant little cafe bar a hundred yards down the road.</em></li><li><em>The bus stop is a bit further down on the left-hand side.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[south]</strong> in or towards the south <em>OPP up</em>:</div><ul class=\"examples\"><li><em>They drove all the way down from Boston to Miami.</em></li><li><em>They sailed down the east coast of Africa.</em></li><li><em>Now he’s bought a villa down south.</em></li><li><em>a trip down Mexico way</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[somewhere local]</strong> at or to a place that is not far away:</div><ul class=\"examples\"><li><em>She’s just gone down to the shops.</em></li><li><em>I saw her down at the station this morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[river]</strong> away from the place where a river starts <em>OPP up</em>:</div><ul class=\"examples\"><li><em>Chunks of ice came floating down the river.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[fastened to a surface]</strong> used with verbs that mean ‘fasten’ to show that something is fastened firmly to the surface or object below it:</div><ul class=\"examples\"><li><em>The coffin lid had been nailed down.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[less]</strong> at or towards a level or amount that is less <em>OPP up</em>:</div><ul class=\"examples\"><li><em>Keep your speed down.</em></li><li><em>House prices have come down in recent months.</em></li><li><em>Turn the radio down.</em></li><li><strong><em>down to</strong>: Sharif cut his report down to only three pages.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[losing]</strong> losing to an opponent by a certain number of points</div><ul class=\"examples\"><li><strong><em>two goals down/three points down etc</strong>: Swindon were six points down at one stage.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[written]</strong> used with verbs that mean ‘write’ to show that you write something on paper or in a book:</div><ul class=\"examples\"><li><em>I’ll write down the address for you.</em></li><li><em>Start by jotting down a few ideas.</em></li><li><em>Let’s put you down as self-employed.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[on a list]</strong> if you are down for something, your name is on a list of people who want to do something or are intended to do something</div><ul class=\"examples\"><li><strong><em>down for</strong>: Purvis is down for the 200 metre freestyle event. / We’ve already put his name down for nursery school.</em></li><li><strong><em>down to do something</strong>: I’ve got you down to do the table decorations.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[to later times]</strong> from an earlier time in history to a later time or to people who are born in later times:</div><ul class=\"examples\"><li><em>a person whose words and actions have inspired millions of people down the centuries</em></li><li><em>This knowledge was handed down in the family from father to son.</em></li><li><em>The story has been passed down the generations for a thousand years.</em></li><li><strong><em>down to</strong>: traditions that have come down to us from medieval times</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[paid immediately]</strong> paid to someone immediately:</div><ul class=\"examples\"><li><em>A top quality freezer for only £20 down and £5 a week for a year.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[every part]</strong> from top to bottom:</div><ul class=\"examples\"><li><em>I want you to wash my car down.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[swallowed]</strong> in or into your stomach as a result of swallowing:</div><ul class=\"examples\"><li><em>Meg’s been very ill and can’t keep her food down.</em></li><li><em>He gulped down the coffee.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[sad]</strong> unhappy or sad: ► see thesaurus at sad</div><ul class=\"examples\"><li><em>Tim’s been feeling down.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[computer]</strong> if a computer is down, it is not working <em>OPP up</em> ► see thesaurus at broken</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>be down to somebody</strong> if an action or decision is down to you, it is your responsibility: → be up to somebody at up1</div><ul class=\"examples\"><li><em>It’s down to me to make sure that everyone is happy.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>be down to somebody/something</strong> to be the result of one person’s actions or one particular thing:</div><ul class=\"examples\"><li><em>Chris’s success is all down to him.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>be down to your last pound/dollar/litre etc</strong> to be left with only a small amount of something:</div><ul class=\"examples\"><li><em>We’re down to our last five dollars.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>down to something/somebody</strong> including everything or everyone, even the smallest thing or the least important person:</div><ul class=\"examples\"><li><em>Everyone uses the cafeteria, from the managing director down to the office boy.</em></li><li><em>The plans were all complete down to the last detail.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>be/go down with something</strong> to have a particular illness:</div><ul class=\"examples\"><li><em>Jane’s gone down with flu.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>Down with somebody/something</strong> <em>spoken</em> used to say that you strongly oppose a government, leader etc and want them to lose their power:</div><ul class=\"examples\"><li><em>Down with the government!</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>be down on somebody/something</strong> <em>informal</em> to have a severe attitude towards someone or something, especially when this is unfair:</div><ul class=\"examples\"><li><em>Why is Mark so down on her at the moment?</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>[leaving university]</strong> <em>British English</em> used to say that someone leaves or has left a university at the end of a period of study</div><ul class=\"examples\"><li><strong><em>down from</strong>: Sarah came down from Oxford in 1966.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>[completed]</strong> already done or completed:</div><ul class=\"examples\"><li><em>Well, you’ve passed your second test, so it’s two down and four more to go.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>down under</strong> <em>informal</em> in or to Australia or New Zealand</div><div class=\"sense\"><span class=\"snum\">29</span> <strong>Down!</strong> <em>spoken</em> used to tell a jumping dog to get down</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>be down with somebody</strong> <em>spoken</em> <em>informal</em> to be friends with someone</div></div>","2186":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> down‧load</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdaʊnˈləʊd $ ˈdaʊnloʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to move information or programs from a computer network to a small computer:</div><ul class=\"examples\"><li><em>games that can be downloaded free from the Internet</em></li></ul></div>","2187":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> down‧stairs</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdaʊnˈsteəz◂ $ -ˈsterz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">towards or on a lower floor of a building, especially a house <em>OPP upstairs</em>:</div><ul class=\"examples\"><li><em>Rosie ran downstairs to answer the door.</em></li><li><em>Charles was downstairs in the kitchen.</em></li></ul></div>","2188":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> down‧town</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌdaʊnˈtaʊn◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\">to or in the centre or main business area of a town or city → uptown:</div><ul class=\"examples\"><li><em>I have to go downtown later.</em></li></ul></div>","2189":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> down‧wards</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdaʊnwədz $ -wərdz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> towards a lower level or position <em>OPP upwards</em>:</div><ul class=\"examples\"><li><em>Nina glanced downwards.</em></li><li><em>Hold out your hands with your palms facing downwards.</em></li><li><em>The body was lying face downwards (=with the front of the body on the floor).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used when a number or amount becomes smaller <em>OPP upwards</em>:</div><ul class=\"examples\"><li><em>The death toll was later revised downwards to 689.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>from the chairman/president/top etc downwards</strong> used to mean that people of all levels in an organization, country etc are affected by something:</div><ul class=\"examples\"><li><em>Everyone from the chairman downwards is taking a pay cut.</em></li></ul></div>","2190":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> doz‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdʌzən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(plural dozen or dozens)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> twelve:</div><ul class=\"examples\"><li><em>a dozen eggs</em></li><li><strong><em>two/three/four etc dozen</strong> (=24, 36, 48 etc): The number of deaths has risen to more than two dozen.</em></li><li><strong><em>dozens of people/companies/cars etc</strong> (=but not hundreds or thousands): Dozens of people were killed.</em></li><li><em>Chris, Helen, and half a dozen others went on holiday together.</em></li><li><em>A dozen or so (=about 12) cars were parked near the entrance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> a lot of</div><ul class=\"examples\"><li><strong><em>a dozen</strong>: I’ve heard this story a dozen times before.</em></li><li><strong><em>dozens of something</strong>: She’s had dozens of boyfriends.</em></li><li><em>We collected dozens and dozens of shells on the beach.</em></li></ul></div>","2191":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the written abbreviation of doctor</div><div class=\"sense\"><span class=\"snum\">2</span> the written abbreviation of drive:</div><ul class=\"examples\"><li><em>88 Park Dr</em></li></ul></div>","2192":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɑːft $ dræft/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[piece of writing]</strong> a piece of writing or a plan that is not yet in its finished form:</div><ul class=\"examples\"><li><em>the rough draft of his new novel</em></li><li><em>I read the first draft and thought it was very good.</em></li><li><em>All parties eventually approved the final draft (=finished form) of the peace treaty.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[military]</strong> <strong>the draft</strong> <em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a system in which people are ordered to join the army, navy etc, especially during a war <em>SYN conscription</em></div><div class=\"subsense\"><span class=\"subnum\">b)</span> the group of people who are ordered to do this</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[money]</strong> <em>especially British English</em> a written order for money to be paid by a bank, especially from one bank to another</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sports]</strong> <em>American English</em> a system in which professional teams choose players from colleges to join their teams</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cold air/beer]</strong> the American spelling of draught</div></div>","2193":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dræɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(past tense and past participle dragged, present participle dragging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[pull something]</strong> <span class=\"gram\">[transitive]</span> to pull something along the ground, often because it is too heavy to carry ► see thesaurus at pull</div><ul class=\"examples\"><li><strong><em>drag something away/along/through etc</strong>: Inge managed to drag the table into the kitchen.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[pull somebody]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to pull someone somewhere where they do not want to go, in a way that is not gentle:</div><ul class=\"examples\"><li><em>He grabbed her arm and dragged her into the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>drag yourself to/into/out of etc something</strong> <em>informal</em> to move somewhere with difficulty, especially because you are ill, tired, or unhappy:</div><ul class=\"examples\"><li><em>I dragged myself out of bed and into the bathroom.</em></li><li><em>Can you drag yourself away from (=stop watching) the TV for a minute?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[persuade somebody to come]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> <em>informal</em> if you drag someone somewhere, you persuade or force them to come with you when they do not want to:</div><ul class=\"examples\"><li><em>Mom dragged us to a classical music concert.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[computer]</strong> <span class=\"gram\">[transitive]</span> to move words, pictures etc on a computer screen by pulling them along with the mouse:</div><ul class=\"examples\"><li><em>You can drag and drop text like this.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[be boring]</strong> <span class=\"gram\">[intransitive]</span> if time or an event drags, it seems to go very slowly because nothing interesting is happening:</div><ul class=\"examples\"><li><em>Friday afternoons always drag.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[touch the ground]</strong> <span class=\"gram\">[intransitive]</span> if something is dragging along the ground, part of it is touching the ground as you move</div><ul class=\"examples\"><li><strong><em>drag along/in/on</strong>: Your coat’s dragging in the mud.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>drag your feet/heels</strong> <em>informal</em> to take too much time to do something because you do not want to do it:</div><ul class=\"examples\"><li><em>The authorities are dragging their feet over banning cigarette advertising.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>drag a lake/river etc</strong> to look for something in a lake, river etc by pulling a heavy net along the bottom:</div><ul class=\"examples\"><li><em>The police are dragging the lake for the missing girl’s body.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>drag somebody’s name through the mud</strong> to tell people about the bad things that someone has done, so that they will have a bad opinion of them</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>drag somebody through the courts</strong> to force someone to go to a court of law, especially in order to make them have a bad experience because you are angry with them</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>drag somebody kicking and screaming into something</strong> to force someone to do something that they do not want to – used humorously:</div><ul class=\"examples\"><li><em>The party will have to be dragged kicking and screaming into the 21st century.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>look as if you’ve been dragged through a hedge backwards</strong> to look very untidy – used humorously</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>[injured leg/foot]</strong> <span class=\"gram\">[transitive]</span> if you drag your leg, foot etc, you cannot lift it off the ground as you walk because it is injured:</div><ul class=\"examples\"><li><em>a bird dragging its broken wing</em></li></ul></div>","2194":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drag‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdræɡən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large imaginary animal that has wings and a long tail and can breathe out fire</div><div class=\"sense\"><span class=\"snum\">2</span> a woman who behaves in an angry, unfriendly way</div></div>","2195":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dreɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[liquid]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> to make the water or liquid in something flow away:</div><ul class=\"examples\"><li><em>The swimming pool is drained and cleaned every winter.</em></li><li><strong><em>drain something from something</strong>: Brad drained all the oil from the engine.</em></li><li><em>Can you drain the spaghetti, please (=pour away the water from the pan)?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if liquid drains away, it flows away</div><ul class=\"examples\"><li><strong><em>drain away/off/from</strong>: I watched the bath water drain away.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[intransitive]</span> if something drains, the liquid that is in it or on it flows away and it becomes dry:</div><ul class=\"examples\"><li><em>Open ditches drain very efficiently.</em></li><li><em>She washed up and left the dishes to drain.</em></li><li><strong><em>well-drained/poorly-drained soil</strong> (=soil from which water flows away quickly or slowly): This plant needs rich, well-drained soil.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make somebody tired]</strong> <span class=\"gram\">[transitive]</span> to make someone feel very tired and without any energy:</div><ul class=\"examples\"><li><em>Working with children all day really drains you.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[use too much]</strong> <span class=\"gram\">[transitive]</span> to use too much of something, especially money, so that there is not enough left:</div><ul class=\"examples\"><li><em>Huge imports were draining the country’s currency reserves.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the colour/blood drains from somebody’s face/cheeks</strong> used to say that someone’s face becomes very pale, because they are frightened or shocked:</div><ul class=\"examples\"><li><em>When the verdict was read out, all the colour drained from Zelda’s cheeks.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>drain a glass/cup etc</strong> <em>written</em> to drink all the liquid in a glass, cup etc:</div><ul class=\"examples\"><li><em>Hannah drained her mug in one gulp.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>especially British English</em> a pipe that carries water or waste liquids away:</div><ul class=\"examples\"><li><em>The flood was caused by a blocked drain.</em></li><li><em>There’s a problem with the drains.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> the frame of metal bars over a drain where water etc can flow into it SYN grate<em>American English</em></div><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> the hole in the bottom of a bath or sink that water flows out through SYN plughole<em>British English</em></div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a drain on something</strong> something that continuously uses a lot of time, money etc:</div><ul class=\"examples\"><li><em>The war was an enormous drain on the country’s resources.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>down the drain</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if time, effort, or money goes down the drain, it is wasted or produces no results:</div><ul class=\"examples\"><li><em>Well that’s it. 18 months’ work down the drain.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if an organization, country etc goes down the drain, it becomes worse or fails:</div><ul class=\"examples\"><li><em>That’s why this country’s going down the drain!</em></li></ul></div></div>","2196":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drain‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdreɪnɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the process or system by which water or waste liquid flows away:</div><ul class=\"examples\"><li><em>A handful of pebbles in the bottom of a flowerpot will help drainage.</em></li><li><em>a plan to improve the town’s drainage system</em></li></ul></div>","2197":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dra‧ma</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrɑːmə $ ˈdrɑːmə, ˈdræmə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a play for the theatre, television, radio etc, usually a serious one, or plays in general → comedy:</div><ul class=\"examples\"><li><em>the great traditions of ancient Greek drama</em></li><li><strong><em>a TV/television/radio drama</strong>: the award-winning TV drama ‘Prime Suspect’</em></li><li><em>a new drama series for Saturday nights</em></li><li><em>a drama critic</em></li><li><em>a courtroom drama (=one that takes place in a court of law)</em></li><li><em>a lavish costume drama (=one about events in a past century)</em></li><li><em>He plays a Russian spy in the comedy drama ‘Sleepers’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> acting – used when talking about it as a subject to study or teach:</div><ul class=\"examples\"><li><em>young actors coming out of drama school</em></li><li><em>our drama teacher</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> an exciting event or set of events, or the quality of being exciting:</div><ul class=\"examples\"><li><em>Maggie’s life is always full of drama.</em></li><li><em>accidents, burst pipes, and other domestic dramas</em></li><li><em>a night of high drama (=very exciting events)</em></li><li><em>the drama of the moment</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>make a drama out of something</strong> to become upset about a small problem and make it seem worse than it really is:</div><ul class=\"examples\"><li><em>Brian always makes such a drama out of everything.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>drama queen</strong> a woman or homosexual man who tends to behave as if situations are worse than they really are – used to show disapproval</div></div>","2198":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dra‧mat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /drəˈmætɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> great and sudden</div><ul class=\"examples\"><li><strong><em>dramatic change/shift/improvement</strong>: Computers have brought dramatic changes to the workplace.</em></li><li><strong><em>dramatic increase/rise/fall/drop/reduction etc</strong>: Universities have suffered a dramatic drop in student numbers.</em></li><li><strong><em>dramatic effect/results</strong>: A serious accident can have a dramatic effect on your family’s finances.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> exciting or impressive: ► see thesaurus at exciting</div><ul class=\"examples\"><li><em>A superb goal by Owen earned United a dramatic victory yesterday.</em></li><li><em>Some of the most dramatic events in American history happened here.</em></li><li><em>the dramatic scenery of the Grand Canyon</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> connected with acting or plays:</div><ul class=\"examples\"><li><em>the amateur dramatic society</em></li><li><em>the dramatic arts</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> intended to be impressive, so that people notice:</div><ul class=\"examples\"><li><em>She needed a stunning dress to help her make a dramatic entrance.</em></li><li><em>Tristan threw up his hands in a dramatic gesture.</em></li></ul></div>","2199":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dra‧mat‧i‧cally</span><span class=\"meta-item\"><strong>IPA:</strong> /drəˈmætɪkli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a great and sudden way</div><ul class=\"examples\"><li><strong><em>increase/rise/fall/drop dramatically</strong>: Output has increased dramatically.</em></li><li><em>Three years on, Jack’s life has dramatically changed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that is intended to be impressive, so that people notice:</div><ul class=\"examples\"><li><em>She leaned forward dramatically.</em></li></ul></div>","2200":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dreɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to put something somewhere so that it hangs or lies loosely</div><ul class=\"examples\"><li><strong><em>drape something over/around/across something</strong>: He took off his coat and draped it over a chair. / Mina lay back, her arms draped lazily over the cushions.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to cover or decorate something with a cloth</div><ul class=\"examples\"><li><strong><em>drape something over/around something</strong>: Jack emerged with a towel draped around him.</em></li><li><strong><em>drape something with/in something</strong>: The soldiers’ coffins were draped with American flags.</em></li></ul></div>","2201":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dras‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdræstɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">extreme and sudden</div><ul class=\"examples\"><li><strong><em>drastic action/measures</strong>: NATO threatened drastic action if its terms were not met.</em></li><li><em>drastic cuts in government spending</em></li><li><em>Drastic changes are needed if environmental catastrophe is to be avoided.</em></li></ul></div>","2202":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɔː $ drɒː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense drew /druː/, past participle drawn /drɔːn $ drɒːn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[picture]</strong> <span class=\"gram\">[intransitive, transitive]</span> to produce a picture of something using a pencil, pen etc:</div><ul class=\"examples\"><li><em>Katie had drawn a cottage with a little stream running next to it.</em></li><li><em>She asked the little girl to draw a picture of the man she’d spoken to.</em></li><li><em>Keith was drawing a complicated-looking graph.</em></li><li><em>I’ve never been able to draw very well.</em></li><li><strong><em>draw somebody something</strong>: Can you draw me a map of how to get there?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>draw (somebody’s) attention</strong> to make someone notice something</div><ul class=\"examples\"><li><strong><em>draw to</strong>: I have been asked to draw your attention to the following points.</em></li><li><em>A dark house can draw attention to the fact that the house is empty.</em></li><li><strong><em>draw attention to yourself</strong>: He didn’t want to draw attention to himself.</em></li><li><em>The case drew international attention.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>draw a conclusion</strong> to decide that a particular fact or principle is true according to the information you have been given RegisterIn everyday English, people usually say reach a conclusion or come to a conclusion.</div><ul class=\"examples\"><li><strong><em>draw from</strong>: It would be unwise to draw firm conclusions from the results of a single survey.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>draw a comparison/parallel/distinction etc</strong> to compare two people or things and show how they are similar or different RegisterIn everyday English, people usually say make a comparison or distinction (but NOT make a parallel).</div><ul class=\"examples\"><li><strong><em>draw between</strong>: The author draws a comparison between East and West Germany and the North-South divide in England. / The report draws a distinction between various forms of health care.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[get a reaction]</strong> <span class=\"gram\">[transitive]</span> to get a particular kind of reaction from someone</div><ul class=\"examples\"><li><strong><em>draw something from somebody</strong>: His remarks drew an angry response from Democrats.</em></li><li><strong><em>draw praise/criticism</strong>: The movie drew praise from critics.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[attract]</strong> <span class=\"gram\">[transitive]</span> to attract someone or make them want to do something</div><ul class=\"examples\"><li><strong><em>draw somebody to something</strong>: What first drew you to teaching?</em></li><li><em>Beth felt strangely drawn to this gentle stranger.</em></li><li><em>The festival is likely to draw huge crowds.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[get something you need]</strong> <span class=\"gram\">[transitive]</span> to get something that you need or want from someone or something</div><ul class=\"examples\"><li><strong><em>draw something from something</strong>: I drew a lot of comfort from her kind words. / Plants draw nourishment from the soil.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[give information]</strong> <strong>be drawn</strong> <span class=\"gram\">[usually in negatives]</span> to give information in reply to questions about something:</div><ul class=\"examples\"><li><em>She refused to be drawn on the subject.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[move]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move in a particular direction: RegisterIn everyday English, people usually use pull rather than draw:· The train was pulling into the station.</div><ul class=\"examples\"><li><em>She drew away, but he pulled her close again.</em></li><li><em>The boat drew alongside us and a man appeared on the deck.</em></li><li><em>I arrived just as the train was drawing into the station.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>draw near/closer</strong> to become closer in time or space: RegisterIn everyday English, people usually say get nearer/closer:· Christmas is getting nearer.</div><ul class=\"examples\"><li><em>Maria grew anxious as the men drew closer.</em></li><li><em>Christmas is drawing near.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>draw level</strong> to move into a position where you are equal to someone else in a race, game, or competition:</div><ul class=\"examples\"><li><em>Black drew level with the other runners.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[pull somebody/something]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to move someone or something in a particular direction by pulling them gently ► see thesaurus at pull</div><ul class=\"examples\"><li><strong><em>draw somebody/something aside/up/across etc</strong>: Bobby drew a chair up to the table. / Hussain drew me aside to whisper in my ear.</em></li><li><strong><em>draw the curtains/a blind etc</strong> (=close them by pulling them gently)</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[pull a vehicle]</strong> <span class=\"gram\">[transitive]</span> if an animal draws a vehicle, it pulls it along: ► see thesaurus at pull</div><ul class=\"examples\"><li><em>a carriage drawn by six horses</em></li><li><em>an ox-drawn cart</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[take something out]</strong> <span class=\"gram\">[transitive]</span> to take something out of a container, pocket etc RegisterIn everyday English, people usually use pull something out or take something out rather than draw something out:· Ali reached into his pocket and pulled out a piece of paper.</div><ul class=\"examples\"><li><strong><em>draw something out/from something</strong>: Ali reached into his pocket and drew out a piece of paper.</em></li><li><strong><em>draw a gun/sword/weapon etc</strong>: Maria drew her gun nervously and peered out into the gloom.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>draw a line (between something)</strong> to think or show that one thing is different from another:</div><ul class=\"examples\"><li><em>Adolescents often use drugs simply to try to draw a line between their own and their parents’ way of life.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>draw the line (at something)</strong> to allow or accept something up to a particular point, but not beyond it:</div><ul class=\"examples\"><li><em>I don’t mind doing some gardening but I draw the line at digging.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>where do you draw the line?</strong> <em>spoken</em> used to say it is impossible to decide at which point an acceptable limit has been reached:</div><ul class=\"examples\"><li><em>Some say 50 is too old to have a baby, but where do you draw the line?</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>draw a line under something</strong> to say that something is completely finished and you will not think about it again:</div><ul class=\"examples\"><li><em>I just want to draw a line under the relationship.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>draw somebody’s eye (to something)</strong> if something draws your eye, it makes you notice it:</div><ul class=\"examples\"><li><em>My eye was drawn to a painting on the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[from a bank]</strong> (also draw out) <span class=\"gram\">[transitive]</span> to take money from your bank account <em>SYN withdraw</em>:</div><ul class=\"examples\"><li><em>Hughes had drawn $8,000 in cash from a bank in Toronto.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[receive money]</strong> <span class=\"gram\">[transitive]</span> to receive an amount of money regularly from a government or financial institution:</div><ul class=\"examples\"><li><em>How long have you been drawing unemployment benefit?</em></li><li><em>I’ll be drawing my pension before he’ll ever get around to asking me to marry him!</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>draw a cheque (on something)</strong> <em>British English</em>, draw a check (on something) <em>American English</em> to write a cheque for taking money out of a particular bank account</div><div class=\"sense\"><span class=\"snum\">23</span> <strong>[breathe]</strong> <span class=\"gram\">[intransitive, transitive]</span> to take air or smoke into your lungs:</div><ul class=\"examples\"><li><em>She drew a deep breath.</em></li><li><em>Ruth paused to draw breath, her voice barely hiding her excitement.</em></li><li><em>He lit his pipe and drew deeply.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>draw breath</strong> to find time to have a rest when you are busy:</div><ul class=\"examples\"><li><em>I’ve hardly had a moment to draw breath.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>[take liquid from something]</strong> <span class=\"gram\">[transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to take a liquid from something such as a barrel or tap</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to take water from a well</div><div class=\"sense\"><span class=\"snum\">26</span> <strong>[fire]</strong> <span class=\"gram\">[intransitive]</span> if a fire or chimney draws, it lets the air flow through to make the fire burn well</div><div class=\"sense\"><span class=\"snum\">27</span> <strong>[choose]</strong> <span class=\"gram\">[intransitive, transitive]</span> to choose by chance a ticket etc that will win a prize:</div><ul class=\"examples\"><li><em>The winning ticket will be drawn at the Christmas Party.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>draw lots/straws</strong> to decide who will do something by taking pieces of paper out of a container or choosing straws of hidden lengths:</div><ul class=\"examples\"><li><em>We drew lots to see who would go first.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>draw the short straw</strong> used to say that someone has been unlucky because they were chosen to do something that no one else wanted to do:</div><ul class=\"examples\"><li><em>He drew the short straw and had to drive everyone to the party.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>[game]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>especially British English</em> to finish without either side winning in a game such as football <em>SYN tie</em>:</div><ul class=\"examples\"><li><em>They drew 3–3.</em></li><li><strong><em>draw with</strong>: Liverpool drew with Juventus.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>be drawn against somebody</strong> <em>British English</em> to be chosen by chance to play or compete against someone:</div><ul class=\"examples\"><li><em>England have been drawn against France in next month’s game.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>draw a blank</strong> <em>informal</em> to be unsuccessful in finding information or the answer to a problem:</div><ul class=\"examples\"><li><em>All his investigations have drawn a blank so far.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>draw to a halt/stop</strong> if a vehicle draws to a halt or stop, it slows down and stops</div><div class=\"sense\"><span class=\"snum\">34</span> <strong>draw to a close/end</strong> to end:</div><ul class=\"examples\"><li><em>Festival-goers began to drift off as the evening drew to an end.</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>draw a veil over something</strong> to deliberately keep something unpleasant or embarrassing from being known:</div><ul class=\"examples\"><li><em>I’d rather draw a veil over what happened last night.</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>draw blood</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make someone bleed:</div><ul class=\"examples\"><li><em>The dog bit her so hard that it drew blood.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make someone angry or embarrass them in an argument, especially a public one:</div><ul class=\"examples\"><li><em>Barker sought to draw blood by mentioning his rival’s weakness of character.</em></li></ul><div class=\"sense\"><span class=\"snum\">37</span> <strong>draw a bow</strong> to bend a bow by pulling back the string in order to shoot an arrow</div><div class=\"sense\"><span class=\"snum\">38</span> <strong>[ship]</strong> <span class=\"gram\">[transitive]</span> <em>technical</em> if a ship draws a particular depth, it needs that depth of water to float in</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the final result of a game or competition in which both teams or players have the same number of points <em>SYN tie</em>:</div><ul class=\"examples\"><li><em>The match ended in a draw.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an occasion when someone or something is chosen by chance, especially the winning ticket in a lottery, or the teams who will play against each other in a competition:</div><ul class=\"examples\"><li><em>England has been selected to play Germany in the draw for the first round of the World Cup.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> a competition in which people whose names or tickets are chosen by chance win money or prizes:</div><ul class=\"examples\"><li><em>Congratulations! You have been entered into our £100,000 prize draw!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a performer, place, event etc that a lot of people come to see:</div><ul class=\"examples\"><li><em>It is hoped that the new art gallery will be a big draw for visitors.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> when you breathe in smoke from a cigarette <em>SYN drag</em>:</div><ul class=\"examples\"><li><em>Maltravers took a long draw on his cigarette.</em></li></ul></div></div>","2203":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> draw‧back</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrɔːbæk $ ˈdrɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a disadvantage of a situation, plan, product etc: ► see thesaurus at disadvantage</div><ul class=\"examples\"><li><em>It’s a great city – the only drawback is the weather.</em></li><li><strong><em>drawback of/to (doing) something</strong>: The main drawback to these products is that they tend to be too salty.</em></li></ul></div>","2204":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɔː $ drɒːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> part of a piece of furniture, such as a desk, that you pull out and push in and use to keep things in: → bottom drawer, chest of drawers, top-drawer</div><ul class=\"examples\"><li><em>She took a file from her desk drawer.</em></li><li><em>The scissors are in the kitchen drawer (=drawer in a piece of kitchen furniture).</em></li><li><strong><em>top/bottom/right-hand/left-hand drawer</strong>: He opened the top drawer of his desk, and took out a brown envelope.</em></li><li><strong><em>sock/cutlery drawer</strong> (=one for keeping socks, or knives, forks etc in)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>drawers</strong> <span class=\"gram\">[plural]</span> <em>old-fashioned</em> underwear that women and girls wear between their waist and the tops of their legs <em>SYN knickers</em></div></div>","2205":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> draw‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrɔːɪŋ $ ˈdrɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a picture that you draw with a pencil, pen etc</div><ul class=\"examples\"><li><strong><em>drawing of</strong>: a drawing of Canterbury Cathedral</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the art or skill of making pictures, plans etc with a pen or pencil:</div><ul class=\"examples\"><li><em>I’ve never been very good at drawing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>American English</em> a competition in which people whose names or tickets are chosen by chance win money or prizes SYN draw<em>British English</em>:</div><ul class=\"examples\"><li><em>The church social will include a buffet dinner and a prize drawing.</em></li></ul></div>","2206":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dred/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[transitive]</span> to feel anxious or worried about something that is going to happen or may happen:</div><ul class=\"examples\"><li><em>I’ve got an interview tomorrow and I’m dreading it.</em></li><li><strong><em>dread doing something</strong>: I’m dreading going back to work.</em></li><li><strong><em>dread somebody doing something</strong>: Tim dreaded his parents finding out.</em></li><li><strong><em>dread (that)</strong>: I’m dreading that I’ll be asked to make a speech.</em></li><li><strong><em>dread the thought/prospect of (doing) something</strong>: He dreaded the prospect of being all alone in that house.</em></li><li><em>I dread to think what will happen if they get elected (=I think it will be very bad).</em></li></ul></div>","2207":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dread‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdredfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely unpleasant <em>SYN terrible</em>: ► see thesaurus at bad, horrible</div><ul class=\"examples\"><li><em>We’ve had some dreadful weather lately.</em></li><li><em>Michelle felt absolutely dreadful (=very ill).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> used to emphasize how bad something or someone is <em>SYN terrible</em>:</div><ul class=\"examples\"><li><em>a dreadful mistake</em></li></ul></div>","2208":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /driːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[while sleeping]</strong> a series of thoughts, images, and feelings that you experience when you are asleep → daydream:</div><ul class=\"examples\"><li><em>I had lots of dreams last night.</em></li><li><strong><em>dream about</strong>: a dream about drowning</em></li><li><strong><em>in a dream</strong>: In my dream I flew to a forest of enormous trees.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[wish]</strong> a wish to do, be, or have something – used especially when this seems unlikely:</div><ul class=\"examples\"><li><em>Her dream is to make a movie.</em></li><li><strong><em>dream of (doing) something</strong>: She had dreams of university.</em></li><li><strong><em>fulfil/realize a dream</strong>: I fulfilled a childhood dream when I became champion.</em></li><li><em>I have just met the man of my dreams (=the perfect man)!</em></li><li><strong><em>beyond your wildest dreams</strong> (=better than anything you imagined or hoped for)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>dream house/home/job etc</strong> something that seems perfect to someone:</div><ul class=\"examples\"><li><em>I’ve finally found my dream house.</em></li><li><em>Win a dream holiday for two in San Francisco!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in a dream</strong> having a state of mind in which you do not notice or pay attention to things around you:</div><ul class=\"examples\"><li><em>Ruth went about her tasks in a dream.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be a dream come true</strong> if something is a dream come true, it happens after you have wanted it to happen for a long time:</div><ul class=\"examples\"><li><em>Marriage to her is a dream come true.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>like a dream</strong> extremely well or effectively:</div><ul class=\"examples\"><li><em>The plan worked like a dream.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be/live in a dream world</strong> to have ideas or hopes that are not correct or likely to happen:</div><ul class=\"examples\"><li><em>If you think that all homeless people have it as easy as me, then you are living in a dream world.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be a dream</strong> be perfect or very desirable:</div><ul class=\"examples\"><li><em>Her latest boyfriend is an absolute dream.</em></li><li><em>Some performers are a dream to work with; others are not.</em></li><li><strong><em>somebody’s dream</strong> (=something someone would really like): She’s every adolescent schoolboy’s dream.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>in your dreams</strong> <em>spoken</em> used to say in a rude way that something is not likely to happen:</div><ul class=\"examples\"><li><em>‘I’m going to ask her to go out with me.’ ‘In your dreams!’</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dremt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(past tense and past participle dreamed or dreamt /dremt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[wish]</strong> <span class=\"gram\">[intransitive, transitive]</span> to think about something that you would like to happen or have GRAMMARYou dream of doing something: · I’ve always dreamed of being an artist. ✗Don’t say: I’ve always dreamed to be an artist.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><strong><em>dream of/about (doing) something</strong>: She dreamed of becoming a chef. / He’s got the sort of money that you and I can only dream about.</em></li><li><strong><em>dream (that)</strong>: She dreamed that one day she would be famous.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[while sleeping]</strong> <span class=\"gram\">[intransitive, transitive]</span> to have a dream while you are asleep</div><ul class=\"examples\"><li><strong><em>dream about</strong>: I dreamt about you last night.</em></li><li><strong><em>dream (that)</strong>: It’s quite common to dream that you’re falling.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[not pay attention]</strong> <span class=\"gram\">[intransitive]</span> to think about something else and not give your attention to what is happening around you <em>SYN daydream</em>:</div><ul class=\"examples\"><li><em>She had been dreaming and had not followed the conversation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[imagine]</strong> <span class=\"gram\">[intransitive, transitive]</span> to imagine that you have done, seen, or heard something that you have not:</div><ul class=\"examples\"><li><em>I was sure I posted the letter but I must have dreamt it.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>never dreamed (that)</strong> used to say that you did not think that something would happen:</div><ul class=\"examples\"><li><em>We never dreamed that we would get through to the next round.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>wouldn’t dream of (doing) something</strong> <em>spoken</em> used to say that you would never do something because you think it is bad or wrong:</div><ul class=\"examples\"><li><em>I wouldn’t dream of letting strangers look after my own grandmother!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>who would have dreamt that...?</strong> <em>spoken</em> used to express surprise about something that has happened:</div><ul class=\"examples\"><li><em>Who would have dreamt that this would happen?</em></li></ul></div></div>","2209":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dres/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a piece of clothing worn by a woman or girl that covers the top of her body and part or all of her legs → skirt: ► see thesaurus at clothes</div><ul class=\"examples\"><li><em>Sheila wore a long red dress.</em></li><li><em>a summer dress</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> clothes for men or women of a particular type or for a particular occasion:</div><ul class=\"examples\"><li><em>a gentleman in evening dress (=formal clothes worn especially at important social events)</em></li><li><em>The play was performed in modern dress (=clothes from the present time).</em></li><li><strong><em>dress code</strong> (=a standard of what you should wear for a particular situation): This restaurant has a strict dress code – no tie, no service.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[put on clothes]</strong> <span class=\"gram\">[intransitive, transitive]</span> to put clothes on yourself or someone else: RegisterIn everyday English, people usually say get dressed rather than dress:· I got dressed and went downstairs for breakfast.</div><ul class=\"examples\"><li><em>Can you wait a minute? I’m just getting dressed.</em></li><li><em>She dressed quickly and went out of the house.</em></li><li><em>I usually have to dress the kids in the mornings.</em></li><li><strong><em>dress somebody in something</strong>: She dressed Louis in his best blue shirt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[wear clothes]</strong> <span class=\"gram\">[intransitive]</span> to wear a particular kind of clothes:</div><ul class=\"examples\"><li><em>Dress warmly if you’re going out for a walk.</em></li><li><strong><em>dress casually/smartly</strong>: I spend most of my time in the house with young children, so I dress casually.</em></li><li><strong><em>dress for</strong>: How do you normally dress for work?</em></li><li><em>We usually dress for dinner (=wear formal clothes for our evening meal).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[make/choose clothes]</strong> <span class=\"gram\">[transitive]</span> to make or choose clothes for someone:</div><ul class=\"examples\"><li><em>Versace dressed some of the most famous people in Hollywood.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[wound/cut etc]</strong> <span class=\"gram\">[transitive]</span> to clean, treat, and cover a wound</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[meat/fish]</strong> <span class=\"gram\">[transitive]</span> to clean and prepare meat or fish so that it is ready to cook or eat:</div><ul class=\"examples\"><li><em>dressed crab</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[salad]</strong> <span class=\"gram\">[transitive]</span> to put oil, vinegar, salt etc onto a salad</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[window]</strong> <span class=\"gram\">[transitive]</span> to put an attractive arrangement in a shop window → window dresser</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[soldiers]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>technical</em> to stand in a straight line, or to make soldiers do this</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[hair]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to arrange someone’s hair into a special style</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[wood/stone etc]</strong> <span class=\"gram\">[transitive]</span> <em>technical</em> to prepare or put a special surface onto wood, stone, leather etc</div></div></div>","2210":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dress‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdresɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a mixture of liquids, usually oil and vinegar, that you put on salad or raw vegetables: → French dressing, salad dressing</div><ul class=\"examples\"><li><em>a vinaigrette dressing</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> <em>American English</em> stuffing(1)</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a special piece of material used to cover and protect a wound:</div><ul class=\"examples\"><li><em>The nurse came to change his dressing.</em></li></ul></div>","2211":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈdressing gown</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of clothing like a long loose coat that you wear inside the house, usually over night clothes <em>SYN bathrobe</em> <em>, robe</em></div></div>","2212":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drib‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to let liquid come out of your mouth onto your face:</div><ul class=\"examples\"><li><em>Watch out, the baby is dribbling on your shirt!</em></li><li><em>He was dribbling tea onto his tie.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a liquid dribbles somewhere, it flows in a thin irregular stream:</div><ul class=\"examples\"><li><em>Blood from the wound dribbled down the side of his face.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to move the ball along with you by short kicks, bounces, or hits in a game of football, basketball etc:</div><ul class=\"examples\"><li><em>He was trying to dribble the ball past his opponents.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if something such as money or news dribbles somewhere, it comes or goes in small irregular amounts:</div><ul class=\"examples\"><li><em>Money is finally dribbling back into the country now.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to pour something out slowly in an irregular way:</div><ul class=\"examples\"><li><em>Dribble a few drops of olive oil over the pizza.</em></li></ul></div>","2213":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /draɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">dried substances, such as food or flowers, have had the water removed:</div><ul class=\"examples\"><li><em>dried herbs</em></li></ul></div>","2214":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɪft/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move slowly]</strong> to move slowly on water or in the air</div><ul class=\"examples\"><li><strong><em>drift out/towards etc</strong>: The rubber raft drifted out to sea. / Smoke drifted up from the jungle ahead of us.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[without plan]</strong> to move, change, or do something without any plan or purpose</div><ul class=\"examples\"><li><strong><em>drift around/along etc</strong>: Jenni spent the year drifting around Europe.</em></li><li><strong><em>drift into</strong>: I just drifted into teaching, really.</em></li><li><strong><em>drift away</strong>: The others drifted away. Melanie stayed.</em></li><li><strong><em>drift from something to something</strong>: The conversation drifted from one topic to another.</em></li><li><strong><em>let your gaze/eyes/thoughts/mind etc drift</strong>: Idly she let her eyes drift over his desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[change]</strong> to gradually change from being in one condition, situation etc into another without realizing it</div><ul class=\"examples\"><li><strong><em>drift into</strong>: She was just drifting into sleep when the alarm went off.</em></li><li><em>He drifted in and out of consciousness.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[money/prices]</strong> if values, prices, shares etc drift, they gradually change:</div><ul class=\"examples\"><li><em>The dollar drifted lower against the yen today.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[snow/sand]</strong> if snow, sand etc drifts, the wind blows it into large piles</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>let something drift</strong> to allow something, especially something bad, to continue in the same way:</div><ul class=\"examples\"><li><em>He couldn’t let the matter drift for much longer.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[snow/sand]</strong> <span class=\"gram\">[countable]</span> a large pile of snow or sand that has been blown by the wind</div><ul class=\"examples\"><li><strong><em>drift of</strong>: The road is blocked with massive drifts of snow.</em></li><li><em>a snow drift</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[change]</strong> <span class=\"gram\">[singular]</span> a slow change or development from one situation, opinion etc to another</div><ul class=\"examples\"><li><strong><em>drift towards/to</strong>: a drift towards longer working hours</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[movement of people]</strong> <span class=\"gram\">[singular, uncountable]</span> a slow movement of large numbers of people that has not been planned</div><ul class=\"examples\"><li><strong><em>drift from/to/into</strong>: the drift from the countryside to the cities</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the drift (of something)</strong> the general meaning of what someone is saying:</div><ul class=\"examples\"><li><em>So what’s the drift of the argument?</em></li><li><strong><em>follow/get/catch somebody’s drift</strong> (=understand the general meaning of what someone is saying): She didn’t quite get my drift, did she?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[ships/planes]</strong> <span class=\"gram\">[uncountable]</span> the movement of a ship or plane from its original direction because of the movement of the wind or water</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[slow movement]</strong> <span class=\"gram\">[uncountable]</span> very slow movement, especially over water or through the air</div></div></div>","2215":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a tool or machine used for making holes in something: → pneumatic drill</div><ul class=\"examples\"><li><em>an electric drill</em></li><li><em>a whine like a dentist’s drill</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a method of teaching students, sports players etc something by making them repeat the same lesson, exercise etc many times:</div><ul class=\"examples\"><li><em>a pronunciation drill</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>fire/emergency drill</strong> an occasion when people practise what they should do in a dangerous situation such as a fire</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> military training in which soldiers practise marching, using weapons etc:</div><ul class=\"examples\"><li><em>rifle drill</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the drill</strong> <em>British English</em> <em>old-fashioned</em> the usual way that something is done:</div><ul class=\"examples\"><li><em>‘You know the drill?’ ‘Not really. Tell me again what to do.’</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[uncountable]</span> a type of strong cotton cloth</div><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a machine for planting seeds in rows</div><div class=\"subsense\"><span class=\"subnum\">b)</span> a row of seeds planted by a machine</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to make a hole in something using a drill:</div><ul class=\"examples\"><li><em>Drill a hole in each corner.</em></li><li><strong><em>drill into/through</strong>: He accidentally drilled into a water pipe.</em></li><li><strong><em>drill for oil/water/gas etc</strong>: BP has been licensed to drill for oil in the area.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to teach students, sports players etc by making them repeat the same lesson, exercise etc many times</div><ul class=\"examples\"><li><strong><em>drill somebody in something</strong>: She was drilling the class in the forms of the past tense.</em></li><li><strong><em>drill somebody to do something</strong>: I acted instinctively because I had been trained and drilled to do just that. / The crew were well drilled in handling emergency situations.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to train soldiers to march or perform other military actions:</div><ul class=\"examples\"><li><em>The sergeant was drilling the new recruits.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to plant seeds in rows using a machine</div></div></div>","2216":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(past tense drank /dræŋk/, past participle drunk /drʌŋk/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to take liquid into your mouth and swallow it:</div><ul class=\"examples\"><li><em>You should drink plenty of water.</em></li><li><em>What would you like to drink?</em></li><li><em>Take a seat while I get you something to drink.</em></li><li><em>She filled the glass and drank.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to drink alcohol, especially regularly or too much:</div><ul class=\"examples\"><li><em>He’s been drinking heavily since his wife died.</em></li><li><em>I don’t drink.</em></li><li><em>Don’t drink and drive.</em></li><li><em>My flatmate Cherry drinks like a fish (=regularly drinks a lot of alcohol).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>drink yourself silly/into a stupor/to death etc</strong> to drink so much alcohol that you become very drunk or unconscious, or die:</div><ul class=\"examples\"><li><em>If he goes on this way he’ll drink himself to death.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>drink somebody under the table</strong> to drink more alcohol than someone but not feel as ill as them:</div><ul class=\"examples\"><li><em>He could drink nearly anyone under the table.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>What are you drinking?</strong> <em>spoken</em> used to offer to buy someone a drink, especially in a pub</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>drink somebody’s health</strong> <em>British English</em> to wish someone good health before having an alcoholic drink</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an amount of liquid that you drink, or the act of drinking something</div><ul class=\"examples\"><li><strong><em>drink of</strong>: Have a drink of water. / He took a drink of his coffee.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> liquid that you can drink:</div><ul class=\"examples\"><li><em>What’s your favourite drink?</em></li><li><em>food and drink companies</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> an alcoholic drink:</div><ul class=\"examples\"><li><em>He’d obviously had a few drinks.</em></li><li><em>Let’s go for a drink.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the habit of drinking too much alcohol, in a way that is very bad for your health:</div><ul class=\"examples\"><li><em>The marriage ended because of her husband’s drink problem (=he drank too much alcohol).</em></li><li><em>They had driven him to drink (=made him start drinking too much alcohol regularly).</em></li><li><em>After her retirement from the stage she took to drink (=started drinking too much alcohol).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>drinks</strong> <span class=\"gram\">[plural]</span> <em>British English</em> a social occasion when you have alcoholic drinks and sometimes food</div><ul class=\"examples\"><li><strong><em>for drinks</strong>: Don’t forget we’re invited to the Jones’ for drinks on Sunday.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>the drink</strong> <em>old-fashioned</em> the sea, a lake, or another large area of water</div></div></div>","2217":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drink‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrɪŋkə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who regularly drinks alcohol:</div><ul class=\"examples\"><li><em>Dave has always been a bit of a drinker.</em></li><li><em>He was a heavy drinker (=he drank a lot).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>coffee/wine/champagne etc drinker</strong> someone who regularly drinks coffee, wine etc</div></div>","2218":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈdrinking ˌwater</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">water that is pure enough for you to drink</div></div>","2219":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle dripped, present participle dripping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to let liquid fall in drops:</div><ul class=\"examples\"><li><em>The tap’s dripping.</em></li><li><em>Her boots were muddy and her hair was dripping.</em></li><li><strong><em>drip blood/water/sweat etc</strong>: John came in, his arm dripping blood.</em></li><li><strong><em>be dripping with blood/sweat etc</strong>: The hand that held the gun was dripping with sweat.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to fall in drops</div><ul class=\"examples\"><li><strong><em>drip down/from etc</strong>: The rain dripped down his neck. / Water was dripping through the ceiling.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be dripping with something</strong> to contain or be covered in a lot of something</div><ul class=\"examples\"><li><strong><em>be dripping with jewels/gems/pearls etc</strong>: All the princes were dripping with gems.</em></li><li><em>His tone was now dripping with sarcasm.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one of the drops of liquid that fall from something:</div><ul class=\"examples\"><li><em>I put some plastic buckets on the floor to catch the drips.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> the sound or action of a liquid falling in drops:</div><ul class=\"examples\"><li><em>The silence was broken only by a regular drip, drip, drip.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a piece of equipment used in hospitals for putting liquids directly into your blood through a tube <em>SYN IV</em></div><ul class=\"examples\"><li><strong><em>be/put somebody on a drip</strong>: At the hospital they put me on a drip.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>informal</em> someone who is boring and weak</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>drip, drip, drip</strong> used to talk about something happening gradually or continually over a period of time:</div><ul class=\"examples\"><li><em>the drip, drip, drip of new revelations every day</em></li></ul></div></div>","2220":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /draɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense drove /drəʊv $ droʊv/, past participle driven /ˈdrɪvən/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[vehicle]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive, transitive]</span> to make a car, truck, bus etc move along</div><ul class=\"examples\"><li><strong><em>drive to/down/off etc</strong>: I am planning to drive to Morocco next year.</em></li><li><em>the man driving the car</em></li><li><em>Can you drive?</em></li><li><em>So when did you learn to drive?</em></li><li><em>Bye! Drive carefully!</em></li><li><em>He drives 12 miles to work.</em></li><li><em>He drives (=has) a BMW estate.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a car, truck etc drives somewhere, it moves there:</div><ul class=\"examples\"><li><em>After the accident, the other car just drove off.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[intransitive]</span> if people drive somewhere, they travel somewhere in a car:</div><ul class=\"examples\"><li><em>Shall we drive or take the bus?</em></li><li><strong><em>drive to/down/off etc</strong>: They drove back to Woodside.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to take someone somewhere in a car, truck etc:</div><ul class=\"examples\"><li><em>She drove Anna to London.</em></li><li><em>I’ll drive you home.</em></li><li><strong><em>drive yourself</strong>: I drove myself to hospital.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make somebody move]</strong> <span class=\"gram\">[transitive]</span> to force a person or animal to go somewhere:</div><ul class=\"examples\"><li><em>Torrential rain drove the players off the course.</em></li><li><em>With a few loud whistles, they drove the donkeys out of the enclosure.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[make somebody do something]</strong> <span class=\"gram\">[transitive]</span> to strongly influence someone to do something</div><ul class=\"examples\"><li><strong><em>drive somebody to do something</strong>: The detective wondered what had driven Christine to phone her.</em></li><li><strong><em>drive somebody to/into something</strong>: The noises in my head have nearly driven me to suicide.</em></li><li><em>Phil, driven by jealousy, started spying on his wife.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[make somebody/something be in a bad state]</strong> <span class=\"gram\">[transitive]</span> to make someone or something get into a bad or extreme state, usually an emotional one</div><ul class=\"examples\"><li><strong><em>drive somebody crazy/nuts/mad/insane</strong> (=make someone feel very annoyed): This cough is driving me mad!</em></li><li><strong><em>drive somebody crazy/wild</strong> (=make someone feel very sexually excited)</em></li><li><strong><em>drive somebody up the wall/out of their mind</strong> (=make someone feel very annoyed)</em></li><li><strong><em>drive somebody to distraction/desperation</strong>: The mosquitoes drive me to distraction.</em></li><li><strong><em>drive somebody/something into something</strong>: The factory had been driven into bankruptcy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[hit/push something into something]</strong> <span class=\"gram\">[transitive]</span> to hit or push something into something else</div><ul class=\"examples\"><li><strong><em>drive something into something</strong>: We watched Dad drive the posts into the ground. / She drove her heels into the sand.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[make somebody work]</strong> <span class=\"gram\">[transitive]</span> to make a person or animal work hard</div><ul class=\"examples\"><li><strong><em>drive yourself</strong>: Don’t drive yourself too hard.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[sports]</strong> <span class=\"gram\">[intransitive, transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to move a ball etc forward in a game of baseball, football, golf etc by hitting or kicking it hard and fast:</div><ul class=\"examples\"><li><em>He drove the ball into the corner of the net.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to run with the ball towards the goal in sports such as basketball and American football</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[provide power]</strong> <span class=\"gram\">[transitive]</span> to provide the power for a vehicle or machine</div><ul class=\"examples\"><li><strong><em>petrol-driven/electrically-driven/battery-driven etc</strong>: a petrol-driven lawn mower</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[rain/wind etc]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if rain, snow, wind etc drives somewhere, it moves very quickly in that direction:</div><ul class=\"examples\"><li><em>The rain was driving down hard.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>drive a coach and horses through something</strong> to destroy an argument, plan etc completely:</div><ul class=\"examples\"><li><em>The new bill will drive a coach and horses through recent trade agreements.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[make a hole]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to make a large hole in something using heavy equipment or machinery:</div><ul class=\"examples\"><li><em>They drove a tunnel through the mountains.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>drive something home</strong> to make something completely clear to someone:</div><ul class=\"examples\"><li><em>He didn’t have to drive the point home. The videotape had done that.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>drive a wedge between somebody</strong> to do something that makes people disagree or start to dislike each other:</div><ul class=\"examples\"><li><em>I don’t want to drive a wedge between you and your father.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in a car]</strong> <span class=\"gram\">[countable]</span> a journey in a car ► see thesaurus at journey</div><ul class=\"examples\"><li><strong><em>drive to/along etc</strong>: Let’s go for a drive along the coast. / Taylor took me for a drive through the town.</em></li><li><strong><em>an hour’s/a two-hour etc drive</strong>: It’s a two-hour drive from Calais to Thiepval.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[natural need]</strong> <span class=\"gram\">[countable]</span> a strong natural need or desire:</div><ul class=\"examples\"><li><em>The treatment will not affect your sex drive.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[outside your house]</strong> <span class=\"gram\">[countable]</span> the hard area or road between your house and the street <em>SYN driveway</em></div><ul class=\"examples\"><li><strong><em>in/on the drive</strong>: He parked his car in the drive.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[effort]</strong> <span class=\"gram\">[countable]</span> an effort to achieve something, especially an effort by an organization for a particular purpose:</div><ul class=\"examples\"><li><em>a recruitment drive for new members</em></li><li><em>an economy drive (=effort to reduce spending)</em></li><li><strong><em>drive to do something</strong>: a nationwide drive to crack down on crime</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[determination]</strong> <span class=\"gram\">[uncountable]</span> determination and energy to succeed:</div><ul class=\"examples\"><li><em>Brian has got tremendous drive.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[power]</strong> <span class=\"gram\">[uncountable]</span> the power from an engine that makes the wheels of a vehicle go round</div><ul class=\"examples\"><li><strong><em>front-wheel/rear-wheel/four-wheel drive</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[computer]</strong> <span class=\"gram\">[countable]</span> a piece of equipment in a computer that is used to get information from a disk or to store information on it → disk drive</div><ul class=\"examples\"><li><strong><em>hard/floppy/A etc drive</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[sport]</strong> <span class=\"gram\">[countable]</span> an act of hitting a ball hard, especially in tennis, baseball, or golf:</div><ul class=\"examples\"><li><em>He hit a long, high drive to right field.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[military attack]</strong> <span class=\"gram\">[countable]</span> several military attacks</div><ul class=\"examples\"><li><strong><em>drive into</strong>: a drive deep into enemy territory</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[animals]</strong> <span class=\"gram\">[countable]</span> when animals such as cows or sheep are brought together and made to move in a particular direction</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>Drive</strong> used in the names of roads:</div><ul class=\"examples\"><li><em>141 Park Drive</em></li></ul></div></div>","2221":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> driv‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdraɪvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who drives a car, bus etc → chauffeur:</div><ul class=\"examples\"><li><em>a taxi driver</em></li><li><em>Do you think you’re a good driver?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> a piece of software that makes a computer work with another piece of equipment such as a printer or a mouse</div><div class=\"sense\"><span class=\"snum\">3</span> a golf club with a wooden head</div></div>","2222":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drive‧way</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdraɪvweɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the hard area or road between your house and the street <em>SYN drive</em></div></div>","2223":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈdriving ˌlicence</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> an official document or card that says that you are legally allowed to drive SYN driver’s license<em>American English</em></div></div>","2224":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> driz‧zle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrɪzəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>it drizzles</strong> if it is drizzling, light rain and mist come out of the sky:</div><ul class=\"examples\"><li><em>The rain isn’t too bad – it’s only drizzling.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to let a liquid fall on food in a small stream or in small drops:</div><ul class=\"examples\"><li><em>Drizzle the soy sauce over the chicken.</em></li></ul></div>","2225":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drɒp $ drɑːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(past tense and past participle dropped, present participle dropping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[let something fall]</strong> <span class=\"gram\">[transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stop holding or carrying something so that it falls:</div><ul class=\"examples\"><li><em>He dropped his briefcase on a chair.</em></li><li><em>She screamed and dropped the torch.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make something such as a bomb fall from a plane:</div><ul class=\"examples\"><li><em>U.S. planes began dropping bombs on the city.</em></li><li><em>Supplies are being dropped for the refugees.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[fall]</strong> <span class=\"gram\">[intransitive]</span> to fall suddenly onto the ground or into something</div><ul class=\"examples\"><li><strong><em>drop from/off</strong>: The apples are beginning to drop from the trees. / Your button has dropped off.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[move your body down]</strong> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to lower yourself or part of your body suddenly</div><ul class=\"examples\"><li><strong><em>drop down/onto/into</strong>: He dropped down onto the floor and hid under the table.</em></li><li><em>She dropped her head back against the cushion.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[become less]</strong> <span class=\"gram\">[intransitive]</span> to fall to a lower level or amount, especially a much lower level or amount ► see thesaurus at decrease</div><ul class=\"examples\"><li><strong><em>drop suddenly/sharply/dramatically</strong>: The number of deaths on the roads has dropped sharply. / Temperatures drop quite dramatically at night, so bring some warm clothing.</em></li><li><strong><em>drop to</strong>: Their share of the market dropped to 50 percent this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[reduce]</strong> <span class=\"gram\">[transitive]</span> to reduce the level or amount of something:</div><ul class=\"examples\"><li><em>You might be able to get them to drop the price.</em></li><li><em>As soon as she saw the police car she dropped her speed.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[not include]</strong> <span class=\"gram\">[transitive]</span> to decide not to include someone or something:</div><ul class=\"examples\"><li><em>His name was dropped from the list.</em></li><li><strong><em>drop somebody from a team/side</strong>: Taylor was bitterly disappointed to be dropped from the England side.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[stop doing something]</strong> <span class=\"gram\">[transitive]</span> to stop doing something, discussing something, or continuing with something:</div><ul class=\"examples\"><li><em>The proposal was dropped after opposition from civil liberties groups.</em></li><li><strong><em>drop charges/drop a case</strong>: New evidence was presented to the court and the case was dropped.</em></li><li><strong><em>drop a subject at school/university</strong> (=stop studying it): Students are allowed to drop history in Year 9.</em></li><li><em>You can’t expect me to drop everything (=completely stop doing whatever I am doing) whenever you’re in town.</em></li><li><em>Oh, drop the ‘Senator’ (=stop calling me ‘Senator’) – just call me Gordon.</em></li><li><em>Some time later, the matter was quietly dropped.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[stop talking about something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to stop talking about something</div><ul class=\"examples\"><li><strong><em>drop the subject</strong>: To her relief, Julius dropped the subject.</em></li><li><strong><em>drop it</strong> (=stop talking about a subject): Just drop it, will you? I don’t want to talk about it anymore. / ‘What about the money?’ ‘We’ve agreed to let it drop (=we have agreed not to talk about it anymore).’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[take somebody somewhere]</strong> (also drop off) <span class=\"gram\">[transitive]</span> to take someone by car to a place and leave them there, especially on your way to another place:</div><ul class=\"examples\"><li><em>Just drop me here – I can walk the rest of the way.</em></li><li><strong><em>drop somebody at something</strong>: She dropped Johnny at the school gates at about 8:30.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[take something somewhere]</strong> <span class=\"gram\">[transitive]</span> to take something to a place and leave it there</div><ul class=\"examples\"><li><strong><em>drop something round/in</strong>: I’ve got your books – I’ll drop them round to your place later.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[visit]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to visit someone you know, usually without arranging a particular time</div><ul class=\"examples\"><li><strong><em>drop by/round</strong>: I just dropped by to see how you were getting on. / The kids drop round and see her from time to time.</em></li><li><strong><em>drop into</strong>: Jan dropped into the office this morning to tell me her news.</em></li><li><strong><em>drop in (on somebody)</strong>: Why don’t you drop in for a drink one evening?</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[slope downwards]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a path, land etc drops, it goes down suddenly, forming a steep slope</div><ul class=\"examples\"><li><strong><em>drop down</strong>: The cliff dropped down over a hundred feet to the sea below.</em></li><li><strong><em>drop away</strong>: On the left the ground drops away, giving a view over the rooftops.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[end a relationship]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to suddenly stop having a relationship with someone, especially a romantic relationship:</div><ul class=\"examples\"><li><em>She dropped him as soon as she found out he had been seeing another woman.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>until/till you drop</strong> until you are too tired to continue doing something:</div><ul class=\"examples\"><li><em>We’re going to shop till we drop!</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>drop a hint</strong> to suggest or ask for something in an indirect way, hoping that the person you are talking to will understand what you mean:</div><ul class=\"examples\"><li><em>He dropped some big hints about what he wanted for his birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>drop somebody a line/note</strong> <em>informal</em> to write a short letter to someone:</div><ul class=\"examples\"><li><em>Drop us a line to let us know how you’re getting on.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>drop dead</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>informal</em> to die suddenly</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>spoken</em> <em>informal</em> an impolite expression which you say to someone when you are extremely angry with them</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>somebody’s jaw dropped</strong> used to say that someone was very surprised</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>drop your eyes/gaze</strong> to stop looking at someone and look down, usually because you feel embarrassed or uncomfortable:</div><ul class=\"examples\"><li><em>Ben looked at me in horror for a moment and then dropped his gaze.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>the wind drops</strong> the wind stops:</div><ul class=\"examples\"><li><em>They waited for the wind to drop.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>drop a bombshell</strong> <em>informal</em> to suddenly tell someone a shocking piece of news:</div><ul class=\"examples\"><li><em>Finally she dropped the bombshell. She was pregnant and I was the father.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>drop somebody in it</strong> <em>informal</em> to say or do something that gets someone else into trouble:</div><ul class=\"examples\"><li><em>You told her where we went on Friday night! You’ve really dropped me in it now!</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>drop $50/£2,000 etc</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to lose money in a business deal, a game etc:</div><ul class=\"examples\"><li><em>Phil dropped $200 playing poker yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>drop a catch</strong> to fail to catch a ball hit by a batsman in cricket</div><div class=\"sense\"><span class=\"snum\">25</span> <strong>drop a point</strong> to lose a point in a sports competition:</div><ul class=\"examples\"><li><em>Real Madrid dropped a point at home yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>be dropping like flies</strong> <em>informal</em> if people are dropping like flies, they are getting ill or dying in large numbers</div><div class=\"sense\"><span class=\"snum\">27</span> <strong>drop a clanger/brick</strong> <em>British English</em> to say something embarrassing in a social situation</div><div class=\"sense\"><span class=\"snum\">28</span> <strong>drop a stitch</strong> to let the wool fall off the needle when you are knitting</div><div class=\"sense\"><span class=\"snum\">29</span> <strong>drop anchor</strong> to lower a boat’s anchor to the bottom of the sea, a lake etc so that the boat does not float away</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>drop acid</strong> <em>informal</em> to swallow LSD (=an illegal drug)</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[liquid]</strong> <span class=\"gram\">[countable]</span> a very small amount of liquid that falls in a round shape → rain drop, teardrop ► see thesaurus at piece</div><ul class=\"examples\"><li><strong><em>drop of</strong>: As the first drops of rain began to fall, Michael started to run. / A single drop of blood splashed onto the floor. / A drop of sweat ran down her forehead and into her eye.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[small amount]</strong> <span class=\"gram\">[usually singular]</span> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a small amount of liquid that you drink, especially alcohol</div><ul class=\"examples\"><li><strong><em>drop of</strong>: She likes to add a drop of brandy to her tea.</em></li><li><em>George hasn’t touched a drop (=drunk any alcohol) for years.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a small amount of something</div><ul class=\"examples\"><li><strong><em>drop of</strong>: I haven’t got a drop of sympathy for him.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[reduction]</strong> <span class=\"gram\">[singular]</span> a reduction in the amount, level, or number of something, especially a large or sudden one <em>SYN fall</em></div><ul class=\"examples\"><li><strong><em>drop in</strong>: Manufacturers report a big drop in new orders. / a drop in temperature</em></li><li><strong><em>a sharp/dramatic/marked drop in something</strong>: The results showed a sharp drop in profits.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[distance to ground]</strong> <span class=\"gram\">[singular]</span> a distance from a higher point down to the ground or to a lower point:</div><ul class=\"examples\"><li><em>There was a steep drop on one side of the track.</em></li><li><em>a 20-metre drop</em></li><li><em>There was an almost sheer (=vertical) drop to the valley below.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>at the drop of a hat</strong> immediately and without pausing to think about what you are going to do:</div><ul class=\"examples\"><li><em>Some of these corporations threaten to sue at the drop of a hat.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[delivery]</strong> <span class=\"gram\">[countable]</span> an act of delivering something somewhere, for example by dropping it from a plane <em>SYN delivery</em>: → mail drop</div><ul class=\"examples\"><li><em>Air drops (=from a plane) of food aid were made to the region yesterday.</em></li><li><em>My first drop of the day is usually somewhere in north London.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lemon/fruit/chocolate etc drop</strong> a sweet that tastes of lemon etc</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>a drop in the ocean</strong> <em>British English</em>, a drop in the bucket <em>American English</em> a very small amount of something compared to what is needed or wanted:</div><ul class=\"examples\"><li><em>5,000 new schools are to be built, but this is just a drop in the ocean for such a vast country.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>eye/ear etc drops</strong> a type of medicine that you put in your eye, ear etc, one drop at a time</div></div></div>","2226":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /draʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a long period of dry weather when there is not enough water for plants and animals to live</div></div>","2227":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /draʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to die from being under water for too long, or to kill someone in this way:</div><ul class=\"examples\"><li><em>Many people drowned when the boat overturned.</em></li><li><em>Jane was drowned in the river.</em></li><li><strong><em>drown yourself</strong>: Depressed, Peter tried to drown himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also drown out) <span class=\"gram\">[transitive]</span> if a loud noise drowns out another sound, it prevents it from being heard:</div><ul class=\"examples\"><li><em>A train blew its whistle and drowned his voice.</em></li><li><em>The noise of the battle was drowned out by his aircraft’s engine.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to cover something, especially food, with more liquid than is necessary or nice</div><ul class=\"examples\"><li><strong><em>drown something in something</strong>: The fish was drowned in a rich sauce.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> to have a very strong feeling or a serious problem that is difficult to deal with</div><ul class=\"examples\"><li><strong><em>drown in</strong>: Relief agencies are drowning in frustration. / The country is drowning in debt.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>drown your sorrows</strong> to drink a lot of alcohol in order to forget your problems</div></div>","2228":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drʌɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an illegal substance such as marijuana or cocaine, which some people take in order to feel happy, relaxed, or excited:</div><ul class=\"examples\"><li><em>A lot of young people start taking drugs at school.</em></li><li><em>She always looks as though she’s on drugs (=taking drugs).</em></li><li><em>Jimi Hendrix died of a drug overdose.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a medicine, or a substance for making medicines:</div><ul class=\"examples\"><li><em>a drug used in the treatment of cancer</em></li><li><strong><em>drug for</strong>: new drugs for AIDS-related conditions</em></li><li><em>Drugs prescribed (=ordered for people) by doctors can be extremely hazardous if used in the wrong way.</em></li><li><em>The big drug companies make huge profits.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a substance that people doing a sport sometimes take illegally to improve their performance:</div><ul class=\"examples\"><li><em>She was banned from the Olympics after failing a drug test (=a test that shows if you have taken drugs).</em></li><li><strong><em>performance-enhancing drugs</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[usually singular]</span> a substance such as tobacco, coffee, or alcohol, that makes you want more and more of it</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>be (like) a drug</strong> if an activity is like a drug, you enjoy it so much that you want to do it more and more:</div><ul class=\"examples\"><li><em>Athletics is like a drug – it keeps dragging you back for more.</em></li></ul></div>","2229":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drug‧store</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrʌɡstɔː $ -stɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>especially American English</em> a shop where you can buy medicines, beauty products etc SYN chemist<em>British English</em></div></div>","2230":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /drʌm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a musical instrument made of skin stretched over a circular frame, played by hitting it with your hand or a stick:</div><ul class=\"examples\"><li><em>a big bass drum</em></li><li><em>1,000 people marched, beating drums and carrying flags.</em></li><li><strong><em>on drums</strong>: Trumpeter Red Rodney was playing with Kenny Clarke on drums (=playing the drums).</em></li><li><em>Jones played the drums in an all-girl band.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large round container for storing liquids such as oil, chemicals etc:</div><ul class=\"examples\"><li><em>a 5-gallon oil drum</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> something that looks like a drum, especially part of a machine:</div><ul class=\"examples\"><li><em>a brake drum</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>bang/beat the drum for somebody/something</strong> to speak eagerly in support of someone or something:</div><ul class=\"examples\"><li><em>The company is banging the drum for their new software.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the drum of something</strong> a sound like the sound a drum makes:</div><ul class=\"examples\"><li><em>the drum of the rain on the window</em></li></ul></div>","2231":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> drum‧mer</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdrʌmə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who plays drums</div></div>","2232":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[not before noun]</span> unable to control your behaviour, speech etc because you have drunk too much alcohol <em>OPP sober</em>:</div><ul class=\"examples\"><li><em>You’re drunk.</em></li><li><em>David would get drunk and I would have to take him home and put him to bed.</em></li><li><strong><em>drunk on</strong>: He was drunk on beer and whisky.</em></li><li><strong><em>blind drunk<em>British English</em></strong> (=very drunk): All she wants to do is get blind drunk.</em></li><li><strong><em>drunk as a lord</strong> (also<strong>drunk as a skunk)</strong> (=very drunk): He turned up one morning, drunk as a lord.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>being drunk and disorderly</strong> <em>law</em> the crime of behaving in a violent noisy way in a public place when you are drunk</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>drunk on/with something</strong> so excited by a feeling that you behave in a strange way:</div><ul class=\"examples\"><li><em>drunk with happiness</em></li></ul></div>","2233":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /draɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative drier, superlative driest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not wet]</strong> without water or liquid inside or on the surface <em>OPP wet</em>: → bone dry</div><ul class=\"examples\"><li><em>I need to change into some dry clothes.</em></li><li><em>Make sure that the surface is clean and dry before you start to paint.</em></li><li><em>You should store disks in a cool, dry place.</em></li><li><strong><em>shake/rub/wipe etc something dry</strong>: Jean rubbed her hair dry. / The path is dry as a bone (=very dry).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[weather]</strong> having very little rain or moisture <em>OPP wet</em> → arid:</div><ul class=\"examples\"><li><em>The weather was hot and dry.</em></li><li><em>Eastern areas should stay dry tomorrow.</em></li><li><em>the dry season</em></li><li><em>These plants do not grow well in dry conditions (=when there is not much rain).</em></li><li><em>a prolonged dry spell (=period)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>dry mouth/skin/lips/hair etc</strong> without enough of the liquid or oil that is normally in your mouth, skin etc → parched:</div><ul class=\"examples\"><li><em>His heart was pounding and his mouth was dry.</em></li><li><em>Mary has dry, sensitive skin.</em></li><li><em>a shampoo for dry hair</em></li><li><em>She licked her dry lips.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>run/go dry</strong> if a lake, river etc runs dry, all the water gradually disappears, especially because there has been no rain:</div><ul class=\"examples\"><li><em>The river ran dry last summer.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[humour]</strong> someone with a dry sense of humour says funny and clever things while seeming to be serious:</div><ul class=\"examples\"><li><em>He had a delightfully dry sense of humour.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[boring]</strong> boring, very serious, and without humour: ► see thesaurus at boring</div><ul class=\"examples\"><li><em>In schools, science is often presented in a dry and uninteresting manner.</em></li><li><em>a dry debate on policies</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>dry cough</strong> a cough which does not produce any phlegm</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>dry wine/sherry etc</strong> wine etc that is not sweet:</div><ul class=\"examples\"><li><em>a glass of dry white wine</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[without alcohol]</strong> not drinking alcohol, or not allowing any alcohol to be sold:</div><ul class=\"examples\"><li><em>Paula had been dry for a year before she started drinking again.</em></li><li><em>Kuwait’s a dry country.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[voice]</strong> showing no emotion when you speak:</div><ul class=\"examples\"><li><em>‘Good evening gentlemen,’ he said, in a dry voice.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>dry bread/toast</strong> bread etc eaten on its own without anything such as butter or jam spread on it</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[thirsty]</strong> <em>informal</em> thirsty</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>not a dry eye in the house</strong> used to say that everyone was crying because something was very sad – often used humorously</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle dried, present participle drying, third person singular dries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make something dry, or to become dry:</div><ul class=\"examples\"><li><em>Mrs Brown hung the washing on the line to dry.</em></li><li><em>He was drying his hair with a towel.</em></li><li><em>Mary dried her hands.</em></li><li><em>Leave the first coat of paint to dry before adding another.</em></li><li><em>She stood up and dried her eyes (=wiped away her tears).</em></li><li><strong><em>dry yourself</strong>: He quickly dried himself on the thin towel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also dry up<em>British English</em>) to rub plates, dishes etc dry with a cloth after they have been washed:</div><ul class=\"examples\"><li><em>You wash and I’ll dry.</em></li><li><em>Shall I dry up these glasses?</em></li></ul></div></div>","2234":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dry‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdraɪə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a machine that dries things, especially clothes</div></div>","2235":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjuːəl $ ˈduːəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">having two of something or two parts → single</div><ul class=\"examples\"><li><strong><em>dual role/purpose/function</strong>: The bridge has a dual role, carrying both road and rail.</em></li><li><em>a dual system of education</em></li><li><strong><em>dual citizenship/nationality</strong>: She has dual nationality, of Canada and Britain (=she is a citizen of Canada and Britain).</em></li></ul></div>","2236":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌdual ˈcarriageway</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> a main road that has two lines of traffic travelling in each direction, with a narrow part between them that has no traffic → single carriageway SYN divided highway<em>American English</em></div></div>","2237":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧bi‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjuːbiəs $ ˈduː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> probably not honest, true, right etc:</div><ul class=\"examples\"><li><em>The firm was accused of dubious accounting practices.</em></li><li><em>Many critics regard this argument as dubious or, at best, misleading.</em></li><li><em>The assumption that growth in one country benefits the whole world is highly dubious.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[not before noun]</span> not sure whether something is good or true <em>SYN doubtful</em>:</div><ul class=\"examples\"><li><em>I can see you are dubious; take some time to think about it.</em></li><li><strong><em>dubious about</strong>: Some universities are dubious about accepting students over the age of 30.</em></li><li><em>‘Are you sure you know what you are doing?’ Andy said, looking dubious.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the dubious honour/distinction/pleasure (of doing something)</strong> a dubious honour etc is the opposite of an honour – used about something unpleasant that happens:</div><ul class=\"examples\"><li><em>The Stephensons had the dubious honor of being the 100th family to lose their home in the fire.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not good or not of good quality:</div><ul class=\"examples\"><li><em>The room was decorated in dubious taste.</em></li></ul></div>","2238":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dʌk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a very common water bird with short legs and a wide beak, used for its meat, eggs, and soft feathers</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a female duck → drake</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the meat of a duck used as food:</div><ul class=\"examples\"><li><em>roast duck with orange sauce</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>take to something like a duck to water</strong> to learn how to do something very easily:</div><ul class=\"examples\"><li><em>She took to dancing like a duck to water.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> (also ducks) <em>British English</em> <em>spoken</em> used to speak to someone, especially a woman, in a friendly way:</div><ul class=\"examples\"><li><em>What can I get you, ducks?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable]</span> a score of zero by a batsman in a game of cricket</div></div>","2239":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /djuː $ duː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[expected]</strong> <span class=\"gram\">[not before noun]</span> expected to happen or arrive at a particular time → due date</div><ul class=\"examples\"><li><strong><em>due to do something</strong>: The team are due to fly to Italy next month. / His new book is due to be published next year.</em></li><li><strong><em>due in/on/at</strong>: She’s pregnant and the baby’s due in April.</em></li><li><em>The final results of the experiment are due on December 9.</em></li><li><em>I’m due at his office at 4.30.</em></li><li><strong><em>due for</strong>: The car is due for its annual service again.</em></li><li><strong><em>due back</strong>: When are the library books due back?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[owed]</strong> owed to someone either as a debt or because they have a right to it:</div><ul class=\"examples\"><li><em>Any money due you will be sent by cheque through the post.</em></li><li><strong><em>due to</strong>: Thanks are due to all those who took part.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[money]</strong> if an amount of money is due, it must be paid at a particular time:</div><ul class=\"examples\"><li><em>The next income tax payment is due on 31 January.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in due course</strong> at some time in the future when it is the right time, but not before:</div><ul class=\"examples\"><li><em>Further details will be announced in due course.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[proper]</strong> <span class=\"gram\">[only before noun]</span> <em>formal</em> proper or suitable:</div><ul class=\"examples\"><li><em>He was banned for six months for driving without due care and attention.</em></li><li><strong><em>due regard/consideration</strong>: We want the best for each individual child with due regard for the interests of the other children.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>with (all) due respect</strong> <em>spoken</em> used when you disagree with someone or criticize them in a polite way:</div><ul class=\"examples\"><li><em>Dad, with all due respect, was not a very good husband.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>due north/south/east/west</strong> directly to the north, south, east, or west</div></div></div>","2240":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dʌl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\">(comparative duller, superlative dullest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[boring]</strong> not interesting or exciting: ► see thesaurus at boring RegisterIn everyday English, people usually say boring rather than dull:· a long, boring film</div><ul class=\"examples\"><li><em>Life is never dull when Elizabeth is here.</em></li><li><em>a dull movie</em></li><li><em>It sounded pretty dull to me.</em></li><li><em>The weekly meeting tends to be deadly dull (=very dull).</em></li><li><em>Last week we had a hurricane. Never a dull moment running a hotel in the Caribbean (=it’s always interesting or exciting).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[colour/light]</strong> not bright or shiny:</div><ul class=\"examples\"><li><em>The bird is dull brown and gray in colour.</em></li><li><em>Her eyes were dull with dark shadows beneath them.</em></li><li><em>the dull afternoon light</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[weather]</strong> not bright and with lots of clouds:</div><ul class=\"examples\"><li><em>Outside the weather was hazy and dull.</em></li><li><em>a dull sky</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[pain]</strong> a dull pain is not severe but does not stop <em>OPP sharp</em>:</div><ul class=\"examples\"><li><em>a dull ache in her lower back</em></li><li><em>The pain was dull but persistent.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[sound]</strong> not clear or loud:</div><ul class=\"examples\"><li><em>The gates shut with a dull thud.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[knife/blade]</strong> not sharp <em>SYN blunt</em></div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[not intelligent]</strong> <em>old-fashioned</em> not able to think quickly or understand things easily <em>SYN stupid</em>:</div><ul class=\"examples\"><li><em>If you don’t understand then you’re duller than I thought.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[trade]</strong> if business on the Stock Exchange is dull, few people are buying and selling <em>OPP brisk</em></div></div>","2241":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dʌm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>informal</em> stupid: ► see thesaurus at stupid</div><ul class=\"examples\"><li><em>What a dumb question.</em></li><li><em>a bunch of dumb kids</em></li><li><em>‘What is it?’ I asked, playing dumb (=pretending to be stupid).</em></li><li><em>She’s no dumb blonde (=a pretty woman with blonde hair who seems stupid).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> unable to speak, because you are angry, surprised, shocked etc:</div><ul class=\"examples\"><li><em>He stared at the burnt-out car in dumb disbelief.</em></li><li><em>She was struck dumb with terror.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>old-fashioned</em> someone who is dumb is not able to speak at all. Many people think that this use is offensive → mute → deaf and dumb at deaf(1)</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>dumb luck</strong> <em>informal</em> something good that happens in an unexpected way, especially when it is not deserved:</div><ul class=\"examples\"><li><em>It was just dumb luck that we found the place at all.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>dumb animals/creatures</strong> used to talk about animals when you want to emphasize that humans often treat them badly and they cannot protect themselves</div></div>","2242":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dʌmp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[put something somewhere]</strong> <span class=\"gram\">[always + adverb/preposition]</span> to put something somewhere in a careless untidy way: ► see thesaurus at put</div><ul class=\"examples\"><li><em>Merrill dumped her suitcase down in the hall.</em></li><li><strong><em>dump something on something</strong>: They dump tons of salt on icy road surfaces to make driving safer.</em></li><li><strong><em>dump something in/into something</strong>: He found a can of beef stew and dumped it in a saucepan to heat.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[get rid of something]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to get rid of something that you do not want:</div><ul class=\"examples\"><li><em>Ellie dumped all the photos of her ex-husband.</em></li><li><em>He dumped her body into the sea.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to get rid of waste material by taking it from people’s houses and burying it under the soil:</div><ul class=\"examples\"><li><em>Britain dumps more of its waste than any other European country.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[end relationship]</strong> <em>informal</em> to end a relationship with someone:</div><ul class=\"examples\"><li><em>Vicky dumped Neil yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sell goods]</strong> to get rid of goods by selling them in a foreign country at a much lower price</div><ul class=\"examples\"><li><strong><em>dump in/on</strong>: a campaign to stop cheap European beef being dumped in West Africa</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[copy information]</strong> <em>technical</em> to copy information stored in a computer’s memory on to something else such as a disk or magnetic tape → dumping</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[waste]</strong> a place where unwanted waste is taken and left</div><ul class=\"examples\"><li><strong><em>rubbish dump<em>British English,</em></strong> <strong>garbage dump</em>American English</strong><em>: The fire probably started in a rubbish dump.</em></li><li><em>Put the rest into a sack to take to the dump.</em></li><li><em>an underground nuclear waste dump</em></li><li><em>a dump site</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[weapons]</strong> a place where military supplies are stored, or the supplies themselves:</div><ul class=\"examples\"><li><em>There has been a series of explosions in an ammunition dump.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[unpleasant place]</strong> <em>informal</em> a place that is unpleasant to live in because it is dirty, ugly, untidy etc:</div><ul class=\"examples\"><li><em>‘What a dump,’ she added as they entered the village.</em></li><li><em>Why are you living in a dump like this?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>down in the dumps</strong> <em>informal</em> very sad and without much interest in life:</div><ul class=\"examples\"><li><em>She’s feeling a bit down in the dumps.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[computer]</strong> <em>technical</em> the act of copying the information stored in a computer’s memory onto something else, such as a disk:</div><ul class=\"examples\"><li><em>a screen dump</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>take a dump</strong> <em>informal</em> <em>not polite</em> to pass solid waste from the bowels</div></div></div>","2243":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧o</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjuːəʊ $ ˈduːoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural duos)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> two people who perform together or are often seen together:</div><ul class=\"examples\"><li><em>the comedy duo Reeves and Mortimer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of music for two performers <em>SYN duet</em></div></div>","2244":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧pli‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjuːplɪkeɪt $ ˈduː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to copy something exactly:</div><ul class=\"examples\"><li><em>New copies of the form can be duplicated from a master copy.</em></li><li><em>The video was duplicated illegally.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to repeat something in exactly the same way:</div><ul class=\"examples\"><li><em>We don’t want staff to duplicate each other’s work.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧pli‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjuːpləkət $ ˈduː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">exactly the same as something, or made as an exact copy of something:</div><ul class=\"examples\"><li><em>A duplicate copy should be made for the county record office.</em></li><li><em>a duplicate key</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an exact copy of something that you can use in the same way</div><ul class=\"examples\"><li><strong><em>duplicate of</strong>: Locksmiths can make duplicates of most keys.</em></li><li><em>She kept both the duplicate and the original.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in duplicate</strong> if something is in duplicate, there are two copies of it:</div><ul class=\"examples\"><li><em>Copies of the proposal should be sent in duplicate.</em></li></ul></div></div>","2245":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /djʊˈreɪʃən $ dʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the length of time that something continues:</div><ul class=\"examples\"><li><em>The course is of three years’ duration.</em></li><li><strong><em>for the duration (of something)</strong>: The package includes cycle hire for the duration of your holiday.</em></li></ul></div>","2246":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dur‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjʊərɪŋ $ ˈdʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> from the beginning to the end of a period of time:</div><ul class=\"examples\"><li><em>During the summer she worked as a lifeguard.</em></li><li><em>He slept calmly during the early part of the night.</em></li><li><em>Foxes remain hidden during the day.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> at some point in a period of time: ► Don’t say ‘during doing something’ or ‘during someone does something’. Use while: They chatted while waiting for the train (NOT during waiting for the train). | He stole her money while she slept (NOT during she slept).</div><ul class=\"examples\"><li><em>My father was killed during the war.</em></li><li><em>I mentioned the subject during our discussions at her Washington office.</em></li></ul></div>","2247":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dʌsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the time before it gets dark when the sky is becoming less bright <em>SYN twilight</em> → dawn, dusk:</div><ul class=\"examples\"><li><em>The street lights go on at dusk.</em></li></ul></div>","2248":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dʌst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> dry powder consisting of extremely small bits of dirt that is in buildings on furniture, floors etc if they are not kept clean:</div><ul class=\"examples\"><li><em>All the furniture was covered in dust.</em></li><li><em>a thick layer of dust</em></li><li><em>There’s not a speck of dust in the kitchen.</em></li><li><strong><em>gather/collect dust</strong> (=become covered with dust): Her old trophies were collecting dust on the shelves.</em></li><li><em>Dust particles floated in the sunlight.</em></li><li><em>A sudden breeze sent motes of dust (=small bits of dust) dancing in the air.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> dry powder consisting of extremely small bits of earth or sand:</div><ul class=\"examples\"><li><em>The wind was blowing dust and leaves up from the ground.</em></li><li><em>A car sped past in a cloud of dust.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> powder consisting of extremely small bits of a particular substance</div><ul class=\"examples\"><li><strong><em>coal/brick/chalk etc dust</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a dust</strong> <em>British English</em> the act of dusting something:</div><ul class=\"examples\"><li><em>I need to give the sitting room a dust.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>let the dust settle/wait for the dust to settle</strong> to allow or wait for a confused situation to become clear</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to clean the dust from a surface by moving something such as a soft cloth across it:</div><ul class=\"examples\"><li><em>Rachel dusted the books and the bookshelves.</em></li><li><em>I was dusting in the bedroom when the phone rang.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> (also dust down, dust off) to remove something such as dust or dirt from your clothes by brushing them with your hands:</div><ul class=\"examples\"><li><em>He got to his feet and dusted his knees.</em></li><li><strong><em>dust yourself (down/off)</strong>: Corbett dusted himself down and walked off.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to put a fine powder over something</div><ul class=\"examples\"><li><strong><em>dust something with something</strong>: Dust the biscuits with icing sugar.</em></li></ul></div></div>","2249":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dust‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdʌsti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> covered with dust: ► see thesaurus at dirty</div><ul class=\"examples\"><li><em>Adrian cycled along the dusty road.</em></li><li><em>Everything’s really dusty.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>dusty blue/pink etc</strong> blue etc that is not bright but is slightly grey:</div><ul class=\"examples\"><li><em>The curtains had faded to a dusty pink.</em></li></ul></div>","2250":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdjuːti $ ˈduː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(plural duties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[something you must do]</strong> <span class=\"gram\">[countable, uncountable]</span> something that you have to do because it is morally or legally right <em>SYN obligation</em>:</div><ul class=\"examples\"><li><em>I promise I will do my duty.</em></li><li><em>We feel it is our duty to help her.</em></li><li><em>Local authorities have a duty to keep the streets clean.</em></li><li><em>You have a duty to your husband and to your children.</em></li><li><em>She has a strong sense of moral duty.</em></li><li><em>The unions have failed in their duty to female workers.</em></li><li><em>In the traditional Hindu family, the son is duty-bound to look after his mother.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[work]</strong> <span class=\"gram\">[countable usually plural, uncountable]</span> something you have to do as part of your job</div><ul class=\"examples\"><li><strong><em>duties</strong>: Martin’s duties included cleaning the cars. / She works for her father doing part-time secretarial duties.</em></li><li><em>He will soon be fit enough to carry out his duties (=do his job).</em></li><li><em>He can only do light duties.</em></li><li><em>When Juliet reported for duty (=arrived and said she was ready to start work) she was sent to check on a new patient.</em></li><li><em>A teacher may be fired for neglect of duty (=failing to do their job properly).</em></li><li><em>He did three tours of duty in Vietnam (=three periods working in a foreign country as a soldier, government officer etc).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be on/off duty</strong> to be working or not working at a particular time, especially when you are doing a job which people take turns to do, so that someone is always doing it:</div><ul class=\"examples\"><li><em>He’s on night duty.</em></li><li><em>Mary goes on duty (=starts working) tonight at half past ten.</em></li><li><em>What time do you go off duty (=finish work)?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[tax]</strong> <span class=\"gram\">[countable, uncountable]</span> a tax you pay on something you buy → death duties, stamp duty</div><ul class=\"examples\"><li><strong><em>duty on</strong>: the duty on cigarettes</em></li><li><strong><em>customs duty</strong> (=tax paid on goods coming into the country)</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>do duty as something</strong> to be used as something <em>SYN serve as something</em>:</div><ul class=\"examples\"><li><em>The living room also does duty as a home office.</em></li></ul></div>","2251":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> du‧vet</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈduːveɪ, ˈdjuː- $ duːˈveɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a large cloth bag filled with feathers or similar material that you use to cover yourself in bed SYN comforter<em>American English</em></div></div>","2252":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌdiː viː ˈdiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">(digital video disc or digital versatile disc) a type of computer disc that can store a large amount of information, sound, pictures, and video:</div><ul class=\"examples\"><li><em>a DVD player</em></li><li><em>The film is now out on video and DVD.</em></li></ul></div>","2253":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /dwel/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive always + adverb/preposition]</span></span><span class=\"meta-item\">(past tense and past participle dwelt /dwelt/ or dwelled)</span></div><div class=\"entry-body\"><div class=\"sense\"><em>literary</em> to live in a particular place:</div><ul class=\"examples\"><li><em>They dwelt in the forest.</em></li></ul></div>","2254":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dwin‧dle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdwɪndl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">(also dwindle away) to gradually become less and less or smaller and smaller: ► see thesaurus at decrease</div><ul class=\"examples\"><li><em>The elephant population is dwindling.</em></li><li><em>His money had dwindled away.</em></li><li><strong><em>dwindle to</strong>: The stream has dwindled to a trickle.</em></li></ul></div>","2255":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /daɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a substance you use to change the colour of your clothes, hair etc:</div><ul class=\"examples\"><li><em>hair dye</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a dye job</strong> <em>informal</em> someone who has had a dye job has used a substance to change the colour of their hair</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to give something a different colour using a dye</div><ul class=\"examples\"><li><strong><em>dye something black/blue/blonde etc</strong>: Priscilla’s hair was dyed jet black.</em></li></ul></div></div>","2256":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dy‧nam‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /daɪˈnæmɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> full of energy and new ideas, and determined to succeed: ► see thesaurus at energetic</div><ul class=\"examples\"><li><em>dynamic and ambitious people</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> continuously moving or changing:</div><ul class=\"examples\"><li><em>a dynamic and unstable process</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> relating to a force or power that causes movement</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>dynamics</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[plural]</span> the way in which things or people behave, react, and affect each other</div><ul class=\"examples\"><li><strong><em>dynamic of</strong>: the dynamics of the family</em></li><li><em>He did research on group dynamics and leadership styles.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> the science relating to the movement of objects and the forces involved in movement</div><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[plural]</span> changes in how loudly music is played or sung</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> <em>formal</em> something that causes action or change</div><ul class=\"examples\"><li><strong><em>dynamic of</strong>: She regards class conflict as a central dynamic of historical change.</em></li></ul></div></div>","2257":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> dyn‧a‧sty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈdɪnəsti $ ˈdaɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural dynasties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a family of kings or other rulers whose parents, grandparents etc have ruled the country for many years:</div><ul class=\"examples\"><li><em>The Habsburg dynasty ruled in Austria from 1278 to 1918.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a period of time when a particular family ruled a country or area</div><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> a group or family that controls a particular business or organization for a long time:</div><ul class=\"examples\"><li><em>the Rothschild banking dynasty</em></li></ul></div>"};